-- NEW HAMPSHIRE SMASH: crouched, both fists cocked at his hips... then he
-- punches the air behind him and the wind fires him forward like a missile,
-- both fists leading, a cone of wind wrapped round him, and it all goes off
-- where he stops
function Effects.NewHampshireSmash(char, data, isLocal, ability)
	local root = charParts(char)
	if not root then
		return
	end
	local d = flatten(data.Dir, root)
	local travel = (ability and ability.TravelTime) or 0.4
	if isLocal then
		face(root, d)
	end
	VFX.Motion(char, "NewHampshire")
	-- the wind-up: air sucked in round his fists
	for i = 1, 4 do
		task.delay(i * 0.05, function()
			if root.Parent then
				shockDisc(handPos(char, true), -d, 4, 0.5, 0.12, WIND)
				shockDisc(handPos(char, false), -d, 4, 0.5, 0.12, WIND)
			end
		end)
	end
	VFX.PlaySound("DetroitCharge", root.Position, 0.6)
	task.wait(0.25)
	if not root.Parent then
		return
	end
	if isLocal then
		dash(root, d * 150, travel)
	end
	-- he punches the air behind him: the launch
	local back = root.Position - d * 2.5
	shockDisc(back, -d, 3, 22, 0.3, WIND, 10)
	billboardRing(back, 3, 24, Color3.new(1, 1, 1), 8, 0.3)
	streaks(back, -d, 16, 3, 8, 22, WIND, 0.35)
	dustPuffs(groundPoint(back), 1.3, 7, Color3.fromRGB(205, 196, 190), 1, true)
	VFX.PlaySound("MightSmash", back, 0.8)
	VFX.ShakeAt(back, 1.6, 80, 0.25)
	local stopTrail = addTrail(root, GOLD, 0.35, 3)
	local t0 = os.clock()
	while os.clock() - t0 < travel and root.Parent do
		-- the cone of wind he's pushing, and the street torn up under him
		local nose = root.Position + d * 3.5
		shockDisc(nose, d, 2, 11, 0.16, WIND, -4)
		streaks(nose, -d, 3, 2.5, 6, 12, WIND, 0.2)
		if rng:NextNumber() < 0.5 then
			dustPuffs(groundPoint(root.Position), 0.8, 2, Color3.fromRGB(205, 196, 190), 0.6, false)
		end
		task.wait(0.04)
	end
	stopTrail(0)
	if not root.Parent then
		return
	end
	-- where he stops, the wind he was pushing goes off
	local center = root.Position + d * 5
	VFX.Pose(char, "Blast", 0.35)
	windBlast(center, d, 1.2)
	for i = 1, 3 do
		task.delay(i * 0.04, function()
			shockDisc(center, d, 6, 30, 0.4, WIND, 30)
		end)
	end
	shockDisc(groundPoint(center) + UP * 0.4, UP, 4, 34, 0.35, GOLD)
	rocks(groundPoint(center), 1.3, 8)
	VFX.PlaySound("MightImpact", center, 0.8)
	VFX.ShakeAt(center, 2.4, 120, 0.4)
end

