-- Kneel and charge: the fist glows orange-white (reference clip)
local function chargeFist(char, root, time, scale)
	local fist = newPart(Vector3.one * 0.4, CFrame.new(handPos(char, true)), Color3.fromRGB(255, 190, 90), Enum.Material.Neon, Enum.PartType.Ball)
	local core = newPart(Vector3.one * 0.2, CFrame.new(handPos(char, true)), Color3.new(1, 1, 1), Enum.Material.Neon, Enum.PartType.Ball)
	local light = Instance.new("PointLight")
	light.Color = Color3.fromRGB(255, 200, 120)
	light.Range = 16
	light.Brightness = 4
	light.Parent = fist
	tween(fist, time, { Size = Vector3.one * 3.2 * scale })
	tween(core, time, { Size = Vector3.one * 2 * scale })
	local t0 = os.clock()
	while os.clock() - t0 < time and root.Parent do
		local hand = handPos(char, true)
		fist.CFrame = CFrame.new(hand)
		core.CFrame = CFrame.new(hand)
		if rng:NextNumber() < 0.5 then
			sparks(hand, 0.3 * scale, Color3.new(1, 1, 1), GOLD, 3)
		end
		task.wait()
	end
	fist:Destroy()
	core:Destroy()
end

function Effects.DetroitSmash(char, data, isLocal)
	local root = charParts(char)
	if not root then
		return
	end
	local d = flatten(data.Dir, root)
	if isLocal then
		face(root, d)
	end
	VFX.Motion(char, "DetroitSmash")
	VFX.PlaySound("DetroitCharge", root.Position, 1)
	-- (round 77) "SMASH!" from the All Might folder, its shout on the punch
	local who = char:GetAttribute("Quirk")
	if who == "OneForAll" or who == "PrimeMight" then
		VFX.Voice("MightSmash", root, 0.35)
