	local origin = root.Position + d * 3 + Vector3.new(0, 1, 0)
	if nearCamera(origin, 80) then
		VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.2)
	end
	windBlast(origin, d, 1.6)
	for i = 1, 5 do
		task.delay(i * 0.03, function()
			shockDisc(origin, d, 8, 38, 0.5, WIND, 75)
		end)
