	for s = 10, 75, 13 do
		task.delay(s / 220, function()
			local right = d:Cross(UP)
			local p = groundPoint(origin + d * s + right * rand(-5, 5))
			dustPuffs(p, 1.5 + s / 70, 4, Color3.fromRGB(206, 196, 186), 1.2, true)
