function Effects.OklahomaSmash(char, data, isLocal)
	local root = charParts(char)
	if not root then
		return
	end
	local d = flatten(data.Dir, root)
	VFX.Pose(char, "Blast", 0.45)
	-- spin in place (the caster owns their physics, so everyone sees it)
	if isLocal then
		task.spawn(function()
			local t0 = os.clock()
			local last = t0
			while os.clock() - t0 < 0.4 and root.Parent do
				local now = os.clock()
				root.CFrame = root.CFrame * CFrame.Angles(0, (now - last) * 32, 0)
				last = now
				RunService.Heartbeat:Wait()
			end
			if root.Parent then
				face(root, d)
			end
		end)
	end
	local t0 = os.clock()
	while os.clock() - t0 < 0.3 and root.Parent do
		local a = rand(0, math.pi * 2)
		local out = Vector3.new(math.cos(a), 0, math.sin(a))
		streaks(root.Position + out * 3, out:Cross(UP), 2, 0.5, 6, 10, WIND, 0.2)
		task.wait(0.03)
	end
	if not root.Parent then
		return
