-- ONE FOR ALL
---------------------------------------------------------------------------

do -- ALL MIGHT's grapples, counter and weather (one table: the local limit)
	local AM = {}

	-- a golden ghost of him in his prime, flaring over his body
	function AM.ghost(char, life)
		local model = outlineModel(Color3.fromRGB(120, 70, 10))
		for _, part in char:GetChildren() do
			if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" and part.Transparency < 1 then
				local g = newPart(part.Size * 1.35, part.CFrame, GOLD, Enum.Material.Neon, nil, model)
				g.Transparency = 0.35
				tween(g, life, { Size = part.Size * 1.8, Transparency = 1 })
			end
		end
		cleanup(model, life + 0.1)
	end

	-- HERO'S COUNTER: the stance - planted, arms crossed, waiting for it
	function Effects.HeroCounter(char, _data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		local window = (ability and ability.Window) or 0.9
		VFX.Pose(char, "CounterStance", window)
		billboardRing(root.Position, 2, 10, GOLD, 4, 0.3)
		VFX.PlaySound("GuardUp", root.Position, 1)
		if isLocal then
			VFX.Hooks.Dim(0.2, window)
		end
		local t0 = os.clock()
		while os.clock() - t0 < window and root.Parent and char:GetAttribute("Countering") ~= false do
			if rng:NextNumber() < 0.4 then
				sparks(root.Position + Vector3.new(rand(-1.5, 1.5), rand(-1, 2), rand(-1.5, 1.5)), 0.3, Color3.new(1, 1, 1), GOLD, 2)
			end
			task.wait(0.06)
		end
	end

	-- ...and it caught something: the Symbol of Peace, for one punch
	function Effects.HeroCounterHit(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		local tr = target and target:FindFirstChild("HumanoidRootPart")
		local d = flatten(tr and (tr.Position - root.Position) or root.CFrame.LookVector, root)
		local me = Players.LocalPlayer
		if me and me.Character == char then
			face(root, d)
			VFX.ImpactFrame(0.1)
		end
		AM.ghost(char, 0.5)
		VFX.Motion(char, "DetroitSmash")
		VFX.PlaySound("Parry", root.Position, 1)
		sparks(root.Position + d * 2, 1, Color3.new(1, 1, 1), GOLD, 20)
		task.wait(0.14)
		if not root.Parent then
			return
		end
		local origin = root.Position + d * 3 + UP
		windBlast(origin, d, 1.3)
		for i = 1, 4 do
			task.delay(i * 0.03, function()
				shockDisc(origin, d, 7, 32, 0.45, WIND, 60)
			end)
		end
		billboardRing(origin, 3, 26, GOLD, 8, 0.3)
		VFX.PlaySound("MightImpact", origin, 1)
		VFX.ShakeAt(origin, 3, 150, 0.5)
		if nearCamera(origin, 60) then
			VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.2)
		end
	end

	-- BACKDROP DRIVER, part 1: he lunges to wrap them up
	function Effects.BackdropDriver(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
			dash(root, d * 45, 0.12)
		end
		VFX.Pose(char, "BearHug", 0.3)
		VFX.PlaySound("Swing", root.Position, 1)
	end

	-- BACKDROP DRIVER, part 2 (the server says he caught them): the arch, the
	-- leap back, and the street behind him caves in
	function Effects.BackdropCatch(char, data, _isLocal, ability)
		local root, hum = charParts(char)
		if not root then
			return
		end
		ability = ability or Config.FindAbilityById("BackdropDriver") or {}
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		if not target then
			VFX.Pose(char, "Stagger", 0.3) -- (grabbed thin air)
			return
		end
		local d = typeof(data.Dir) == "Vector3" and data.Dir or flatten(root.CFrame.LookVector, root)
		local me = Players.LocalPlayer
		local over = ability.OverTime or 0.55
		VFX.Motion(char, "Suplex")
		VFX.PlaySound("Leap", root.Position, 1)
		if me and me.Character == char and hum then
			launch(root, hum, -d * 10 + UP * 22)
		end
		local stopTrail = addTrail(root, GOLD, 0.3, 2.4)
		task.wait(over)
		stopTrail(0)
		if not root.Parent then
			return
		end
		local impact = groundPoint(root.Position - d * 3.5)
		local R = ability.Crater or 16
		VFX.ImpactFrame(0.08)
		shockDisc(impact + UP * 0.4, UP, 6, R * 4, 0.5, WIND)
		shockDisc(impact + UP * 0.6, UP, 4, R * 2.6, 0.4, GOLD)
		billboardRing(impact + UP, 3, R * 2.5, Color3.new(1, 1, 1), 8, 0.3)
		dustPuffs(impact, 2.4, 12, Color3.fromRGB(206, 196, 186), 1.4, true)
		rocks(impact, 2.4, 22)
		groundMark(impact, R * 0.7, Color3.fromRGB(52, 46, 44), 14)
		VFX.PlaySound("MightImpact", impact, 1)
		VFX.PlaySound("Downslam", impact, 1)
		VFX.ShakeAt(impact, 4, 160, 0.6)
	end

	-- WEATHER CHANGER (ult V): the uppercut at the sky, the updraft that
	-- sucks everyone up, the clouds torn open overhead, then the rain of it
	function Effects.WeatherChanger(char, _data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local R = ability.Radius or 45
		local hang = ability.HangTime or 1.1
		if isLocal then
			VFX.Hooks.Dim(0.3, 1.2)
		end
		VFX.Motion(char, "SkyUppercut")
		VFX.PlaySound("DetroitCharge", root.Position, 1.2)
		chargeFist(char, root, 0.45, 1.3)
		if not root.Parent then
			return
		end
		local g = groundPoint(root.Position)
		AM.ghost(char, 0.4)
		VFX.PlaySound("MightImpact", root.Position, 1.2)
		VFX.PlaySound("Wind", root.Position, 1.2)
		if nearCamera(root.Position, 90) then
			VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.25)
		end
		-- the updraft: a column of wind roaring up off the street
		for i = 1, 6 do
			task.delay(i * 0.05, function()
				shockDisc(g + UP * (i * 6), UP, R * 0.6, R * 1.6, 0.5, WIND, 40)
			end)
		end
		for _ = 1, 3 do
			streaks(g + UP * 2, UP, 24, R * 0.5, 16, 140, WIND, 0.6)
		end
		dustPuffs(g, 2.6, 14, Color3.fromRGB(206, 196, 186), 1.5, true)
		rocks(g, 2.6, 24)
		-- the clouds split open overhead
		local sky = g + UP * 110
		for i = 1, 14 do
			local a = i / 14 * math.pi * 2
			local out = Vector3.new(math.cos(a), 0, math.sin(a))
			local puff = newPart(Vector3.one * 26, CFrame.new(sky + out * 10), Color3.fromRGB(236, 238, 244), Enum.Material.SmoothPlastic, Enum.PartType.Ball)
			puff.Transparency = 0.25
			tween(puff, 1.2, { CFrame = CFrame.new(sky + out * (R * 2.2)), Size = Vector3.one * 44 }, Enum.EasingStyle.Quad)
			tween(puff, 1.6, { Transparency = 1 }, nil, nil, hang + 0.8)
			cleanup(puff, hang + 2.6)
		end
		billboardRing(sky, 10, R * 4, Color3.new(1, 1, 1), 10, 0.8)
		VFX.ShakeAt(g, 4, 200, 0.8)
		-- ...then it all comes back down: rain, and the crash
		task.delay(hang, function()
			local t0 = os.clock()
			while os.clock() - t0 < 1.6 do
				for _ = 1, 6 do
					local from = g + Vector3.new(rand(-R, R), rand(60, 90), rand(-R, R))
					local drop = newPart(Vector3.new(0.15, 4, 0.15), CFrame.new(from), Color3.fromRGB(190, 210, 240), Enum.Material.Glass)
					drop.Transparency = 0.4
					tween(drop, 0.5, { CFrame = CFrame.new(from - UP * 70) }, Enum.EasingStyle.Linear)
					cleanup(drop, 0.55)
				end
				task.wait(0.05)
			end
		end)
		task.delay(hang + 0.35, function()
			shockDisc(g + UP * 0.5, UP, 6, R * 3, 0.5, WIND)
			VFX.PlaySound("Downslam", g, 1.2)
			VFX.ShakeAt(g, 3.5, 200, 0.6)
		end)
	end
end

function Effects.PlusUltraRush(char, data, isLocal, ability)
	local root = charParts(char)
	if not root then
		return
	end
	local d = flatten(data.Dir, root)
	local right = d:Cross(UP)
	if isLocal then
		face(root, d)
		dash(root, d * 80, 0.15)
	end
	task.wait(0.2)
	local hits = (ability and ability.Hits) or 12
	for k = 1, hits do
		if not root.Parent then
			return
		end
		VFX.Pose(char, k % 2 == 0 and "PunchL" or "PunchR", 0.08)
		local p = root.Position + d * 4.5 + right * rand(-2.2, 2.2) + UP * rand(-1, 2)
		local fist = newPart(Vector3.one * 1.5, CFrame.new(p), k % 3 == 0 and GOLD or Color3.new(1, 1, 1), Enum.Material.Neon, Enum.PartType.Ball)
		tween(fist, 0.06, { Size = Vector3.one * 4.5 })
		tween(fist, 0.1, { Size = Vector3.one * 5, Transparency = 1 }, nil, nil, 0.06)
		cleanup(fist, 0.2)
		shockDisc(p, d, 2, 9, 0.16, WIND, 10)
		streaks(p, d, 3, 1, 4, 10, WIND, 0.12)
		VFX.ShakeAt(p, 0.6, 50, 0.08)
		task.wait(0.1)
	end
	task.wait(0.05)
	if not root.Parent then
		return
	end
	-- final PLUS ULTRA punch
	VFX.Pose(char, "PunchR", 0.5)
	local origin = root.Position + d * 4 + UP
	if nearCamera(origin, 90) then
		VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.25)
	end
	for i = 1, 6 do
		task.delay(i * 0.03, function()
			shockDisc(origin, d, 8, 34, 0.45, WIND, 60)
		end)
	end
	shockDisc(origin, d, 4, 26, 0.25, GOLD)
	windBlast(origin, d, 1.8)
	VFX.PlaySound("MightSmash", origin, 1.2)
	VFX.ShakeAt(origin, 3, 160, 0.5)
end

function Effects.TexasSmashMax(char, data, isLocal)
	local root = charParts(char)
	if not root then
		return
	end
	local d = flatten(data.Dir, root)
	if isLocal then
		face(root, d)
		VFX.Hooks.Dim(0.5, 0.6)
	end
	VFX.Pose(char, "Kneel", 0.35)
	task.spawn(function()
		local t0 = os.clock()
		while os.clock() - t0 < 0.35 and root.Parent do
			local hand = handPos(char, true)
			bolt(hand, 2, GOLD)
			shockDisc(hand, d, 9, 1, 0.12, WIND)
			task.wait(0.05)
		end
	end)
	chargeFist(char, root, 0.35, 1.6)
	if not root.Parent then
		return
	end
	VFX.Pose(char, "PunchR", 0.6)
	local origin = root.Position + d * 4 + UP
	if nearCamera(origin, 140) then
		VFX.ImpactFrame(0.1)
		VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.35)
	end
	windBlast(origin, d, 2.6)
	for i = 1, 10 do
		task.delay(i * 0.03, function()
			shockDisc(origin, d, 16, 62, 0.6, WIND, 135)
		end)
	end
	shockDisc(origin, d, 6, 40, 0.28, GOLD)
	streaks(origin, d, 70, 15, 22, 230, WIND, 0.5)
	-- corkscrew of wind around the blast
	for i = 1, 40 do
		task.delay(i * 0.012, function()
			local a = i * 0.55
			local basis = CFrame.lookAt(origin, origin + d)
			local p = origin + d * (i * 3) + basis.RightVector * math.cos(a) * 9 + basis.UpVector * math.sin(a) * 9
			local seg = newPart(Vector3.new(0.45, 0.45, 8), CFrame.lookAt(p, p + d), WIND, Enum.Material.Neon)
			tween(seg, 0.4, { Transparency = 1, CFrame = CFrame.lookAt(p + d * 20, p + d * 21) })
			cleanup(seg, 0.45)
		end)
	end
	for s = 12, 130, 12 do
		task.delay(s / 260, function()
			local p = groundPoint(origin + d * s + d:Cross(UP) * rand(-8, 8))
			dustPuffs(p, 2 + s / 60, 4, Color3.fromRGB(206, 196, 186), 1.4, true)
			if s % 36 == 0 then
				rocks(p, 1.6, 6)
			end
		end)
	end
	VFX.PlaySound("MightSmash", origin, 1.2)
	VFX.ShakeAt(origin, 4.5, 240, 0.8)
end

