-- HALF-COLD HALF-HOT: Phosphor
---------------------------------------------------------------------------

function Effects.Phosphor(char, data, isLocal)
	local root = charParts(char)
	if not root then
		return
	end
	local dir = aimDir(data, root)
	if isLocal then
		face(root, dir)
		VFX.Hooks.Dim(0.4, 0.8)
	end
	VFX.Pose(char, "PunchL", 0.8)
	local glow = newPart(Vector3.one * 0.4, CFrame.new(handPos(char, false)), PAL.PHOSPHOR_CORE, Enum.Material.Neon, Enum.PartType.Ball)
	tween(glow, 0.3, { Size = Vector3.one * 3 })
	cleanup(glow, 0.32)
	local t0 = os.clock()
	while os.clock() - t0 < 0.3 and root.Parent do
		local hand = handPos(char, false)
		glow.CFrame = CFrame.new(hand)
		shockDisc(hand, dir, 7, 1, 0.12, PAL.PHOSPHOR_GLOW)
		sparks(hand, 0.4, PAL.PHOSPHOR_CORE, PAL.PHOSPHOR_GLOW, 5)
		task.wait(0.05)
	end
	if not root.Parent then
		return
	end
	local from = handPos(char, false) + dir
	local to = from + dir * 110
	beam(from, to, 2.2, PAL.PHOSPHOR_CORE, PAL.PHOSPHOR_GLOW, 0.5)
	beam(from, to, 3.4, FIRE[2], FIRE[4], 0.4)
	for i = 1, 9 do
		local p = from + dir * (i * 12)
		task.delay(i * 0.012, function()
			Flame.burst(p, rand(4, 6), 8)
		end)
	end
	for i = 1, 6 do
		task.delay(i * 0.02, function()
			shockDisc(from + dir * (i * 16), dir, 9, 3, 0.25, PAL.PHOSPHOR_GLOW)
		end)
	end
	local hitPos = firstHit(from, dir, 110)
	if hitPos then
		toonExplosion(hitPos, 1.8)
	end
	if nearCamera(from, 60) then
		VFX.Hooks.Flash(Color3.fromRGB(235, 230, 255), 0.25)
	end
	VFX.PlaySound("Fire", from, 1.2)
	VFX.ShakeAt(from, 2.2, 120, 0.4)
end

function Effects.GlacialField(char, data, isLocal, ability)
	local root = charParts(char)
	if not root then
		return
	end
	if isLocal then
		VFX.Hooks.Dim(0.35, 0.7)
	end
	VFX.Pose(char, "Ground", 0.8)
	task.wait(0.2)
	if not root.Parent then
		return
	end
	local g = groundPoint(root.Position)
	-- (round 81) ice floods the ground in a huge circle (the sheet: solid Ice,
	-- with ragged frost crust past its rim - the see-through Glass floor that
	-- fought it for the same plane is gone), clusters of crystals erupt
	-- across it in a wave out from him, cold mist rolls out over it and the
	-- air goes cold
	local model = spikeLayout("GlacialField", data, root, flatten(data.Dir, root))
	IceKit.particles(g + UP * 0.5, "puff", 16, 2.4)
	for r = 10, 40, 10 do
		task.delay(r / 90, function()
			local a0 = rand(0, math.pi * 2)
			for i = 1, 3 do
				local a = a0 + i / 3 * math.pi * 2
				frostMist(g + Vector3.new(math.cos(a) * r, 1, math.sin(a) * r), 1.6, 3)
			end
		end)
	end
	shockDisc(g + UP * 0.5, UP, 6, 86, 0.5, ICE_TIP)
	shockDisc(g + UP * 1.5, UP, 4, 60, 0.7, IceKit.PAL.MIST2)
	sparks(g + UP * 2, 2.5, ICE_TIP, Color3.fromRGB(120, 200, 255), 70)
	IceKit.light(g + UP * 8, 50, 1.6, (ability and ability.IceDuration) or 5)
	IceKit.snow(CFrame.new(g + UP * 30), Vector3.new(70, 2, 70), (ability and ability.IceDuration) or 5, 40, 1.4)
	if nearCamera(g, 80) then
		IceKit.coldTint(0.9, 0.6, 2.2)
	end
	VFX.PlaySound("Ice", g, 1.2)
	VFX.PlaySound("IceRumble", g, 1)
	VFX.ShakeAt(g, 2.8, 160, 0.5)
	task.wait((ability and ability.IceDuration) or 5)
	shatter(model, 120, { from = g })
end

function Effects.HeatwaveMax(char, data, isLocal, ability)
	cinematicFor(char, "HeatwaveMax", isLocal, ability and ability.Name or "FLASHFREEZE HEATWAVE", Color3.fromRGB(255, 150, 90))
