-- (round 68) winded: doubled over a punch to the stomach - bent in half,
-- both arms clutched round the middle, the knees gone soft
POSES.Winded = {
	Hips = { 0, 0, 0, 0, -0.35, 0.3 },
	Waist = { -48, 0, 4 }, Neck = { -6, 0, -6 },
	RightArm = { 34, 0, -28 }, RightElbow = 100, LeftArm = { 40, 0, -26 }, LeftElbow = 104,
	RightLeg = 20, LeftLeg = 6, RightKnee = 34, LeftKnee = 26,
