---------------------------------------------------------------------------
-- Persistent auras (every client draws them for everyone): Full Cowl's green
-- lightning crawling over the whole body, and Infinity's shimmer
---------------------------------------------------------------------------

local COWL_LIMBS = {
	"UpperTorso", "LowerTorso", "Head", "RightUpperArm", "RightLowerArm", "RightHand", "LeftUpperArm", "LeftLowerArm", "LeftHand",
	"RightUpperLeg", "RightLowerLeg", "RightFoot", "LeftUpperLeg", "LeftLowerLeg", "LeftFoot",
	"Torso", "Right Arm", "Left Arm", "Right Leg", "Left Leg",
}
local SEG_POOL = 48
local auraState = setmetatable({}, { __mode = "k" }) -- [character] = pooled segments + timers

-- 0 = off, 1 = Full Cowl (always on for the 9th holder), 2 = Full Cowl
-- 100% (the ult)
local function cowlLevel(char)
	if char:GetAttribute("Quirk") ~= "FullCowl" then
		return 0
	end
	return char:GetAttribute("UltActive") and 2 or 1
end
VFX.CowlLevel = cowlLevel

local function auraOf(char)
	local st = auraState[char]
	if not st then
		st = { segs = {}, hideAt = {}, idx = 0, nextArc = 0, nextSpark = 0, limbs = nil, limbsAt = 0 }
		auraState[char] = st
	end
	return st
end

local function freeAura(char, st)
	for _, seg in st.segs do
		pcall(seg.Destroy, seg)
	end
	if st.shell then
		pcall(st.shell.Destroy, st.shell)
	end
	auraState[char] = nil
end

-- a character that was destroyed (or left) - never touch it again
local function gone(inst)
	local ok, parent = pcall(function()
		return inst.Parent
	end)
	return not ok or parent == nil
end

local function takeSeg(st)
	st.idx = st.idx % SEG_POOL + 1
	local seg = st.segs[st.idx]
	if not seg or not seg.Parent then
		seg = newPart(Vector3.new(0.12, 0.12, 1), CFrame.new(), COWL_GREEN, Enum.Material.Neon)
		seg.Transparency = 1
		st.segs[st.idx] = seg
	end
	return seg, st.idx
end

-- one jagged arc skittering around a limb's surface
local function cowlArc(st, part, now, full)
	local s = part.Size
	local rx, rz = s.X / 2 + 0.06, s.Z / 2 + 0.06
	local a = rand(0, math.pi * 2)
	local y = rand(-0.5, 0.5) * s.Y
	local prev = (part.CFrame * CFrame.new(math.cos(a) * rx, y, math.sin(a) * rz)).Position
	local life = rand(0.04, 0.08)
	for _ = 1, full and 4 or 3 do
		a += rand(-1.1, 1.1)
		y = math.clamp(y + rand(-0.35, 0.35) * s.Y, -s.Y * 0.6, s.Y * 0.6)
		local out = full and rand(0, 0.6) or rand(0, 0.2) -- at 100% the arcs leap off the body
		local nxt = (part.CFrame * CFrame.new(math.cos(a) * (rx + out), y, math.sin(a) * (rz + out))).Position
		local len = (nxt - prev).Magnitude
		if len > 0.05 then
			local seg, i = takeSeg(st)
			local thick = full and 0.12 or 0.065
			seg.Size = Vector3.new(thick, thick, len + 0.1)
			seg.CFrame = CFrame.lookAt((prev + nxt) / 2, nxt)
			seg.Color = rng:NextNumber() < 0.3 and COWL_CORE or COWL_GREEN
			seg.Transparency = 0
			st.hideAt[i] = now + life
		end
		prev = nxt
	end
end

-- Unlimited Void: tint the view while the camera is inside a domain
local Lighting = game:GetService("Lighting")
local activeDomains = {} -- [character] = { Center, Radius, Model }
local voidTint
local function updateVoidView()
	local cam = workspace.CurrentCamera
	local inside = false
	if cam then
		for _, d in activeDomains do
			if (cam.CFrame.Position - d.Center).Magnitude < d.Radius then
				inside = true
			end
		end
	end
	if inside and not voidTint then
		voidTint = Instance.new("ColorCorrectionEffect")
		voidTint.Name = "UnlimitedVoid"
		voidTint.TintColor = Color3.fromRGB(205, 195, 255)
		voidTint.Brightness = -0.12
		voidTint.Contrast = 0.3
		voidTint.Saturation = -0.4
		voidTint.Parent = Lighting
	elseif not inside and voidTint then
		voidTint:Destroy()
		voidTint = nil
	end
end

local lastVoidCheck = 0
RunService.Heartbeat:Connect(function()
	local now = os.clock()
	for char, st in auraState do
		if gone(char) then
			freeAura(char, st)
			continue
		end
		for i, t in st.hideAt do
			if now >= t then
				local seg = st.segs[i]
				if seg and not gone(seg) then
					seg.Transparency = 1
				end
				st.hideAt[i] = nil
			end
		end
	end
	local cam = workspace.CurrentCamera
	for _, plr in Players:GetPlayers() do
		local char = plr.Character
		if not char or gone(char) then
			continue
		end
		local root = char:FindFirstChild("HumanoidRootPart")
		if not root then
			continue
		end
		local level = cowlLevel(char)
		local infinity = char:GetAttribute("Infinity") == true
		local st = auraState[char]
		local far = cam and (cam.CFrame.Position - root.Position).Magnitude > 320
		if (level == 0 and not infinity) or far then
			if st then
				freeAura(char, st)
			end
			continue
		end
		st = auraOf(char)
		if level > 0 and now >= st.nextArc then
			st.nextArc = now + (level == 2 and 0.045 or 0.09)
			if not st.limbs or now - st.limbsAt > 1 then
				st.limbs = {}
				st.limbsAt = now
				for _, name in COWL_LIMBS do
					local part = char:FindFirstChild(name)
					if part and part:IsA("BasePart") then
						table.insert(st.limbs, part)
					end
				end
			end
			if #st.limbs > 0 then
				for _ = 1, level == 2 and 2 or 1 do
					local part = st.limbs[rng:NextInteger(1, #st.limbs)]
					if part.Parent then
						cowlArc(st, part, now, level == 2)
					end
				end
			end
			if now >= st.nextSpark then
				st.nextSpark = now + rand(0.45, 0.7) / level
				sparks(root.Position + rng:NextUnitVector() * 1.5, 0.25, COWL_CORE, COWL_GREEN, 4)
				if level == 2 then
					bolt(root.Position + rng:NextUnitVector() * 1.2, 3, COWL_GREEN)
				end
			end
		end
		if infinity then
			if not st.shell or not st.shell.Parent then
				st.shell = newPart(Vector3.one * 8, root.CFrame, PAL.BLUE_CORE, Enum.Material.ForceField, Enum.PartType.Ball)
			end
			st.shell.CFrame = root.CFrame
			st.shell.Transparency = 0.55 + 0.2 * math.sin(now * 5)
		elseif st.shell then
			st.shell:Destroy()
			st.shell = nil
		end
	end
	if now - lastVoidCheck > 0.2 then
		lastVoidCheck = now
		updateVoidView()
	end
end)

-- A living black tendril (Blackwhip), redrawn every frame between two moving
-- points: it lashes out first, then follows whoever it has hold of
local function tendril(fromFn, toFn, duration, opts)
	opts = opts or {}
	local model
	if opts.Outline == false then
		model = Instance.new("Model")
		model.Name = "Tendril"
		model.Parent = folder
	else
		model = outlineModel(opts.OutlineColor or WHIP_GLOW)
	end
	local n = opts.Segments or 10
	local thick = opts.Thick or 0.42
	local segs = {}
	for i = 1, n do
		segs[i] = newPart(Vector3.new(thick, thick, 1), CFrame.new(), opts.Color or WHIP_DARK, Enum.Material.SmoothPlastic, nil, model)
	end
	local phase = rand(0, math.pi * 2)
	local amp = opts.Wave or 1.2
	local grow = opts.Grow or 0.12
	local side = rng:NextUnitVector()
	local t0 = os.clock()
	task.spawn(function()
		while os.clock() - t0 < duration do
			local a, b = fromFn(), toFn()
			if not a or not b then
				break
			end
			local t = os.clock() - t0
			local reach = math.clamp(t / grow, 0, 1)
			local fade = math.clamp((duration - t) / 0.15, 0, 1)
			local d = b - a
			if d.Magnitude > 0.1 then
				local dirU = d.Unit
				local perp = dirU:Cross(side)
				if perp.Magnitude < 0.1 then
					perp = dirU:Cross(UP)
				end
				perp = perp.Magnitude > 0.01 and perp.Unit or Vector3.new(1, 0, 0)
				local perp2 = dirU:Cross(perp)
				local prev = a
				for i = 1, n do
					local s = i / n * reach
					local w = math.sin(s * math.pi) * amp * fade
					local p = a + d * s + perp * math.sin(s * 9 + phase + t * 14) * w + perp2 * math.cos(s * 7 + phase + t * 11) * w * 0.6
					local len = (p - prev).Magnitude
					local k = thick * (1 - 0.45 * i / n)
					if len > 0.01 then
						segs[i].Size = Vector3.new(k, k, len + 0.12)
						segs[i].CFrame = CFrame.lookAt((prev + p) / 2, p)
					end
					prev = p
				end
			end
			task.wait(1 / 60)
		end
		model:Destroy()
	end)
	return model
end

-- (round 75) Deku's BLACKWHIP, done properly: not a chain of square sticks
-- but a braid - a black core with three strands twisting round it, round
-- in section, thick at his forearm and tapering to a point, a dark-green
-- rim (the Highlight) and a spark of One For All at the tip. It lashes out,
-- then pulls taut on whatever it has hold of. Same arguments as tendril.
function VFX.whipRope(fromFn, toFn, duration, opts)
	opts = opts or {}
	local model = outlineModel(opts.OutlineColor or WHIP_GLOW)
	model.Name = "Blackwhip"
	local n = math.clamp((opts.Segments or 14) + 6, 14, 26)
	local strands = opts.Strands or 3
	local thick = (opts.Thick or 0.3) * 1.25
	local core = Color3.fromRGB(10, 13, 12)
	local tone = opts.Color or Color3.fromRGB(16, 42, 34)
	local chains = {}
	for k = 0, strands do
		local list = {}
		for i = 1, n do
			list[i] = newPart(Vector3.new(1, 0.2, 0.2), CFrame.new(), k == 0 and core or tone, Enum.Material.SmoothPlastic, Enum.PartType.Cylinder, model)
		end
		chains[k] = list
	end
	local tip = newPart(Vector3.one * 0.4, CFrame.new(), opts.TipColor or Color3.fromRGB(110, 255, 190), Enum.Material.Neon, Enum.PartType.Ball, model)
	tip.Transparency = 0.2
	local phase = rand(0, math.pi * 2)
	local amp = opts.Wave or 0.8
	local grow = opts.Grow or 0.1
	local side = rng:NextUnitVector()
	local t0 = os.clock()
	local AXIS = CFrame.Angles(0, math.rad(90), 0) -- (a cylinder runs along X)
	task.spawn(function()
		local centre = {}
		while os.clock() - t0 < duration do
			local a, b = fromFn(), toFn()
			if not a or not b then
				break
			end
			local t = os.clock() - t0
			local reach = math.clamp(t / grow, 0, 1)
			local fade = math.clamp((duration - t) / 0.15, 0, 1)
			local span = b - a
			if span.Magnitude > 0.1 then
				local dirU = span.Unit
				local perp = dirU:Cross(side)
				if perp.Magnitude < 0.1 then
					perp = dirU:Cross(UP)
				end
				perp = perp.Magnitude > 0.01 and perp.Unit or Vector3.new(1, 0, 0)
				local perp2 = dirU:Cross(perp)
				-- the centre line: a lazy S that pulls taut as it fades
				for i = 0, n do
					local s = i / n * reach
					local w = math.sin(s * math.pi) * amp * fade
					centre[i] = a + span * s + perp * math.sin(s * 6 + phase + t * 9) * w + perp2 * math.cos(s * 5 + phase + t * 7) * w * 0.5
				end
				for k = 0, strands do
					local list = chains[k]
					local prev
					for i = 0, n do
						local s = i / n
						local taper = 1 - 0.75 * s
						local p = centre[i]
						if k > 0 then
							-- the strands twist round the core
							local ang = phase + k / strands * math.pi * 2 + s * 14 + t * 10
							p += (perp * math.cos(ang) + perp2 * math.sin(ang)) * thick * 0.42 * taper
						end
						if i > 0 then
							local seg = list[i]
							local len = (p - prev).Magnitude
							local w = thick * (k == 0 and 0.62 or 0.4) * taper
							if len > 0.01 then
								seg.Size = Vector3.new(len + w * 0.8, w, w)
								seg.CFrame = CFrame.lookAt((prev + p) / 2, p) * AXIS
							end
						end
						prev = p
					end
				end
				tip.CFrame = CFrame.new(centre[n])
				tip.Size = Vector3.one * thick * (0.45 + 0.2 * math.sin(t * 30))
			end
			task.wait(1 / 60)
		end
		model:Destroy()
	end)
	return model
end

-- (round 75) the BLACKWHIP SLINGSHOT (Deku: dash, then Blackwhip): a whip
-- from each forearm shoots out ahead and bites into whatever's there (a
-- wall, the street far ahead), they stretch - and the tension throws him
-- down them. (His own machine flies him: the client's WhipDash.)
function Effects.WhipDash(char, data, isLocal)
	local root = charParts(char)
	if not root then
		return
	end
	local d = (typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.01) and data.Dir.Unit or root.CFrame.LookVector
	local time = tonumber(data.Time) or 0.5
	local speed = tonumber(data.Speed) or 165
	local from = root.Position
	rayParams.FilterDescendantsInstances = characterList()
	local reach = speed * time + 14
	local hit = workspace:Raycast(from + UP, d * reach, rayParams)
	local anchor = hit and hit.Position or groundPoint(from + d * reach)
	VFX.Pose(char, "WhipCast", time + 0.1)
	VFX.PlaySound("Blackwhip", from, 1)
	if isLocal then
		VFX.Hooks.SpeedLines(time)
	end
	local t0 = os.clock()
	local flatD = flatten(d, root)
	for k = -1, 1, 2 do
		local spot = anchor + flatD:Cross(UP) * k * 1.8 + UP * rand(-0.4, 0.9)
		VFX.whipRope(function()
			return root.Parent and handPos(char, k > 0) or nil
		end, function()
			return from:Lerp(spot, math.clamp((os.clock() - t0) / 0.12, 0, 1))
		end, time + 0.08, { Wave = 0.45, Grow = 0.02, Thick = 0.3, Segments = 16, OutlineColor = Color3.fromRGB(80, 230, 160) })
	end
	-- where they bite in
	task.delay(0.12, function()
		sparks(anchor, 0.8, COWL_CORE, COWL_GREEN, 12)
		shockDisc(anchor, -d, 1, 8, 0.25, COWL_GREEN)
		bolt(anchor, 2.5, COWL_GREEN)
	end)
	task.wait(0.08)
	if not root.Parent then
		return
	end
	-- the yank
	shockDisc(root.Position, d, 2, 16, 0.25, COWL_GREEN, 3)
	billboardRing(root.Position, 2, 12, COWL_CORE, 4, 0.2)
	VFX.PlaySound("Launch", root.Position, 0.9)
	local stopTrail = addTrail(root, COWL_GREEN, 0.3, 2)
	local t1 = os.clock()
	while os.clock() - t1 < time and root.Parent do
		afterimage(char, COWL_GREEN, 0.2)
		streaks(root.Position, -d, 2, 2, 6, 12, WIND, 0.18)
		if rng:NextNumber() < 0.6 then
			bolt(root.Position, 2.2, COWL_GREEN)
		end
		task.wait(0.05)
	end
	stopTrail(0)
end

-- Ride a parabola to `target` (only the caster's own client: it owns the physics)
local function flyArc(root, from, target, height, travel)
	local char = root.Parent
	local hum = char and char:FindFirstChildOfClass("Humanoid")
	local dest = target + UP * 3
	local att = Instance.new("Attachment")
	att.Name = "ManchesterTravel"
	att.Parent = root
	local lv = Instance.new("LinearVelocity")
	lv.Attachment0 = att
	lv.MaxForce = moverForce(root, 20000)
	lv.RelativeTo = Enum.ActuatorRelativeTo.World
	lv.Parent = root
	cleanup(lv, travel + 0.15)
	cleanup(att, travel + 0.15)
	local t0 = os.clock()
	local landed = false
	while root.Parent and char.Parent and (not hum or hum.Health > 0) do
		if char:GetAttribute("Stunned") or char:GetAttribute("Ragdolled") or char:GetAttribute("Grabbed") then
			break
		end
		local t = os.clock() - t0
		local s = math.clamp(t / travel, 0, 1)
		local p1 = arcPosition(from, dest, height, s)
		local p2 = arcPosition(from, dest, height, math.clamp((t + 1 / 60) / travel, 0, 1))
		lv.VectorVelocity = (p2 - p1) * 60 + (p1 - root.Position) * 10
		if s >= 1 then
			landed = true
			break
		end
		RunService.Heartbeat:Wait()
	end
	lv:Destroy()
	att:Destroy()
	if landed and root.Parent then
		local v = root.AssemblyLinearVelocity
		root.AssemblyLinearVelocity = Vector3.new(v.X * 0.12, math.max(v.Y, -22), v.Z * 0.12)
	end
	return landed
end

-- green lightning bursting off a point for a while
local function cowlBurst(center, radius, duration, rate)
	task.spawn(function()
		local t0 = os.clock()
		while os.clock() - t0 < duration do
			for _ = 1, rate or 2 do
				bolt(center, radius, rng:NextNumber() < 0.3 and COWL_CORE or COWL_GREEN)
			end
			task.wait(0.03)
		end
	end)
end

---------------------------------------------------------------------------
-- ONE FOR ALL: 9TH (Deku)
---------------------------------------------------------------------------

do -- Deku presentation: short motions, white pressure, mint edge, readable silhouettes.
local MINT = Color3.fromRGB(154, 245, 206)
local WHITE = Color3.fromRGB(246, 255, 252)
local TEAL = Color3.fromRGB(14, 57, 54)
local POWER = Color3.fromRGB(66, 239, 165)

local function active(char)
	local root, hum = charParts(char)
	return root and (not hum or hum.Health > 0) and not char:GetAttribute("Stunned") and not char:GetAttribute("Ragdolled") and not char:GetAttribute("Grabbed")
end

-- Thin tapered curves describe the force; they never obscure the fighters.
local function curveStroke(points, width, color, life, parent)
	local model = Instance.new("Model")
	model.Name = "CowlPressureArc"
	model.Parent = parent or folder
	for i = 1, #points - 1 do
		local a, b = points[i], points[i + 1]
		local delta = b - a
		if delta.Magnitude > 0.01 then
			local taper = math.sin(math.pi * (i - 0.5) / (#points - 1))
			local thick = math.max(0.025, width * taper)
			local seg = newPart(Vector3.new(thick, thick, delta.Magnitude + 0.03), CFrame.lookAt((a + b) / 2, b), color, Enum.Material.Neon, nil, model)
			seg.Transparency = 0.18
			tween(seg, life, { Transparency = 1, Size = Vector3.new(0.015, 0.015, seg.Size.Z) })
		end
	end
	cleanup(model, life + 0.04)
	return model
end

local function heelArc(root, d, radius, roll, color, parent)
	local basis = CFrame.lookAt(root.Position + UP * 0.15, root.Position + UP * 0.15 + d) * CFrame.Angles(0, 0, roll)
	local points = {}
	for i = 0, 14 do
		local angle = math.rad(-72 + 152 * i / 14)
		table.insert(points, basis:PointToWorldSpace(Vector3.new(math.sin(angle) * radius, math.cos(angle) * radius * 0.22, -math.cos(angle) * radius)))
	end
	curveStroke(points, 0.28, color, 0.18, parent)
end

local function briefTrail(part, duration, color, width, life)
	if not part then return function() end end
	local stop = addTrail(part, color, life or 0.12, width or 0.45)
	stop(duration)
	return stop
end

local function contact(pos, dir, strong)
	shockDisc(pos, dir, 0.6, strong and 10 or 5.5, strong and 0.2 or 0.14, WHITE)
	sparks(pos, strong and 0.44 or 0.23, WHITE, MINT, strong and 10 or 5)
	streaks(pos, dir, strong and 6 or 3, 0.4, strong and 3.5 or 2, strong and 7 or 4, WHITE, 0.15)
end

-- DELAWARE SMASH: AIR FORCE: side-on and low, flick after flick from
-- alternate hands, each one a bullet of compressed air - a rippling ball of
-- pressure shedding rings as it goes - the last one bigger, blowing them away
function Effects.DelawareSmash(char, data, isLocal, ability)
	local root = charParts(char)
	if not root then return end
	local d = aimDir(data, root)
	if isLocal then face(root, d) end
	local shots = (ability and ability.Shots) or 1
	local gap = (ability and ability.Gap) or 0.13
	local length = data.Air and 80 or ((ability and ability.Range) or 110)
	task.wait(0.07)
	for i = 1, shots do
		if not active(char) then return end
		local right = i % 2 == 1
		local last = i == shots
		VFX.Motion(char, right and "AirForceR" or "AirForceL")
		task.wait(0.05)
		local from = handPos(char, right) + d * 0.6
		local hit = firstHit(from, d, length)
		local to = hit or (from + d * length)
		local travel = math.max(0.03, (to - from).Magnitude / 420)
		local size = last and 2.6 or 1.7
		local ball = newPart(Vector3.one * size, CFrame.lookAt(from, from + d), WHITE, Enum.Material.ForceField, Enum.PartType.Ball)
		ball.Name = "DelawarePressure"
		ball.Transparency = 0.1
		local core = newPart(Vector3.one * size * 0.45, CFrame.new(from), WHITE, Enum.Material.Neon, Enum.PartType.Ball)
		core.Transparency = 0.35
		local stop = briefTrail(ball, travel, MINT, size * 0.5, 0.12)
		shockDisc(from, d, 0.5, last and 7 or 4.5, 0.14, WHITE)
		billboardRing(from, 0.6, last and 6 or 4, MINT, 3, 0.14)
		sparks(from, 0.3, WHITE, COWL_GREEN, 6)
		VFX.PlaySound("AirBullet", from, last and 1.4 or 1.1)
		if isLocal and data.Air then dash(root, -d * 10 + UP * 5, 0.06) end
		tween(ball, travel, { CFrame = CFrame.lookAt(to, to + d) }, Enum.EasingStyle.Linear)
		tween(core, travel, { CFrame = CFrame.new(to) }, Enum.EasingStyle.Linear)
		-- rings of pressure peeling off it as it goes
		for k = 1, math.min(6, math.floor((to - from).Magnitude / 12)) do
			task.delay(travel * k / 7, shockDisc, from:Lerp(to, k / 7), d, size * 0.8, size * 2.4, 0.18, WHITE)
		end
		cleanup(ball, travel + 0.1)
		cleanup(core, travel + 0.1)
		task.delay(travel, function()
			ball.Transparency = 1
			core.Transparency = 1
			stop(0)
			shockDisc(to, -d, 1, hit and (last and 16 or 9) or 5, 0.22, WHITE)
			if hit then
				billboardRing(to, 1, last and 18 or 10, WHITE, 5, 0.2)
			end
		end)
		if not last then
			task.wait(math.max(gap - 0.05, 0))
		end
	end
end

-- (the server's word that an air bullet landed)
function Effects.AirForceHit(_, data)
	local pos = typeof(data.Pos) == "Vector3" and data.Pos
	if not pos then return end
	local d = typeof(data.Dir) == "Vector3" and data.Dir or UP
	contact(pos, -d, data.Last == true)
	if data.Last then
		billboardRing(pos, 2, 24, WHITE, 7, 0.25)
		streaks(pos, d, 10, 0.4, 5, 16, WHITE, 0.25)
		VFX.PlaySound("DetroitImpact", pos, 0.8)
		VFX.ShakeAt(pos, 1.2, 60, 0.2)
	else
		VFX.PlaySound("Hit", pos, 0.8)
	end
end

function Effects.Blackwhip(char, data, isLocal, ability)
	local root = charParts(char)
	if not root then return end
	local d = aimDir(data, root)
	if isLocal then face(root, d) end
	VFX.Motion(char, "WhipCast")
	task.wait(0.12)
	if not active(char) then return end
	local from = handPos(char, true)
	local length = (ability and ability.Range) or 60
	local hit = firstHit(from, d, length)
	local reach = hit and (hit - from).Magnitude or length
	local t0 = os.clock()
	VFX.PlaySound("Blackwhip", from, 0.85)
	VFX.whipRope(function()
		return active(char) and handPos(char, true) or nil
	end, function()
		local t = os.clock() - t0
		local s = t < 0.12 and t / 0.12 or math.max(0, 1 - (t - 0.15) / 0.14)
		return from + d * reach * s
	end, 0.3, { Wave = 0.6, Grow = 0.015, Thick = 0.36, Segments = 16, Color = TEAL, OutlineColor = MINT })
end

function Effects.BlackwhipCatch(char, data)
	local target = typeof(data.Target) == "Instance" and data.Target
	local troot = target and target:FindFirstChild("HumanoidRootPart")
	if not char or not troot then return end
	local duration = data.Duration or 0.32
	VFX.Pose(char, "WhipCast", duration)
	VFX.whipRope(function()
		return active(char) and handPos(char, true) or nil
	end, function()
		return troot.Parent and troot.Position + UP * 0.35 or nil
	end, duration, { Wave = 0.35, Grow = 0.025, Thick = 0.25, Segments = 14, Color = TEAL, OutlineColor = MINT })
	local delta = char:GetPivot().Position - troot.Position
	contact(troot.Position + UP * 0.4, delta.Magnitude > 0.01 and delta.Unit or UP, false)
	VFX.PlaySound("Hit", troot.Position, 0.55)
end

-- Deku's R: the next quirk into his 4th slot (a crackle in its colour)
local PICK_COLORS = { Blackwhip = Color3.fromRGB(20, 30, 24), Smokescreen = SMOKE_GREY, Float = Color3.new(1, 1, 1), FaJinSmash = Color3.fromRGB(255, 70, 60), Gearshift = Color3.fromRGB(140, 255, 214) }
function Effects.QuirkCycle(char)
	local root = charParts(char)
	if not root then return end
	local quirk = Config.Quirks[char:GetAttribute("Quirk") or ""]
	local owner = Players:GetPlayerFromCharacter(char)
	local picked = quirk and owner and Config.PickedExtra(quirk, owner:GetAttribute("QuirkPick"))
	local color = picked and PICK_COLORS[picked.Id] or MINT
	VFX.Pose(char, "CycleFist", 0.3) -- (a fist clenched: the next quirk answering)
	sparks(handPos(char, true), 0.22, WHITE, color, 6)
	VFX.PlaySound("Spark", root.Position, 0.5)
end

function Effects.Smokescreen(char, _data, isLocal, ability)
	local root = charParts(char)
	if not root then
		return
	end
	local radius = (ability and ability.Radius) or 24
	local duration = (ability and ability.Duration) or 5
	local pos = root.Position
	VFX.Pose(char, "Clap", 0.3)
	smokeBurst(pos, SMOKE_GREY, 14, radius, duration, 70)
	smokeBurst(pos + UP * 4, SMOKE_DEEP, 10, radius * 0.8, duration * 0.8, 40)
	for i = 1, 12 do
		local a = i / 12 * math.pi * 2
		local out = Vector3.new(math.cos(a), 0, math.sin(a))
		celPuff(folder, pos, pos + out * radius * rand(0.5, 0.9) + UP * rand(1, 6), rand(6, 10), SMOKE_DEEP, Color3.fromRGB(196, 160, 236), 0.25, 1.4, i * 0.01)
	end
	if not isLocal then
		afterimage(char, SMOKE_GREY, 0.3)
		hideCharacter(char, 0.8) -- he vanishes into it
	end
	VFX.PlaySound("Smokescreen", pos, 1)
end

-- Server: you're choking in a smokescreen
function Effects.Smoked(_, data)
	VFX.Hooks.Flash(SMOKE_GREY, data.Duration or 2)
	VFX.Hooks.Dim(0.5, data.Duration or 2)
end

-- ST. LOUIS SMASH: AIR FORCE: he coils, spins right round on one foot and
-- the kick comes round the front - and out of it flies a blade of
-- compressed air, a white crescent skimming down the street, tearing it up
function Effects.StLouisSmash(char, data, isLocal, ability)
	local root = charParts(char)
	if not root then return end
	local a = Config.AimedDirection(data.Dir, root.CFrame.LookVector, ability and ability.Aim)
	local d = flatten(a, root)
	if isLocal then
		face(root, d)
		dash(root, d * 30, 0.16)
	end
	VFX.Motion(char, "StLouis")
	local foot = limb(char, "RightFoot", "Right Leg")
	briefTrail(foot, 0.36, MINT, 0.7, 0.14)
	briefTrail(foot, 0.36, WHITE, 0.3, 0.1)
	VFX.PlaySound("Swish", root.Position, 1)
	task.wait(0.18)
	if not active(char) then return end
	shockDisc(root.Position - UP * 1.5, UP, 3, 16, 0.25, WHITE)
	heelArc(root, d, 5.2, math.rad(13), WHITE)
	heelArc(root, d, 4.8, math.rad(13), MINT)
	VFX.PlaySound("Kick", root.Position + d * 3, 1.1)
	local range = (ability and ability.Range) or 45
	if range <= 16 then return end
	local width = (ability and ability.BladeWidth) or 16
	local from = root.Position + d * 3
	local right = d:Cross(UP).Unit
	local blade = {}
	for k = -5, 5 do
		local f = k / 5
		local seg = newPart(Vector3.new(0.35, 0.4 + (1 - math.abs(f)) * 0.9, width / 10 + 0.4), CFrame.new(from), k % 2 == 0 and WHITE or MINT, Enum.Material.Neon)
		seg.Transparency = 0.1
		table.insert(blade, { part = seg, f = f })
	end
	local travel = range / 150
	local t0 = os.clock()
	VFX.PlaySound("Wind", from, 1)
	local conn
	conn = RunService.RenderStepped:Connect(function()
		local u = math.clamp((os.clock() - t0) / travel, 0, 1)
		local center = from + a * range * u
		for _, e in blade do
			-- (the crescent bows forward in the middle)
			local p = center + right * e.f * width * 0.5 + d * (1 - e.f * e.f) * width * 0.25
			e.part.CFrame = CFrame.lookAt(p, p + right)
			e.part.Transparency = 0.1 + 0.8 * u ^ 3
		end
		if u >= 1 then
			conn:Disconnect()
			for _, e in blade do
				e.part:Destroy()
			end
		end
	end)
	for k = 1, 6 do
		task.delay(travel * k / 6, function()
			local p = from + a * range * k / 6
			local g = groundPoint(p)
			if (g - p).Magnitude < 8 then
				dustPuffs(g, 0.5, 2, Color3.fromRGB(206, 200, 190), 0.5, false)
				groundMark(g, 1.5, Color3.fromRGB(70, 66, 60), 2)
			end
			streaks(p, a, 3, 0.3, 4, 8, WHITE, 0.15)
		end)
	end
end

function Effects.CowlKickHit(_, data)
	local pos = typeof(data.Pos) == "Vector3" and data.Pos
	if not pos then return end
	local d = typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.01 and data.Dir.Unit or UP
	contact(pos, d, true)
	VFX.PlaySound("Hit", pos, 0.8)
	VFX.ShakeAt(pos, 0.65, 35, 0.12)
end

function Effects.ManchesterSmash(char, data, isLocal, ability)
	local root = charParts(char)
	if not root then return end
	local travel = (ability and ability.TravelTime) or 0.46
	local height = (ability and ability.Height) or 16
	local target = aimGround(root, data, (ability and ability.Range) or 38)
	local d = flatten(target - root.Position, root)
	local from = root.Position
	VFX.Motion(char, "Manchester")
	local g = groundPoint(from)
	shockDisc(g + UP * 0.2, UP, 2, 12, 0.3, WHITE)
	dustPuffs(g, 0.7, 4, Color3.fromRGB(200, 200, 192), 0.55, false)
	VFX.PlaySound("Leap", g, 0.9)
	local stops = {}
	for _, name in { { "RightFoot", "Right Leg" }, { "LeftFoot", "Left Leg" } } do
		table.insert(stops, briefTrail(limb(char, name[1], name[2]), travel, WHITE, 0.65, 0.16))
	end
	-- the somersault's wind wheeling round him
	for k = 1, 3 do
		task.delay(travel * (0.15 + k * 0.15), function()
			if active(char) then heelArc(root, d, 3.2, math.rad(90), k % 2 == 0 and WHITE or MINT) end
		end)
	end
	task.delay(travel * 0.72, function()
		if active(char) then
			heelArc(root, d, 4.2, math.rad(90), WHITE)
			VFX.PlaySound("Swish", root.Position, 1)
		end
	end)
	if isLocal then
		face(root, d)
		local ring = shockDisc(target + UP * 0.08, UP, 24, 24, travel, MINT)
		ring.Transparency = 0.78
		flyArc(root, from, target, height, travel)
		if ring.Parent then ring:Destroy() end
	else
		task.wait(travel)
	end
	for _, stop in stops do
		stop(0)
	end
end

-- the axe kick lands: a crater, the street heaving up round it, and a
-- shockwave rolling out past it
function Effects.ManchesterLand(_, data)
	local pos = typeof(data.Pos) == "Vector3" and data.Pos
	if not pos then return end
	local R = tonumber(data.Radius) or 12
	local S = tonumber(data.Shock) or R * 1.8
	shockDisc(pos + UP * 0.18, UP, 2, R * 2.4, 0.3, WHITE)
	shockDisc(pos + UP * 0.25, UP, 1, R * 1.6, 0.22, MINT)
	shockDisc(pos + UP * 0.3, UP, R, S * 2.2, 0.45, WHITE)
	billboardRing(pos + UP, 3, R * 2.6, WHITE, 8, 0.3)
	streaks(pos + UP * 2.5, -UP, 6, 0.4, 3, 5, WHITE, 0.16)
	for i = 1, 10 do
		local ang = i / 10 * math.pi * 2 + rand(-0.2, 0.2)
		local out = Vector3.new(math.cos(ang), 0, math.sin(ang))
		local at = pos + out * R * rand(0.7, 0.95) + UP * 0.4
		local slab = newPart(Vector3.new(rand(3, 5), rand(0.8, 1.4), rand(3, 5)), CFrame.lookAt(at, at + out) * CFrame.Angles(math.rad(rand(25, 45)), 0, 0), Color3.fromRGB(96, 96, 100), Enum.Material.Slate)
		tween(slab, 0.5, { Transparency = 1 }, nil, nil, 2.2)
		cleanup(slab, 2.8)
	end
	dustPuffs(pos, 1.4, 8, Color3.fromRGB(202, 202, 191), 1, true)
	rocks(pos, 1.3, 10)
	groundMark(pos, R * 0.6, Color3.fromRGB(61, 66, 61), 4)
	sparks(pos + UP * 0.8, 0.8, WHITE, MINT, 18)
	VFX.PlaySound("Smash", pos, 1.3)
	VFX.PlaySound("Downslam", pos, 0.9)
	VFX.ShakeAt(pos, 2.2, 90, 0.3)
end

-- FA JIN (Deku's 4th, tap 4 to start, tap 4 again to let go - or it goes by
-- itself at full). The third user's quirk stores the kinetic energy of a
-- repeated motion, glowing red: he squats - down, up, down, up - each one
-- quicker than the last, and the energy burns up his legs as red veins from
-- the feet to the hips, a ring of dust kicked off the street at the bottom
-- of every squat. Then it all goes out through his legs at once: the street
-- bursts under him, he rockets forward and it ends in one straight Detroit
-- Smash - a gale that scours the street, bigger the longer he stored it
do
	local FJ = {
		charging = setmetatable({}, { __mode = "k" }), -- [char] = token while he charges
		GOLD = Color3.fromRGB(255, 184, 70),
		DEEP = Color3.fromRGB(255, 118, 36),
		PALE = Color3.fromRGB(255, 244, 214),
		DUST = Color3.fromRGB(206, 200, 188),
		RED = Color3.fromRGB(255, 38, 38),
		BURN = Color3.fromRGB(255, 84, 60),
		HOT = Color3.fromRGB(255, 170, 140),
	}
	-- the squats: down (hips sunk, legs forward, body over his knees, arms
	-- out for balance) and up again, over `period` seconds - FaJinSquat1 is
	-- the first slow one, FaJinSquat8 the fastest (FJ.period gives the tempo)
	function FJ.period(k)
		return 0.52 - 0.41 * math.clamp(k, 0, 1) ^ 0.8
	end
	for i = 1, 8 do
		local p = FJ.period((i - 1) / 7)
		MOTIONS["FaJinSquat" .. i] = {
			mute = 0.3,
			{ pose = { Hips = { 0, 0, 0, 0, -1.55, -0.2 }, Crouch = 1.35, Waist = { -24, 0, 0 }, Neck = { 16, 0, 0 }, RightArm = { 86, 0, 6 }, LeftArm = { 86, 0, 6 }, RightElbow = 10, LeftElbow = 10, RightLeg = 71, LeftLeg = 71, RightKnee = 112, LeftKnee = 112 }, t = p * 0.45, style = Enum.EasingStyle.Sine },
			{ pose = { Hips = { 0, 0, 0, 0, -0.15, 0 }, Crouch = 0.1, Waist = { -4, 0, 0 }, Neck = { 2, 0, 0 }, RightArm = { 36, 0, 12 }, LeftArm = { 36, 0, 12 }, RightElbow = 96, LeftElbow = 96, RightLeg = 10, LeftLeg = 10, RightKnee = 10, LeftKnee = 10 }, t = p * 0.55, style = Enum.EasingStyle.Sine },
			recover = 0.2,
		}
	end
	-- the launch: low and flat out behind the fist, then the punch
	MOTIONS.FaJinLaunch = {
		{ pose = { Hips = { -30, 10, 0, 0, -0.6, -0.4 }, Crouch = 0.8, Waist = { -24, 18, 0 }, Neck = { 24, -14, 0 }, RightArm = { -46, 0, 18 }, RightElbow = 100, LeftArm = { 70, 0, 0 }, LeftElbow = 20, LeftLeg = 40, LeftKnee = 70, RightLeg = -44, RightKnee = 20 }, t = 0.06, hold = 0.18, style = SNAP },
		recover = 0.2,
	}
	MOTIONS.FaJinRelease = {
		{ pose = { Hips = { -12, 26, 0, 0, -0.5, -1.1 }, Waist = { -16, 34, 0 }, Neck = { -6, -40, 0 }, RightArm = { 96, 0, -4 }, RightElbow = 0, RightWrist = { -8, 0, 0 }, LeftArm = { -38, 0, 30 }, LeftElbow = 55, LeftLeg = 50, LeftKnee = 52, RightLeg = -38, RightKnee = 6 }, t = 0.035, hold = 0.55, style = SNAP },
		recover = 0.32,
	}

	-- the veins: jagged red lines over a limb's surface, from the end of it
	-- (a foot) up to where it joins the body (the hip), with short branches
	-- off them. names: the R15 pieces from the end up, then the R6 limb.
	-- v.update(k) shows as much of them as the charge has reached (k 0 -> 1);
	-- v.finish() flashes them and lets them go.
	function FJ.veins(char, names)
		local parts = {}
		for i = 1, #names - 1 do
			local p = char:FindFirstChild(names[i])
			if p then
				table.insert(parts, p)
			end
		end
		if #parts == 0 then
			parts = { char:FindFirstChild(names[#names]) }
		end
		if not parts[1] then
			return nil
		end
		local total = 0
		for _, p in parts do
			total += p.Size.Y
		end
		-- u runs 0 (the fist) to 1 (the shoulder); a face and a spot across it
		local function spot(u, side, w)
			local y = u * total
			for i, p in parts do
				if y <= p.Size.Y or i == #parts then
					local s = p.Size
					local ly = math.clamp(-s.Y / 2 + y, -s.Y / 2, s.Y / 2)
					local off
					if side == 1 then
						off = Vector3.new(w * s.X * 0.42, ly, -s.Z / 2 - 0.03)
					elseif side == 2 then
						off = Vector3.new(s.X / 2 + 0.03, ly, w * s.Z * 0.42)
					elseif side == 3 then
						off = Vector3.new(w * s.X * 0.42, ly, s.Z / 2 + 0.03)
					else
						off = Vector3.new(-s.X / 2 - 0.03, ly, w * s.Z * 0.42)
					end
					return { part = p, off = off, u = u, w = w }
				end
				y -= p.Size.Y
			end
		end
		local seeded = Random.new(9)
		local segs = {}
		local function line(points, thick)
			for i = 1, #points - 1 do
				local part = newPart(Vector3.new(thick, thick, 0.2), CFrame.new(), FJ.RED, Enum.Material.Neon)
				part.Name = "Vein"
				part.Transparency = 1
				table.insert(segs, { a = points[i], b = points[i + 1], part = part, thick = thick })
			end
		end
		for v = 1, 8 do
			local side = (v - 1) % 4 + 1
			local w = seeded:NextNumber(-0.5, 0.5)
			local u = seeded:NextNumber(0, 0.06)
			local points = {}
			while u < 1 do
				table.insert(points, spot(u, side, w))
				u += seeded:NextNumber(0.09, 0.15)
				w = math.clamp(w + seeded:NextNumber(-0.28, 0.28), -0.9, 0.9)
			end
			table.insert(points, spot(1, side, w))
			line(points, v <= 4 and 0.11 or 0.075)
			-- a couple of short branches off it
			for _ = 1, 2 do
				local from = points[seeded:NextInteger(2, math.max(#points - 2, 2))]
				if from then
					local bw = from.w
					local branch = { from }
					local bu, dir = from.u, seeded:NextNumber() < 0.5 and -1 or 1
					for _ = 1, 2 do
						bu = math.min(bu + seeded:NextNumber(0.05, 0.08), 1)
						bw = math.clamp(bw + dir * seeded:NextNumber(0.25, 0.4), -0.95, 0.95)
						table.insert(branch, spot(bu, side, bw))
					end
					line(branch, 0.055)
				end
			end
		end
		local vs = { segs = segs, k = 0 }
		function vs.update(k)
			vs.k = k
			local reach = k * 1.04
			local burn = k >= 1
			for _, sg in segs do
				local a, b = sg.a, sg.b
				if not (a.part.Parent and b.part.Parent) or a.u >= reach then
					sg.part.Transparency = 1
				else
					local pa = a.part.CFrame:PointToWorldSpace(a.off)
					local pb = b.part.CFrame:PointToWorldSpace(b.off)
					if b.u > reach then
						pb = pa:Lerp(pb, (reach - a.u) / math.max(b.u - a.u, 1e-3))
					end
					local len = (pb - pa).Magnitude
					if len < 0.02 then
						sg.part.Transparency = 1
					else
						local t = sg.thick * (burn and 1.35 or 1)
						sg.part.Size = Vector3.new(t, t, len + t)
						sg.part.CFrame = CFrame.lookAt((pa + pb) / 2, pb, a.part.CFrame.LookVector)
						-- (it throbs, harder the fuller it gets)
						sg.part.Transparency = rng:NextNumber() * (0.1 + 0.25 * k)
						sg.part.Color = burn and FJ.BURN or FJ.RED
					end
				end
			end
		end
		function vs.finish()
			for _, sg in segs do
				if sg.part.Transparency < 1 then
					sg.part.Color = FJ.HOT
					tween(sg.part, 0.3, { Transparency = 1 })
				end
				cleanup(sg.part, 0.35)
			end
		end
		return vs
	end

	-- ONE FOR ALL AT 100% (the way he had to use it before Full Cowl): the
	-- whole of it through one arm - and the arm can't take it. While
	-- BrokenArmR / BrokenArmL on a character is ahead of the server clock,
	-- that arm is dressed in the bruise: black-purple and swollen at the
	-- hand, purple up the forearm, red-purple at the shoulder, split with
	-- dark cracks and burst veins. It fades as it heals.
	FJ.PURPLE = { Color3.fromRGB(56, 24, 68), Color3.fromRGB(102, 46, 122), Color3.fromRGB(150, 70, 110) } -- hand, forearm, upper arm
	FJ.CRACK = Color3.fromRGB(30, 10, 36)
	FJ.bruises = setmetatable({}, { __mode = "k" }) -- [char] = { R = rec?, L = rec? }
	function FJ.bruiseOn(char, side)
		local holder = Instance.new("Folder")
		holder.Name = "OFABruise" .. side
		holder.Parent = char
		local rec = { holder = holder, parts = {} }
		local seeded = Random.new(side == "R" and 7 or 11)
		-- one band of it round a limb: `from`..`to` along it (0 = the hand end)
		local function band(limb, from, to, color, swell, alpha)
			local s = limb.Size
			local h = s.Y * (to - from)
			local cf = limb.CFrame * CFrame.new(0, -s.Y / 2 + s.Y * (from + to) / 2, 0)
			local p = newPart(Vector3.new(s.X * swell, h, s.Z * swell), cf, color, Enum.Material.SmoothPlastic, nil, holder)
			p.Transparency = alpha or 0
			table.insert(rec.parts, { part = p, alpha = alpha or 0 })
			-- cracks and burst veins across its faces
			for _ = 1, math.max(2, math.floor(h * 3)) do
				local face = seeded:NextInteger(1, 4)
				local y = seeded:NextNumber(-h / 2 + 0.1, h / 2 - 0.1)
				local w = seeded:NextNumber(-0.35, 0.35)
				local len = seeded:NextNumber(0.25, 0.55)
				local x, z, rot
				if face == 1 then
					x, z, rot = w * s.X * swell, -s.Z * swell / 2 - 0.02, CFrame.Angles(0, 0, seeded:NextNumber(-1, 1))
				elseif face == 2 then
					x, z, rot = s.X * swell / 2 + 0.02, w * s.Z * swell, CFrame.Angles(seeded:NextNumber(-1, 1), 0, 0)
				elseif face == 3 then
					x, z, rot = w * s.X * swell, s.Z * swell / 2 + 0.02, CFrame.Angles(0, 0, seeded:NextNumber(-1, 1))
				else
					x, z, rot = -s.X * swell / 2 - 0.02, w * s.Z * swell, CFrame.Angles(seeded:NextNumber(-1, 1), 0, 0)
				end
				local red = seeded:NextNumber() < 0.3
				local c = newPart(Vector3.new(0.05, len, 0.05), cf * CFrame.new(x, y, z) * rot, red and Color3.fromRGB(150, 24, 44) or FJ.CRACK, Enum.Material.SmoothPlastic, nil, holder)
				table.insert(rec.parts, { part = c, alpha = 0 })
			end
			return p
		end
		local r6 = char:FindFirstChild(side == "R" and "Right Arm" or "Left Arm")
		if r6 then
			band(r6, 0, 0.28, FJ.PURPLE[1], 1.12)
			band(r6, 0.28, 0.62, FJ.PURPLE[2], 1.07)
			band(r6, 0.62, 1, FJ.PURPLE[3], 1.04, 0.2)
		else
			local pre = side == "R" and "Right" or "Left"
			for i, n in { pre .. "Hand", pre .. "LowerArm", pre .. "UpperArm" } do
				local limb = char:FindFirstChild(n)
				if limb then
					band(limb, 0, 1, FJ.PURPLE[i], ({ 1.14, 1.08, 1.05 })[i], i == 3 and 0.2 or 0)
				end
			end
		end
		-- welded on: they move with the arm
		for _, e in rec.parts do
			local limb = r6
			if not limb then
				local best, bestD
				for _, n in { "Hand", "LowerArm", "UpperArm" } do
					local l = char:FindFirstChild((side == "R" and "Right" or "Left") .. n)
					if l then
						local dd = (l.CFrame.Position - e.part.CFrame.Position).Magnitude
						if not bestD or dd < bestD then
							best, bestD = l, dd
						end
					end
				end
				limb = best
			end
			if limb then
				local w = Instance.new("WeldConstraint")
				w.Part0 = limb
				w.Part1 = e.part
				w.Parent = e.part
				e.part.Massless = true
				e.part.Anchored = false
			end
		end
		return rec
	end
	function FJ.bruiseOff(rec)
		for _, e in rec.parts do
			tween(e.part, 1, { Transparency = 1 })
		end
		cleanup(rec.holder, 1.05)
	end
	FJ.bruiseClock = 0
	RunService.RenderStepped:Connect(function(dt)
		FJ.bruiseClock += dt
		if FJ.bruiseClock < 0.25 then
			return
		end
		FJ.bruiseClock = 0
		local now = workspace:GetServerTimeNow()
		for _, plr in Players:GetPlayers() do
			local char = plr.Character
			if char then
				local recs = FJ.bruises[char] or {}
				for _, side in { "R", "L" } do
					local untilT = tonumber(char:GetAttribute("BrokenArm" .. side))
					local broken = untilT ~= nil and untilT > now
					if broken and not recs[side] and char:FindFirstChild("HumanoidRootPart") then
						recs[side] = FJ.bruiseOn(char, side)
						FJ.bruises[char] = recs
					elseif broken and VFX.BLOOD and (Config.BrokenArms or {}).Drip ~= false and rng:NextNumber() < 0.2 and char:FindFirstChild("HumanoidRootPart") and nearCamera(char.HumanoidRootPart.Position, 150) then
						local arm = char:FindFirstChild(side == "R" and "Right Arm" or "Left Arm") or char:FindFirstChild(side == "R" and "RightHand" or "LeftHand")
						if arm then
							VFX.BLOOD.drip(arm, (arm.CFrame * CFrame.new(0, -arm.Size.Y / 2, 0)).Position, 1)
						end
					elseif not broken and recs[side] then
						FJ.bruiseOff(recs[side])
						recs[side] = nil
					end
				end
			end
		end
	end)

	-- 100%: DETROIT SMASH. The wind-up: the power gathers in one arm - red
	-- veins up it, red and green lightning off the fist...
	POSES.HundredWindR = { RightArm = { -70, 0, 30 }, RightElbow = 100, LeftArm = { 70, 0, 10 }, LeftElbow = 30, Waist = { 6, 40, 0 }, Neck = { 0, -30, 0 }, RightLeg = -20, LeftLeg = 40, LeftKnee = 50, RightKnee = 20, Crouch = 0.5 }
	POSES.HundredWindL = { LeftArm = { -70, 0, 30 }, LeftElbow = 100, RightArm = { 70, 0, 10 }, RightElbow = 30, Waist = { 6, -40, 0 }, Neck = { 0, 30, 0 }, LeftLeg = -20, RightLeg = 40, RightKnee = 50, LeftKnee = 20, Crouch = 0.5 }
	POSES.HundredPunchR = { RightArm = { 96, 0, 0 }, RightElbow = 0, LeftArm = { -40, 0, 30 }, LeftElbow = 40, Waist = { 14, -34, 0 }, Neck = { -8, 26, 0 }, RightLeg = -30, LeftLeg = 44, LeftKnee = 30, RightKnee = 10, Crouch = 0.45 }
	POSES.HundredPunchL = { LeftArm = { 96, 0, 0 }, LeftElbow = 0, RightArm = { -40, 0, 30 }, RightElbow = 40, Waist = { 14, 34, 0 }, Neck = { -8, -26, 0 }, LeftLeg = -30, RightLeg = 44, RightKnee = 30, LeftKnee = 10, Crouch = 0.45 }
	-- (after: the broken arm hangs, the other one holds it)
	POSES.HundredHurtR = { RightArm = { 10, 0, 8 }, RightElbow = 10, LeftArm = { 40, 34, 0 }, LeftElbow = 90, Waist = { 16, 10, 0 }, Neck = { 14, -12, 0 }, RightKnee = 16, LeftKnee = 22, Crouch = 0.3 }
	POSES.HundredHurtL = { LeftArm = { 10, 0, 8 }, LeftElbow = 10, RightArm = { 40, 34, 0 }, RightElbow = 90, Waist = { 16, -10, 0 }, Neck = { 14, 12, 0 }, RightKnee = 22, LeftKnee = 16, Crouch = 0.3 }
	MOTIONS.HundredWindR = { { pose = "HundredWindR", t = 0.2, hold = 0.45 }, recover = 0.3 }
	MOTIONS.HundredWindL = { { pose = "HundredWindL", t = 0.2, hold = 0.45 }, recover = 0.3 }
	MOTIONS.HundredPunchR = { { pose = "HundredPunchR", t = 0.05, hold = 0.35, style = SNAP }, { pose = "HundredHurtR", t = 0.25, hold = 0.35 }, recover = 0.4 }
	MOTIONS.HundredPunchL = { { pose = "HundredPunchL", t = 0.05, hold = 0.35, style = SNAP }, { pose = "HundredHurtL", t = 0.25, hold = 0.35 }, recover = 0.4 }
	function FJ.whichArm(char)
		local now = workspace:GetServerTimeNow()
		local rB = (tonumber(char:GetAttribute("BrokenArmR")) or 0) > now
		local lB = (tonumber(char:GetAttribute("BrokenArmL")) or 0) > now
		return not rB or lB
	end
	function Effects.HundredSmash(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		local right = FJ.whichArm(char)
		local startup = (ability and ability.Startup) or 0.55
		VFX.MuteGait(char, startup + 0.9)
		VFX.Motion(char, right and "HundredWindR" or "HundredWindL")
		local vs = FJ.veins(char, right and { "RightHand", "RightLowerArm", "RightUpperArm", "Right Arm" } or { "LeftHand", "LeftLowerArm", "LeftUpperArm", "Left Arm" })
		local t0 = os.clock()
		local conn
		conn = RunService.RenderStepped:Connect(function()
			local k = math.clamp((os.clock() - t0) / (startup * 0.9), 0, 1)
			if vs then
				vs.update(k)
			end
			if os.clock() - t0 > startup + 0.08 or not char.Parent then
				conn:Disconnect()
				if vs then
					vs.finish()
				end
			end
		end)
		task.spawn(function()
			while os.clock() - t0 < startup and char.Parent do
				local hand = handPos(char, right)
				bolt(hand + rng:NextUnitVector() * 0.4, 1.3, rng:NextNumber() < 0.55 and FJ.RED or COWL_GREEN)
				task.wait(0.04)
			end
		end)
		sparks(handPos(char, right), 0.6, FJ.HOT, FJ.RED, 8)
		VFX.PlaySound("CowlCharge", root.Position, 1)
		if Players.LocalPlayer and Players.LocalPlayer.Character == char then
			VFX.Hooks.Callout("ONE FOR ALL... 100%!!", FJ.RED)
		end
	end
	-- ...and the punch: a gale that blows the street away - and the crack of
	-- the arm going with it
	function Effects.HundredSmashBlast(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		local right = data.Side ~= "L"
		local range, width = tonumber(data.Range) or 100, tonumber(data.Width) or 26
		VFX.Motion(char, right and "HundredPunchR" or "HundredPunchL")
		local fist = handPos(char, right) + d
		windBlast(fist, d, 2.4)
		for k = 1, 9 do
			task.delay(k * 0.035, shockDisc, fist + d * (range * k / 9), d, width * 0.3, width * 1.15, 0.35, WHITE, 6)
		end
		billboardRing(fist, 2, 40, WHITE, 8, 0.3)
		billboardRing(fist, 2, 26, FJ.RED, 6, 0.25)
		streaks(fist, d, 22, 0.5, 14, range * 0.6, WHITE, 0.45)
		for k = 1, 6 do
			task.delay(k * 0.05, dustPuffs, groundPoint(fist + d * (range * k / 7)), 1.4, 4, FJ.DUST, 1, true)
		end
		VFX.PlaySound("HundredSmash", fist, 1.3)
		VFX.ShakeAt(fist, 3, 220, 0.5)
		if nearCamera(fist, 80) then
			VFX.ImpactFrame(0.1)
		end
		if Players.LocalPlayer and Players.LocalPlayer.Character == char then
			VFX.Hooks.Callout("DETROIT SMASH!!", Color3.fromRGB(255, 240, 150))
		end
		task.delay(0.14, function()
			if not root.Parent then
				return
			end
			-- (round 75) the arm holds now: steam off it, the green crackling out
			local hand = handPos(char, right)
			dustPuffs(hand, 0.5, 3, Color3.fromRGB(235, 240, 238), 0.7, false)
			sparks(hand, 0.7, COWL_CORE, COWL_GREEN, 10)
			bolt(hand, 1.6, COWL_GREEN)
			billboardRing(hand, 0.4, 5, COWL_GREEN, 3, 0.2)
		end)
	end

	function Effects.FaJinSmash(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or Config.FindAbilityById("FaJinSmash") or {}
		local spec = ability.Hold or {}
		local max = spec.Max or 2.4
		local token = {}
		FJ.charging[char] = token
		if isLocal then
			face(root, flatten(data.Dir, root))
			VFX.Hooks.Dim(0.18, max)
		end
		VFX.PlaySound("DetroitCharge", root.Position, 0.6)
		local glow = Instance.new("PointLight")
		glow.Color = FJ.RED
		glow.Range = 6
		glow.Brightness = 0.4
		glow.Parent = root
		local legs = {}
		for _, names in { { "RightFoot", "RightLowerLeg", "RightUpperLeg", "Right Leg" }, { "LeftFoot", "LeftLowerLeg", "LeftUpperLeg", "Left Leg" } } do
			table.insert(legs, FJ.veins(char, names))
		end
		local k = 0
		local conn = RunService.RenderStepped:Connect(function()
			for _, v in legs do
				v.update(k)
			end
		end)
		local t0 = os.clock()
		local level, nextSquat = 1, 0
		while FJ.charging[char] == token and root.Parent and os.clock() - t0 < max + 0.6 do
			local now = os.clock() - t0
			k = math.clamp(now / max, 0, 1)
			local reached = 1
			for i, t in spec.Levels or {} do
				if now >= t then
					reached = i + 1
				end
			end
			local g = groundPoint(root.Position)
			if reached > level then
				-- a new level: the legs flare, the street cracks under him
				level = reached
				billboardRing(g + UP * 1.5, 2, 8 + level * 6, level >= 3 and Color3.new(1, 1, 1) or FJ.RED, 6, 0.3)
				sparks(g + UP * 1, 0.4 * level, FJ.HOT, FJ.RED, 10 * level)
				groundMark(g, 2 + level, Color3.fromRGB(70, 40, 36), 3)
				VFX.PlaySound("DetroitCharge", root.Position, 0.6 + 0.25 * level)
				if level >= 3 then
					rocks(g, 0.9, 6)
					VFX.PlaySound("Spark", root.Position, 1)
				end
				if isLocal then
					VFX.Shake(0.25 * level, 0.22)
				end
			end
			-- the squats: each one quicker than the one before
			if os.clock() >= nextSquat then
				local period = FJ.period(k)
				VFX.Motion(char, "FaJinSquat" .. math.clamp(math.floor(k * 7 + 0.5) + 1, 1, 8))
				nextSquat = os.clock() + period
				task.delay(period * 0.45, FJ.thump, char, k, isLocal)
			end
			glow.Brightness = 0.4 + 3.2 * k
			glow.Range = 6 + 12 * k
			-- red crackling off his legs, more as it builds
			if rng:NextNumber() < 0.12 + 0.4 * k then
				bolt(g + Vector3.new(rand(-1.2, 1.2), rand(0.5, 3), rand(-1.2, 1.2)), 0.9 + 1.2 * k, FJ.RED)
			end
			task.wait(0.03)
		end
		conn:Disconnect()
		for _, v in legs do
			v.finish()
		end
		glow:Destroy()
		if FJ.charging[char] == token then
			FJ.charging[char] = nil
		end
	end

	-- the bottom of a squat: dust kicked out of the street, a red ring round
	-- his feet, a thump - bigger the more he's stored
	function FJ.thump(char, k, isLocal)
		local root = char and char:FindFirstChild("HumanoidRootPart")
		if not root or not FJ.charging[char] then
			return
		end
		local g = groundPoint(root.Position)
		shockDisc(g + UP * 0.25, UP, 3, 8 + 14 * k, 0.3, k > 0.66 and FJ.RED or FJ.DUST)
		billboardRing(g + UP * 0.8, 2, 6 + 8 * k, FJ.RED, 3 + 3 * k, 0.22)
		if k > 0.3 then
			dustPuffs(g, 0.35 + 0.5 * k, 2 + math.floor(3 * k), FJ.DUST, 0.6, false)
		end
		VFX.PlaySound("FaJinSwing", root.Position, 0.35 + 0.45 * k)
		if isLocal and k > 0.5 then
			VFX.Shake(0.12 + 0.25 * k, 0.12)
		end
	end

	-- ...and the second tap: everything he stored goes out through his legs -
	-- the street bursts under him, he rockets forward - and into one punch
	function Effects.FaJinSmashRelease(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		FJ.charging[char] = nil
		ability = ability or Config.FindAbilityById("FaJinSmash") or {}
		local level = math.clamp(tonumber(data.Level) or 1, 1, 3)
		local k = tonumber(data.Power)
		if not k then
			k = (level - 1) / 2 -- (his own screen: the level he let go at)
		end
		k = math.clamp(k, 0, 1)
		local d = flatten(typeof(data.Dir) == "Vector3" and data.Dir or root.CFrame.LookVector, root)
		if isLocal then
			face(root, d)
		end
		local L = ability.Launch or {}
		local time = L.Time or 0.24
		local dist = (L.Min or 16) + ((L.Max or 62) - (L.Min or 16)) * k
		local g = groundPoint(root.Position)
		shockDisc(g + UP * 0.3, UP, 4, 20 + 22 * k, 0.4, FJ.RED)
		billboardRing(g + UP * 1.2, 3, 18 + 18 * k, FJ.RED, 7, 0.3)
		sparks(g + UP, 0.7 + k, FJ.HOT, FJ.RED, 16 + math.floor(16 * k))
		dustPuffs(g, 0.8 + 0.8 * k, 5 + math.floor(4 * k), FJ.DUST, 1, true)
		groundMark(g, 4 + 3 * k, Color3.fromRGB(64, 40, 36), 4)
		rocks(g, 0.7 + 0.6 * k, 4 + math.floor(5 * k))
		streaks(g + UP * 2, -d, 10, 0.3, 6, 12 + 10 * k, FJ.RED, 0.3)
		VFX.PlaySound("Launch", g, 0.9)
		VFX.Motion(char, "FaJinLaunch")
		local stopTrail = addTrail(root, FJ.RED, 0.25, 2.2)
		if isLocal then
			dash(root, d * (dist / time), time)
			VFX.Shake(0.5 + 0.6 * k, 0.2)
		end
		task.wait(time)
		stopTrail()
		if not root.Parent then
			return
		end
		VFX.Motion(char, "FaJinRelease")
		local length = (ability.Range or 110) * (0.65 + 0.35 * k)
		local width = (ability.Width or 26) * (0.7 + 0.3 * k)
		local right = d:Cross(UP).Unit
		local origin = root.Position + d * 3.5 + UP * 1.2
		-- the fist: a flash, a ring of air and the whole screen jolts
		billboardRing(origin, 2, 18 + 22 * k, Color3.new(1, 1, 1), 8, 0.25)
		shockDisc(origin, d, 2, width * 0.8, 0.22, FJ.PALE, 6)
		shockDisc(origin, d, 1, width * 0.5, 0.18, FJ.GOLD, 10)
		sparks(origin, 0.8 + k, FJ.PALE, FJ.GOLD, 24 + math.floor(24 * k))
		bolt(origin, 3 + 2 * k, FJ.RED)
		billboardRing(origin, 1, 10 + 12 * k, FJ.RED, 4, 0.2)
		VFX.PlaySound("DetroitImpact", origin, 0.9 + 0.3 * k)
		VFX.PlaySound("FaJinRelease", origin, 0.7 + 0.4 * k)
		if isLocal then
			VFX.ImpactFrame(0.05 + 0.05 * k)
			VFX.Hooks.Flash(FJ.PALE, 0.1 + 0.08 * k)
		end
		VFX.ShakeAt(origin, 1.1 + 1.4 * k, 90 + 70 * k, 0.35 + 0.25 * k)
		-- the pressure: a gold cone of air rushing down the street
		local cone = newPart(Vector3.new(2, 2, 2), CFrame.lookAt(origin, origin + d) * CFrame.Angles(0, math.rad(90), 0), FJ.GOLD, Enum.Material.Neon, Enum.PartType.Cylinder)
		cone.Transparency = 0.45
		local mid = origin + d * length * 0.5
		tween(cone, 0.3, { Size = Vector3.new(length, width * 0.55, width * 0.55), CFrame = CFrame.lookAt(mid, mid + d) * CFrame.Angles(0, math.rad(90), 0), Transparency = 1 }, Enum.EasingStyle.Quad)
		cleanup(cone, 0.4)
		local core = newPart(Vector3.new(2, 1, 1), CFrame.lookAt(origin, origin + d) * CFrame.Angles(0, math.rad(90), 0), Color3.new(1, 1, 1), Enum.Material.Neon, Enum.PartType.Cylinder)
		core.Transparency = 0.2
		tween(core, 0.22, { Size = Vector3.new(length, width * 0.2, width * 0.2), CFrame = CFrame.lookAt(mid, mid + d) * CFrame.Angles(0, math.rad(90), 0), Transparency = 1 }, Enum.EasingStyle.Quad)
		cleanup(core, 0.3)
		-- the energy he wound up, unwinding down it as a spiral
		local helix = {}
		for i = 0, 24 do
			local f = i / 24
			local a = f * (10 + 8 * k)
			local r = 1.2 + width * 0.22 * f
			table.insert(helix, origin + d * length * 0.85 * f + (right * math.cos(a) + UP * math.sin(a)) * r)
		end
		curveStroke(helix, 0.3 + 0.35 * k, FJ.GOLD, 0.4)
		streaks(origin, d, 12 + math.floor(12 * k), width / 30, 10 + 6 * k, length * 0.8, Color3.new(1, 1, 1), 0.3)
		-- the gale travels: rings of air, dust walls and rubble all the way down
		local waves = 5 + math.floor(3 * k)
		for i = 1, waves do
			task.delay(i / waves * 0.32, function()
				local f = i / waves
				local p = origin + d * length * f
				shockDisc(p, d, width * (0.35 + 0.3 * f), width * (0.7 + 0.5 * f), 0.35, i % 2 == 0 and Color3.new(1, 1, 1) or FJ.GOLD, 6)
				local g = groundPoint(p)
				dustPuffs(g, 0.6 + 0.7 * k, 3, FJ.DUST, 1, i % 2 == 0)
				groundMark(g, 2.5 + width * 0.12, Color3.fromRGB(70, 66, 60), 3.5)
				if i % 2 == 0 then
					rocks(g, 0.6 + 0.5 * k, 3 + level)
				end
				for side = -1, 1, 2 do
					celPuff(folder, g + right * side * width * 0.3 + UP, g + right * side * width * (0.6 + 0.3 * k) + UP * rand(2, 5), 3 + 3 * k, FJ.DUST, Color3.new(1, 1, 1), 0.5, 0.9)
				end
			end)
		end
		-- full power: the far end of it bursts
		if level >= 3 then
			task.delay(0.34, function()
				local e = origin + d * length * 0.9
				billboardRing(e, 4, width * 2.2, Color3.new(1, 1, 1), 10, 0.4)
				shockDisc(groundPoint(e) + UP * 0.4, UP, 4, width * 1.6, 0.45, FJ.GOLD)
				dustPuffs(groundPoint(e), 1.5, 8, FJ.DUST, 1.3, true)
				VFX.PlaySound("Smash", e, 0.9)
				VFX.ShakeAt(e, 1.6, 120, 0.4)
			end)
		end
	end

	-- (knocked out, or never let go: the wind-up just stops)
	function VFX.FaJinDrop(char)
		FJ.charging[char] = nil
	end
end

-- GEARSHIFT (Deku's 4th, the 2nd user Kudo's quirk - in the anime it wraps
-- whatever it touches in a glowing blue aura, and living things' eyes glow
-- blue): each press shifts him up a gear like a driver working the stick -
-- LOW, SECOND, THIRD, TOP - and he's faster and harder-hitting with every
-- one: the blue aura on him, a cog of light spinning round each fist and
-- ankle, quicker every gear, blue streaks peeling off him as he runs. At
-- TOP GEAR the next press is OVERDRIVE into TRANSMISSION: he's on them in a
-- blink, the punches come faster and faster, then DETROIT SMASH: QUINTUPLE
-- - five of them - and the last sends them flying, geared down (glowing
-- blue, eyes and all, and slow). Then the recoil hits him.
do
	local GS = {
		GLOW = Color3.fromRGB(96, 178, 255),
		CORE = Color3.fromRGB(226, 242, 255),
		DEEP = Color3.fromRGB(30, 84, 220),
		FAJIN = Color3.fromRGB(255, 70, 60),
		rigs = setmetatable({}, { __mode = "k" }), -- [char] = { cogs, gear, spin }
		LIMBS = {
			{ "RightHand", "Right Arm", -0.95 }, { "LeftHand", "Left Arm", -0.95 },
			{ "RightFoot", "Right Leg", -0.8 }, { "LeftFoot", "Left Leg", -0.8 },
		},
	}
	-- the shift: low like a driver in his seat, the right hand down on the
	-- stick at his hip - forward... and yanked back into the next gear
	MOTIONS.GearshiftShift = {
		{ pose = { Hips = { -6, 0, 0, 0, -0.4, 0 }, Crouch = 0.55, Waist = { -18, -10, 0 }, Neck = { 12, 10, 0 }, RightArm = { 28, 0, 14 }, RightElbow = 64, LeftArm = { 60, 0, 10 }, LeftElbow = 84, RightLeg = 30, LeftLeg = -6 }, t = 0.05, hold = 0.03 },
		{ pose = { Hips = { -6, 0, 0, 0, -0.4, 0 }, Crouch = 0.55, Waist = { -14, -16, 0 }, Neck = { 12, 14, 0 }, RightArm = { -22, 0, 18 }, RightElbow = 86, LeftArm = { 60, 0, 10 }, LeftElbow = 84, RightLeg = 30, LeftLeg = -6 }, t = 0.035, hold = 0.1, style = SNAP },
		recover = 0.18,
	}

	-- a cog: teeth round a ring, flat to `axis`
	function GS.cog(radius, teeth, thick)
		local parts = {}
		for i = 1, teeth do
			local a = i / teeth * math.pi * 2
			local tooth = newPart(Vector3.new(thick * 1.4, thick, radius * 0.42), CFrame.new(), GS.GLOW, Enum.Material.Neon)
			table.insert(parts, { part = tooth, a = a, r = radius * 1.08, len = true })
			local rim = newPart(Vector3.new(thick * 0.7, thick * 0.7, radius * 2 * math.sin(math.pi / teeth) + 0.05), CFrame.new(), GS.CORE, Enum.Material.Neon)
			table.insert(parts, { part = rim, a = a + math.pi / teeth, r = radius * 0.86 })
		end
		return parts
	end

	-- place a cog's pieces round `cf` (its axis cf's Y), turned `spin`
	function GS.placeCog(cog, cf, spin)
		for _, e in cog do
			local a = e.a + spin
			local at = cf * CFrame.new(math.cos(a) * e.r, 0, math.sin(a) * e.r)
			if e.len then
				e.part.CFrame = CFrame.lookAt(at.Position, cf.Position) * CFrame.new(0, 0, e.part.Size.Z * 0.1)
			else
				e.part.CFrame = CFrame.lookAt(at.Position, at.Position + cf:VectorToWorldSpace(Vector3.new(-math.sin(a), 0, math.cos(a))), cf.UpVector)
			end
		end
	end

	function GS.drop(char)
		local rig = GS.rigs[char]
		if not rig then
			return
		end
		GS.rigs[char] = nil
		if rig.aura then
			rig.aura:Destroy()
		end
		for _, cog in rig.cogs do
			for _, e in cog do
				tween(e.part, 0.25, { Transparency = 1, Size = e.part.Size * 0.3 })
				cleanup(e.part, 0.3)
			end
		end
	end

	function GS.step(dt)
		local now = os.clock()
		for _, plr in Players:GetPlayers() do
			local char = plr.Character
			local gear = char and char:GetAttribute("Gearshift")
			local root = char and char:FindFirstChild("HumanoidRootPart")
			local rig = char and GS.rigs[char]
			if gear and root then
				if not rig then
					rig = { cogs = {}, spin = 0 }
					for _ = 1, #GS.LIMBS do
						table.insert(rig.cogs, GS.cog(0.95, 8, 0.16))
					end
					-- (the blue aura Gearshift wraps him in)
					local aura = Instance.new("Highlight")
					aura.Name = "GearshiftAura"
					aura.FillColor = GS.GLOW
					aura.OutlineColor = GS.CORE
					aura.DepthMode = Enum.HighlightDepthMode.Occluded
					aura.Parent = char
					rig.aura = aura
					GS.rigs[char] = rig
				end
				rig.aura.FillTransparency = 0.88 - 0.06 * gear + math.sin(now * (6 + 2 * gear)) * 0.04
				rig.aura.OutlineTransparency = 0.6 - 0.08 * gear
				rig.spin += dt * (3 + 5 * gear)
				for i, spec in GS.LIMBS do
					local limbPart = limb(char, spec[1], spec[2])
					if limbPart then
						local at = limbPart.CFrame * CFrame.new(0, limbPart.Size.Y / 2 + spec[3], 0)
						GS.placeCog(rig.cogs[i], at, i % 2 == 0 and -rig.spin or rig.spin)
					end
				end
				-- green streaks off him, the faster he's going
				local v = root.AssemblyLinearVelocity
				local flat = Vector3.new(v.X, 0, v.Z)
				if flat.Magnitude > 18 and now - (rig.streak or 0) > 0.12 - 0.02 * gear then
					rig.streak = now
					local back = -flat.Unit
					local p = root.Position + Vector3.new(rand(-1.2, 1.2), rand(-2, 1.5), rand(-1.2, 1.2))
					local s = newPart(Vector3.new(0.12, 0.12, 3 + gear), CFrame.lookAt(p, p + back) * CFrame.new(0, 0, -(3 + gear) / 2), GS.GLOW, Enum.Material.Neon)
					tween(s, 0.25, { Transparency = 1, Size = Vector3.new(0.04, 0.04, 5 + gear * 2) })
					cleanup(s, 0.3)
				end
			elseif rig then
				GS.drop(char)
			end
		end
		for char in GS.rigs do
			if not char.Parent then
				GS.drop(char)
			end
		end
	end
	RunService.RenderStepped:Connect(GS.step)

	-- a big cog of light behind him, spun up and gone
	function GS.bigCog(cf, radius, life)
		local cog = GS.cog(radius, 10, 0.3)
		local t0 = os.clock()
		local conn
		conn = RunService.RenderStepped:Connect(function()
			local t = os.clock() - t0
			if t > life then
				conn:Disconnect()
				for _, e in cog do
					e.part:Destroy()
				end
				return
			end
			GS.placeCog(cog, cf * CFrame.Angles(math.pi / 2, 0, 0), t * 9)
			for _, e in cog do
				e.part.Transparency = math.clamp((t / life - 0.5) * 2, 0, 1)
			end
		end)
	end

	function Effects.Gearshift(char, _data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or Config.FindAbilityById("Gearshift") or {}
		local top = ability.TopGear or 4
		local gear = char:GetAttribute("Gearshift") or 0
		if gear >= top then
			-- OVERDRIVE into TRANSMISSION: the rush itself comes from the
			-- server (TransmissionRush, GearshiftHit)
			VFX.Motion(char, "GearshiftShift")
			GS.bigCog(root.CFrame * CFrame.new(0, 0.5, 1.8), 5, 0.45)
			return
		end
		local new = gear + 1
		VFX.Motion(char, "GearshiftShift")
		GS.bigCog(root.CFrame * CFrame.new(0, 0.5, 1.6), 2.4 + new * 0.6, 0.5)
		local g = groundPoint(root.Position)
		shockDisc(g + UP * 0.3, UP, 3, 10 + new * 4, 0.3, GS.GLOW)
		sparks(root.Position, 0.4 + 0.15 * new, GS.CORE, GS.GLOW, 8 + new * 3)
		VFX.PlaySound("ReciproRev", root.Position, 0.5 + 0.12 * new)
		VFX.PlaySound("Snap", root.Position, 0.8)
		if isLocal then
			local names = ability.Gears or {}
			VFX.Hooks.Callout(names[new] or ("GEAR " .. new), new >= top and Color3.fromRGB(255, 240, 150) or GS.GLOW)
			VFX.Shake(0.15 + 0.1 * new, 0.15)
		end
	end

	-- OVERDRIVE (Gearshift and Fa Jin together, 120%): red and blue burst
	-- off him and he's on them in a blink, a streak and a string of
	-- afterimages from where he was
	function Effects.TransmissionRush(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local d = typeof(data.Dir) == "Vector3" and data.Dir or root.CFrame.LookVector
		local at = root.Position
		billboardRing(at, 2, 26, GS.FAJIN, 6, 0.3)
		billboardRing(at, 2, 20, GS.GLOW, 6, 0.3)
		sparks(at, 1.2, GS.CORE, GS.FAJIN, 24)
		streaks(at, -d, 16, 0.3, 10, 24, GS.GLOW, 0.35)
		for i = 1, 4 do
			task.delay(i * 0.03, function()
				if char.Parent then
					afterimage(char, i % 2 == 0 and GS.FAJIN or GS.GLOW, 0.3)
				end
			end)
		end
		VFX.PlaySound("BlitzGo", at, 1.2)
		VFX.PlaySound("Dash", at, 1)
		if Players.LocalPlayer and Players.LocalPlayer.Character == char then
			VFX.Hooks.Callout("OVERDRIVE!!", Color3.fromRGB(255, 120, 110))
			VFX.Shake(0.8, 0.25)
		end
	end

	-- every punch faster than the last: the rings get bigger, the sound
	-- piles up, and the last one's a Detroit Smash
	function Effects.GearshiftHit(char, data)
		local root = charParts(char)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos
		if not root or not pos then
			return
		end
		local n, hits = tonumber(data.N) or 1, tonumber(data.Hits) or 9
		local d = typeof(data.Dir) == "Vector3" and data.Dir or root.CFrame.LookVector
		local f = math.clamp(n / hits, 0, 1)
		local q = tonumber(data.Quintuple)
		if q then
			-- DETROIT SMASH: QUINTUPLE - five of them, a gale each
			VFX.Pose(char, q % 2 == 1 and "PunchR" or "PunchL", 0.14)
			windBlast(pos, d, 1 + q * 0.2)
			billboardRing(pos, 3, 30 + q * 6, q % 2 == 1 and Color3.new(1, 1, 1) or GS.GLOW, 8, 0.25)
			shockDisc(pos, d, 4, 22 + q * 3, 0.26, GS.CORE, 14)
			sparks(pos, 1 + q * 0.15, GS.CORE, GS.GLOW, 18)
			VFX.PlaySound("DetroitImpact", pos, 1 + q * 0.1)
			VFX.ShakeAt(pos, 1 + q * 0.25, 90, 0.2)
			-- a count over the hit: x1 ... x5
			local anchor = newPart(Vector3.one * 0.1, CFrame.new(pos + UP * 3), GS.GLOW)
			anchor.Transparency = 1
			local bb = Instance.new("BillboardGui")
			bb.Size = UDim2.fromOffset(140, 60)
			bb.AlwaysOnTop = true
			bb.LightInfluence = 0
			bb.MaxDistance = 200
			bb.Parent = anchor
			local label = Instance.new("TextLabel")
			label.BackgroundTransparency = 1
			label.Size = UDim2.fromScale(1, 1)
			label.Font = Enum.Font.LuckiestGuy
			label.TextScaled = true
			label.Text = "x" .. q
			label.TextColor3 = GS.CORE
			label.TextStrokeColor3 = GS.DEEP
			label.TextStrokeTransparency = 0
			label.Parent = bb
			tween(anchor, 0.6, { CFrame = anchor.CFrame + UP * 3 })
			tween(label, 0.3, { TextTransparency = 1, TextStrokeTransparency = 1 }, nil, nil, 0.3)
			cleanup(anchor, 0.65)
			if q == 1 and Players.LocalPlayer and Players.LocalPlayer.Character == char then
				VFX.Hooks.Callout("DETROIT SMASH: QUINTUPLE!!", Color3.fromRGB(255, 240, 150))
			end
			return
		end
		if data.Final then
			VFX.Pose(char, "PunchR", 0.4)
			billboardRing(pos, 4, 60, Color3.new(1, 1, 1), 10, 0.35)
			billboardRing(pos, 2, 40, GS.GLOW, 8, 0.3)
			shockDisc(pos, d, 4, 30, 0.3, GS.CORE, 18)
			streaks(pos, d, 18, 0.3, 14, 50, Color3.new(1, 1, 1), 0.35)
			sparks(pos, 1.6, GS.CORE, GS.GLOW, 36)
			windBlast(pos, d, 2.2)
			VFX.PlaySound("DetroitImpact", pos, 1.5)
			VFX.PlaySound("Smash", pos, 1.2)
			VFX.ShakeAt(pos, 2.4, 120, 0.4)
			if Players.LocalPlayer and Players.LocalPlayer.Character == char then
				VFX.Hooks.Callout("DETROIT SMASH!!", Color3.fromRGB(255, 240, 150))
			end
			return
		end
		if n == 1 and Players.LocalPlayer and Players.LocalPlayer.Character == char then
			VFX.Hooks.Callout("TRANSMISSION!!", GS.GLOW)
		end
		VFX.Pose(char, n % 2 == 0 and "PunchL" or "PunchR", 0.07 + 0.08 * (1 - f))
		billboardRing(pos, 1, 8 + 14 * f, n % 2 == 0 and GS.GLOW or Color3.new(1, 1, 1), 3 + 3 * f, 0.15)
		sparks(pos, 0.4 + 0.6 * f, GS.CORE, GS.GLOW, 6 + math.floor(10 * f))
		if f > 0.5 then
			shockDisc(pos, d, 2, 8 + 10 * f, 0.18, GS.GLOW, 6)
		end
		VFX.PlaySound(f > 0.6 and "HeavyHit" or "Hit", pos, 0.7 + 0.3 * f)
		VFX.ShakeAt(pos, 0.3 + 0.7 * f, 60, 0.08)
	end

	-- the recoil: steam off him and down on one knee for a moment
	function Effects.GearshiftRecoil(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local time = tonumber(data.Time) or 0.6
		VFX.Pose(char, "Kneel", time)
		for i = 1, 6 do
			task.delay(i * time / 6, function()
				if root.Parent then
					celPuff(folder, root.Position + Vector3.new(rand(-1, 1), rand(0, 2), rand(-1, 1)), root.Position + UP * rand(4, 7), 1.2, Color3.fromRGB(200, 204, 210), Color3.new(1, 1, 1), 0.6, 0.8)
				end
			end)
		end
		VFX.PlaySound("Wind", root.Position, 0.5)
	end

	-- GEARED DOWN: Gearshift on someone else - the blue aura, the eyes
	-- glowing blue, slow as a crawl for a few seconds
	function Effects.GearedDown(char, data)
		local head = char and char:FindFirstChild("Head")
		if not head then
			return
		end
		local time = tonumber(data.Time) or 3
		local aura = Instance.new("Highlight")
		aura.FillColor = GS.GLOW
		aura.OutlineColor = GS.CORE
		aura.FillTransparency = 0.55
		aura.DepthMode = Enum.HighlightDepthMode.Occluded
		aura.Parent = char
		tween(aura, 0.5, { FillTransparency = 1, OutlineTransparency = 1 }, nil, nil, math.max(time - 0.5, 0))
		cleanup(aura, time + 0.1)
		local eyes = {}
		for side = -1, 1, 2 do
			local eye = newPart(Vector3.new(0.22, 0.12, 0.05), head.CFrame, GS.GLOW, Enum.Material.Neon)
			table.insert(eyes, { part = eye, off = CFrame.new(side * 0.22, 0.12, -head.Size.Z / 2 - 0.02) })
		end
		local t0 = os.clock()
		local conn
		conn = RunService.RenderStepped:Connect(function()
			if os.clock() - t0 > time or not head.Parent then
				conn:Disconnect()
				for _, e in eyes do
					e.part:Destroy()
				end
				return
			end
			for _, e in eyes do
				e.part.CFrame = head.CFrame * e.off
			end
		end)
		VFX.PlaySound("Snap", head.Position, 0.6)
	end

	-- DANGER SENSE (Deku at 100%, the 4th user's quirk): the manga's jagged
	-- lines round his head, a red flash, and he's already a step aside
	function Effects.DangerSense(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local head = char:FindFirstChild("Head")
		local at = head and head.Position or root.Position + UP * 1.5
		local RED = Color3.fromRGB(255, 70, 70)
		for i = 1, 9 do
			local a = i / 9 * math.pi * 2
			local out = Vector3.new(math.cos(a), rand(-0.2, 0.7), math.sin(a)).Unit
			local side = out:Cross(UP).Magnitude > 0.1 and out:Cross(UP).Unit or Vector3.new(1, 0, 0)
			local prev = at + out * 1.1
			for k = 1, 3 do
				local nxt = at + out * (1.1 + k * 0.7) + side * (k % 2 == 0 and 0.25 or -0.25)
				local seg = newPart(Vector3.new(0.09, 0.09, (nxt - prev).Magnitude + 0.05), CFrame.lookAt((prev + nxt) / 2, nxt), RED, Enum.Material.Neon)
				tween(seg, 0.35, { Transparency = 1 }, nil, nil, 0.1)
				cleanup(seg, 0.5)
				prev = nxt
			end
		end
		afterimage(char, RED, 0.3)
		VFX.PlaySound("Blink", at, 1)
		local me = Players.LocalPlayer
		if me and me.Character == char then
			VFX.Hooks.Callout("DANGER SENSE!", Color3.fromRGB(255, 90, 90))
			local from = typeof(data.From) == "Vector3" and data.From or root.Position - root.CFrame.LookVector
			local away = flatten(root.Position - from, root)
			local step = away:Cross(UP).Unit * (rng:NextNumber() < 0.5 and -1 or 1)
			dash(root, (step * 0.8 + away * 0.6).Unit * 70, 0.12)
		end
	end

	-- the gears run down to neutral by themselves
	function Effects.GearshiftDown(char)
		local root = charParts(char)
		if root then
			VFX.PlaySound("Snap", root.Position, 0.5)
		end
	end
end

-- V: Float (Nana Shimura's quirk). (round 75) Pressing it doesn't lift him:
-- gravity lets go of him - a pale swirl at his feet, the street's dust
-- drifting up round him - but he's on his feet till he jumps (his own
-- machine floats him: VFX.Hooks.FloatArm). Everyone sees the lift-off, the
-- Air Force flicks and the touch-down through FloatFX.
function Effects.Float(char, _data, isLocal, ability)
	local root, hum = charParts(char)
	if not root then
		return
	end
	local pale = Color3.fromRGB(236, 255, 246)
	VFX.Pose(char, "FloatIdle", 0.45)
	local g = groundPoint(root.Position)
	shockDisc(g + UP * 0.3, UP, 2, 16, 0.5, pale)
	billboardRing(root.Position - UP * 2.5, 1.5, 10, COWL_GREEN, 3, 0.4)
	VFX.PlaySound("ZeroG", root.Position, 0.7)
	-- weightless: the dust round him lifting off the street
	for _ = 1, 10 do
		local p = g + Vector3.new(rand(-5, 5), 0.2, rand(-5, 5))
		local mote = newPart(Vector3.one * rand(0.15, 0.35), CFrame.new(p), Color3.fromRGB(210, 220, 214), Enum.Material.SmoothPlastic, Enum.PartType.Ball)
		tween(mote, rand(1.2, 2), { Position = p + UP * rand(3, 7), Transparency = 1 }, Enum.EasingStyle.Sine, Enum.EasingDirection.Out)
		cleanup(mote, 2.1)
	end
	if isLocal then
		if VFX.Hooks.FloatArm then
			VFX.Hooks.FloatArm(ability)
		elseif hum then
			launch(root, hum, UP * ((ability and ability.Lift) or 18)) -- (no machine to fly him: a hop)
		end
	end
end

do
	VFX.FloatHover = setmetatable({}, { __mode = "k" }) -- [char] = the lift it's showing
	function Effects.FloatFX(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local pale = Color3.fromRGB(236, 255, 246)
		if data.Kind == "End" then
			VFX.FloatHover[char] = nil
			sparks(root.Position - UP * 2.5, 0.4, pale, COWL_GREEN, 6)
			return
		end
		if data.Kind == "Boost" then
			-- AIR FORCE flicked out behind him throws him down the aim
			local d = (typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.01) and data.Dir.Unit or root.CFrame.LookVector
			VFX.Pose(char, "Flick", 0.25)
			local back = root.Position - d * 2.5
			shockDisc(back, -d, 1.5, 12, 0.3, WIND, 3)
			billboardRing(back, 1, 9, COWL_CORE, 3, 0.25)
			streaks(back, -d, 6, 1.5, 8, 18, WIND, 0.25)
			afterimage(char, COWL_GREEN, 0.25)
			VFX.PlaySound("AirBullet", back, 0.9)
			return
		end
		-- the lift-off: up, soft as anything, and hanging there
		local token = {}
		VFX.FloatHover[char] = token
		local g = groundPoint(root.Position)
		shockDisc(g + UP * 0.3, UP, 3, 22, 0.45, pale)
		dustPuffs(g, 1, 6, Color3.fromRGB(206, 200, 190), 0.9, false)
		streaks(root.Position - UP * 2, -UP, 6, 2, 6, 10, WIND, 0.3)
		VFX.PlaySound("Leap", root.Position, 0.6)
		VFX.PlaySound("ZeroG", root.Position, 0.5)
		task.spawn(function()
			local t0 = os.clock()
			local last = root.Position
			while VFX.FloatHover[char] == token and root.Parent and os.clock() - t0 < 12 do
				local v = (root.Position - last) / 0.15
				last = root.Position
				VFX.Pose(char, v.Magnitude > 18 and "Skydive" or "FloatIdle", 0.4)
				-- Nana's quirk: a pale ring under him, motes drifting off him
				billboardRing(root.Position - UP * 2.7, 1.2, 5, pale, 2, 0.3)
				local m = newPart(Vector3.one * rand(0.12, 0.25), CFrame.new(root.Position + rng:NextUnitVector() * rand(1, 2.2)), pale, Enum.Material.Neon, Enum.PartType.Ball)
				tween(m, 0.7, { Position = m.Position + UP * rand(1, 2.5) - v * 0.05, Transparency = 1 })
				cleanup(m, 0.75)
				task.wait(0.15)
			end
			if VFX.FloatHover[char] == token then
				VFX.FloatHover[char] = nil
			end
		end)
	end
end

function Effects.GearshiftRush(char, data, isLocal, ability)
	local root = charParts(char)
	if not root then return end
	local d = flatten(data.Dir, root)
	if isLocal then face(root, d); dash(root, d * 65, 0.12) end
	afterimage(char, TEAL, 0.14)
	local left = limb(char, "LeftFoot", "Left Leg")
	local right = limb(char, "RightFoot", "Right Leg")
	briefTrail(left, 0.65, MINT, 0.45, 0.09)
	briefTrail(right, 0.65, WHITE, 0.45, 0.09)
	task.wait(0.12)
	local hits = (ability and ability.Hits) or 6
	for i = 1, hits do
		if not active(char) then return end
		VFX.Pose(char, i % 2 == 0 and "RainCross" or "PunchR", 0.075)
		local hand = handPos(char, i % 2 ~= 0)
		local endPoint = hand + d * 3.5
		curveStroke({ hand - d * 0.4, hand + UP * 0.3, endPoint }, 0.16, i % 2 == 0 and MINT or WHITE, 0.11)
		if i == 3 then afterimage(char, TEAL, 0.12) end
		VFX.PlaySound("Swing", hand, 0.42)
		task.wait(0.065)
	end
	if not active(char) then return end
	VFX.Motion(char, "StLouis")
	heelArc(root, d, 4.6, math.rad(75), WHITE)
	VFX.PlaySound("Kick", root.Position + d * 3, 0.8)
end

function Effects.BlackwhipSlam(char, data, isLocal, ability)
	local root = charParts(char)
	if not root then return end
	local d = flatten(data.Dir, root)
	if isLocal then face(root, d) end
	VFX.Motion(char, "WhipBind")
	VFX.PlaySound("Blackwhip", root.Position, 0.95)
	local range = (ability and ability.Range) or 55
	for k = -1, 1 do
		local dir = (CFrame.Angles(0, math.rad(k * 15), 0) * d).Unit
		local from = root.Position + UP
		local t0 = os.clock()
		VFX.whipRope(function()
			return active(char) and handPos(char, k >= 0) or nil
		end, function()
			local t = os.clock() - t0
			local reach = t < 0.18 and t / 0.18 or math.max(0, 1 - (t - 0.24) / 0.15)
			return from + dir * range * reach
		end, 0.4, { Wave = 0.65, Grow = 0.02, Thick = 0.28, Segments = 14, Color = TEAL, OutlineColor = POWER })
	end
end

function Effects.BlackwhipBind(char, data)
	local targets = type(data.Targets) == "table" and data.Targets or {}
	local slamDelay = data.SlamDelay or 0.6
	local duration = data.Duration or 0.75
	for i, target in targets do
		local troot = typeof(target) == "Instance" and target:FindFirstChild("HumanoidRootPart")
		if troot then
			VFX.whipRope(function()
				return active(char) and handPos(char, i % 2 == 0) or nil
			end, function()
				return troot.Parent and troot.Position or nil
			end, duration, { Wave = 0.6, Grow = 0.045, Thick = 0.3, Segments = 14, Color = TEAL, OutlineColor = POWER })
			task.delay(slamDelay, function()
				if active(char) and troot.Parent then
					local g = groundPoint(troot.Position)
					shockDisc(g + UP * 0.15, UP, 2, 17, 0.24, WHITE)
					sparks(g + UP, 0.4, WHITE, POWER, 8)
					dustPuffs(g, 0.6, 4, Color3.fromRGB(198, 200, 190), 0.55, false)
					rocks(g, 0.75, 4)
					VFX.PlaySound("Smash", g, 0.8)
					VFX.ShakeAt(g, 0.9, 42, 0.16)
				end
			end)
		end
	end
end

