	---------------------------------------------------------------------------

	SHOTS.MillionSmash = {
		{ T = 0.55, From = { V(2.5, 1.2, -4), V(0.8, 0.8, 0) }, To = { V(2, 1.4, -3), V(0.8, 0.9, 0) }, Fov = { 50, 38 } },
		{ T = 0.5, Cut = true, From = { V(-3, 2, 6), V(0, 2, -20) }, To = { V(-2, 2, 4), V(0, 2, -30) }, Fov = { 60, 70 } },
		{ T = 1.4, Cut = true, From = { V(40, 25, -40), V(0, 5, -90) }, To = { V(60, 45, -60), V(0, 5, -140) }, Fov = { 75, 80 } },
	}

	function Effects.MillionSmash(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		local ult = char:GetAttribute("UltActive") == true
		local range = ult and 300 or ((ability and ability.Range) or 230)
		cinematicFor(char, "MillionSmash", isLocal, (ability and ability.Name) or "1,000,000% SMASH", COWL_GREEN)
		VFX.Pose(char, "PunchCharge", 1)
		VFX.PlaySound("MillionCharge", root.Position, 1)
		-- the arm charges: green lightning and a golden glow in the fist
		task.spawn(chargeFist, char, root, 1, 1.8)
		local t0 = os.clock()
		local flicked = false
		while os.clock() - t0 < 1.05 and root.Parent do
			bolt(handPos(char, true), 2.2, COWL_GREEN)
			if rng:NextNumber() < 0.5 then
				bolt(root.Position + UP, 3, COWL_CORE)
			end
			if not flicked and os.clock() - t0 > 0.72 then
				-- DELAWARE... (the flick first)
				flicked = true
				VFX.Motion(char, "Flick")
				shockDisc(handPos(char, true), d, 1, 14, 0.2, WIND)
				sparks(handPos(char, true), 0.8, COWL_CORE, COWL_GREEN, 16)
				VFX.PlaySound("AirBullet", root.Position, 1.4)
				if isLocal then
					VFX.Hooks.Callout("DELAWARE...", COWL_GREEN)
				end
			end
			task.wait(0.05)
		end
		if not root.Parent then
			return
		end
		if isLocal then
			VFX.Hooks.Callout("DETROIT SMASH!!", Color3.fromRGB(255, 240, 150))
		end
		VFX.Motion(char, "DetroitSmash")
		local origin = root.Position + d * 3 + UP * 1.5
		if nearCamera(origin, 200) then
			VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.3)
			VFX.ImpactFrame(0.14)
		end
		windBlast(origin, d, 4)
		-- the wall of wind rolling down the street
		for i = 1, 14 do
			task.delay(i * 0.04, function()
				shockDisc(origin + d * i * 6, d, 20 + i * 2, 70 + i * 3, 0.9, WIND, range - i * 6)
			end)
		end
		streaks(origin, d, 60, 18, 26, range, WIND, 0.8)
		for s = 12, range, 18 do
			task.delay(s / 300, function()
				local right = d:Cross(UP)
				for _, off in { -1, 0, 1 } do
					local p = groundPoint(origin + d * s + right * off * (12 + s * 0.1))
					dustPuffs(p, 2.4 + s / 90, 4, Color3.fromRGB(206, 196, 186), 1.6, true)
				end
				if s % 36 == 12 then
					rocks(groundPoint(origin + d * s), 2, 6)
				end
			end)
		end
		VFX.PlaySound("MillionSmash", origin, 1.6)
		VFX.PlaySound("DetroitImpact", origin, 1.5)
		VFX.ShakeAt(origin, 6, 400, 1.2)
	end

	function Effects.ProminenceBurn(char, _data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		local ult = char:GetAttribute("UltActive") == true
		local radius = ult and 46 or ((ability and ability.Radius) or 36)
		VFX.Pose(char, "ArmsUp", 0.9)
		local torso = limb(char, "UpperTorso", "Torso") or root
		local stop = Flame.attach(torso, 4.5, 2)
		VFX.PlaySound("Prominence", root.Position, 1)
		task.wait(0.7)
		stop()
		if not root.Parent then
			return
		end
		local center = root.Position
		local g = groundPoint(center)
		if nearCamera(center, 120) then
			VFX.Hooks.Flash(Color3.fromRGB(255, 190, 110), 0.3)
		end
		if VFX.HF and VFX.HF.mono then
			VFX.HF.mono(center, 0.9) -- (so hot it goes black and white)
		end
		Flame.column(g, 120, radius * 0.35, 1.3)
		Flame.burst(center, radius * 0.3, 40)
		for i = 1, 14 do
			local a = i / 14 * math.pi * 2
			local out = Vector3.new(math.cos(a), 0, math.sin(a))
			task.delay(i * 0.01, function()
				Flame.burst(g + out * radius * rand(0.4, 0.8) + UP * 2, rand(5, 8), 10)
				Flame.spot(g + out * radius * rand(0.6, 1) + UP * 0.2, rand(3, 5), rand(1, 2), 3)
			end)
		end
		shockDisc(g + UP * 0.5, UP, 6, radius * 2.4, 0.5, Color3.fromRGB(255, 150, 60))
		billboardRing(center, 4, radius * 1.6, Color3.fromRGB(255, 200, 80), 12, 0.4)
		emberCloud(center + UP * 6, radius, 2.5, 90)
		VFX.ShakeAt(center, 4, 200, 0.8)
		if isLocal then
			VFX.Hooks.Callout("PROMINENCE BURN!!", Color3.fromRGB(255, 140, 40))
		end
	end

	-- a swirl of dark purple mist (Kurogiri)
	local function warpMist(pos, size, life)
		local disc = newPart(Vector3.new(0.3, 1, 1), CFrame.new(pos + UP * 0.15) * CFrame.Angles(0, 0, math.rad(90)), WARP_DARK, Enum.Material.Neon, Enum.PartType.Cylinder)
		disc.Transparency = 0.1
		tween(disc, 0.2, { Size = Vector3.new(0.3, size, size) })
		tween(disc, 0.3, { Size = Vector3.new(0.3, 0.5, 0.5), Transparency = 1 }, nil, nil, life)
		cleanup(disc, life + 0.35)
		for i = 1, 10 do
			local a = i / 10 * math.pi * 2
			local off = Vector3.new(math.cos(a) * size * 0.35, rand(0.5, 4), math.sin(a) * size * 0.35)
			celPuff(folder, pos, pos + off, rand(2.5, 4), WARP_DARK, WARP_MIST, 0.15, life, rand(0, 0.1))
		end
		smokeBurst(pos + UP * 2, WARP_MIST, 4, size * 0.4, life + 0.3, 20)
	end

	function Effects.WarpGate(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		local ult = char:GetAttribute("UltActive") == true
		local range = ult and 320 or ((ability and ability.Range) or 250)
		local target = aimGround(root, data, range)
		local d = flatten(data.Dir, root)
		VFX.Pose(char, "Cross", 0.45)
		warpMist(groundPoint(root.Position), 9, 0.5)
		warpMist(target, 9, 0.7)
		VFX.PlaySound("WarpGate", root.Position, 1)
		VFX.PlaySound("WarpGate", target, 1)
		task.wait(0.35)
		if not root.Parent then
			return
		end
		if isLocal then
			local dest = target + UP * 3.2
			root.CFrame = CFrame.lookAt(dest, dest + d)
			root.AssemblyLinearVelocity = Vector3.zero
		end
		sparks(target + UP * 2, 0.5, WARP_MIST, Color3.fromRGB(255, 230, 120), 16)
	end

	-- the Sky Coffin's warp gates: into the mist at one...
	function Effects.SkyWarp(char, data)
		local from = typeof(data.From) == "Vector3" and data.From
		if from then
			warpMist(from - UP * 3, 8, 0.5)
			VFX.PlaySound("WarpGate", from, 1)
		end
		if isMine(char) then
			VFX.Hooks.Callout(data.Up and "THE SKY COFFIN" or "BACK TO THE CITY", data.Up and Color3.fromRGB(255, 214, 90) or WARP_MIST)
		end
	end
	-- ...and out of the other (sent once they're there, so the camera's there too)
	function Effects.SkyWarpOut(_, data)
		local to = typeof(data.To) == "Vector3" and data.To
		if to then
			warpMist(to - UP * 3, 8, 0.6)
			VFX.PlaySound("WarpGate", to, 1)
		end
	end

	-- Eri's Rewind: golden rings closing in, time running backwards
	function Effects.Rewind(char)
		local root = charParts(char)
		if not root then
			return
		end
		VFX.PlaySound("Rewind", root.Position, 1)
		VFX.Pose(char, "Present", 0.6)
		for i = 0, 5 do
			task.delay(i * 0.08, function()
				if root.Parent then
					billboardRing(root.Position, 22 - i * 2, 1, REWIND_GOLD, 6, 0.35)
				end
			end)
		end
		sparks(root.Position, 0.6, REWIND_GOLD, HEAL_GREEN, 30)
		if nearCamera(root.Position, 60) then
			VFX.Hooks.Flash(REWIND_GOLD, 0.2)
		end
		if isMine(char) then
			VFX.Hooks.Callout("REWIND!", REWIND_GOLD)
		end
	end

	function Effects.NewOrder(char, _data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		VFX.Pose(char, "ArmsUp", 0.6)
		VFX.PlaySound("NewOrder", root.Position, 1)
		local g = groundPoint(root.Position)
		shockDisc(g + UP * 1, UP, 6, 200, 0.7, STAR_BLUE)
		shockDisc(g + UP * 1.5, UP, 4, 160, 0.55, Color3.new(1, 1, 1))
		billboardRing(root.Position, 4, 40, STAR_BLUE, 10, 0.45)
		sparks(root.Position + UP * 2, 1, Color3.new(1, 1, 1), STAR_BLUE, 40)
		if isLocal then
			VFX.Hooks.Callout("NEW ORDER: FLOAT!", STAR_BLUE)
		end
	end

	function Effects.NewOrderFloat(_, data)
		for _, model in type(data.Targets) == "table" and data.Targets or {} do
			if typeof(model) == "Instance" then
				aura(model, STAR_BLUE, data.Time or 2.6, 24, 1)
			end
		end
	end

	function Effects.NewOrderSlam(_, data)
		task.wait(0.35)
		for _, model in type(data.Targets) == "table" and data.Targets or {} do
			local r = typeof(model) == "Instance" and model:FindFirstChild("HumanoidRootPart")
			if r then
				local g = groundPoint(r.Position)
				shockDisc(g + UP * 0.5, UP, 3, 24, 0.4, WIND)
				dustPuffs(g, 1.4, 5, Color3.fromRGB(206, 196, 186), 1, true)
				rocks(g, 1.2, 4)
				VFX.PlaySound("NewOrderSlam", g, 0.8)
			end
		end
	end

	---------------------------------------------------------------------------
	-- Food: eating, the snack machines, and the shopkeeper's speech bubble
	---------------------------------------------------------------------------

	function Effects.Eat(char, data)
		local root = charParts(char)
		local item = Config.Items[data.Item or ""]
		if not root or not item then
			return
		end
		VFX.Pose(char, "Drink", 0.7)
		local hand = limb(char, "RightHand", "Right Arm")
		local food
		if data.Item == "PizzaSlice" then
			food = newPart(Vector3.new(0.15, 0.9, 1.2), CFrame.new(handPos(char, true)), Color3.fromRGB(245, 200, 100), Enum.Material.SmoothPlastic)
			local wedge = Instance.new("SpecialMesh")
			wedge.MeshType = Enum.MeshType.Wedge
			wedge.Parent = food
		elseif data.Item == "WholePizza" then
			food = newPart(Vector3.new(1.8, 0.3, 1.8), CFrame.new(handPos(char, true)), Color3.fromRGB(190, 150, 100), Enum.Material.Cardboard)
		else
			food = newPart(Vector3.new(0.6, 0.8, 0.25), CFrame.new(handPos(char, true)), item.Color or Color3.new(1, 1, 1), Enum.Material.SmoothPlastic)
		end
		local t0 = os.clock()
		task.spawn(function()
			while os.clock() - t0 < 0.7 and food.Parent and hand and hand.Parent do
				food.CFrame = hand.CFrame * CFrame.new(0, -hand.Size.Y / 2 - 0.2, -0.3)
				task.wait()
			end
			food:Destroy()
		end)
		VFX.PlaySound(item.Sound or "Munch", root.Position, 1)
		task.wait(0.5)
		if root.Parent then
			sparks(root.Position, 0.35, HEAL_GREEN, Color3.new(1, 1, 1), 16)
			floatText(root.Position + UP * 3, data.Item == "WholePizza" and "FULL HP" or ("+" .. tostring(data.Heal or item.Heal)), HEAL_GREEN)
		end
	end

	-- where a snack machine stands (its feet, facing out)
	local function machineBase(machine)
		local body = typeof(machine) == "Instance" and machine:FindFirstChild("Body")
		return body and body.CFrame * CFrame.new(0, -3.2, 0) or nil
	end

	-- the snack falls off its shelf into the flap
	function Effects.Vend(_, data)
		local base = machineBase(data.Machine)
		local item = Config.Items[data.Item or ""]
		if not base then
			return
		end
		VFX.PlaySound("Vend", base.Position + UP * 3, 1)
		local snack = newPart(Vector3.new(0.5, 0.7, 0.18), base * CFrame.new(-0.5, 4.6, -1.4), item and item.Color or Color3.new(1, 1, 1))
		tween(snack, 0.4, { CFrame = base * CFrame.new(-0.5, 1.05, -1.4) * CFrame.Angles(math.rad(80), 0, 0) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
		cleanup(snack, 0.9)
	end

	-- punched: the whole machine rocks back and forth for a moment
	local shaking = setmetatable({}, { __mode = "k" })
	function Effects.MachineHit(_, data)
		local machine = data.Machine
		local base = machineBase(machine)
		if not base or shaking[machine] then
			return
		end
		shaking[machine] = true
		VFX.PlaySound("MachineHit", base.Position + UP * 3, 1)
		sparks(base.Position + UP * 3 + base.LookVector * 1.6, 0.3, Color3.new(1, 1, 1), Color3.fromRGB(255, 200, 120), 8)
		local parts = {}
		for _, p in machine:GetDescendants() do
			if p:IsA("BasePart") then
				parts[p] = base:ToObjectSpace(p.CFrame)
			end
		end
		for i = 1, 6 do
			local tilt = CFrame.Angles(math.rad((i % 2 == 0 and 1 or -1) * (7 - i) * 0.9), 0, 0)
			for p, rel in parts do
				if p.Parent then
					p.CFrame = base * tilt * rel
				end
			end
			task.wait(0.04)
		end
		for p, rel in parts do
			if p.Parent then
				p.CFrame = base * rel
			end
		end
		shaking[machine] = nil
	end

	-- the free snack flies out of the flap and lands on the pavement
	function Effects.SnackDrop(_, data)
		local to = data.Pos
		local base = machineBase(data.Machine)
		local item = Config.Items[data.Item or ""]
		if typeof(to) ~= "Vector3" or not base then
			return
		end
		local from = (base * CFrame.new(-0.5, 1.05, -1.7)).Position
		local flying = newPart(Vector3.new(0.9, 0.9, 0.9), CFrame.new(from), item and item.Color or Color3.new(1, 1, 1))
		local t0 = os.clock()
		while os.clock() - t0 < 0.4 do
			local k = (os.clock() - t0) / 0.4
			flying.CFrame = CFrame.new(from:Lerp(to, k) + UP * math.sin(math.pi * k) * 3) * CFrame.Angles(k * 9, k * 5, 0)
			task.wait()
		end
		flying:Destroy()
		dustPuffs(to, 0.4, 3, Color3.fromRGB(220, 215, 205), 0.6, false)
		floatText(to + UP * 2, "FREE SNACK!", Color3.fromRGB(255, 220, 90))
	end

	-- a speech bubble over a shopkeeper's head (and a wave)
	local bubbles = setmetatable({}, { __mode = "k" })
	function Effects.NpcSay(_, data)
		local npc = data.Npc
		local head = typeof(npc) == "Instance" and npc:FindFirstChild("Head")
		if not head then
			return
		end
		if bubbles[npc] then
			bubbles[npc]:Destroy()
		end
		local bb = Instance.new("BillboardGui")
		bb.Name = "SpeechBubble"
		bb.Size = UDim2.fromOffset(260, 70)
		bb.StudsOffset = Vector3.new(0, 3.6, 0)
		bb.MaxDistance = 70
		bb.Adornee = head
		local box = Instance.new("TextLabel")
		box.Size = UDim2.fromScale(1, 1)
		box.BackgroundColor3 = Color3.new(1, 1, 1)
		box.Font = Enum.Font.GothamBold
		box.TextColor3 = Color3.fromRGB(30, 30, 36)
		box.TextScaled = true
		box.TextWrapped = true
		box.Text = tostring(data.Text or "")
		box.Parent = bb
		local corner = Instance.new("UICorner")
		corner.CornerRadius = UDim.new(0, 14)
		corner.Parent = box
		local pad = Instance.new("UIPadding")
		pad.PaddingLeft = UDim.new(0, 10)
		pad.PaddingRight = UDim.new(0, 10)
		pad.PaddingTop = UDim.new(0, 6)
		pad.PaddingBottom = UDim.new(0, 6)
		pad.Parent = box
		bb.Parent = folder
		bubbles[npc] = bb
		cleanup(bb, 4)
		VFX.Pose(npc, "Wave", 0.9)
		VFX.PlaySound("Bell", head.Position, 0.6)
	end

	---------------------------------------------------------------------------
	-- Dev toys
	---------------------------------------------------------------------------

	function Effects.MoneyRain(_, data)
		local pos = data.Pos
		if typeof(pos) ~= "Vector3" then
			return
		end
		VFX.PlaySound("Bucks", pos, 1)
		for _ = 1, 40 do
			local start = pos + Vector3.new(rand(-12, 12), rand(14, 26), rand(-12, 12))
			local bill = newPart(Vector3.new(1.2, 0.05, 0.55), CFrame.new(start) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)), MONEY_GREEN)
			local fall = rand(1.6, 2.6)
			local land = groundPoint(start) + UP * 0.1
			tween(bill, fall, { CFrame = CFrame.new(land) * CFrame.Angles(0, rand(0, 6), 0) }, Enum.EasingStyle.Sine, Enum.EasingDirection.In)
			tween(bill, 0.5, { Transparency = 1 }, nil, nil, fall + 1)
			cleanup(bill, fall + 1.6)
		end
	end

	function Effects.Boing(char)
		local head = char and char:FindFirstChild("Head")
		if head then
			VFX.PlaySound("Boing", head.Position, 1)
			sparks(head.Position, 0.4, Color3.fromRGB(255, 160, 220), Color3.new(1, 1, 1), 16)
		end
	end

	function Effects.Launch(_, data)
		local r = typeof(data.Target) == "Instance" and data.Target:FindFirstChild("HumanoidRootPart")
		if r then
			local g = groundPoint(r.Position)
			dustPuffs(g, 1.2, 5, Color3.fromRGB(206, 196, 186), 1, true)
			shockDisc(g + UP * 0.5, UP, 3, 18, 0.35, WIND)
			VFX.PlaySound("Launch", g, 0.8)
		end
	end

	---------------------------------------------------------------------------
	-- DISCO PARTY: a mirror ball, sweeping coloured lights, music, and
	-- everyone standing around nearby dances on the beat
	---------------------------------------------------------------------------

	local DISCO_COLORS = {
		Color3.fromRGB(255, 60, 120), Color3.fromRGB(60, 200, 255), Color3.fromRGB(255, 220, 60),
		Color3.fromRGB(120, 255, 120), Color3.fromRGB(190, 90, 255), Color3.fromRGB(255, 140, 40),
	}
	local DANCES = { "Dance1", "Dance2", "Dance3", "Dance4" }
	local BEAT = 0.5
	local discoToken = 0

	function VFX.SetDisco(on, center)
		discoToken += 1
		local token = discoToken
		local old = folder:FindFirstChild("DiscoParty")
		if old then
			old:Destroy()
		end
		local tint = game:GetService("Lighting"):FindFirstChild("DiscoTint")
		if not on then
			if tint then
				tint:Destroy()
			end
			return
		end
		center = typeof(center) == "Vector3" and center or Vector3.zero
		local party = Instance.new("Model")
		party.Name = "DiscoParty"
		party.Parent = folder
		local ballPos = center + UP * 16
		local ball = newPart(Vector3.one * 5, CFrame.new(ballPos), Color3.fromRGB(220, 224, 235), Enum.Material.Foil, Enum.PartType.Ball, party)
		ball.Reflectance = 0.7
		newPart(Vector3.new(0.15, 30, 0.15), CFrame.new(ballPos + UP * 17), Color3.fromRGB(60, 60, 66), nil, nil, party)
		local glitter = Instance.new("ParticleEmitter")
		glitter.Texture = "rbxasset://textures/particles/sparkles_main.dds"
		glitter.LightEmission = 1
		glitter.Size = NumberSequence.new(0.5, 0)
		glitter.Speed = NumberRange.new(20, 40)
		glitter.SpreadAngle = Vector2.new(180, 180)
		glitter.Lifetime = NumberRange.new(0.3, 0.6)
		glitter.Rate = 40
		glitter.Parent = ball
		local beams = {}
		for i = 1, 6 do
			local b = newPart(Vector3.new(0.6, 0.6, 30), CFrame.new(ballPos), DISCO_COLORS[i], Enum.Material.Neon, nil, party)
			b.Transparency = 0.55
			local light = Instance.new("PointLight")
			light.Color = DISCO_COLORS[i]
			light.Range = 18
			light.Brightness = 2
			light.Parent = b
			beams[i] = b
		end
		local music = Instance.new("Sound")
		music.SoundId = Config.Music and Config.Music.Disco or ""
		music.Looped = true
		music.Volume = 0.7
		music.RollOffMaxDistance = 260
		music.RollOffMinDistance = 30
		music.Parent = ball
		music:Play()
		if not tint then
			tint = Instance.new("ColorCorrectionEffect")
			tint.Name = "DiscoTint"
			tint.Parent = game:GetService("Lighting")
		end
		task.spawn(function()
			local t0 = os.clock()
			local nextBeat = 0
			local beat = 0
			while discoToken == token and party.Parent do
				local t = os.clock() - t0
				ball.CFrame = CFrame.new(ballPos) * CFrame.Angles(0, t * 1.5, 0)
				for i, b in beams do
					local a = t * 1.3 + i / #beams * math.pi * 2
					local tilt = 0.55 + 0.3 * math.sin(t * 0.9 + i)
					local dir = Vector3.new(math.cos(a) * math.cos(tilt), -math.sin(tilt), math.sin(a) * math.cos(tilt))
					b.CFrame = CFrame.lookAt(ballPos + dir * 17, ballPos + dir * 34)
				end
				-- the whole scene takes on the colour of the beat
				local near = false
				local cam = workspace.CurrentCamera
				if cam then
					near = (cam.CFrame.Position - center).Magnitude < 120
				end
				tint.TintColor = near and Color3.new(1, 1, 1):Lerp(DISCO_COLORS[beat % #DISCO_COLORS + 1], 0.25) or Color3.new(1, 1, 1)
				if t >= nextBeat then
					nextBeat = t + BEAT
					beat += 1
					for i, target in characterList() do
						if target ~= folder and target:IsA("Model") then
							local root = target:FindFirstChild("HumanoidRootPart")
							local hum = target:FindFirstChildOfClass("Humanoid")
							if root and hum and hum.Health > 0 and (root.Position - center).Magnitude < 70
								and root.AssemblyLinearVelocity.Magnitude < 3 and not target:GetAttribute("Stunned") then
								VFX.Pose(target, DANCES[(beat + i) % #DANCES + 1], BEAT + 0.1)
							end
						elseif target.Name == "Dummies" then
							-- dummies dance too
							for j, dummy in target:GetChildren() do
								local root = dummy:FindFirstChild("HumanoidRootPart")
								if root and (root.Position - center).Magnitude < 70 and root.AssemblyLinearVelocity.Magnitude < 3 then
									VFX.Pose(dummy, DANCES[(beat + j) % #DANCES + 1], BEAT + 0.1)
								end
							end
						end
					end
				end
				task.wait()
			end
		end)
	end
end
addItemEffects()

---------------------------------------------------------------------------
-- Dispatcher
---------------------------------------------------------------------------

-- effects whose animation belongs to the target rather than the caster
---------------------------------------------------------------------------
-- LEMILLION: Permeation. A copy of his body drops through the street (the
-- street itself hides it as it goes under) while the real one is hidden and
-- held by the server; coming back out, a copy rises out of the ground and the
-- real body takes its place. Phasing (Permeate, the Prediction stance) makes
-- him a see-through ghost with a golden outline.
---------------------------------------------------------------------------
do
	-- (a few tables rather than many locals: this file sits at Luau's
	-- 200-locals-in-scope limit)
	local C = {
		GOLD = Color3.fromRGB(255, 214, 60),
		PHASE = Color3.fromRGB(255, 240, 196),
		RED = Color3.fromRGB(214, 40, 44),
		DIRT = Color3.fromRGB(196, 186, 172),
		SINK = 0.3,
		STRIKES = { "PunchR", "Kick", "PunchL", "PunchR", "Kick", "PunchL", "AxeKick", "FinishUppercut" },
	}
	local S = {
		hide = setmetatable({}, { __mode = "k" }), -- [char] = os.clock() it stays hidden until
		fade = setmetatable({}, { __mode = "k" }), -- [char] = os.clock() it stays see-through until
		look = {}, -- [char] = { Glow = Highlight }
	}
	local Lem = {}

	function Lem.isMine(char)
		local me = Players.LocalPlayer
		return me ~= nil and char ~= nil and me.Character == char
	end

	-- this form's version of a move (the ult has bigger ones)
	function Lem.ability(char, id)
		local quirk = Config.Quirks.Lemillion
		local set = (char:GetAttribute("UltActive") and quirk.Ult.Abilities) or quirk.Abilities
		for _, a in set do
			if a.Id == id then
				return a
			end
		end
		return Config.FindAbilityById(id) or {}
	end

	function Lem.setAlpha(char, alpha)
		for _, d in char:GetDescendants() do
			if (d:IsA("BasePart") and d.Name ~= "HumanoidRootPart") or d:IsA("Decal") then
				d.LocalTransparencyModifier = alpha
			end
		end
	end

	-- a still copy of the body as it stands right now (clothes, hair, gear)
	function Lem.double(char)
		local was = char.Archivable
		char.Archivable = true
		local ok, copy = pcall(char.Clone, char)
		char.Archivable = was
		if not ok or not copy then
			return nil
		end
		for _, d in copy:GetDescendants() do
			if d:IsA("LuaSourceContainer") or d:IsA("Sound") or d:IsA("ParticleEmitter") or d:IsA("Highlight")
				or d:IsA("BillboardGui") or d:IsA("Constraint") or d:IsA("Trail") then
				d:Destroy()
			elseif d:IsA("BasePart") then
				d.Anchored = true
				d.CanCollide = false
				d.CanQuery = false
				d.CanTouch = false
				d.CastShadow = false
				d.LocalTransparencyModifier = 0
				if d.Name == "HumanoidRootPart" then
					d.Transparency = 1
				end
			elseif d:IsA("Decal") then
				d.LocalTransparencyModifier = 0
			end
		end
		local hum = copy:FindFirstChildOfClass("Humanoid")
		if hum then
			hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
			hum.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff
			hum.EvaluateStateMachine = false
		end
		copy.Name = "PhaseDouble"
		copy.Parent = folder
		return copy
	end

	-- move a copy from one place to another over `time` (eased), then remove it
	function Lem.glide(copy, from, to, time, style)
		if not copy then
			return
		end
		copy:PivotTo(from)
		task.spawn(function()
			local t0 = os.clock()
			while copy.Parent and os.clock() - t0 < time do
				local a = TweenService:GetValue(math.clamp((os.clock() - t0) / time, 0, 1), style or Enum.EasingStyle.Quad, Enum.EasingDirection.In)
				copy:PivotTo(from:Lerp(to, a))
				task.wait()
			end
			copy:Destroy()
		end)
	end

	function Lem.ripple(g, size, color)
		shockDisc(g + UP * 0.15, UP, 1, size, 0.35, color or C.PHASE)
		billboardRing(g + UP * 0.3, size * 0.3, size, C.GOLD, 2, 0.3)
		dustPuffs(g, 0.5, 3, C.DIRT, 0.5, false)
	end

	-- down through the street
	function Lem.sink(char, root, time, extraHidden)
		local copy = Lem.double(char)
		S.hide[char] = os.clock() + time + (extraHidden or 0)
		local pivot = char:GetPivot()
		Lem.glide(copy, pivot, pivot - UP * 6.5, time, Enum.EasingStyle.Quad)
		Lem.ripple(groundPoint(root.Position), 9)
		VFX.PlaySound("PhaseSink", root.Position, 1)
	end

	-- up out of it, at cf (where the real body is about to be)
	function Lem.rise(char, cf, time)
		local copy = Lem.double(char)
		local g = groundPoint(cf.Position)
		Lem.glide(copy, cf - UP * 6, cf, time, Enum.EasingStyle.Quart)
		Lem.ripple(g, 10, C.GOLD)
		streaks(g + UP, UP, 10, 1.5, 6, 14, C.PHASE, 0.3)
		dustPuffs(g, 1, 5, C.DIRT, 0.8, true)
		VFX.PlaySound("PhaseOut", g, 1)
	end

	-- hidden / see-through bodies, kept up every frame (the camera resets the
	-- local body's transparency as it zooms)
	RunService:BindToRenderStep("LemillionPhase", Enum.RenderPriority.Camera.Value + 2, function()
		local now = os.clock()
		for _, plr in Players:GetPlayers() do
			local char = plr.Character
			if not char or gone(char) then
				continue
			end
			local hidden = char:GetAttribute("Submerged") == true or (S.hide[char] or 0) > now
			local phasing = char:GetAttribute("Phasing") == true or char:GetAttribute("Countering") == true
			local faded = (S.fade[char] or 0) > now
			local st = S.look[char]
			if hidden or phasing or faded then
				if not st then
					st = {}
					S.look[char] = st
				end
				Lem.setAlpha(char, hidden and 1 or 0.55)
				if phasing and not hidden then
					if not st.Glow or not st.Glow.Parent then
						local h = Instance.new("Highlight")
						h.Name = "PhaseGlow"
						h.FillColor = C.PHASE
						h.OutlineColor = C.GOLD
						h.FillTransparency = 0.75
						h.OutlineTransparency = 0.15
						h.DepthMode = Enum.HighlightDepthMode.Occluded
						h.Adornee = char
						h.Parent = folder
						st.Glow = h
					end
				elseif st.Glow then
					st.Glow:Destroy()
					st.Glow = nil
				end
			elseif st then
				Lem.setAlpha(char, 0)
				if st.Glow then
					st.Glow:Destroy()
				end
				S.look[char] = nil
			end
		end
		for char, st in S.look do
			if gone(char) then
				if st.Glow then
					pcall(st.Glow.Destroy, st.Glow)
				end
				S.look[char] = nil
			end
		end
	end)

