		{ T = 0.8, Cut = true, From = { V(-24, -29, -24), V(0, -33, 0) }, To = { V(-32, -24, -32), V(0, -31, 0) }, Fov = { 70, 82 }, Style = Enum.EasingStyle.Quad },
