	-- CHICKEN KICK -----------------------------------------------------------
	function Effects.ChickenKick(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		if data.Air then
			SE.bambooSweep(char, root, d, isLocal) -- (round 59: 1 in the air)
			return
		end
		SE.chickenLeg(char, true, 1.35, 0.75)
		VFX.Motion(char, "ChickenKick")
		SE.pop(root.Position - UP * 2 + d, 1)
		task.wait(0.15)
		if not root.Parent then
			return
		end
		local front = root.Position + d * 3
		shockDisc(front + UP * 1.5, UP, 2, 14, 0.25, SE.TALON, 8)
		streaks(front, UP, 12, 2, 7, 18, WIND, 0.3)
		billboardRing(front + UP * 2, 2, 12, Color3.new(1, 1, 1), 6, 0.2)
		dustPuffs(groundPoint(root.Position + d * 2), 0.9, 5, Color3.fromRGB(205, 196, 190), 0.7, false)
		VFX.PlaySound("ChickenKick", front, 1)
		VFX.ShakeAt(front, 1.3, 50, 0.2)
	end

	-- TAKO SNATCH ------------------------------------------------------------
	-- the arm shoots out along the aim (his own screen: straight away), then
	-- the server says who it caught
	function Effects.TakoSnatch(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		local aim = Config.AimedDirection(data.Dir, d, { Up = 75, Down = 30 })
		if isLocal then
			face(root, d)
		end
		VFX.Pose(char, aim.Y > 0.35 and "TentacleCastUp" or "TentacleCast", 0.6)
		SE.pop(handPos(char, true), 1)
		VFX.PlaySound("Tentacle", root.Position, 1)
		local reach = (ability and ability.Range) or 45
		SE.reach(char, 0.9, 11, root.Position + UP * 1.5 + aim * reach, 1.8, math.min(reach / 160, 0.28) + 0.12)
	end

	function Effects.TakoSnatchCatch(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		if not SE.arms[char] then
			-- (they never saw it go out: it reaches for them now)
			local reach = tonumber(data.Reach) or 30
			local dir = typeof(data.Dir) == "Vector3" and data.Dir.Unit or root.CFrame.LookVector
			SE.reach(char, 0.9, 11, root.Position + UP * 1.5 + dir * reach, 1.8, 0.1)
		end
		if not target then
			if typeof(data.Swing) == "Vector3" then
				return -- (it latched onto a building: TakoSwing takes it from here)
			end
			local arm = SE.arms[char]
			if arm then
				arm.retract = os.clock() + 0.05
			end
			return
		end
		SE.caught(char, target, 0.55, 3)
		VFX.Pose(char, "ThrashUp", 0.3)
		task.delay(0.26, function()
			if char.Parent then
				VFX.Pose(char, "ThrashRight", 0.35)
			end
		end)
	end

	-- ...it hit a building instead: the tentacle holds on to it and he swings
	-- off it (his own screen swings him; everyone sees the tentacle)
	function Effects.TakoSwing(char, data)
		local root = charParts(char)
		local anchor = typeof(data.Anchor) == "Vector3" and data.Anchor
		if not root or not anchor then
			return
		end
		local time = tonumber(data.Time) or 1
		local arm = SE.reach(char, 0.8, 11, anchor, 0.3, 0.06)
		arm.life = time + 0.2
		VFX.Pose(char, "SwingHang", time)
		SE.pop(anchor, 0.8)
		VFX.PlaySound("Tentacle", anchor, 0.9)
		if Players.LocalPlayer and char == Players.LocalPlayer.Character then
			VFX.Swing(char, anchor, {
				Time = time,
				OnEnd = function()
					if SE.arms[char] == arm then
						arm.retract = os.clock()
					end
				end,
			})
		end
	end


	-- (round 60) ...it hit a building instead: THE ZIP. The tentacle holds on
	-- and reels him in to it (his own screen moves him; everyone sees the
	-- tentacle, and his body fly along it). A jump on the way: the point launch.
	POSES.ZipPull = { RightArm = { 160, 0, 4 }, RightElbow = 4, LeftArm = { 40, 0, 30 }, LeftElbow = 50, Waist = { -16, 0, 0 }, Neck = { -14, 0, 0 }, RightLeg = -24, LeftLeg = 18, RightKnee = 30, LeftKnee = 55 }
	POSES.ZipCling = { RightArm = { 150, 0, 16 }, RightElbow = 30, LeftArm = { 140, 0, 20 }, LeftElbow = 40, Waist = { 6, 0, 0 }, Neck = { -8, 0, 0 }, RightLeg = 30, LeftLeg = 12, RightKnee = 70, LeftKnee = 45 }
	POSES.ZipLaunch = { RightArm = { 170, 0, 30 }, LeftArm = { 170, 0, 30 }, RightElbow = 10, LeftElbow = 10, Waist = { 26, 0, 0 }, Neck = { 16, 0, 0 }, RightLeg = 80, LeftLeg = 80, RightKnee = 110, LeftKnee = 110 }
	function Effects.TakoZip(char, data)
		local root = charParts(char)
		local anchor = typeof(data.Anchor) == "Vector3" and data.Anchor
		if not root or not anchor then
			return
		end
		local spec = (Config.FindAbilityById and Config.FindAbilityById("TakoSnatch") or {}).Zip or {}
		local arm = SE.reach(char, 0.8, 11, anchor, 0.1, 0.05)
		arm.life = (spec.MaxTime or 1.4) + (spec.Cling or 0.45) + 0.4
		VFX.Pose(char, "ZipPull", spec.MaxTime or 1.4)
		SE.pop(anchor, 0.8)
		VFX.PlaySound("ZipPull", root.Position, 1)
		local function letGo()
			if SE.arms[char] == arm then
				arm.retract = os.clock()
			end
		end
		if Players.LocalPlayer and char == Players.LocalPlayer.Character then
			local st
			st = VFX.Zip(char, anchor, {
				Normal = data.Normal,
				Ledge = data.Ledge == true,
				Speed = spec.Speed, Accel = spec.Accel, MaxTime = spec.MaxTime, Cling = spec.Cling,
				LaunchUp = spec.LaunchUp, LaunchForward = spec.LaunchForward,
				OnLaunch = function()
					letGo()
					VFX.Pose(char, "ZipLaunch", 0.45)
					VFX.PlaySound("ZipLaunch", root.Position, 1)
					streaks(root.Position, UP, 6, 1, 5, 12, SE.TENT, 0.25)
				end,
				OnEnd = function(launched)
					letGo()
					if not launched then
						VFX.ReleasePose(char, 0.2)
					end
				end,
			})
			if st then
				-- (on the wall: hands on it)
				task.spawn(function()
					while VFX.Zipping(char) and char.Parent do
						if st.clinging then
							VFX.Pose(char, "ZipCling", 0.2)
						end
						task.wait(0.1)
					end
				end)
			else
				letGo()
			end
		else
			-- (someone else: the tentacle lets go once they'd be there)
			task.delay(math.min((anchor - root.Position).Magnitude / 110 + 0.35, (spec.MaxTime or 1.4) + 0.3), letGo)
		end
	end

	-- a tentacle slams someone into the street
	function Effects.TentacleSlam(_, data)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos
		if not pos then
			return
		end
		local big = data.Big == true
		shockDisc(pos + UP * 0.4, UP, 2, big and 22 or 14, 0.3, SE.TENT)
		dustPuffs(pos, big and 1.3 or 0.9, big and 8 or 5, Color3.fromRGB(205, 196, 190), 0.9, false)
		rocks(pos, big and 1.2 or 0.8, big and 7 or 4)
		groundMark(pos, big and 4 or 3, Color3.fromRGB(58, 52, 50), 4)
		VFX.PlaySound("TentacleSlam", pos, 1)
		VFX.ShakeAt(pos, big and 2 or 1.3, 70, 0.25)
	end

	-- TAKO THRASH ------------------------------------------------------------
	function Effects.TakoThrash(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		if data.Air then
			SE.urchin(char, root, isLocal) -- (round 59: 3 in the air)
			return
		end
		VFX.Pose(char, "ThrashHold", 0.4)
		SE.pop(handPos(char, true), 1.4)
		VFX.PlaySound("Tentacle", root.Position, 1.1)
		SE.reach(char, 1.5, 12, root.Position + d * 14 + UP * 0.5, 4, 0.18)
	end

	function Effects.TakoThrashCatch(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		if not SE.arms[char] then
			local d = flatten(data.Dir, root)
			SE.reach(char, 1.5, 12, root.Position + d * 14, 4, 0.08)
		end
		if not target then
			local arm = SE.arms[char]
			if arm then
				arm.retract = os.clock()
			end
			return
		end
		SE.caught(char, target, 0.8, 4)
		VFX.Motion(char, "TakoThrash")
	end

	-- SNACK (R) ---------------------------------------------------------------
	function Effects.Snack(char, _data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		VFX.Pose(char, "Eat", 0.6)
		-- a takoyaki ball (or a clam, or a drumstick) out of a pouch and down
		local kind = rng:NextInteger(1, 3)
		local food
		if kind == 1 then
			food = newPart(Vector3.one * 0.7, CFrame.new(handPos(char, true)), Color3.fromRGB(196, 134, 64), Enum.Material.SmoothPlastic, Enum.PartType.Ball)
			local sauce = newPart(Vector3.new(0.72, 0.2, 0.72), CFrame.new(handPos(char, true)), Color3.fromRGB(80, 44, 24), Enum.Material.SmoothPlastic, Enum.PartType.Ball)
			SE.attach(food, sauce, CFrame.new(0, 0.22, 0))
			sauce.Parent = food
		elseif kind == 2 then
			food = newPart(Vector3.new(0.8, 0.35, 0.7), CFrame.new(handPos(char, true)), SE.SHELL, Enum.Material.Slate)
			local m = Instance.new("SpecialMesh")
			m.MeshType = Enum.MeshType.Sphere
			m.Parent = food
		else
			food = newPart(Vector3.new(0.5, 1, 0.5), CFrame.new(handPos(char, true)), Color3.fromRGB(190, 110, 50), Enum.Material.SmoothPlastic)
		end
		local hand = SE.limb(char, "RightArm")
		if hand then
			SE.attach(hand, food, CFrame.new(0, -hand.Size.Y / 2 - 0.3, -0.3))
		end
		VFX.PlaySound("Snack", root.Position, 1)
		task.wait(0.45)
		if food.Parent then
			tween(food, 0.12, { Size = food.Size * 0.1, Transparency = 1 })
			cleanup(food, 0.15)
		end
		if root.Parent then
			dustPuffs(root.Position + UP * 1.5 + root.CFrame.LookVector, 0.3, 3, Color3.fromRGB(200, 150, 90), 0.4, false)
			if isLocal and not char:GetAttribute("Stunned") then
				VFX.Hooks.Callout("MUNCH! +STOMACH", Color3.fromRGB(255, 210, 140))
			end
		end
	end

	-- SWORDFISH / CLAM HAMMER ---------------------------------------------------
	function Effects.Swordfish(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		if data.Air then
			-- CLAM HAMMER: both fists up and closed into a clamshell, a beat of
			-- hang time, then brought down - he drops with it
			SE.hammer(char, 0.85)
			VFX.Motion(char, "ClamHammer")
			SE.pop(root.Position + UP * 4, 1.2)
			VFX.PlaySound("Manifest", root.Position, 1)
			if isLocal then
				dash(root, UP * 14 + d * 4, 0.16)
			end
			task.wait(0.18)
			if not root.Parent then
				return
			end
			VFX.PlaySound("HeavySwing", root.Position, 1)
			streaks(root.Position + UP * 3, -UP, 8, 2, 6, 10, WIND, 0.25)
			if isLocal then
				local stop = dash(root, -UP * 100 + d * 16, 0.6)
				local t0 = os.clock()
				while os.clock() - t0 < 0.6 and root.Parent do
					local hit = groundRay(root.Position, 8)
					if hit and root.Position.Y - hit.Position.Y < 3.6 then
						break
					end
					task.wait()
				end
				stop()
			end
			return
		end
		-- the hand becomes a swordfish and he lunges with the bill
		SE.bill(char, 1.05)
		VFX.Pose(char, "SwordThrust", 0.35)
		SE.pop(handPos(char, true), 1.1)
		if isLocal then
			dash(root, d * 60, 0.16)
		end
		VFX.PlaySound("Swing", root.Position, 1)
		task.wait(0.12)
		if root.Parent then
			streaks(root.Position + d * 3 + UP, d, 6, 0.6, 6, 10, SE.FISH_BELLY, 0.2)
			shockDisc(root.Position + d * 6 + UP, d, 1, 7, 0.2, WIND, 4)
		end
	end

	-- the bill went in: lifted on it, then flung off it straight ahead (round 59)
	function Effects.SwordfishImpale(char, data)
		local root = charParts(char)
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		local troot = target and target:FindFirstChild("HumanoidRootPart")
		if not root or not troot then
			return
		end
		local d = flatten(data.Dir, root)
		VFX.Motion(char, "SwordfishFling")
		sparks(troot.Position, 0.8, SE.FISH_BELLY, Color3.fromRGB(190, 30, 40), 12)
		billboardRing(troot.Position, 1.5, 8, SE.FISH_BELLY, 5, 0.18)
		VFX.PlaySound("Impale", troot.Position, 1)
		VFX.ShakeAt(troot.Position, 1.2, 40, 0.2)
		task.wait(0.4)
		if not root.Parent then
			return
		end
		local at = troot.Parent and troot.Position or (root.Position + d * 5)
		streaks(at, d, 8, 1, 7, 14, WIND, 0.25)
		shockDisc(at, d, 1.5, 12, 0.22, WIND, 6)
		VFX.PlaySound("HeavyHit", at, 1)
	end

	-- the clam hammer comes down: the street caves in round him
	function Effects.ClamHammerLand(_, data)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos
		if not pos then
			return
		end
		shockDisc(pos + UP * 0.4, UP, 3, 30, 0.35, SE.SHELL)
		shockDisc(pos + UP * 1.2, UP, 3, 22, 0.28, WIND)
		billboardRing(pos + UP, 3, 24, Color3.new(1, 1, 1), 8, 0.3)
		for i = 1, 8 do
			local a = i / 8 * math.pi * 2
			dustPuffs(pos + Vector3.new(math.cos(a), 0, math.sin(a)) * rand(4, 8), 1.2, 2, Color3.fromRGB(205, 196, 190), 1, true)
		end
		rocks(pos, 1.5, 9)
		groundMark(pos, 6, Color3.fromRGB(52, 46, 44), 5)
		VFX.PlaySound("Downslam", pos, 1)
		VFX.PlaySound("HeavyHit", pos, 1)
		VFX.ShakeAt(pos, 2.2, 90, 0.35)
	end

	-- (round 59) -------------------------------------------------------------
	-- THE GLIDE: falling a while, chicken wings grow out of his back, spread,
	-- and he glides down on them (his own screen holds the fall; everyone's
	-- sees the wings, told by the parkour relay) - folded away as he lands
	POSES.SEGlide = { RightArm = { 25, 0, 60 }, LeftArm = { 25, 0, 60 }, RightElbow = 15, LeftElbow = 15, Waist = { -10, 0, 0 }, Neck = { -12, 0, 0 }, RightLeg = 14, LeftLeg = 4, RightKnee = 28, LeftKnee = 18 }
	SE.gliders = setmetatable({}, { __mode = "k" }) -- [char] = the glide on now
	function VFX.SEGlide(char, on)
		local g = SE.gliders[char]
		local spec = Config.Quirks.Manifest.Glide or {}
		if not on then
			if g then
				SE.gliders[char] = nil
				g.fold()
				VFX.ReleasePose(char, 0.2)
			end
			return
		end
		if g then
			return
		end
		local flap, fold = SE.wings(char, nil)
		if not flap then
			return
		end
		g = { fold = fold }
		SE.gliders[char] = g
		flap(1, 0.12)
		VFX.Pose(char, "SEGlide", (spec.MaxTime or 12) + 0.5)
		local root = charParts(char)
		if root then
			VFX.PlaySound("Manifest", root.Position, 0.6)
			sparks(root.Position + UP, 0.5, SE.FEATHER, Color3.fromRGB(220, 214, 200), 6)
		end
		task.spawn(function()
			local t0 = os.clock()
			while SE.gliders[char] == g and char.Parent do
				task.wait(0.9)
				if SE.gliders[char] ~= g then
					break
				end
				flap(1, 0.22)
				local r = charParts(char)
				if r then
					sparks(r.Position + UP * 0.6 - r.CFrame.LookVector * 0.8, 0.3, SE.FEATHER, Color3.fromRGB(220, 214, 200), 2)
				end
				-- (down on the street, or never told it ended: fold them away)
				if not r or (groundRay(r.Position, 4) and os.clock() - t0 > 0.3) or os.clock() - t0 > (spec.MaxTime or 12) + 0.5 then
					VFX.SEGlide(char, false)
				end
			end
		end)
	end

	-- URCHIN SPIKES (3 in the air): he curls up, then sea urchin spines burst
	-- out of every inch of him - long, dark purple, pale at the tips - hold
	-- there a beat, and pull back in
	SE.URCHIN = Color3.fromRGB(58, 24, 72)
	SE.URCHIN_TIP = Color3.fromRGB(176, 120, 196)
	POSES.UrchinCurl = { RightArm = { 60, 0, -40 }, LeftArm = { 60, 0, -40 }, RightElbow = 70, LeftElbow = 70, Waist = { 22, 0, 0 }, Neck = { 18, 0, 0 }, RightLeg = 60, LeftLeg = 60, RightKnee = 85, LeftKnee = 85 }
	POSES.UrchinBurst = { RightArm = { 75, 0, 85 }, LeftArm = { 75, 0, 85 }, RightElbow = 5, LeftElbow = 5, Waist = { -14, 0, 0 }, Neck = { -18, 0, 0 }, RightLeg = 25, LeftLeg = -25, RightKnee = 10, LeftKnee = 10 }
	MOTIONS.UrchinSpikes = { { pose = "UrchinCurl", t = 0.08, hold = 0.04 }, { pose = "UrchinBurst", t = 0.05, hold = 0.32, style = Enum.EasingStyle.Back }, recover = 0.25 }
	function SE.urchin(char, root, isLocal)
		local spec = Config.FindAbilityById and Config.FindAbilityById("TakoThrash") or {}
		VFX.Motion(char, "UrchinSpikes")
		SE.pop(root.Position, 1.2)
		VFX.PlaySound("Manifest", root.Position, 1)
		if isLocal then
			dash(root, UP * 2, 0.5) -- (he hangs there in his spines)
		end
		task.wait(0.12)
		if not root.Parent then
			return
		end
		local n = spec.UrchinSpines or 44
		local reach = (spec.UrchinRadius or 11) - 2.5
		local spines = {}
		for i = 1, n do
			-- spread evenly over him (a golden-angle spiral), a little ragged
			local y = 1 - (i - 0.5) / n * 2
			local r = math.sqrt(1 - y * y)
			local a = i * 2.39996
			local dir = (Vector3.new(math.cos(a) * r, y, math.sin(a) * r) + rng:NextUnitVector() * 0.12).Unit
			local len = reach * rand(0.7, 1.05)
			local base = newPart(Vector3.new(0.05, 0.34, 0.34), CFrame.new(root.Position), SE.URCHIN, Enum.Material.SmoothPlastic, Enum.PartType.Cylinder)
			base.Name = "UrchinSpine"
			local tip = newPart(Vector3.new(0.05, 0.16, 0.16), CFrame.new(root.Position), SE.URCHIN_TIP, Enum.Material.SmoothPlastic, Enum.PartType.Cylinder)
			table.insert(spines, { dir = dir, len = len, base = base, tip = tip, off = Vector3.new(dir.X * 1, dir.Y * 1.5, dir.Z * 0.6) })
		end
		VFX.PlaySound("Impale", root.Position, 1.1)
		VFX.PlaySound("HeavyHit", root.Position, 0.8)
		billboardRing(root.Position, 2, (spec.UrchinRadius or 11) * 2, SE.URCHIN_TIP, 7, 0.25)
		sparks(root.Position, 1, SE.URCHIN_TIP, SE.URCHIN, 12)
		VFX.ShakeAt(root.Position, 1.4, 50, 0.25)
		-- out in 0.08s, held, back in 0.15s
		local t0 = os.clock()
		local conn
		conn = RunService.RenderStepped:Connect(function()
			local t = os.clock() - t0
			local k = t < 0.08 and t / 0.08 or t < 0.4 and 1 or math.max(0, 1 - (t - 0.4) / 0.15)
			if t > 0.56 or not root.Parent then
				conn:Disconnect()
				for _, sp in spines do
					sp.base:Destroy()
					sp.tip:Destroy()
				end
				return
			end
			local center = root.Position
			for _, sp in spines do
				local from = center + sp.off
				local len = math.max(sp.len * k, 0.05)
				local cut = len * 0.62
				local mid = from + sp.dir * (cut / 2)
				sp.base.Size = Vector3.new(math.max(cut, 0.05), 0.34, 0.34)
				sp.base.CFrame = CFrame.lookAt(mid, mid + sp.dir) * CFrame.Angles(0, math.pi / 2, 0)
				local tipMid = from + sp.dir * (cut + (len - cut) / 2)
				sp.tip.Size = Vector3.new(math.max(len - cut, 0.05), 0.16, 0.16)
				sp.tip.CFrame = CFrame.lookAt(tipMid, tipMid + sp.dir) * CFrame.Angles(0, math.pi / 2, 0)
			end
		end)
	end

	-- BAMBOO SWEEP (1 in the air): a stalk of bamboo grows out of his arm and
	-- sweeps round him - from his left round to his right, tilted down at the
	-- street, growing as it goes, biggest at the end - then back round to
	-- where it started, shrinking, and into his arm. The same curve as the
	-- server's hits (Config.BambooAt). Glossy green, darker at every node,
	-- leaves at the tip.
	SE.BAMBOO = Color3.fromRGB(112, 158, 64)
	SE.BAMBOO_NODE = Color3.fromRGB(70, 108, 40)
	SE.BAMBOO_LEAF = Color3.fromRGB(128, 184, 76)
	POSES.BambooWind = { RightArm = { 80, 0, -60 }, RightElbow = 10, LeftArm = { 20, 0, 40 }, LeftElbow = 30, Waist = { -6, 38, 0 }, Neck = { 0, 18, 0 }, RightLeg = 30, LeftLeg = 12, RightKnee = 45, LeftKnee = 35 }
	POSES.BambooSwing = { RightArm = { 80, 0, 85 }, RightElbow = 0, LeftArm = { 20, 0, 40 }, LeftElbow = 30, Waist = { -10, -42, 0 }, Neck = { 0, -24, 0 }, RightLeg = 30, LeftLeg = 12, RightKnee = 45, LeftKnee = 35 }
	function SE.bambooSweep(char, root, d, isLocal)
		local ability = Config.FindAbilityById and Config.FindAbilityById("ChickenKick") or {}
		local spec = ability.Air or {}
		local windUp = spec.WindUp or 0.12
		local hold = spec.HoldTime or 0
		local total = (spec.SwingTime or 0.45) + hold + (spec.ReturnTime or 0.35)
		VFX.Pose(char, "BambooWind", windUp + 0.05)
		SE.pop(handPos(char, true), 1)
		VFX.PlaySound("Manifest", root.Position, 1)
		if isLocal then
			dash(root, UP * 3, windUp + total) -- (he hangs in the air while it goes round)
		end
		local right = d:Cross(UP)
		-- (round 72) the ground under a point (the stalk's tip drags along it)
		local function floorY(p)
			local hit = groundRay(p, 90)
			return hit and hit.Position.Y
		end
		-- the stalk: the culm, a node every so often, leaves at the tip
		local culm = newPart(Vector3.new(0.1, 1, 1), CFrame.new(root.Position), SE.BAMBOO, Enum.Material.SmoothPlastic, Enum.PartType.Cylinder)
		culm.Name = "Bamboo"
		culm.Reflectance = 0.08
		local nodes = {}
		for k = 1, 6 do
			nodes[k] = newPart(Vector3.new(0.22, 1, 1), CFrame.new(root.Position), SE.BAMBOO_NODE, Enum.Material.SmoothPlastic, Enum.PartType.Cylinder)
			nodes[k].Name = "BambooNode"
		end
		local leaves = {}
		for k = 1, 3 do
			leaves[k] = newPart(Vector3.new(0.08, 0.55, 2.4), CFrame.new(root.Position), SE.BAMBOO_LEAF, Enum.Material.SmoothPlastic)
			leaves[k].Name = "BambooLeaf"
		end
		local all = { culm }
		for _, p in nodes do
			table.insert(all, p)
		end
		for _, p in leaves do
			table.insert(all, p)
		end
		task.wait(windUp)
		if not root.Parent then
			for _, p in all do
				p:Destroy()
			end
			return
		end
		VFX.Pose(char, "BambooSwing", (spec.SwingTime or 0.45) + hold + 0.05)
		VFX.PlaySound("HeavySwing", root.Position, 1)
		task.delay((spec.SwingTime or 0.45) + hold, function()
			if char.Parent then
				VFX.Pose(char, "BambooWind", (spec.ReturnTime or 0.35) + 0.1)
				VFX.PlaySound("Swing", root.Position, 0.9)
			end
		end)
		local t0 = os.clock()
		local frame = 0
		local lastScrape, scrapes, scraping = nil, 0, false
		local conn
		conn = RunService.RenderStepped:Connect(function()
			local ang, len, thick = Config.BambooAt(spec, os.clock() - t0)
			if not ang or not root.Parent then
				conn:Disconnect()
				-- back into his arm
				for _, p in all do
					tween(p, 0.1, { Size = p.Size * Vector3.new(0.1, 0.5, 0.5), Transparency = 1 })
					cleanup(p, 0.12)
				end
				if root.Parent then
					SE.pop(handPos(char, true), 0.8)
				end
				return
			end
			frame += 1
			local a = math.rad(ang)
			local flat = d * math.cos(a) + right * math.sin(a)
			local from = handPos(char, true)
			local dir, low
			dir, len, low = Config.BambooAim(spec, from, flat, len, floorY)
			local tip = from + dir * len
			-- (round 72) dragging along the street: a scrape torn into it
			-- behind the tip, dust kicked up
			if low then
				local skim = (spec.Skim or 0.4) - 0.05
				if lastScrape and (tip - lastScrape).Magnitude > 1.2 then
					if scrapes < 40 then
						scrapes += 1
						local a0, a1 = lastScrape - UP * skim, tip - UP * skim
						local mark = newPart(Vector3.new(thick * 0.8, 0.06, (a1 - a0).Magnitude + 0.3), CFrame.lookAt((a0 + a1) / 2, a1), Color3.fromRGB(58, 52, 44), Enum.Material.Slate)
						mark.Name = "BambooScrape"
						mark.Transparency = 0.2
						tween(mark, 1.2, { Transparency = 1 }, Enum.EasingStyle.Linear, nil, 2.5)
						cleanup(mark, 3.8)
					end
					lastScrape = tip
				elseif not lastScrape then
					lastScrape = tip
				end
				if frame % 2 == 0 then
					dustPuffs(tip - UP * 0.3, 0.3, 1, Color3.fromRGB(196, 186, 170), 0.6)
				end
				if not scraping then
					scraping = true
					VFX.PlaySound("Skid", tip, 0.9)
				end
			else
				lastScrape = nil
			end
			local orient = CFrame.lookAt(from, tip) * CFrame.Angles(0, math.pi / 2, 0)
			culm.Size = Vector3.new(len, thick, thick)
			culm.CFrame = CFrame.lookAt((from + tip) / 2, tip) * CFrame.Angles(0, math.pi / 2, 0)
			for k, p in nodes do
				p.Size = Vector3.new(0.22, thick * 1.14, thick * 1.14)
				p.CFrame = orient + dir * (len * k / 7)
			end
			for k, p in leaves do
				local sway = math.sin(os.clock() * 14 + k) * 12
				p.CFrame = CFrame.lookAt(tip, tip + dir) * CFrame.Angles(math.rad((k - 2) * 40 + sway), math.rad((k - 2) * 25), 0) * CFrame.new(0, 0, -0.9)
			end
			if frame % 3 == 0 then
				sparks(tip, 0.4, SE.BAMBOO_LEAF, SE.BAMBOO, 2)
			end
		end)
	end

	-- the M1s: every hit is something he grew (Config.M1.Styles.Manifest =
	-- Mixed: a straight, a kick, a rising strike, a finishing kick)
	function VFX.ManifestPunch(char, count, finisher, fist, look)
		if finisher then
			SE.talon(char, true, 1.5, 0.35)
			shockDisc(fist, look, 1.5, 12, 0.2, SE.TALON, 6)
			return
		end
		if count == 1 then
			-- a tentacle lash off the fist
			local tent = SE.tentacle(0.32, 6)
			local t0 = os.clock()
			local conn
			conn = RunService.RenderStepped:Connect(function()
				local t = os.clock() - t0
				if not char.Parent or t > 0.2 then
					conn:Disconnect()
					tent.fade(0.1)
					return
				end
				local from = handPos(char, true)
				local k = t < 0.08 and t / 0.08 or 1 - (t - 0.08) / 0.12
				tent.set(from, from + look * 6 * k, 0.4, 0.3)
			end)
		elseif count == 2 then
			SE.talon(char, false, 1.1, 0.25)
		else
			SE.clamFist(char, true, 0.3)
		end
	end

	-- a dash: a flap of chicken wings
	QUIRK_FX.Dash.Manifest = function(char, root, dir)
		local flap = SE.wings(char, 0.4)
		if flap then
			flap(1, 0.1)
		end
		sparks(root.Position - dir * 1.5 + UP, 0.5, SE.FEATHER, Color3.fromRGB(220, 214, 200), 6)
		legTrails(char, 0.25, SE.TENT)
	end

	-- the awakening: tentacles and shells burst out of him
	QUIRK_FX.Ult.Manifest = function(_char, root, g)
		for i = 1, 6 do
			local a = i / 6 * math.pi * 2
			local tent = SE.tentacle(0.9, 8)
			local out = Vector3.new(math.cos(a), 0, math.sin(a))
			local t0 = os.clock()
			local conn
			conn = RunService.RenderStepped:Connect(function()
				local t = os.clock() - t0
				if not root.Parent or t > 0.8 then
					conn:Disconnect()
					tent.fade(0.25)
					return
				end
				local k = math.sin(math.clamp(t / 0.8, 0, 1) * math.pi)
				tent.set(root.Position, root.Position + out * 12 * k + UP * 6 * k, 3, 0.8)
			end)
		end
		billboardRing(root.Position, 3, 30, SE.PLASMA, 6, 0.45)
		dustPuffs(g, 1.4, 8, SE.TENT:Lerp(Color3.new(1, 1, 1), 0.3), 1.2, false)
		VFX.PlaySound("Manifest", root.Position, 1.2)
	end

	-- CHIMERA KRAKEN: eight giant tentacles thrashing round him in a wave ---
	function Effects.Kraken(char, _data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local radius = ability.Radius or 30
		local hits = ability.Hits or 4
		local total = 0.35 + hits * 0.2 + 0.35
		VFX.Pose(char, "KrakenSpread", total)
		VFX.PlaySound("Kraken", root.Position, 1.2)
		if isLocal then
			VFX.Hooks.Dim(0.25, 0.4)
		end
		local tents = {}
		for i = 1, 8 do
			tents[i] = { t = SE.tentacle(2.2, 12, i % 2 == 0 and SE.TENT or SE.TENT_DARK), a = i / 8 * math.pi * 2 }
		end
		local t0 = os.clock()
		local lastRing = 0
		local conn
		conn = RunService.RenderStepped:Connect(function()
			local t = os.clock() - t0
			if not root.Parent or t > total then
				conn:Disconnect()
				for _, e in tents do
					e.t.fade(0.3)
				end
				return
			end
			local grow = math.clamp(t / 0.35, 0, 1)
			local spin = t * math.pi * 2 * 0.9
			local last = t > total - 0.35
			for i, e in tents do
				local a = e.a + spin
				local out = Vector3.new(math.cos(a), 0, math.sin(a))
				local from = root.Position + UP * 0.5 + out * 1.2
				local reach = radius * grow * (last and (1 + (t - (total - 0.35)) * 1.4) or 1)
				local tip = root.Position + out * reach + UP * (4 + math.sin(t * 6 + i) * 3)
				e.t.set(from, tip, 6 * grow, 1.2)
			end
			if t - lastRing > 0.2 and grow >= 1 then
				lastRing = t
				local g = groundPoint(root.Position)
				shockDisc(g + UP * 0.4, UP, radius * 0.4, radius * 1.1, 0.25, SE.TENT, 0)
				dustPuffs(g, 1.2, 5, Color3.fromRGB(205, 196, 190), 0.7, false)
				VFX.ShakeAt(root.Position, 1.4, 80, 0.15)
				VFX.PlaySound("Wind", root.Position, 0.7)
			end
		end)
		task.wait(total - 0.35)
		if root.Parent then
			billboardRing(root.Position, 4, radius * 2.2, SE.TENT, 10, 0.4)
			VFX.PlaySound("HeavyHit", root.Position, 1.2)
			VFX.ShakeAt(root.Position, 3, 140, 0.4)
		end
	end

	-- CHIMERA CENTAUR: bull legs, horns, fruit on vines - a stampede ---------
	function Effects.Centaur(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local d = flatten(data.Dir, root)
		local run = 0.7
		local range = ability.Range or 70
		local torso = SE.limb(char, "Torso")
		local life = 0.3 + run + 0.4
		local body = {}
		if torso then
			-- the bull's body behind and below him, four legs, a tail
			local BULL = Color3.fromRGB(96, 62, 40)
			local back = newPart(Vector3.new(2.6, 2, 4.4), torso.CFrame, BULL, Enum.Material.Fabric)
			SE.attach(torso, back, CFrame.new(0, -1.6, 2.2))
			table.insert(body, back)
			for _, x in { -0.9, 0.9 } do
				for _, z in { 0.6, 3.8 } do
					local leg = newPart(Vector3.new(0.6, 2.6, 0.6), torso.CFrame, BULL, Enum.Material.Fabric)
					SE.attach(torso, leg, CFrame.new(x, -3.4, z))
					local hoof = newPart(Vector3.new(0.7, 0.4, 0.8), torso.CFrame, Color3.fromRGB(34, 30, 28), Enum.Material.SmoothPlastic)
					SE.attach(torso, hoof, CFrame.new(x, -4.8, z - 0.05))
					table.insert(body, leg)
					table.insert(body, hoof)
				end
			end
			local tail = newPart(Vector3.new(0.2, 1.8, 0.2), torso.CFrame, BULL, Enum.Material.Fabric)
			SE.attach(torso, tail, CFrame.new(0, -1.2, 4.5) * CFrame.Angles(math.rad(-30), 0, 0))
			table.insert(body, tail)
		end
		local head = char:FindFirstChild("Head")
		if head then
			for _, side in { -1, 1 } do
				local horn = newPart(Vector3.new(0.3, 1.2, 0.3), head.CFrame, Color3.fromRGB(236, 228, 206), Enum.Material.SmoothPlastic, Enum.PartType.Wedge)
				SE.attach(head, horn, CFrame.new(side * 0.55, 0.6, -0.1) * CFrame.Angles(0, 0, math.rad(side * -35)))
				table.insert(body, horn)
			end
		end
		-- vines swinging hard fruit off both hands
		local FRUIT = { Color3.fromRGB(60, 140, 60), Color3.fromRGB(226, 60, 130), Color3.fromRGB(120, 80, 40) }
		local vines = {}
		for i, right in { true, false } do
			vines[i] = { tent = SE.tentacle(0.3, 6, Color3.fromRGB(70, 150, 60)), fruit = newPart(Vector3.one * 1.6, CFrame.new(root.Position), FRUIT[i + (right and 0 or 1)], Enum.Material.SmoothPlastic, Enum.PartType.Ball), right = right }
		end
		SE.pop(root.Position, 2)
		VFX.PlaySound("Centaur", root.Position, 1.2)
		VFX.Pose(char, "CentaurRear", 0.3)
		local t0 = os.clock()
		local conn
		conn = RunService.RenderStepped:Connect(function()
			local t = os.clock() - t0
			if not root.Parent or t > life then
				conn:Disconnect()
				for _, v in vines do
					v.tent.fade(0.2)
					tween(v.fruit, 0.2, { Transparency = 1 })
					cleanup(v.fruit, 0.25)
				end
				for _, p in body do
					if p.Parent then
						tween(p, 0.25, { Transparency = 1 })
						cleanup(p, 0.3)
					end
				end
				return
			end
			for i, v in vines do
				local from = handPos(char, v.right)
				local a = t * 12 + i * math.pi
				local r = root.CFrame.RightVector * (v.right and 1 or -1)
				local tip = from + r * 3.5 + Vector3.new(math.cos(a), math.sin(a) * 0.6, math.sin(a)) * 3
				v.tent.set(from, tip, 0.6, 0.4)
				v.fruit.CFrame = CFrame.new(tip)
			end
		end)
		task.wait(0.3)
		if not root.Parent then
			return
		end
		VFX.Pose(char, "Tuck", run)
		if isLocal then
			face(root, d)
			dash(root, d * (range / run), run)
		end
		local g0 = os.clock()
		while os.clock() - g0 < run and root.Parent do
			local g = groundPoint(root.Position)
			dustPuffs(g, 1, 3, Color3.fromRGB(205, 196, 190), 0.8, false)
			VFX.PlaySound("Kick", g, 0.5)
			VFX.ShakeAt(g, 1.2, 60, 0.1)
			task.wait(0.09)
		end
		if root.Parent then
			shockDisc(root.Position + d * 2, d, 3, 22, 0.3, WIND, 12)
		end
	end

	-- OCTOPUS MIRAGE: a puff of ink, and he fades into the street -------------
	function SE.fade(char, amount)
		local saved, switched = {}, {}
		for _, p in char:GetDescendants() do
			if (p:IsA("BasePart") or p:IsA("Decal")) and p.Name ~= "HumanoidRootPart" then
				saved[p] = p.Transparency
				p.Transparency = math.max(p.Transparency, amount)
			elseif amount > 0.9 and (p:IsA("Highlight") or p:IsA("ParticleEmitter") or p:IsA("Light") or p:IsA("Trail") or p:IsA("BillboardGui")) and p.Enabled then
				-- (an outline or a glow would give him away)
				switched[p] = true
				p.Enabled = false
			end
		end
		local hum = char:FindFirstChildOfClass("Humanoid")
		local shown = hum and hum.DisplayDistanceType
		if hum and amount > 0.9 then
			hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
		end
		return function()
			for p, v in saved do
				if p.Parent then
					p.Transparency = v
				end
			end
			for p in switched do
				if p.Parent then
					p.Enabled = true
				end
			end
			if hum and shown and hum.Parent then
				hum.DisplayDistanceType = shown
			end
		end
	end

	function Effects.OctopusMirage(char, _data, _isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local g = groundPoint(root.Position)
		smokeBurst(root.Position, SE.INK, 4, 5, 1.2, 8)
		dustPuffs(g, 1.2, 6, SE.INK, 1, false)
		VFX.PlaySound("PhaseSink", root.Position, 0.8)
		VFX.Pose(char, "StingCrouch", 0.3)
		local mine = Players.LocalPlayer and Players.LocalPlayer.Character == char
		-- (you can just make yourself out; everyone else sees a shimmer at most)
		local restore = SE.fade(char, mine and 0.75 or 0.97)
		SE.faded[char] = true
		local t0 = os.clock()
		local vanish = ability.Vanish or 1.4
		-- (the server's attribute says when he's out of it)
		while root.Parent and os.clock() - t0 < vanish + 0.6 and (os.clock() - t0 < 0.4 or char:GetAttribute("Mirage")) do
			if rng:NextNumber() < 0.25 then
				sparks(root.Position + Vector3.new(rand(-1, 1), rand(-2, 2), rand(-1, 1)), 0.2, Color3.fromRGB(220, 230, 240), Color3.fromRGB(160, 170, 190), 2)
			end
			task.wait(0.05)
		end
		SE.faded[char] = nil
		restore()
	end

	-- ...up out of it behind them, a scorpion's tail over his shoulder, a sting
	function Effects.MirageStrike(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		local troot = target and target:FindFirstChild("HumanoidRootPart")
		smokeBurst(root.Position, SE.INK, 3, 4, 0.9, 6)
		VFX.PlaySound("PhaseOut", root.Position, 0.9)
		if not troot then
			return
		end
		VFX.Pose(char, "StingCrouch", 0.5)
		local tail = SE.tentacle(0.7, 10, Color3.fromRGB(110, 40, 40))
		local stinger = newPart(Vector3.new(0.5, 1.4, 0.5), CFrame.new(root.Position), Color3.fromRGB(40, 20, 20), Enum.Material.SmoothPlastic, Enum.PartType.Wedge)
		local t0 = os.clock()
		local conn
		conn = RunService.RenderStepped:Connect(function()
			local t = os.clock() - t0
			if not root.Parent or not troot.Parent or t > 0.45 then
				conn:Disconnect()
				tail.fade(0.2)
				tween(stinger, 0.2, { Transparency = 1 })
				cleanup(stinger, 0.25)
				return
			end
			local from = root.Position - root.CFrame.LookVector * 0.6 - UP * 0.5
			local k = math.clamp(t / 0.14, 0, 1)
			local over = from + UP * 6 + root.CFrame.LookVector * 1
			local tip = over:Lerp(troot.Position + UP * 0.5, k)
			tail.set(from, tip, 3 * (1 - k * 0.5), 0.1)
			stinger.CFrame = CFrame.lookAt(tip, tip + (tip - over).Unit) * CFrame.Angles(math.rad(-90), 0, 0)
		end)
		task.wait(0.14)
		if troot.Parent then
			sparks(troot.Position, 1, SE.VENOM, Color3.fromRGB(90, 220, 120), 16)
			billboardRing(troot.Position, 2, 12, SE.VENOM, 6, 0.25)
			VFX.PlaySound("Sting", troot.Position, 1)
			VFX.ShakeAt(troot.Position, 1.5, 50, 0.2)
		end
	end

	-- server: venom in them (purple bubbles for as long as it lasts)
	function Effects.Poisoned(_, data)
		local target = data.Target
		local troot = typeof(target) == "Instance" and target:FindFirstChild("HumanoidRootPart")
		if not troot then
			return
		end
		local pe = Instance.new("ParticleEmitter")
		pe.Texture = "rbxasset://textures/particles/sparkles_main.dds"
		pe.Color = ColorSequence.new(SE.VENOM, Color3.fromRGB(90, 220, 120))
		pe.LightEmission = 0.4
		pe.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.5), NumberSequenceKeypoint.new(1, 0) })
		pe.Speed = NumberRange.new(1, 3)
		pe.Lifetime = NumberRange.new(0.6, 1)
		pe.Acceleration = Vector3.new(0, 4, 0)
		pe.SpreadAngle = Vector2.new(180, 180)
		pe.Rate = 26
		pe.Parent = troot
		task.delay(tonumber(data.Duration) or 2.5, function()
			pe.Enabled = false
		end)
		cleanup(pe, (tonumber(data.Duration) or 2.5) + 1.2)
	end

	-- PLASMA CANNON: everything he's eaten in one arm ------------------------
	-- the arm: bamboo barrel, alligator jaws round the muzzle, spider crab
	-- plating, sea urchin spines, a watermelon swelling at the shoulder
	function SE.cannonArm(char)
		local arm = SE.limb(char, "RightArm")
		if not arm then
			return nil
		end
		local parts, c0s = {}, {}
		local function add(size, color, material, shape, c0)
			local p = newPart(size, arm.CFrame, color, material or Enum.Material.SmoothPlastic, shape)
			table.insert(parts, p)
			table.insert(c0s, c0)
			return p
		end
		local hand = CFrame.new(0, -arm.Size.Y / 2, 0)
		add(Vector3.new(1.5, 2.2, 1.5), SE.CRAB, Enum.Material.Slate, nil, CFrame.new(0, 0, 0))
		for k = 0, 2 do
			add(Vector3.new(3, 1.1, 1.1), Color3.fromRGB(96, 150, 60), Enum.Material.Wood, Enum.PartType.Cylinder, hand * CFrame.new(0, -1 - k * 1.05, 0) * CFrame.Angles(0, 0, math.rad(90)))
			add(Vector3.new(0.25, 1.25, 1.25), Color3.fromRGB(70, 110, 40), Enum.Material.Wood, Enum.PartType.Cylinder, hand * CFrame.new(0, -0.5 - k * 1.05, 0) * CFrame.Angles(0, 0, math.rad(90)))
		end
		for _, side in { 1, -1 } do
			add(Vector3.new(1.4, 0.4, 2.4), Color3.fromRGB(70, 96, 50), Enum.Material.Slate, Enum.PartType.Wedge, hand * CFrame.new(0, -4.1, side * 0.55) * CFrame.Angles(math.rad(side > 0 and -80 or -100), 0, 0))
			for t = -1, 1 do
				add(Vector3.new(0.15, 0.3, 0.15), Color3.new(1, 1, 1), nil, Enum.PartType.Wedge, hand * CFrame.new(t * 0.35, -4.4, side * 0.4))
			end
		end
		local urchin = add(Vector3.one * 1.2, Color3.fromRGB(70, 30, 90), nil, Enum.PartType.Ball, CFrame.new(0.4, 0.5, 0.6))
		for k = 1, 8 do
			local a = k / 8 * math.pi * 2
			add(Vector3.new(0.12, 1.1, 0.12), Color3.fromRGB(50, 20, 60), nil, nil, CFrame.new(0.4, 0.5, 0.6) * CFrame.Angles(a, 0, a * 0.5) * CFrame.new(0, 0.9, 0))
		end
		urchin.Material = Enum.Material.Slate
		add(Vector3.new(1.8, 1.6, 1.8), Color3.fromRGB(46, 120, 50), nil, Enum.PartType.Ball, CFrame.new(0, 1.3, 0.3))
		add(Vector3.new(0.2, 1.4, 0.2), Color3.fromRGB(150, 110, 70), Enum.Material.Wood, nil, CFrame.new(-0.5, 1.6, 0) * CFrame.Angles(0, 0, math.rad(30)))
		SE.wear(parts, arm, c0s)
		local orb = newPart(Vector3.one * 0.5, arm.CFrame, SE.PLASMA, Enum.Material.Neon, Enum.PartType.Ball)
		SE.attach(arm, orb, hand * CFrame.new(0, -4.7, 0))
		table.insert(parts, orb)
		return { parts = parts, orb = orb, arm = arm }
	end

	function SE.dropCannon(char)
		local c = SE.cannons[char]
		if not c then
			return
		end
		SE.cannons[char] = nil
		c.over = true
		for _, p in c.parts do
			if p.Parent then
				tween(p, 0.2, { Transparency = 1 })
				cleanup(p, 0.25)
			end
		end
	end
	VFX.SEDrop = SE.dropCannon

	-- HOLD: the arm grows and the shot builds at its mouth
	function Effects.PlasmaCannon(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		SE.dropCannon(char)
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		local c = SE.cannonArm(char)
		if not c then
			return
		end
		SE.cannons[char] = c
		SE.pop(root.Position + d * 2, 2.2)
		VFX.PlaySound("PlasmaCharge", root.Position, 1.1)
		local max = (ability.Hold and ability.Hold.Max) or 2
		local t0 = os.clock()
		while not c.over and root.Parent and os.clock() - t0 < max + 1.2 do
			local k = math.clamp((os.clock() - t0) / max, 0, 1)
			VFX.Pose(char, "CannonAim", 0.2)
			c.orb.Size = Vector3.one * (0.5 + 3.5 * k)
			if rng:NextNumber() < 0.5 then
				local mouth = c.orb.Position
				local from = mouth + rng:NextUnitVector() * rand(4, 9)
				local seg = newPart(Vector3.new(0.25, 0.25, 3), CFrame.lookAt(from, mouth), SE.PLASMA, Enum.Material.Neon)
				tween(seg, 0.2, { CFrame = CFrame.lookAt(mouth, mouth + (mouth - from)), Size = Vector3.new(0.05, 0.05, 1), Transparency = 0.6 })
				cleanup(seg, 0.25)
			end
			task.wait(0.05)
		end
		if not c.over then
			SE.dropCannon(char)
		end
	end

	-- LET GO: the beam (his own screen fires the moment he lets go)
	function Effects.PlasmaCannonRelease(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or Config.FindAbilityById("PlasmaCannon") or {}
		local level = math.clamp(tonumber(data.Level) or 1, 1, 3)
		local c = SE.cannons[char]
		local aim = Config.AimedDirection(data.Dir, flatten(root.CFrame.LookVector, root), { Up = 35, Down = 35 })
		local mouth = c and c.orb.Parent and c.orb.Position or (root.Position + UP * 1.5 + aim * 4)
		if c then
			c.over = true
		end
		local width = (ability.LevelWidth and ability.LevelWidth[level]) or 12
		local length = ability.Range or 260
		task.wait(isLocal and 0.15 or 0)
		if not root.Parent then
			SE.dropCannon(char)
			return
		end
		if isLocal then
			face(root, aim)
			dash(root, -flatten(aim, root) * 30, 0.15) -- (the recoil)
			VFX.ImpactFrame(0.12)
		end
		VFX.Pose(char, "CannonAim", 0.6)
		beam(mouth, mouth + aim * length, width * 0.5, Color3.new(1, 1, 1), SE.PLASMA, 0.7 + level * 0.15)
		for k = 1, 6 do
			task.delay(k * 0.03, function()
				shockDisc(mouth + aim * (k * length / 7), aim, width * 0.6, width * 2.2, 0.35, SE.PLASMA, 6)
			end)
		end
		billboardRing(mouth, 4, width * 3, SE.PLASMA, 8, 0.35)
		VFX.PlaySound("PlasmaFire", mouth, 1.3)
		VFX.ShakeAt(mouth, 2 + level, 300, 0.5)
		if nearCamera(mouth, 120) then
			VFX.Hooks.Flash(SE.PLASMA, 0.25)
		end
		task.wait(0.5)
		SE.dropCannon(char)
	end
end

---------------------------------------------------------------------------
-- CRAZY DIAMOND: the Stand. Built out of parts on every screen and flown
-- beside its user each frame - floating at his shoulder with its arms
-- crossed, then out in front of him to punch, pound the street, or lay its
-- hands on the world to put it back together. Bubblegum-pink body, pale
-- blue armour, hearts on the headgear, chin, shoulders, chest, belt and
-- knees, short spikes on the shoulders and ankles, cables from the back of
-- its head to its back.
---------------------------------------------------------------------------
do
	local CDV = {
		PINK = Color3.fromRGB(240, 146, 196),
		DEEP = Color3.fromRGB(222, 66, 146),
		ARMOR = Color3.fromRGB(142, 214, 238),
		TRIM = Color3.fromRGB(236, 242, 250),
		EYE = Color3.fromRGB(214, 252, 255),
		stands = {}, -- [char] = stand
	}
	-- where it floats (in its user's space) and the shape it holds, per action
	CDV.PLACES = {
		idle = CFrame.new(1.9, 1.3, 2.4),
		punch = CFrame.new(0.4, 0.6, -2.6),
		barrage = CFrame.new(0, 0.7, -2.7),
		ground = CFrame.new(0, 1.4, -3.2),
		restore = CFrame.new(0, 1.3, -2.8),
		rage = CFrame.new(0, 2.4, 1.6),
		dash = CFrame.new(0, 0.8, 1.8),
	}
	-- per limb: { pitch (+ forward), yaw (+ inward), roll (+ outward) } in
	-- degrees; head { pitch, yaw }; lean (+ back), twist (+ left)
	CDV.POSES = {
		idle = { armR = { 78, 58, 0 }, armL = { 72, 58, 0 }, legR = { 12, 0, 5 }, legL = { -8, 0, 6 }, head = { -6, 0 }, lean = -4 },
		punchR = { armR = { 92, 4, 0 }, armL = { 48, 34, 0 }, legR = { -16, 0, 4 }, legL = { 22, 0, 4 }, head = { -4, 0 }, lean = -14, twist = 22 },
		punchL = { armL = { 92, 4, 0 }, armR = { 48, 34, 0 }, legL = { -16, 0, 4 }, legR = { 22, 0, 4 }, head = { -4, 0 }, lean = -14, twist = -22 },
		ground = { armR = { 22, 6, 0 }, armL = { 64, 30, 0 }, legR = { -22, 0, 6 }, legL = { 34, 0, 6 }, head = { -20, 0 }, lean = -38 },
		restore = { armR = { 88, -16, 0 }, armL = { 88, -16, 0 }, legR = { 6, 0, 6 }, legL = { -4, 0, 6 }, head = { -6, 0 }, lean = -8 },
		rage = { armR = { 150, 0, 42 }, armL = { 150, 0, 42 }, legR = { 0, 0, 16 }, legL = { 0, 0, 16 }, head = { 26, 0 }, lean = 14 },
		dash = { armR = { -40, 0, 12 }, armL = { -40, 0, 12 }, legR = { -30, 0, 4 }, legL = { -12, 0, 4 }, head = { -10, 0 }, lean = -30 },
	}
	-- (round 66) its own M1s: a wind-up and a strike for each hit (a right, a
	-- left, a hook, a big straight; an uppercut and a hammer for the slams),
	-- and where it stands for them (m1wind, then out to m1)
	for name, pose in {
		windR = { armR = { 40, -20, 34 }, armL = { 78, 32, 0 }, legR = { -10, 0, 4 }, legL = { 16, 0, 4 }, head = { -4, 0 }, lean = -2, twist = -26 },
		jabR = { armR = { 96, 2, 0 }, armL = { 52, 36, 0 }, legR = { -22, 0, 4 }, legL = { 28, 0, 4 }, head = { -6, 0 }, lean = -18, twist = 30 },
		windL = { armL = { 40, -20, 34 }, armR = { 78, 32, 0 }, legL = { -10, 0, 4 }, legR = { 16, 0, 4 }, head = { -4, 0 }, lean = -2, twist = 26 },
		jabL = { armL = { 96, 2, 0 }, armR = { 52, 36, 0 }, legL = { -22, 0, 4 }, legR = { 28, 0, 4 }, head = { -6, 0 }, lean = -18, twist = -30 },
		windHook = { armR = { 72, -44, 58 }, armL = { 76, 30, 0 }, legR = { -12, 0, 4 }, legL = { 18, 0, 4 }, head = { -4, 0 }, lean = -4, twist = -44 },
		hook = { armR = { 90, 64, 12 }, armL = { 44, 30, 0 }, legR = { -20, 0, 5 }, legL = { 26, 0, 5 }, head = { -6, 0 }, lean = -14, twist = 48 },
		windSmash = { armR = { 18, -12, 42 }, armL = { 100, 22, 0 }, legR = { -24, 0, 6 }, legL = { 30, 0, 6 }, head = { -10, 0 }, lean = 8, twist = -48 },
		smash = { armR = { 100, 0, 0 }, armL = { 26, 30, 10 }, legR = { -32, 0, 6 }, legL = { 38, 0, 6 }, head = { -8, 0 }, lean = -28, twist = 40 },
		windUpper = { armR = { -24, 0, 22 }, armL = { 70, 30, 0 }, legR = { 10, 0, 6 }, legL = { 22, 0, 6 }, head = { 10, 0 }, lean = 16, twist = -24 },
		upper = { armR = { 172, 10, 0 }, armL = { 40, 30, 0 }, legR = { -26, 0, 6 }, legL = { 30, 0, 6 }, head = { 24, 0 }, lean = -26, twist = 22 },
		windHammer = { armR = { 176, 8, 8 }, armL = { 176, 8, 8 }, legR = { -10, 0, 8 }, legL = { 14, 0, 8 }, head = { 16, 0 }, lean = -22, twist = 0 },
		hammer = { armR = { 36, 6, 0 }, armL = { 36, 6, 0 }, legR = { -22, 0, 8 }, legL = { 28, 0, 8 }, head = { -24, 0 }, lean = 42, twist = 0 },
	} do
		CDV.POSES[name] = pose
	end
	CDV.PLACES.m1wind = CFrame.new(0.3, 0.7, -2.2)
	CDV.PLACES.m1 = CFrame.new(0.2, 0.5, -3.1)
	CDV.PLACES.m1up = CFrame.new(0.2, 0.1, -2.9)
	CDV.PLACES.m1down = CFrame.new(0, 2.2, -3)

	function CDV.isUser(char)
		local plr = char and Players:GetPlayerFromCharacter(char)
		local q = plr and plr:GetAttribute("Quirk")
		return q == "CrazyDiamond" or q == "TheWorld" -- (round 74: DIO's)
	end

	function CDV.part(st, key, size, offset, color, material, shape)
		local p = newPart(size, CFrame.new(), color, material or Enum.Material.SmoothPlastic, shape, st.model)
		p.Transparency = 1
		table.insert(st.parts, { part = p, key = key, offset = offset, base = 0 })
		return p
	end

	-- a heart: two balls over a diamond
	function CDV.heart(st, key, cf, size, color)
		for side = -1, 1, 2 do
			CDV.part(st, key, Vector3.one * size * 0.62, cf * CFrame.new(side * size * 0.24, size * 0.14, 0), color, nil, Enum.PartType.Ball)
		end
		CDV.part(st, key, Vector3.new(size * 0.58, size * 0.58, size * 0.3), cf * CFrame.new(0, -size * 0.12, 0) * CFrame.Angles(0, 0, math.rad(45)), color)
	end

	function CDV.build(char)
		local model = Instance.new("Model")
		model.Name = "CrazyDiamond"
		model.Parent = folder
		local st = { char = char, model = model, parts = {}, fists = {}, alpha = 0, shown = -1, action = "idle", actionUntil = 0, lastActive = 0, cf = nil, barrage = 0 }
		st.kind, st.tint, st.shoutStroke = "CrazyDiamond", CDV.PINK, Color3.fromRGB(70, 10, 50)
		local P, A, D, T = CDV.PINK, CDV.ARMOR, CDV.DEEP, CDV.TRIM
		-- body
		CDV.part(st, "torso", Vector3.new(2.3, 2.3, 1.2), CFrame.new(), P)
		CDV.part(st, "torso", Vector3.new(2.42, 1.05, 1.32), CFrame.new(0, 0.58, 0), A)
		CDV.part(st, "torso", Vector3.new(2.42, 0.34, 1.32), CFrame.new(0, -1.0, 0), A)
		CDV.heart(st, "torso", CFrame.new(0, -1.0, -0.7), 0.5, D)
		CDV.heart(st, "torso", CFrame.new(0, -0.32, -0.64), 0.42, D)
		for side = -1, 1, 2 do
			-- the cables from the back of its head
			CDV.part(st, "torso", Vector3.new(0.16, 1.2, 0.16), CFrame.new(side * 0.34, 1.25, 0.62) * CFrame.Angles(math.rad(-30), 0, 0), T, nil, Enum.PartType.Cylinder)
		end
		-- head: tall headgear, the mask over its lower face, glowing eyes
		CDV.part(st, "head", Vector3.new(1.2, 1.3, 1.2), CFrame.new(), P)
		CDV.part(st, "head", Vector3.new(1.3, 0.75, 1.3), CFrame.new(0, 0.36, 0.02), A)
		CDV.part(st, "head", Vector3.new(0.34, 1.2, 1.25), CFrame.new(0, 1.0, 0.1), A)
		CDV.heart(st, "head", CFrame.new(0, 1.42, -0.52), 0.36, D)
		CDV.part(st, "head", Vector3.new(1.26, 0.46, 0.3), CFrame.new(0, -0.36, -0.5), A)
		CDV.heart(st, "head", CFrame.new(0, -0.46, -0.68), 0.24, D)
		for side = -1, 1, 2 do
			CDV.part(st, "head", Vector3.new(0.3, 0.12, 0.05), CFrame.new(side * 0.25, 0.06, -0.61), CDV.EYE, Enum.Material.Neon)
		end
		-- arms: shoulder pads with a heart and two spikes, armoured forearms
		for side, key in { [1] = "armR", [-1] = "armL" } do
			CDV.part(st, key, Vector3.new(1, 1.25, 1), CFrame.new(0, -0.62, 0), P)
			CDV.part(st, key, Vector3.new(1.12, 1.1, 1.12), CFrame.new(0, -1.78, 0), A)
			CDV.part(st, key, Vector3.new(1.1, 0.2, 1.1), CFrame.new(0, -2.36, 0), A)
			st.fists[key] = CDV.part(st, key, Vector3.new(1.05, 0.9, 1.05), CFrame.new(0, -2.72, 0), P) -- (its fist)
			CDV.part(st, key, Vector3.new(1.46, 0.76, 1.46), CFrame.new(0, 0.18, 0), A)
			CDV.heart(st, key, CFrame.new(side * 0.74, 0.16, 0) * CFrame.Angles(0, math.rad(side * 90), 0), 0.4, D)
			for k = -1, 1, 2 do
				CDV.part(st, key, Vector3.new(0.18, 0.44, 0.18), CFrame.new(side * 0.3, 0.72, k * 0.32), T)
			end
		end
		-- legs: shin guards, hearts on the knees, spikes at the ankles
		for side, key in { [1] = "legR", [-1] = "legL" } do
			CDV.part(st, key, Vector3.new(1.05, 1.3, 1.05), CFrame.new(0, -0.66, 0), P)
			CDV.part(st, key, Vector3.new(1.12, 1.25, 1.12), CFrame.new(0, -1.92, 0), A)
			CDV.heart(st, key, CFrame.new(0, -1.32, -0.6), 0.36, D)
			CDV.part(st, key, Vector3.new(1.05, 0.45, 1.3), CFrame.new(0, -2.72, -0.15), P)
			CDV.part(st, key, Vector3.new(0.16, 0.38, 0.16), CFrame.new(side * 0.62, -2.4, 0), T)
		end
		-- a cel outline, and a pink glow when it's angry
		local hl = Instance.new("Highlight")
		hl.Adornee = model
		hl.FillColor = CDV.PINK
		hl.FillTransparency = 1
		hl.OutlineColor = Color3.fromRGB(110, 26, 76)
		hl.OutlineTransparency = 1
		hl.DepthMode = Enum.HighlightDepthMode.Occluded
		hl.Parent = model
		st.highlight = hl
		CDV.stands[char] = st
		return st
	end

	-- (round 74) THE WORLD: DIO's Stand, on the same frame as Crazy Diamond
	-- (the same places, the same poses - it throws his M1s too). Gold, with
	-- dark teal armour: the crested helmet, the mask and the tubes running
	-- from its jaw round to the back of its head, the rounded shoulder pads,
	-- wrist and shin guards; pale slit eyes.
	CDV.GOLD = Color3.fromRGB(236, 194, 70)
	CDV.GOLD_DEEP = Color3.fromRGB(190, 142, 38)
	CDV.TEAL = Color3.fromRGB(34, 90, 84)
	CDV.CREAM = Color3.fromRGB(252, 240, 196)
	function CDV.kindOf(char)
		local plr = char and Players:GetPlayerFromCharacter(char)
		return plr and plr:GetAttribute("Quirk") or nil
	end
	function CDV.buildWorld(char)
		local model = Instance.new("Model")
		model.Name = "TheWorld"
		model.Parent = folder
		local st = { char = char, model = model, parts = {}, fists = {}, alpha = 0, shown = -1, action = "idle", actionUntil = 0, lastActive = 0, cf = nil, barrage = 0 }
		st.kind, st.tint, st.shoutStroke = "TheWorld", CDV.GOLD, Color3.fromRGB(70, 44, 6)
		local G, D, A, C = CDV.GOLD, CDV.GOLD_DEEP, CDV.TEAL, CDV.CREAM
		local diamond = function(key, cf, size, color)
			CDV.part(st, key, Vector3.new(size, size, size * 0.3), cf * CFrame.Angles(0, 0, math.rad(45)), color)
		end
		-- body: a gold torso, the teal chest plate and belt, diamonds down the front
		CDV.part(st, "torso", Vector3.new(2.3, 2.3, 1.2), CFrame.new(), G)
		CDV.part(st, "torso", Vector3.new(2.44, 0.95, 1.34), CFrame.new(0, 0.62, 0), A)
		CDV.part(st, "torso", Vector3.new(2.44, 0.32, 1.34), CFrame.new(0, -1.0, 0), A)
		diamond("torso", CFrame.new(0, 0.62, -0.7), 0.42, D)
		diamond("torso", CFrame.new(0, -0.25, -0.62), 0.34, D)
		diamond("torso", CFrame.new(0, -1.0, -0.7), 0.3, C)
		-- head: gold, the crested teal helmet, the mask, slit eyes, the tubes
		CDV.part(st, "head", Vector3.new(1.2, 1.3, 1.2), CFrame.new(), G)
		CDV.part(st, "head", Vector3.new(1.3, 0.6, 1.3), CFrame.new(0, 0.42, 0.02), A)
		CDV.part(st, "head", Vector3.new(0.26, 0.5, 1.34), CFrame.new(0, 0.86, 0.06), A)
		CDV.part(st, "head", Vector3.new(0.18, 0.34, 0.5), CFrame.new(0, 1.08, -0.42) * CFrame.Angles(math.rad(-24), 0, 0), C)
		CDV.part(st, "head", Vector3.new(1.24, 0.5, 0.26), CFrame.new(0, -0.34, -0.52), D)
		for side = -1, 1, 2 do
			CDV.part(st, "head", Vector3.new(0.34, 0.1, 0.05), CFrame.new(side * 0.25, 0.08, -0.61), C, Enum.Material.Neon)
			-- a tube from the jaw round to the back of the head, and on to the back
			CDV.part(st, "head", Vector3.new(0.16, 0.16, 1.1), CFrame.new(side * 0.6, -0.3, 0.05) * CFrame.Angles(math.rad(10), 0, 0), A, nil, Enum.PartType.Cylinder)
			CDV.part(st, "torso", Vector3.new(0.16, 1.1, 0.16), CFrame.new(side * 0.4, 1.3, 0.6) * CFrame.Angles(math.rad(-28), 0, 0), A)
		end
		-- arms: rounded teal shoulder pads, gold arms, teal wrist guards, gold fists
		for side, key in { [1] = "armR", [-1] = "armL" } do
			CDV.part(st, key, Vector3.new(1, 1.25, 1), CFrame.new(0, -0.62, 0), G)
			CDV.part(st, key, Vector3.new(1.06, 1.1, 1.06), CFrame.new(0, -1.78, 0), G)
			CDV.part(st, key, Vector3.new(1.16, 0.36, 1.16), CFrame.new(0, -2.2, 0), A)
			st.fists[key] = CDV.part(st, key, Vector3.new(1.08, 0.92, 1.08), CFrame.new(0, -2.74, 0), G)
			CDV.part(st, key, Vector3.new(1.5, 0.9, 1.5), CFrame.new(side * 0.06, 0.16, 0), A, nil, Enum.PartType.Ball)
			diamond(key, CFrame.new(side * 0.76, 0.16, 0) * CFrame.Angles(0, math.rad(side * 90), 0), 0.34, C)
		end
		-- legs: gold, teal knee and shin guards, teal boots
		for _, key in { "legR", "legL" } do
			CDV.part(st, key, Vector3.new(1.05, 1.3, 1.05), CFrame.new(0, -0.66, 0), G)
			CDV.part(st, key, Vector3.new(1.12, 1.25, 1.12), CFrame.new(0, -1.92, 0), A)
			diamond(key, CFrame.new(0, -1.32, -0.6), 0.38, C)
			CDV.part(st, key, Vector3.new(1.08, 0.46, 1.32), CFrame.new(0, -2.72, -0.15), A)
		end
		local hl = Instance.new("Highlight")
		hl.Adornee = model
		hl.FillColor = CDV.GOLD
		hl.FillTransparency = 1
		hl.OutlineColor = Color3.fromRGB(74, 50, 8)
		hl.OutlineTransparency = 1
		hl.DepthMode = Enum.HighlightDepthMode.Occluded
		hl.Parent = model
		st.highlight = hl
		CDV.stands[char] = st
		return st
	end

	function CDV.get(char)
		if not char or not char.Parent then
			return nil
		end
		local st, kind = CDV.stands[char], CDV.kindOf(char)
		if st and st.kind ~= kind then
			st.model:Destroy()
			CDV.stands[char] = nil
			st = nil
		end
		return st or (kind == "TheWorld" and CDV.buildWorld(char)) or CDV.build(char)
	end

	-- bring it out and hold an action (it stays out a while after)
	-- (place: where it stands for it, if not its action's own spot)
	function CDV.act(char, action, duration, place)
		local st = CDV.get(char)
		if not st then
			return nil
		end
		if st.alpha < 0.05 then
			local root = char:FindFirstChild("HumanoidRootPart")
			VFX.PlaySound("StandOn", root and root.Position, 0.8)
		end
		st.action = action
		st.place = place
		st.actionUntil = os.clock() + (duration or 0.3)
		st.lastActive = os.clock()
		return st
	end

	-- a floating shout next to it ("DORARARA!")
	function CDV.shout(st, text, size, life)
		local root = st.char:FindFirstChild("HumanoidRootPart")
		if not root then
			return
		end
		local anchor = newPart(Vector3.one * 0.1, CFrame.new(root.Position + Vector3.new(rand(-2, 2), 4.5, 0)), CDV.PINK)
		anchor.Transparency = 1
		local bb = Instance.new("BillboardGui")
		bb.Size = UDim2.fromScale(size, size * 0.3)
		bb.LightInfluence = 0
		bb.MaxDistance = 250
		bb.Adornee = anchor
		bb.Parent = anchor
		local label = Instance.new("TextLabel")
		label.BackgroundTransparency = 1
		label.Size = UDim2.fromScale(1, 1)
		label.Font = Enum.Font.LuckiestGuy
		label.TextScaled = true
		label.Text = text
		label.TextColor3 = st.tint or CDV.PINK
		label.TextStrokeColor3 = st.shoutStroke or Color3.fromRGB(70, 10, 50)
		label.TextStrokeTransparency = 0
		label.Rotation = rand(-8, 8)
		label.Parent = bb
		tween(anchor, life, { CFrame = anchor.CFrame + UP * 2 })
		tween(label, life * 0.4, { TextTransparency = 1, TextStrokeTransparency = 1 }, nil, nil, life * 0.6)
		cleanup(anchor, life + 0.05)
	end

	-- one limb's CFrame from a pose entry
	local function limbCF(pivot, spec, side)
		spec = spec or { 0, 0, 0 }
		return pivot * CFrame.Angles(0, math.rad(side * (spec[2] or 0)), 0) * CFrame.Angles(0, 0, math.rad(side * (spec[3] or 0))) * CFrame.Angles(math.rad(spec[1] or 0), 0, 0)
	end

	-- (round 66) a pose part-way from the one it holds toward `target`: it
	-- moves from pose to pose instead of snapping
	function CDV.blend(st, target, k)
		local cur = st.pose
		if not cur then
			cur = { head = { 0, 0 }, lean = 0, twist = 0 }
			for _, key in { "armR", "armL", "legR", "legL" } do
				cur[key] = { 0, 0, 0 }
			end
			st.pose = cur
			k = 1
		end
		for _, key in { "armR", "armL", "legR", "legL", "head" } do
			local c, t = cur[key], target[key] or {}
			for i = 1, #c do
				c[i] += ((t[i] or 0) - c[i]) * k
			end
		end
		cur.lean += ((target.lean or 0) - cur.lean) * k
		cur.twist += ((target.twist or 0) - cur.twist) * k
		return cur
	end

	function CDV.step(dt)
		local now = os.clock()
		for char, st in CDV.stands do
			local root = char.Parent and char:FindFirstChild("HumanoidRootPart")
			if not root or not CDV.isUser(char) or CDV.kindOf(char) ~= st.kind then
				st.model:Destroy()
				CDV.stands[char] = nil
				continue
			end
			local acting = now < st.actionUntil
			local action = acting and st.action or "idle"
			-- out while it's doing something and for a while after; Shining
			-- Diamond (the ult) keeps it out the whole time
			local plr = Players:GetPlayerFromCharacter(char)
			local raging = plr and plr:GetAttribute("UltActive") == true
			local want = (acting or raging or now - st.lastActive < 7) and 1 or 0
			st.alpha += math.clamp(want - st.alpha, -dt * 5, dt * 6)
			local place = (acting and st.place and CDV.PLACES[st.place]) or CDV.PLACES[action == "punchR" and "punch" or action == "punchL" and "punch" or action] or CDV.PLACES.idle
			local bob = math.sin(now * 2.2) * 0.22
			local target = root.CFrame * place * CFrame.new(0, action == "idle" and bob or 0, 0)
			if not st.cf or (st.cf.Position - target.Position).Magnitude > 40 then
				st.cf = target
			else
				st.cf = st.cf:Lerp(target, 1 - math.exp(-dt * (acting and 22 or 9)))
			end
			local pose = CDV.POSES[action] or CDV.POSES.idle
			if action == "barrage" then
				-- the rush: fists in and out too fast to follow
				st.barrage += dt
				local right = math.floor(st.barrage / 0.045) % 2 == 0
				pose = right and CDV.POSES.punchR or CDV.POSES.punchL
			end
			-- (round 66) quick while it fights, easy at rest; the rush still snaps
			pose = CDV.blend(st, pose, action == "barrage" and 1 or 1 - math.exp(-dt * (acting and 36 or 10)))
			if st.alpha > 0.01 then
				local torso = st.cf * CFrame.Angles(math.rad(pose.lean or 0), math.rad(pose.twist or 0), 0)
				local frames = {
					torso = torso,
					head = torso * CFrame.new(0, 1.82, 0) * CFrame.Angles(math.rad(pose.head[1]), math.rad(pose.head[2]), 0),
					armR = limbCF(torso * CFrame.new(1.62, 0.86, 0), pose.armR, 1),
					armL = limbCF(torso * CFrame.new(-1.62, 0.86, 0), pose.armL, -1),
					legR = limbCF(torso * CFrame.new(0.6, -1.16, 0), pose.legR, 1),
					legL = limbCF(torso * CFrame.new(-0.6, -1.16, 0), pose.legL, -1),
				}
				local parts, cfs = {}, {}
				for i, e in st.parts do
					parts[i] = e.part
					cfs[i] = frames[e.key] * e.offset
				end
				if not pcall(function()
					workspace:BulkMoveTo(parts, cfs, Enum.BulkMoveMode.FireCFrameChanged)
				end) then
					for i, p in parts do
						p.CFrame = cfs[i]
					end
				end
				if action == "barrage" and rng:NextNumber() < 0.6 then
					-- the afterimages: arms everywhere at once
					local ghost = newPart(Vector3.new(1, 1, 2.8), torso * CFrame.new(rand(-1.8, 1.8), rand(-0.4, 1.5), -2.4 - rand(0, 1.2)), st.tint or CDV.PINK, Enum.Material.Neon)
					ghost.Transparency = 0.45
					tween(ghost, 0.1, { Transparency = 1, CFrame = ghost.CFrame * CFrame.new(0, 0, -1.5) })
					cleanup(ghost, 0.12)
				end
			end
			if math.abs(st.alpha - st.shown) > 0.02 then
				st.shown = st.alpha
				for _, e in st.parts do
					e.part.Transparency = 1 - st.alpha
				end
				st.highlight.OutlineTransparency = 1 - st.alpha * 0.9
			end
			local glow = raging and 0.55 or 1
			if st.highlight.FillTransparency ~= glow then
				st.highlight.FillTransparency = glow
			end
		end
	end
	RunService.RenderStepped:Connect(CDV.step)
	VFX.CDV = CDV -- (round 74: DIO's moves drive The World)

	-- (round 66) the M1s ARE the Stand's: it comes out in front of him and
	-- throws them - a right, a left, a hook, and a big straight (an uppercut
	-- for the upslam, a two-fisted hammer for the downslam) - each wound up
	-- and snapped out; Josuke stands his ground and points the way. It
	-- returns the fist it's hitting with: Effects.Punch draws the trail, the
	-- smear and the finisher's wind from that fist, not from him.
	CDV.M1 = {
		{ "windR", "jabR", "armR" }, { "windL", "jabL", "armL" }, { "windHook", "hook", "armR" }, { "windSmash", "smash", "armR" },
		Up = { "windUpper", "upper", "armR" }, Down = { "windHammer", "hammer", "armR" },
	}
	function VFX.StandPunch(char, count, finisher, variant)
		if not CDV.isUser(char) then
			return nil
		end
		local seq = (finisher and CDV.M1[variant or ""]) or CDV.M1[finisher and 4 or math.clamp(count or 1, 1, 3)]
		local windup = finisher and 0.1 or 0.05
		local place = (finisher and variant == "Up" and "m1up") or (finisher and variant == "Down" and "m1down") or "m1"
		local st = CDV.act(char, seq[1], windup + 0.02, "m1wind")
		if not st then
			return nil
		end
		task.delay(windup, function()
			if not st.model.Parent then
				return
			end
			CDV.act(char, seq[2], finisher and 0.4 or 0.24, place)
			task.wait(0.05)
			local fist = st.fists and st.fists[seq[3]]
			if fist and fist.Parent then
				sparks(fist.Position, finisher and 0.8 or 0.4, Color3.new(1, 1, 1), st.tint or CDV.PINK, finisher and 14 or 5)
				if finisher then
					billboardRing(fist.Position, 1.5, 10, st.tint or CDV.PINK, 5, 0.22)
				end
			end
		end)
		if finisher then
			if st.kind == "TheWorld" then
				CDV.shout(st, variant == "Down" and "MUDA!!" or "MUDA MUDA!", 5, 0.8)
			else
				CDV.shout(st, variant == "Down" and "DORA!!" or "DORARA!", 5, 0.8)
			end
		end
		return st.fists and st.fists[seq[3]] or nil
	end

	-- a pink sparkle where something has just been put back
	function CDV.sparkle(pos, size)
		billboardRing(pos, 0.5, size, CDV.PINK, 4, 0.3)
		sparks(pos, 0.5, Color3.new(1, 1, 1), CDV.PINK, 6)
	end

	-- one piece flying from a to b (a CFrame or a point) and fading in as it lands
	function CDV.fly(a, b, size, color, material, time, delayTime, trail)
		task.delay(delayTime or 0, function()
			local to = typeof(b) == "CFrame" and b or CFrame.new(b)
			local p = newPart(size * 0.45, CFrame.new(a) * CFrame.Angles(rand(0, 6), rand(0, 6), 0), color, material)
			local stop = trail and addTrail(p, CDV.PINK, 0.15, math.min(size.Magnitude * 0.3, 1.2)) or nil
			tween(p, time, { CFrame = to, Size = size }, Enum.EasingStyle.Quad, Enum.EasingDirection.InOut)
			task.delay(time, function()
				if stop then
					stop(0)
				end
				p:Destroy()
			end)
		end)
	end

	-- 1: DORARARARA!
	function Effects.Dorarara(char, data, isLocal, ability)
		VFX.Pose(char, "StandUser", 0.7) -- (Josuke strikes a pose while the Stand works)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		local hits, interval = ability.Hits or 14, ability.Interval or 0.085
		local total = 0.15 + hits * interval
		local st = CDV.act(char, "barrage", total)
		if not st then
			return
		end
		CDV.shout(st, ability.Rage and "DORARARARARARA!!" or "DORARARARA!", ability.Rage and 9 or 7, total)
		for k = 1, hits do
			task.delay(0.15 + (k - 1) * interval, function()
				if not root.Parent then
					return
				end
				VFX.PlaySound("Dora", root.Position, 0.55)
				if k % 2 == 0 then
					local front = root.Position + flatten(root.CFrame.LookVector, root) * 4.5 + UP * 0.8
					sparks(front + Vector3.new(rand(-1, 1), rand(-0.6, 1), rand(-1, 1)), 0.5, Color3.new(1, 1, 1), CDV.PINK, 5)
					if k % 4 == 0 then
						billboardRing(front, 1, 6, Color3.new(1, 1, 1), 4, 0.12)
					end
				end
			end)
		end
		task.wait(total)
		if not root.Parent then
			return
		end
		-- DORA!
		CDV.act(char, "punchR", 0.45)
		CDV.shout(st, "DORA!", 5, 0.8)
		local dd = flatten(root.CFrame.LookVector, root)
		local fist = root.Position + dd * 5 + UP
		VFX.PlaySound("DoraFinish", fist, 1)
		shockDisc(fist, dd, 2, 16, 0.3, WIND, 8)
		billboardRing(fist, 2, 18, CDV.PINK, 6, 0.3)
		streaks(fist, dd, 12, 2, 8, 22, WIND, 0.3)
		VFX.ShakeAt(fist, 2.4, 80, 0.3)
		if nearCamera(fist, 60) then
			VFX.ImpactFrame(0.08)
		end
	end

	-- 2: BUILD (the Stand pounds the street; the server sends the stones)
	function Effects.CrazyBuild(char, data, isLocal, ability)
		VFX.Pose(char, "StandUser", 0.7) -- (Josuke strikes a pose while the Stand works)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		CDV.act(char, "ground", 0.5)
		task.wait(0.2)
		local site = aimGround(root, data, (ability and ability.Range) or 60)
		VFX.PlaySound("GroundPunch", root.Position + d * 3, 0.8)
		dustPuffs(groundPoint(root.Position + d * 3.5), 0.8, 4, Color3.fromRGB(200, 190, 184), 0.8, false)
		billboardRing(site + UP, 2, 16, CDV.PINK, 5, 0.35)
	end

	-- the server built something: every stone flies in from its rubble
	function Effects.CrazyBuilt(_char, data)
		local blocks = type(data.Blocks) == "table" and data.Blocks or {}
		local last = 0
		for i, b in blocks do
			if typeof(b.From) == "Vector3" and typeof(b.To) == "CFrame" and typeof(b.Size) == "Vector3" then
				local delayTime = tonumber(b.Delay) or 0.3
				local flight = math.min(0.35, delayTime)
				CDV.fly(b.From, b.To, b.Size, b.Color or CDV.PINK, b.Material, flight, delayTime - flight, i % 3 == 0)
				last = math.max(last, delayTime)
				if i % 4 == 0 then
					task.delay(delayTime, function()
						CDV.sparkle(b.To.Position, 4)
					end)
				end
			end
		end
		local first = blocks[1]
		local at = first and typeof(first.To) == "CFrame" and first.To.Position
		if at then
			VFX.PlaySound(data.Kind == "Prison" and "Rebuild" or "Rebuild", at, 1)
			task.delay(last, function()
				VFX.PlaySound("RestoreSnap", at, 0.8)
				VFX.ShakeAt(at, data.Kind == "Pillar" and 2.5 or 1.2, 90, 0.25)
				if data.Kind == "Pillar" then
					shockDisc(at + UP * 0.5, UP, 4, 24, 0.35, WIND)
					dustPuffs(at, 1.6, 8, Color3.fromRGB(200, 190, 184), 1.2, true)
				end
			end)
		end
	end

	-- 3: YO, ANGELO (pounding the street in front of them)
	function Effects.YoAngelo(char, data, isLocal)
		VFX.Pose(char, "StandUser", 0.7) -- (Josuke strikes a pose while the Stand works)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		local st = CDV.act(char, "ground", 0.8)
		if st then
			CDV.shout(st, "YO, ANGELO!", 6, 1.2)
		end
		for k = 1, 6 do
			task.delay(k * 0.11, function()
				if not root.Parent then
					return
				end
				CDV.act(char, k % 2 == 0 and "ground" or "punchL", 0.12)
				local g = groundPoint(root.Position + d * rand(4, 8))
				VFX.PlaySound("GroundPunch", g, 0.5)
				dustPuffs(g, 0.6, 3, Color3.fromRGB(190, 180, 172), 0.6, false)
				rocks(g, 0.6, 3)
			end)
		end
	end

	-- R: RESTORE (its hands on the world; the server sends what came back)
	function Effects.CrazyRestore(char, _data, isLocal, ability)
		VFX.Pose(char, "StandUser", 0.7) -- (Josuke strikes a pose while the Stand works)
		local root = charParts(char)
		if not root then
			return
		end
		local st = CDV.act(char, "restore", 0.7)
		local radius = (ability and ability.Radius) or 80
		local shell = newPart(Vector3.one * 4, CFrame.new(root.Position), CDV.PINK, Enum.Material.ForceField, Enum.PartType.Ball)
		tween(shell, 0.45, { Size = Vector3.one * radius * 2 })
		tween(shell, 0.3, { Transparency = 1 }, nil, nil, 0.3)
		cleanup(shell, 0.65)
		billboardRing(root.Position, 3, 30, CDV.PINK, 6, 0.4)
		VFX.PlaySound("RestoreSnap", root.Position, 1)
		if st then
			local hands = st.cf and (st.cf * CFrame.new(0, 0.9, -3)).Position
			if hands then
				sparks(hands, 1, Color3.new(1, 1, 1), CDV.PINK, 18)
			end
		end
		if isLocal and nearCamera(root.Position, 40) then
			VFX.Hooks.Flash(Color3.fromRGB(255, 220, 240), 0.2)
		end
	end

	-- the server put things back: every piece flies home, and what came back
	-- glows pink for a moment
	function Effects.Restored(_char, data)
		local flights = type(data.Flights) == "table" and data.Flights or {}
		for i, f in flights do
			if typeof(f.From) == "Vector3" and typeof(f.To) == "Vector3" and typeof(f.Size) == "Vector3" then
				local time = math.clamp((f.To - f.From).Magnitude / 110, 0.25, 0.6)
				CDV.fly(f.From, f.To, f.Size, f.Color or CDV.PINK, f.Material, time, rand(0, 0.12), i % 3 == 0)
			end
		end
		for _, part in type(data.Parts) == "table" and data.Parts or {} do
			if typeof(part) == "Instance" and part:IsA("BasePart") then
				local box = Instance.new("SelectionBox")
				box.Adornee = part
				box.Color3 = CDV.PINK
				box.LineThickness = 0.08
				box.SurfaceColor3 = CDV.PINK
				box.SurfaceTransparency = 0.55
				box.Parent = folder
				tween(box, 0.8, { SurfaceTransparency = 1, Transparency = 1 }, nil, nil, 0.3)
				cleanup(box, 1.2)
			end
		end
		local center = typeof(data.Center) == "Vector3" and data.Center
		if center then
			VFX.PlaySound("RestoreSnap", center, data.Big and 1.4 or 0.8)
			if data.Big then
				VFX.ShakeAt(center, 4, 220, 0.6)
				billboardRing(center + UP * 3, 10, 160, CDV.PINK, 10, 0.7)
				if nearCamera(center, 140) then
					VFX.Hooks.Flash(Color3.fromRGB(255, 200, 235), 0.35)
				end
			end
		end
	end

	-- Ult 3: BREAK AND RESTORE (the punch that shatters everything around)
	function Effects.BreakRestore(char, _data, _isLocal, ability)
		VFX.Pose(char, "StandUser", 0.7) -- (Josuke strikes a pose while the Stand works)
		local root = charParts(char)
		if not root then
			return
		end
		local st = CDV.act(char, "ground", 0.6)
		if st then
			CDV.shout(st, "DORA!!", 7, 1)
		end
		task.wait(0.4)
		if not root.Parent then
			return
		end
		local radius = (ability and ability.Radius) or 60
		local g = groundPoint(root.Position)
		VFX.PlaySound("CDShatter", g, 1.2)
		if nearCamera(g, 200) then
			VFX.ImpactFrame(0.18)
		end
		for i = 1, 3 do
			task.delay(i * 0.06, function()
				shockDisc(g + UP * (0.5 + i), UP, 6, radius * 2.2, 0.7, i == 2 and CDV.PINK or WIND)
			end)
		end
		billboardRing(g + UP * 2, 6, radius * 2.4, CDV.PINK, 12, 0.6)
		rocks(g, 3, 36)
		for k = 1, 14 do
			local a = k / 14 * math.pi * 2
			dustPuffs(g + Vector3.new(math.cos(a), 0, math.sin(a)) * radius * 0.5, 2.4, 2, Color3.fromRGB(206, 196, 186), 1.8, false)
		end
		VFX.ShakeAt(g, 5, 260, 0.7)
		-- then the Stand opens its hands and it all comes home
		task.delay(((ability and ability.Hold) or 1.3) - 0.3, function()
			if char.Parent then
				CDV.act(char, "restore", 0.8)
			end
		end)
	end

	-- G: Shining Diamond - it comes out roaring
	QUIRK_FX.Ult.CrazyDiamond = function(char, root, g)
		CDV.act(char, "rage", 1.3)
		for i = 1, 8 do
			local a = i / 8 * math.pi * 2
			local p = root.Position + Vector3.new(math.cos(a) * 3, 2 + rand(0, 2), math.sin(a) * 3)
			CDV.fly(p, p + Vector3.new(math.cos(a) * 10, rand(4, 10), math.sin(a) * 10), Vector3.new(0.8, 0.8, 0.3), CDV.DEEP, Enum.Material.Neon, 0.5, 0, true)
		end
		billboardRing(root.Position, 3, 34, CDV.PINK, 7, 0.5)
		shockDisc(g + UP * 0.5, UP, 4, 40, 0.5, CDV.PINK)
	end

	-- Dash: it goes with him
	QUIRK_FX.Dash.CrazyDiamond = function(char, root, dir)
		CDV.act(char, "dash", 0.3)
		streaks(root.Position, -dir, 6, 1.2, 5, 10, CDV.PINK, 0.2)
	end
end

---------------------------------------------------------------------------
-- PARKOUR (Config.Parkour): the body's shapes for each move. The mover's own
-- machine moves the body; everyone sees the shape through this effect.
---------------------------------------------------------------------------
do
	local PK_DUST = Color3.fromRGB(205, 196, 190)
	-- over the top: one hand planted, legs swung through to the side
	MOTIONS.PkVault = {
		{ pose = {
			Hips = { 0, 0, -22, 0, 0.2, 0 }, Waist = { -14, 0, 18 }, Neck = { -6, 0, -10 },
			RightArm = { 48, 0, -8 }, RightElbow = 6, LeftArm = { 100, 0, 34 }, LeftElbow = 20,
			RightLeg = 72, RightKnee = 92, LeftLeg = 82, LeftKnee = 104,
		}, t = 0.07, hold = 0.18 },
		{ pose = "Land", t = 0.08, hold = 0.06 },
		recover = 0.2,
	}
	-- hand over hand up the wall, knees driving
	local reachR = {
		RightArm = { 172, 0, -8 }, RightElbow = 18, LeftArm = { 118, 0, -12 }, LeftElbow = 74,
		RightLeg = 12, RightKnee = 22, LeftLeg = 72, LeftKnee = 84, Waist = { -6, 0, 0 },
	}
	local reachL = {
		LeftArm = { 172, 0, -8 }, LeftElbow = 18, RightArm = { 118, 0, -12 }, RightElbow = 74,
		LeftLeg = 12, LeftKnee = 22, RightLeg = 72, RightKnee = 84, Waist = { -6, 0, 0 },
	}
	MOTIONS.PkClimb = {
		{ pose = reachR, t = 0.06, hold = 0.06 },
		{ pose = reachL, t = 0.06, hold = 0.06 },
		recover = 0.12,
	}
	-- over the edge: arms push down, knees come up
	MOTIONS.PkMantle = {
		{ pose = { RightArm = { 150, 0, -10 }, LeftArm = { 150, 0, -10 }, RightElbow = 40, LeftElbow = 40, Waist = { -10, 0, 0 } }, t = 0.06, hold = 0.06 },
		{ pose = {
			RightArm = { 30, 0, -10 }, LeftArm = { 30, 0, -10 }, RightElbow = 5, LeftElbow = 5, Waist = { -28, 0, 0 },
			RightLeg = 95, RightKnee = 110, LeftLeg = 70, LeftKnee = 95,
		}, t = 0.07, hold = 0.1 },
		recover = 0.2,
	}
	-- feet first under it, one arm trailing (the body itself is tipped back)
	MOTIONS.PkSlide = {
		{ pose = {
			Waist = { -12, 0, 0 }, Neck = { -24, 0, 0 },
			RightLeg = 82, RightKnee = 4, LeftLeg = 32, LeftKnee = 96,
			RightArm = { -34, 0, 24 }, RightElbow = 10, LeftArm = { 62, 0, -10 }, LeftElbow = 30,
		}, t = 0.06, hold = 0.34 },
		recover = 0.2,
	}
	-- running along a wall, leaning into it (L / R: which side it's on)
	for side, lean in { L = -1, R = 1 } do
		MOTIONS["PkWallRun" .. side] = {
			{ pose = {
				Hips = { 0, 0, 16 * lean, 0, 0, 0 }, Waist = { -8, 0, 10 * lean },
				RightLeg = 62, RightKnee = 40, LeftLeg = -34, LeftKnee = 72,
				RightArm = { -30, 0, 16 }, LeftArm = { 72, 0, -10 }, LeftElbow = 62,
			}, t = 0.06, hold = 0.08 },
			{ pose = {
				Hips = { 0, 0, 16 * lean, 0, 0, 0 }, Waist = { -8, 0, 10 * lean },
				LeftLeg = 62, LeftKnee = 40, RightLeg = -34, RightKnee = 72,
				LeftArm = { -30, 0, 16 }, RightArm = { 72, 0, -10 }, RightElbow = 62,
			}, t = 0.06, hold = 0.08 },
			recover = 0.15,
		}
	end
	-- the kick off it: coiled, then springing out
	MOTIONS.PkWallKick = {
		{ pose = {
			RightLeg = 76, RightKnee = 96, LeftLeg = 42, LeftKnee = 72,
			RightArm = { 150, 0, 16 }, LeftArm = { 150, 0, 16 }, RightElbow = 20, LeftElbow = 20, Waist = { 10, 0, 0 },
		}, t = 0.05, hold = 0.2, style = Enum.EasingStyle.Back },
		recover = 0.25,
	}
	-- tucked tight (the body itself turns over)
	MOTIONS.PkRoll = {
		{ pose = "Tuck", t = 0.05, hold = 0.34 },
		recover = 0.2,
	}

	-- (round 73) BAKUGO'S EXPLOSION FLIGHT - taking off (Start), every blast
	-- (Pulse) and dropping out (End); the client's BlastFly flies him. Leaning
	-- into it, both palms thrown back behind him, a blast off each one the
	-- other way to where he's going, and a smoke trail between them.
	POSES.BlastFly = {
		Hips = { -38, 0, 0, 0, 0, 0 }, Waist = { -8, 0, 0 }, Neck = { -34, 0, 0 },
		RightArm = { -55, 0, 28 }, LeftArm = { -55, 0, 28 }, RightElbow = 10, LeftElbow = 10,
		RightLeg = -12, LeftLeg = 6, RightKnee = 35, LeftKnee = 12,
	}
	POSES.BlastFlyPush = {
		Hips = { -46, 0, 0, 0, 0, 0 }, Waist = { -10, 0, 0 }, Neck = { -40, 0, 0 },
		RightArm = { -82, 0, 36 }, LeftArm = { -82, 0, 36 }, RightElbow = 0, LeftElbow = 0,
		RightLeg = -20, LeftLeg = 2, RightKnee = 48, LeftKnee = 20,
	}
	MOTIONS.BlastFlyPulse = {
		{ pose = "BlastFlyPush", t = 0.04, hold = 0.06, style = SNAP },
		{ pose = "BlastFly", t = 0.16, hold = 30 },
		recover = 0.2,
	}
	VFX.BlastFlying = setmetatable({}, { __mode = "k" })
	function Effects.BlastFly(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		if data.Kind == "End" then
			if VFX.BlastFlying[char] then
				VFX.BlastFlying[char] = nil
				VFX.ReleasePose(char, 0.2)
			end
			return
		end
		local start = data.Kind == "Start"
		VFX.BlastFlying[char] = true
		local d = (typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.01) and data.Dir.Unit or root.CFrame.LookVector
		VFX.Motion(char, "BlastFlyPulse")
		VFX.MuteGait(char, 0.6)
		-- a blast off each palm, the other way to where he's going
		for _, right in { true, false } do
			local palm = handPos(char, right)
			toonExplosion(palm - d * 0.9, start and 0.32 or 0.22, { NoOutline = true, NoEmbers = true })
		end
		local tail = root.Position - d * 2.5
		dustPuffs(tail, 0.45, 2, SMOKE_LIGHT, 0.7)
		streaks(root.Position, -d, 5, 1.2, 5, 10, Color3.fromRGB(255, 214, 120), 0.25)
		if start then
			-- the take-off: the street blasted under him
			local hit = groundRay(root.Position, 8)
			if hit then
				toonExplosion(hit.Position + UP * 0.5, 0.55, { NoOutline = true, NoEmbers = true })
				shockDisc(hit.Position + UP * 0.3, UP, 3, 18, 0.3, Color3.fromRGB(255, 226, 150))
				dustPuffs(hit.Position, 0.9, 5, Color3.fromRGB(206, 196, 186), 0.9, true)
			end
			VFX.PlaySound("Grenade", root.Position, 0.8)
		end
		VFX.PlaySound("PalmPop", root.Position, start and 1.1 or 0.9)
		if isLocal then
			VFX.ShakeAt(root.Position, start and 0.9 or 0.4, 30, 0.12)
		end
	end

	function Effects.Parkour(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local kind = data.Kind
		if kind == "Glide" or kind == "GlideEnd" then
			-- (round 59) Suneater's wings, out or folded away
			if VFX.SEGlide then
				VFX.SEGlide(char, kind == "Glide")
			end
			return
		end
		if kind == "SlamHop" then
			VFX.M1Kit.slamHop(char, false) -- (round 83) the downslam's hop: its pose
			return
		end
		local t = tonumber(data.Time) or 0.35
		local d = typeof(data.Dir) == "Vector3" and data.Dir or root.CFrame.LookVector
		VFX.MuteGait(char, t + 0.15)
		local g = groundPoint(root.Position)
		if kind == "Vault" then
			VFX.Motion(char, "PkVault")
			VFX.PlaySound("PkVault", root.Position, 1)
			dustPuffs(g, 0.5, 3, PK_DUST, 0.5, false)
		elseif kind == "Mantle" then
			VFX.Motion(char, "PkMantle")
			VFX.PlaySound("PkClimb", root.Position, 1)
		elseif kind == "Climb" or kind == "WallUp" then
			-- hand over hand for as long as it lasts
			task.spawn(function()
				local t0 = os.clock()
				while os.clock() - t0 < t - 0.05 and root.Parent do
					VFX.Motion(char, "PkClimb")
					VFX.PlaySound("PkClimb", root.Position, 0.7)
					task.wait(0.24)
				end
				if kind == "Climb" and root.Parent then
					VFX.Motion(char, "PkMantle")
				end
			end)
		elseif kind == "Slide" then
			VFX.Motion(char, "PkSlide")
			VFX.PlaySound("PkSlide", root.Position, 1)
			for i = 0, 3 do
				task.delay(i * 0.1, function()
					if root.Parent then
						dustPuffs(groundPoint(root.Position), 0.45, 2, PK_DUST, 0.5, false)
					end
				end)
			end
			streaks(root.Position, -d, 5, 1, 4, 8, WIND, 0.2)
		elseif kind == "WallRun" then
			VFX.Motion(char, data.Side == "L" and "PkWallRunL" or "PkWallRunR")
			streaks(root.Position, -d, 4, 0.8, 4, 8, WIND, 0.2)
		elseif kind == "WallKick" then
			VFX.Motion(char, "PkWallKick")
			VFX.PlaySound("PkWallKick", root.Position, 1)
			shockDisc(root.Position - d * 1.2, d, 1, 6, 0.2, WIND, 2)
			dustPuffs(root.Position - d * 1.4, 0.4, 3, PK_DUST, 0.4, false)
		elseif kind == "Roll" then
			VFX.Motion(char, "PkRoll")
			VFX.PlaySound("PkRoll", root.Position, 1)
			dustPuffs(g, 0.8, 5, PK_DUST, 0.7, false)
			shockDisc(g + UP * 0.3, UP, 1.5, 9, 0.25, WIND)
		end
	end
end

---------------------------------------------------------------------------
-- Emotes (the B wheel, Config.Emotes): keyframed motions every client
-- plays. One stops the moment you move, jump, or get hit.
---------------------------------------------------------------------------
do
	-- a few steps played over and over
	local function looped(steps, times, recover)
		local m = { recover = recover or 0.3 }
		for _ = 1, times do
			for _, step in steps do
				table.insert(m, step)
			end
		end
		return m
	end
	MOTIONS.EmoteWave = looped({
		{ pose = { RightArm = { 165, 0, 40 }, RightElbow = 25, LeftArm = { 8, 0, 8 }, Neck = { -4, -12, 6 }, Waist = { 0, -8, 0 } }, t = 0.16, hold = 0.04 },
		{ pose = { RightArm = { 165, 0, 18 }, RightElbow = 65, LeftArm = { 8, 0, 8 }, Neck = { -4, -12, 6 }, Waist = { 0, -8, 0 } }, t = 0.16, hold = 0.04 },
	}, 4)
	MOTIONS.EmotePoint = {
		{ pose = { RightArm = { 70, 0, 0 }, RightElbow = 70, LeftArm = { -10, 0, 12 }, Waist = { -4, 14, 0 }, Neck = { 0, -10, 0 } }, t = 0.1, hold = 0.08 },
		{ pose = { RightArm = { 94, 0, 0 }, RightElbow = 0, LeftArm = { -20, 0, 18 }, LeftElbow = 20, Waist = { -8, 24, 0 }, Neck = { 4, -18, 0 }, RightLeg = -12, LeftLeg = 18, LeftKnee = 20 }, t = 0.08, hold = 1.4, style = Enum.EasingStyle.Back },
		recover = 0.3,
	}
	MOTIONS.EmoteLaugh = looped({
		{ pose = { Waist = { 22, 0, 0 }, Neck = { -28, 0, 0 }, RightArm = { 30, 0, -34 }, RightElbow = 95, LeftArm = { 30, 0, -34 }, LeftElbow = 95 }, t = 0.09, hold = 0.03 },
		{ pose = { Waist = { 12, 0, 0 }, Neck = { -16, 0, 0 }, RightArm = { 26, 0, -34 }, RightElbow = 90, LeftArm = { 26, 0, -34 }, LeftElbow = 90 }, t = 0.09, hold = 0.03 },
	}, 8)
	MOTIONS.EmoteCheer = looped({
		{ pose = { RightArm = { 178, 0, 12 }, RightElbow = 0, LeftArm = { 20, 0, 20 }, LeftElbow = 70, Waist = { 10, -10, 0 }, Neck = { -18, 0, 0 } }, t = 0.1, hold = 0.14 },
		{ pose = { RightArm = { 140, 0, 20 }, RightElbow = 70, LeftArm = { 20, 0, 20 }, LeftElbow = 70, Waist = { 4, -6, 0 }, Neck = { -8, 0, 0 } }, t = 0.12, hold = 0.04 },
	}, 3)
	MOTIONS.EmoteDance = looped({
		{
			pose = {
				Waist = { 0, 16, 8 }, Neck = { 0, -10, -6 }, RightArm = { 60, 0, 40 }, RightElbow = 90, LeftArm = { 20, 0, 60 }, LeftElbow = 60,
				RightLeg = 12, LeftLeg = -10, RightKnee = 22, LeftKnee = 6, Hips = { 0, 0, 0, 0, -0.3, 0 },
			},
			t = 0.17, hold = 0.06, style = Enum.EasingStyle.Sine,
		},
		{
			pose = {
				Waist = { 0, -16, -8 }, Neck = { 0, 10, 6 }, RightArm = { 20, 0, 60 }, RightElbow = 60, LeftArm = { 60, 0, 40 }, LeftElbow = 90,
				RightLeg = -10, LeftLeg = 12, RightKnee = 6, LeftKnee = 22, Hips = { 0, 0, 0, 0, -0.1, 0 },
			},
			t = 0.17, hold = 0.06, style = Enum.EasingStyle.Sine,
		},
	}, 7)
	MOTIONS.EmoteFlex = {
		{ pose = { RightArm = { 100, 0, 70 }, RightElbow = 125, LeftArm = { 100, 0, 70 }, LeftElbow = 125, Waist = { 10, 0, 0 }, Neck = { -12, 0, 0 }, RightLeg = 8, LeftLeg = -8 }, t = 0.14, hold = 0.5, style = Enum.EasingStyle.Back },
		{ pose = { RightArm = { 104, 0, 76 }, RightElbow = 132, LeftArm = { 104, 0, 76 }, LeftElbow = 132, Waist = { 14, 0, 0 }, Neck = { -16, 0, 0 }, RightLeg = 8, LeftLeg = -8 }, t = 0.1, hold = 0.35 },
		{ pose = { RightArm = { 100, 0, 70 }, RightElbow = 125, LeftArm = { 100, 0, 70 }, LeftElbow = 125, Waist = { 10, 0, 0 }, Neck = { -12, 0, 0 }, RightLeg = 8, LeftLeg = -8 }, t = 0.1, hold = 0.6 },
		recover = 0.35,
	}
	MOTIONS.EmoteBow = {
		{ pose = { Waist = { -48, 0, 0 }, Neck = { 12, 0, 0 }, RightArm = { 6, 0, -4 }, LeftArm = { 6, 0, -4 } }, t = 0.35, hold = 0.7, style = Enum.EasingStyle.Sine },
		recover = 0.45,
	}
	MOTIONS.EmoteTaunt = looped({
		{ pose = { LeftArm = { 80, 0, -8 }, LeftElbow = 15, RightArm = { -20, 0, 30 }, RightElbow = 80, Waist = { -4, -20, 0 }, Neck = { 0, 14, 0 } }, t = 0.12, hold = 0.06 },
		{ pose = { LeftArm = { 84, 0, -8 }, LeftElbow = 85, RightArm = { -20, 0, 30 }, RightElbow = 80, Waist = { -4, -20, 0 }, Neck = { 0, 14, 0 } }, t = 0.12, hold = 0.06 },
	}, 4)

	-- THE JIGGY (was DAD MODE): 32 beats of dad dancing, each move on the beat (Bpm)
	do
		local B = 60 / 128
		local function beat(pose, beats, style)
			return { pose = pose, t = math.min(0.12, B * beats * 0.4), hold = B * beats - math.min(0.12, B * beats * 0.4), style = style or SNAP }
		end
		local m = { recover = 0.45 }
		local function add(step)
			table.insert(m, step)
		end
		-- 1-8: the disco point - up to the sky, down to the floor, hips popping
		local up = {
			RightArm = { 165, 0, -20 }, RightElbow = 0, LeftArm = { 10, 0, 30 }, LeftElbow = 10, Waist = { 6, -18, 10 },
			Hips = { 0, 0, 0, 0.25, 0, 0 }, RightLeg = 10, LeftLeg = -6, LeftKnee = 20, Neck = { -22, -15, 0 },
		}
		local down = {
			RightArm = { -35, 0, 40 }, RightElbow = 0, LeftArm = { 10, 0, 30 }, LeftElbow = 10, Waist = { -8, 18, -10 },
			Hips = { 0, 0, 0, -0.25, 0, 0 }, RightKnee = 25, LeftKnee = 8, Neck = { 18, 15, 0 },
		}
		for _ = 1, 4 do
			add(beat(up, 1))
			add(beat(down, 1))
		end
		-- 9-16: the sprinkler - tick, tick, tick... and whoosh back
		for _ = 1, 2 do
			for k = 1, 3 do
				add(beat({
					LeftArm = { 165, 0, -40 }, LeftElbow = 130, RightArm = { 90, 0, 0 }, RightElbow = 0,
					Waist = { 0, -15 * k, 0 }, Hips = { 0, -6 * k, 0, 0, -0.15, 0 }, RightKnee = 15, LeftKnee = 15, Neck = { 0, -8 * k, 0 },
				}, 1))
			end
			add(beat({
				LeftArm = { 165, 0, -40 }, LeftElbow = 130, RightArm = { 90, 0, 0 }, RightElbow = 0,
				Waist = { 0, 32, 0 }, Hips = { 0, 12, 0, 0, -0.15, 0 }, RightKnee = 15, LeftKnee = 15, Neck = { 0, 20, 0 },
			}, 1, Enum.EasingStyle.Back))
		end
		-- 17-24: the lawnmower - pull the cord (nothing), PULL (it starts), mow
		local crouch = { Waist = { -50, 10, 0 }, RightArm = { 40, 0, 10 }, RightElbow = 10, LeftArm = { 20, 0, 20 }, Neck = { 25, 0, 0 }, RightKnee = 30, LeftKnee = 30, Hips = { 0, 0, 0, 0, -0.4, 0 } }
		add(beat(crouch, 1))
		add(beat({ Waist = { 8, -22, 0 }, RightArm = { 150, 0, 30 }, RightElbow = 30, LeftArm = { 40, 0, 20 }, Neck = { -10, 0, 0 } }, 1))
		add(beat(crouch, 1))
		add(beat({ Waist = { 14, -30, 0 }, RightArm = { 172, 0, 40 }, RightElbow = 0, LeftArm = { 60, 0, 30 }, Neck = { -24, 0, 0 }, Hips = { 0, 0, 0, 0, 0.35, 0 } }, 1, Enum.EasingStyle.Back))
		for k = 1, 4 do
			local s = k % 2 == 0 and 1 or -1
			add(beat({
				RightArm = { 62, 0, 0 }, LeftArm = { 62, 0, 0 }, RightElbow = 30, LeftElbow = 30, Waist = { -15, 4 * s, 0 },
				RightLeg = 22 * s, LeftLeg = -22 * s, RightKnee = s > 0 and 30 or 8, LeftKnee = s > 0 and 8 or 30, Neck = { 6, 0, 0 },
			}, 1))
		end
		-- 25-30: the floss, double time
		for k = 1, 12 do
			local s = k % 2 == 0 and 1 or -1
			-- (both arms swung out to one side - one in front, one behind - the
			-- hips thrown the other way)
			add(beat({
				RightArm = { -35 * s, 0, s > 0 and 55 or -45 }, LeftArm = { 35 * s, 0, s > 0 and -45 or 55 }, RightElbow = 0, LeftElbow = 0,
				Hips = { 0, 10 * s, 0, -0.45 * s, 0, 0 }, Waist = { 0, -10 * s, 4 * s }, RightKnee = 14, LeftKnee = 14,
			}, 0.5))
		end
		-- 31-32: DAB
		add(beat({
			Neck = { -30, 34, 0 }, LeftArm = { 100, 0, -52 }, LeftElbow = 125, RightArm = { 30, 0, 128 }, RightElbow = 0,
			Waist = { -14, 24, 0 }, RightLeg = -8, LeftLeg = 12, LeftKnee = 14,
		}, 2, Enum.EasingStyle.Back))
		MOTIONS.EmoteDadMode = m
	end

	-- the party round a Party emote: a light-up dance floor under him, a disco
	-- ball over his head throwing coloured beams, notes floating off him, the
	-- song (heard nearby) and confetti on the last two beats. Returns stop().
	local function party(root, entry, total)
		local bpm, offset = entry.Bpm or 120, entry.Offset or 0
		local beatLen = 60 / bpm
		local colors = {
			Color3.fromRGB(255, 64, 160), Color3.fromRGB(64, 200, 255), Color3.fromRGB(255, 220, 60),
			Color3.fromRGB(120, 255, 110), Color3.fromRGB(190, 110, 255), Color3.fromRGB(255, 130, 50),
		}
		local g = groundPoint(root.Position)
		local parts = {}
		local tiles = {}
		for x = -1, 1 do
			for z = -1, 1 do
				local tile = newPart(Vector3.new(1.9, 0.12, 1.9), CFrame.new(g + Vector3.new(x * 2, 0.07, z * 2)), colors[1], Enum.Material.Neon)
				tile.Transparency = 0.15
				table.insert(tiles, { part = tile, i = (x + 1) + (z + 1) * 3 })
				table.insert(parts, tile)
			end
		end
		local ballAt = root.Position + UP * 6.5
		local ball = newPart(Vector3.one * 1.8, CFrame.new(ballAt), Color3.fromRGB(215, 220, 230), Enum.Material.Foil, Enum.PartType.Ball)
		ball.Reflectance = 0.6
		local cord = newPart(Vector3.new(0.06, 3, 0.06), CFrame.new(ballAt + UP * 2.4), Color3.fromRGB(40, 40, 44))
		table.insert(parts, ball)
		table.insert(parts, cord)
		local light = Instance.new("PointLight")
		light.Range = 16
		light.Brightness = 3
		light.Color = colors[2]
		light.Parent = ball
		local beams = {}
		for k = 1, 4 do
			local beam = newPart(Vector3.new(0.14, 0.14, 7), CFrame.new(ballAt), colors[k], Enum.Material.Neon)
			beam.Transparency = 0.35
			beams[k] = beam
			table.insert(parts, beam)
		end
		local sound = Instance.new("Sound")
		sound.Name = "PartySong"
		local songId, songVolume = VFX.EmoteSong(entry)
		sound.SoundId = songId or ((Config.Music and Config.Music.Disco) or "")
		sound.Volume = songVolume or 0.8
		sound.RollOffMode = Enum.RollOffMode.InverseTapered
		sound.RollOffMinDistance = 12
		sound.RollOffMaxDistance = 90
		sound.Parent = root
		pcall(function()
			sound:Play()
		end)
		local t0 = os.clock()
		local lastBeat = -1
		local confetti = false
		local conn
		conn = RunService.RenderStepped:Connect(function()
			local t = os.clock() - t0
			local b = math.floor((t - offset) / beatLen)
			local spin = t * 2.2
			ball.CFrame = CFrame.new(ballAt) * CFrame.Angles(0, spin, 0)
			for k, beam in beams do
				local a = spin + k * math.pi / 2
				local dir = Vector3.new(math.cos(a) * 0.8, -0.6, math.sin(a) * 0.8).Unit
				beam.CFrame = CFrame.lookAt(ballAt + dir * 4.4, ballAt + dir * 9)
			end
			if b ~= lastBeat and b >= 0 then
				lastBeat = b
				-- the floor lights up on the beat: a checkerboard, flipping, new colours
				for _, tile in tiles do
					local on = (tile.i + b) % 2 == 0
					tile.part.Color = colors[(tile.i + b) % #colors + 1]
					tile.part.Transparency = on and 0.05 or 0.6
				end
				light.Color = colors[b % #colors + 1]
				for k, beam in beams do
					beam.Color = colors[(b + k) % #colors + 1]
				end
				-- a note floating up off him
				local noteAnchor = newPart(Vector3.one * 0.1, CFrame.new(root.Position + UP * 2.5 + Vector3.new(rand(-1.5, 1.5), 0, rand(-1.5, 1.5))), Color3.new(), nil)
				noteAnchor.Transparency = 1
				local bb = Instance.new("BillboardGui")
				bb.Size = UDim2.fromOffset(40, 40)
				bb.AlwaysOnTop = false
				bb.MaxDistance = 90
				bb.Parent = noteAnchor
				local label = Instance.new("TextLabel")
				label.Size = UDim2.fromScale(1, 1)
				label.BackgroundTransparency = 1
				label.Text = b % 2 == 0 and "♪" or "♫"
				label.TextScaled = true
				label.Font = Enum.Font.GothamBlack
				label.TextColor3 = colors[b % #colors + 1]
				label.TextStrokeTransparency = 0
				label.Parent = bb
				tween(noteAnchor, beatLen * 3, { CFrame = noteAnchor.CFrame + UP * 4 + Vector3.new(rand(-1, 1), 0, rand(-1, 1)) }, Enum.EasingStyle.Sine)
				tween(label, beatLen * 3, { TextTransparency = 1, TextStrokeTransparency = 1 })
				cleanup(noteAnchor, beatLen * 3 + 0.05)
				-- (the dab: confetti everywhere)
				if not confetti and b >= 30 then
					confetti = true
					for _ = 1, 40 do
						local bit = newPart(Vector3.new(0.3, 0.05, 0.2), CFrame.new(root.Position + UP * 2) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)), colors[rng:NextInteger(1, #colors)], Enum.Material.SmoothPlastic)
						local out = Vector3.new(rand(-1, 1), 0, rand(-1, 1)) * rand(3, 7)
						tween(bit, 0.35, { CFrame = bit.CFrame + out + UP * rand(4, 8) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
						task.delay(0.35, function()
							tween(bit, 1.2, { CFrame = bit.CFrame * CFrame.Angles(rand(-3, 3), rand(-3, 3), rand(-3, 3)) - UP * 6, Transparency = 1 }, Enum.EasingStyle.Sine)
						end)
						cleanup(bit, 1.6)
					end
					VFX.PlaySound("Confetti", root.Position, 1)
				end
			end
			if t > total + 0.3 then
				conn:Disconnect()
			end
		end)
		local stopped = false
		return function()
			if stopped then
				return
			end
			stopped = true
			conn:Disconnect()
			tween(sound, 0.35, { Volume = 0 })
			task.delay(0.36, function()
				pcall(function()
					sound:Stop()
				end)
				sound:Destroy()
			end)
			for _, p in parts do
				tween(p, 0.3, { Transparency = 1 })
				cleanup(p, 0.35)
			end
		end
	end

	function Effects.Emote(char, data)
		local id = typeof(data.Id) == "string" and data.Id or ""
		local motion = MOTIONS["Emote" .. id]
		local root = charParts(char)
		if not motion or not root then
			return
		end
		VFX.Motion(char, "Emote" .. id)
		local token = poseTokens[char]
		local entry
		for _, e in Config.Emotes or {} do
			if e.Id == id then
				entry = e
				if e.Say then
					VFX.SpeechBubble(char, e.Say, 1.6)
				end
			end
		end
		local total = 0
		for _, step in ipairs(motion) do
			total += (step.t or 0.08) + (step.hold or 0)
		end
		local stop = entry and entry.Party and party(root, entry, total)
		local t0 = os.clock()
		while os.clock() - t0 < total do
			task.wait(0.05)
			if poseTokens[char] ~= token or not root.Parent then
				break -- (something else took the body over)
			end
			local v = root.AssemblyLinearVelocity
			if Vector3.new(v.X, 0, v.Z).Magnitude > 4 or math.abs(v.Y) > 12
				or char:GetAttribute("Stunned") or char:GetAttribute("Ragdolled") then
				VFX.ReleasePose(char, 0.15)
				break
			end
		end
		if stop then
			stop()
		end
	end
end

local TARGET_OWNED = { Hit = true, Guard = true, Parry = true, GuardBreak = true, Block = true }
-- effects that mean a fight is on (for the fighting-stance idle)
local COMBAT_FX = { Punch = true, Hit = true, Guard = true, Block = true, Parry = true, GuardBreak = true }

function VFX.Play(effectId, char, data, isLocal)
	local fn = Effects[effectId]
	if not fn then
		return
	end
	data = data or {}
	local owner = char
	if TARGET_OWNED[effectId] and typeof(data.Target) == "Instance" then
		owner = data.Target
	end
	if COMBAT_FX[effectId] and VFX.MarkCombat then
		-- they're fighting: their idle becomes a guard for a few seconds
		VFX.MarkCombat(char)
		if typeof(data.Target) == "Instance" then
			VFX.MarkCombat(data.Target)
		end
	end
	local info, window = animationFor(effectId, data)
	if info and owner and rigMatches(owner) and Players:GetPlayerFromCharacter(owner) then
		poseBlockedUntil[owner] = os.clock() + math.max(window, info.Length or 0)
		VFX.ReleasePose(owner, 0.1)
		local me = Players.LocalPlayer
		if me and me.Character == owner then
			VFX.PlayAnimation(owner, info)
		end
	end
	task.spawn(function()
		local ok, err = pcall(fn, char, data, isLocal, Config.FindAbilityById(effectId))
		if not ok then
			warn("[VFX] " .. tostring(effectId) .. " failed: " .. tostring(err))
		end
	end)
	-- (round 76) the voice lines that go with it (Config.VoiceCues.Moves)
	if VFX.VC then
		pcall(VFX.VC.onPlay, effectId, char)
	end
end

---------------------------------------------------------------------------
-- SWINGING (Kamui Woods' branches, Suneater's tentacle), the way Insomniac's
-- Spider-Man does it: the line goes out to something tall - either side of
-- the street, up ahead - but the swing itself keeps him on HIS line. The
-- anchor is brought round onto the way he's going and he pendulums along
-- it, so he travels straight down the street instead of being dragged at the
-- building. Momentum carries through (a swing into a swing only gets
-- faster); holding a direction bends the next swing towards it a little.
-- The swinger's own screen moves him (a LinearVelocity along the arc) and
-- lets go flying at the end; everyone else just sees the line.
---------------------------------------------------------------------------
do
	local SW = {
		active = setmetatable({}, { __mode = "k" }), -- [char] = the swing going
		carries = setmetatable({}, { __mode = "k" }), -- [char] = the fling after one
	}

	-- the way he's travelling: his momentum if he's moving (a swing out of a
	-- swing), else where he's looking; a held direction turns it a little
	-- (at most 40 degrees a swing), letting go of the stick keeps him straight
	local function travelDir(root, hum, fallback)
		local v = root.AssemblyLinearVelocity
		local flat = Vector3.new(v.X, 0, v.Z)
		local f = flat.Magnitude > 30 and flat.Unit or fallback
		local want = hum and hum.MoveDirection or Vector3.zero
		want = Vector3.new(want.X, 0, want.Z)
		if want.Magnitude > 0.1 then
			want = want.Unit
			local angle = math.acos(math.clamp(f:Dot(want), -1, 1))
			if angle > 1e-3 then
				local turned = f:Lerp(want, math.min(1, math.rad(40) / angle))
				f = turned.Magnitude > 1e-3 and turned.Unit or want
			end
		end
		return f
	end
	VFX.SwingDirection = travelDir

	-- something a line can hold on to: solid map, not an invisible wall, a
	-- walk-through prop or anyone's stuff (a ray goes on through those)
	local function solidHit(origin, ray, range, params)
		local dir = ray.Unit
		local from, left = origin, range
		for _ = 1, 4 do
			local hit = workspace:Raycast(from, dir * left, params)
			local part = hit and hit.Instance
			if not (part and part:IsA("BasePart") and (part.Transparency > 0.95 or not part.CanCollide)) then
				return hit
			end
			local gone = (hit.Position - from).Magnitude + 0.05
			from, left = from + dir * gone, left - gone
			if left <= 1 then
				return nil
			end
		end
		return nil
	end
	VFX.SwingHit = solidHit

	-- a point to swing from: something above his head, along his line and
	-- high - where he's aiming first (if that's up at something), else the
	-- best of a dense fan up, ahead and to either side (Config.SwingScore)
	function VFX.SwingAnchor(char, aim, range)
		local root, hum = charParts(char)
		if not root then
			return nil
		end
		range = range or 110
		local params = RaycastParams.new()
		params.FilterType = Enum.RaycastFilterType.Exclude
		params.FilterDescendantsInstances = characterList()
		local origin = root.Position + UP * 2
		local look = travelDir(root, hum, flatten(typeof(aim) == "Vector3" and aim or root.CFrame.LookVector, root))
		local right = look:Cross(UP)
		local best, bestScore
		local function try(ray, bonus)
			local hit = solidHit(origin, ray, range, params)
			if hit and hit.Position.Y > root.Position.Y + 3 then
				local rel = hit.Position - root.Position
				local ahead = rel:Dot(look)
				if ahead > -4 then
					-- (off to the side is fine - the swing stays on his line - unless
					-- it's a long way off it)
					local score = Config.SwingScore(ahead, rel.Y, math.abs(rel:Dot(right))) + (bonus or 0)
					if not bestScore or score > bestScore then
						best, bestScore = hit.Position + hit.Normal * 0.3, score
					end
				end
			end
		end
		if typeof(aim) == "Vector3" and aim.Magnitude > 0.01 and aim.Unit.Y > 0.15 then
			try(aim, 25)
		end
		for _, pitch in Config.SwingFan.Pitches do
			for _, yaw in Config.SwingFan.Yaws do
				local a, p = math.rad(yaw), math.rad(pitch)
				local flat = look * math.cos(a) + right * math.sin(a)
				try(flat * math.cos(p) + UP * math.sin(p))
			end
		end
		return best
	end

	function VFX.Swinging(char)
		return SW.active[char] ~= nil
	end

	-- let go now (R again, another move, a knock, a dash) - and no carrying
	-- on the fling from the last one either
	function VFX.SwingRelease(char)
		local st = SW.active[char]
		if st then
			st.release = true
		end
		SW.carries[char] = nil
	end

	-- after letting go: the fling keeps its speed a while (`time`, easing off
	-- a little), so steering in the air bends it but can't eat it. It stops
	-- when he lands, hits a wall, swings again, gets hit or another move or
	-- a dash takes over.
	function SW.carry(char, root, hum, flatV, time)
		local c = {}
		SW.carries[char] = c
		local params = RaycastParams.new()
		params.FilterType = Enum.RaycastFilterType.Exclude
		params.FilterDescendantsInstances = characterList()
		task.spawn(function()
			local t0 = os.clock()
			RunService.Heartbeat:Wait()
			while root.Parent and SW.carries[char] == c and not SW.active[char] do
				local t = os.clock() - t0
				if t > time or char:GetAttribute("Stunned") or char:GetAttribute("Ragdolled") or char:GetAttribute("Grabbed") then
					break
				end
				if hum and hum.FloorMaterial ~= Enum.Material.Air then
					break
				end
				local want = flatV * (1 - 0.3 * t / time)
				local speed = want.Magnitude
				local v = root.AssemblyLinearVelocity
				local have = Vector3.new(v.X, 0, v.Z)
				local along = have:Dot(want.Unit)
				if along < speed then
					if workspace:Raycast(root.Position, want.Unit * math.max(speed * 0.08, 2.5), params) then
						break -- (a wall: he stops against it, not stuck to it)
					end
					-- (topped back up along the fling; the sideways part is the
					-- player steering, and it stays)
					root.AssemblyLinearVelocity = want + (have - want.Unit * along) + Vector3.new(0, v.Y, 0)
				end
				RunService.Heartbeat:Wait()
			end
			if SW.carries[char] == c then
				SW.carries[char] = nil
			end
		end)
		return c
	end
	VFX.SwingCarrying = function(char)
		return SW.carries[char] ~= nil
	end

	-- opts: Time (at most), Speed (along the arc), Exit (speed he lets go
	-- at), Lift (extra up on letting go), Carry (how long the fling keeps
	-- its speed), Range (longest line), OnEnd(). Only for your own
	-- character: it moves the body.
	function VFX.Swing(char, anchor, opts)
		opts = opts or {}
		local root, hum = charParts(char)
		if not root or typeof(anchor) ~= "Vector3" then
			return nil
		end
		local old = SW.active[char]
		if old then
			old.release = true
		end
		local st = { release = false }
		SW.active[char] = st
		SW.carries[char] = nil
		local cam = workspace.CurrentCamera
		local f = travelDir(root, hum, flatten(cam and cam.CFrame.LookVector or root.CFrame.LookVector, root))
		-- the anchor, brought round onto his line (always a little ahead of
		-- him: a swoop down and up, not a hop)
		local p0 = root.Position
		local rel = anchor - p0
		local height = math.max(rel.Y, 6)
		local ahead = rel:Dot(f)
		-- (caught on a wall across his way: the swing crests before it, and
		-- the glance off it at the end carries him on up it)
		local wallParams = RaycastParams.new()
		wallParams.FilterType = Enum.RaycastFilterType.Exclude
		wallParams.FilterDescendantsInstances = characterList()
		local caught = workspace:Raycast(p0 + UP * 2, rel + rel.Unit * 2, wallParams)
		if caught and caught.Normal:Dot(f) < -0.5 then
			ahead -= rel.Magnitude * 0.55
		end
		ahead = math.max(ahead, height * 0.35)
		local pivot = p0 + f * ahead + UP * height
		local r0 = p0 - pivot
		local L = math.clamp(r0.Magnitude, 6, opts.Range or 120)
		local th0 = math.clamp(math.atan2(r0:Dot(f), -r0.Y), -1.4, 0.3)
		-- (he lets go on the way up, about 40 degrees past the bottom: flying
		-- on down the street more than up into the sky)
		local th1 = math.clamp(-th0 * 0.55 + 0.25, 0.45, 0.8)
		-- (the bottom of the arc stays off the street)
		local floor = groundRay(pivot - UP * 2, 220)
		local lowest = pivot.Y - ((floor and floor.Position.Y or pivot.Y - 220) + 3.4)
		local Lb = math.min(L, math.max(lowest, 4))
		-- momentum: already going fast, he swings faster (and lets go faster)
		local v0 = root.AssemblyLinearVelocity
		local carried = math.max(v0:Dot(f), 0)
		local speed = math.max(opts.Speed or 85, carried * 1.08)
		local T = math.clamp(L * (th1 - th0) / speed, 0.5, opts.Time or 1.4)
		local exitSpeed = math.max(opts.Exit or 62, math.min(carried * 0.9, 120))
		local att = Instance.new("Attachment")
		att.Name = "SwingAttachment"
		att.Parent = root
		local lv = Instance.new("LinearVelocity")
		lv.Attachment0 = att
		lv.MaxForce = moverForce(root, 20000)
		lv.RelativeTo = Enum.ActuatorRelativeTo.World
		lv.Parent = root
		cleanup(lv, T + 0.3)
		cleanup(att, T + 0.3)
		if hum then
			pcall(function()
				hum:ChangeState(Enum.HumanoidStateType.Freefall)
			end)
		end
		face(root, f)
		local function at(t)
			local s = math.clamp(t / T, 0, 1)
			local e = (1 - math.cos(math.pi * s)) / 2
			local th = th0 + (th1 - th0) * e
			local len = L - (L - Lb) * math.clamp(1 - math.abs(th) / 1.3, 0, 1)
			return pivot + f * math.sin(th) * len - UP * math.cos(th) * len, th
		end
		-- (a wall in the way: he doesn't smack into it, he glances off along it)
		st.T = T
		st.Dir = f
		task.spawn(function()
			local t0 = os.clock()
			local wall
			while root.Parent and SW.active[char] == st and not st.release do
				if char:GetAttribute("Stunned") or char:GetAttribute("Ragdolled") or char:GetAttribute("Grabbed") then
					break
				end
				local t = os.clock() - t0
				local p1 = at(t)
				local p2 = at(t + 1 / 60)
				local step = (p2 - p1) * 60
				if step.Magnitude > 1 then
					local hit = workspace:Raycast(root.Position, step * 0.1, wallParams)
					if hit and math.abs(hit.Normal.Y) < 0.6 then
						wall = hit.Normal
						break
					end
				end
				lv.VectorVelocity = step + (p1 - root.Position) * 10
				if t >= T then
					break
				end
				RunService.Heartbeat:Wait()
			end
			local _, th = at(math.min(os.clock() - t0, T))
			lv:Destroy()
			att:Destroy()
			local mine = SW.active[char] == st
			if mine then
				SW.active[char] = nil
			end
			-- let go, flying on along the swing (unless a new swing took over)
			if mine and root.Parent and not (char:GetAttribute("Ragdolled") or char:GetAttribute("Grabbed")) then
				local tangent = (f * math.cos(th) + UP * math.sin(th)).Unit
				local out = tangent * exitSpeed + UP * (6 + (opts.Lift or 0))
				if wall then
					-- (the speed he had into the wall carries him up it instead)
					local into = math.max(-out:Dot(wall), 0)
					out = out - wall * out:Dot(wall) + UP * into * 0.7 + wall * 6
				end
				root.AssemblyLinearVelocity = out
				if opts.Carry and not wall and not st.release then
					SW.carry(char, root, hum, Vector3.new(out.X, 0, out.Z), opts.Carry)
				end
			end
			if opts.OnEnd then
				opts.OnEnd()
			end
		end)
		return st
	end

	-- (round 60) THE ZIP (Spider-Man's web zip / point launch): something's
	-- caught hold of `anchor` and reels him in along a straight line to it -
	-- quick, and quicker as he goes - and he ends up ON it: over the lip onto
	-- the roof (opts.Ledge, or a roof it caught), clinging to the wall a
	-- moment (a wall lower down), or carried on (open air). JUMP on the way,
	-- or on the wall, and he doesn't stop there: POINT LAUNCH - flung up and
	-- on over it. opts: Normal (the face it caught), Ledge, Speed, Accel,
	-- MaxTime, Cling, LaunchUp, LaunchForward, OnLaunch(), OnEnd(launched).
	-- Only for your own character: it moves the body.
	function VFX.Zip(char, anchor, opts)
		opts = opts or {}
		local root, hum = charParts(char)
		if not root or typeof(anchor) ~= "Vector3" then
			return nil
		end
		local normal = typeof(opts.Normal) == "Vector3" and opts.Normal.Magnitude > 0.1 and opts.Normal.Unit or nil
		local wall = normal ~= nil and math.abs(normal.Y) < 0.6
		local roof = normal ~= nil and normal.Y >= 0.6
		local ledge = opts.Ledge == true or roof
		-- (where his body ends up: hanging off the face with his hand on the
		-- spot - just under the lip for a ledge - or standing on the roof)
		local stop
		if roof then
			stop = anchor + UP * 3
		elseif wall then
			stop = anchor + normal * 1.7 - UP * (ledge and 1.4 or 2)
		else
			stop = anchor - UP * 2
		end
		local line = stop - root.Position
		if line.Magnitude < 1.5 then
			return nil
		end
		local old = SW.active[char]
		if old then
			old.release = true
		end
		local st = { release = false, zip = true, launch = false }
		SW.active[char] = st
		SW.carries[char] = nil
		local dir = line.Unit
		local flat = Vector3.new(dir.X, 0, dir.Z)
		if flat.Magnitude < 0.1 then
			flat = wall and -Vector3.new(normal.X, 0, normal.Z) or Vector3.new(root.CFrame.LookVector.X, 0, root.CFrame.LookVector.Z)
		end
		flat = flat.Unit
		st.Dir = flat
		local speed = opts.Speed or 150
		local start = math.clamp(root.AssemblyLinearVelocity:Dot(dir), 45, speed)
		local accel = math.max(opts.Accel or 0.18, 0.01)
		local maxT = opts.MaxTime or 1.4
		local att = Instance.new("Attachment")
		att.Name = "ZipAttachment"
		att.Parent = root
		local lv = Instance.new("LinearVelocity")
		lv.Name = "Zip"
		lv.Attachment0 = att
		lv.MaxForce = moverForce(root, 30000)
		lv.RelativeTo = Enum.ActuatorRelativeTo.World
		lv.VectorVelocity = dir * start
		lv.Parent = root
		cleanup(lv, maxT + 1.5)
		cleanup(att, maxT + 1.5)
		if hum then
			pcall(function()
				hum:ChangeState(Enum.HumanoidStateType.Freefall)
			end)
		end
		face(root, flat)
		-- (a jump on the way: the point launch, as he gets there)
		local jumpConn = game:GetService("UserInputService").JumpRequest:Connect(function()
			st.launch = true
		end)
		local wallParams = RaycastParams.new()
		wallParams.FilterType = Enum.RaycastFilterType.Exclude
		wallParams.FilterDescendantsInstances = characterList()
		local function tied()
			return char:GetAttribute("Stunned") or char:GetAttribute("Ragdolled") or char:GetAttribute("Grabbed")
		end
		local function drop()
			if lv.Parent then
				lv:Destroy()
			end
			if att.Parent then
				att:Destroy()
			end
		end
		task.spawn(function()
			local t0 = os.clock()
			while root.Parent and SW.active[char] == st and not st.release and not tied() do
				local t = os.clock() - t0
				local left = stop - root.Position
				if left.Magnitude < 2.2 or left:Dot(dir) < 0 or t > maxT then
					break
				end
				local v = start + (speed - start) * math.clamp(t / accel, 0, 1)
				-- (anything solid in the way before the spot: he's there, against it)
				local ahead = math.min(v / 30 + 1.5, left.Magnitude - 0.5)
				if left.Magnitude > 4 and workspace:Raycast(root.Position, left.Unit * ahead, wallParams) then
					break
				end
				lv.VectorVelocity = left.Unit * v
				RunService.Heartbeat:Wait()
			end
			local ok = root.Parent and SW.active[char] == st and not st.release and not tied()
			if ok and st.launch then
				-- POINT LAUNCH: up and on, over it
				drop()
				SW.active[char] = nil
				local out = UP * (opts.LaunchUp or 88) + flat * (opts.LaunchForward or 58)
				root.AssemblyLinearVelocity = out
				SW.carry(char, root, hum, flat * (opts.LaunchForward or 58), 0.9)
				if opts.OnLaunch then
					opts.OnLaunch()
				end
			elseif ok and ledge then
				-- over the lip onto the roof
				local over = wall and -Vector3.new(normal.X, 0, normal.Z).Unit or flat
				lv.VectorVelocity = UP * 34 + over * 14
				task.wait(0.2)
				if lv.Parent then
					lv.VectorVelocity = over * 18
				end
				task.wait(0.08)
				drop()
				if root.Parent then
					root.AssemblyLinearVelocity = over * 10
				end
			elseif ok and wall then
				-- he clings to the wall a moment - a jump off it launches him
				local away = Vector3.new(normal.X, 0, normal.Z).Unit
				face(root, -away)
				lv.VectorVelocity = Vector3.zero
				st.clinging = true
				local t1 = os.clock()
				while os.clock() - t1 < (opts.Cling or 0.45) and not st.launch and SW.active[char] == st and not st.release and not tied() do
					RunService.Heartbeat:Wait()
				end
				st.clinging = false
				drop()
				if root.Parent and st.launch and not tied() then
					root.AssemblyLinearVelocity = UP * (opts.LaunchUp or 88) * 0.85 + away * 32
					if opts.OnLaunch then
						opts.OnLaunch()
					end
				elseif root.Parent then
					root.AssemblyLinearVelocity = away * 12 + UP * 6
				end
			else
				drop()
				if ok then
					-- (open air: carried on past it)
					root.AssemblyLinearVelocity = dir * 40 + UP * 10
					SW.carry(char, root, hum, flat * 40, 0.5)
				end
			end
			drop()
			if SW.active[char] == st then
				SW.active[char] = nil
			end
			jumpConn:Disconnect()
			if opts.OnEnd then
				opts.OnEnd(ok and st.launch)
			end
		end)
		return st
	end
	-- is he being zipped along right now? (a jump then is the point launch,
	-- not a wall hop)
	function VFX.Zipping(char)
		local st = SW.active[char]
		return st ~= nil and st.zip == true
	end
end

---------------------------------------------------------------------------
-- KAMUI WOODS (Shinji Nishiya): Arbor. Everything he grows is blocky timber
-- in the game's style: square branches in two browns (the grain shows as
-- the shades alternating), stubby twigs, plenty of square autumn-orange
-- leaves; cages of square bars; roots; stakes with wedge points and trunks
-- with bark stripes, sprouting leaves.
---------------------------------------------------------------------------
do
	local KW = {
		WOOD = Color3.fromRGB(150, 94, 52),
		DARK = Color3.fromRGB(104, 62, 34),
		LIGHT = Color3.fromRGB(190, 134, 82),
		LEAF = Color3.fromRGB(236, 128, 36), -- (autumn orange)
		LEAF_DARK = Color3.fromRGB(198, 84, 28),
		LEAF_GOLD = Color3.fromRGB(248, 178, 58),
		DUST = Color3.fromRGB(204, 196, 184),
		arms = setmetatable({}, { __mode = "k" }), -- [char] = the branch out of his arm
		cages = setmetatable({}, { __mode = "k" }), -- [target] = the cage round them
		states = setmetatable({}, { __mode = "k" }), -- [char] = the slingshot going
	}
	VFX.KW = KW

	-- the three leaf shades, turn and turn about (or at random)
	local LEAVES = { KW.LEAF, KW.LEAF_DARK, KW.LEAF_GOLD }
	function KW.leafColor(i)
		return LEAVES[i and (math.floor(i) % 3 + 1) or rng:NextInteger(1, 3)]
	end

	-- a square leaf (a thin tile)
	function KW.leafPart(size, cf, i)
		return newPart(Vector3.new(size, 0.08, size), cf, KW.leafColor(i), Enum.Material.Grass)
	end

	-- A branch: a chain of square wood segments tapering to the tip, the
	-- shades alternating, a twig off every third one and a leaf off every
	-- other one, sides alternating.
	-- b.set(from, to, bend, wiggle) redraws it; b.fade(time) makes it go.
	function KW.branch(thick, segs)
		segs = segs or 8
		local b = { parts = {}, twigs = {}, phase = rand(0, 6) }
		for i = 1, segs do
			b.parts[i] = newPart(Vector3.new(thick, thick, 0.2), CFrame.new(), i % 2 == 0 and KW.DARK or KW.WOOD, Enum.Material.Wood)
			if i % 3 == 0 and i < segs then
				table.insert(b.twigs, { seg = i, side = (i % 2 == 0) and 1 or -1, part = newPart(Vector3.one * 0.2, CFrame.new(), KW.DARK, Enum.Material.Wood) })
			end
			if i % 2 == 0 and i < segs then
				table.insert(b.twigs, { seg = i, side = (i % 4 == 0) and -1 or 1, leaf = true, part = KW.leafPart(0.2, CFrame.new(), i) })
			end
		end
		local frames = {}
		function b.set(from, to, bend, wiggle)
			local span = to - from
			local len = span.Magnitude
			if len < 0.05 then
				return
			end
			local dir = span / len
			local ref = math.abs(dir.Y) < 0.9 and UP or Vector3.new(1, 0, 0)
			local side = dir:Cross(ref).Unit
			local up = side:Cross(dir).Unit
			local now = os.clock()
			local function at(k)
				local wave = math.sin(k * math.pi * 3 + now * 6 + b.phase) * (wiggle or 0.2) * k
				return from + span * k + up * math.sin(k * math.pi) * (bend or 0) + side * wave
			end
			local prev = at(0)
			for i, p in b.parts do
				local k = i / segs
				local nextP = at(k)
				local w = thick * (1 - 0.5 * (k - 1 / segs))
				local seg = nextP - prev
				local segLen = seg.Magnitude
				if segLen > 0.01 then
					local fwd = seg / segLen
					local top = up - fwd * up:Dot(fwd)
					top = top.Magnitude > 0.01 and top.Unit or side:Cross(fwd).Unit
					local cf = CFrame.fromMatrix((prev + nextP) / 2, fwd:Cross(top), top, -fwd)
					p.Size = Vector3.new(w, w, segLen + w * 0.1)
					p.CFrame = cf
					frames[i] = { cf = cf, w = w, len = segLen }
				end
				prev = nextP
			end
			for _, t in b.twigs do
				local f = frames[t.seg]
				if f then
					if t.leaf then
						local size = math.max(f.w * 1.25, 0.5)
						t.part.Size = Vector3.new(size, 0.08, size)
						t.part.CFrame = f.cf * CFrame.new(t.side * (f.w / 2 + size * 0.45), f.w * 0.3, 0) * CFrame.Angles(0, math.rad(45), math.rad(t.side * 24))
					else
						t.part.Size = Vector3.new(f.w * 0.4, f.w * 0.4, f.w * 1.6)
						t.part.CFrame = f.cf * CFrame.new(t.side * f.w * 0.55, 0, 0) * CFrame.Angles(0, math.rad(t.side * 50), 0) * CFrame.new(0, 0, -f.w * 0.5)
					end
				end
			end
		end
		function b.fade(time)
			for _, p in b.parts do
				tween(p, time or 0.2, { Transparency = 1, Size = p.Size * Vector3.new(0.3, 0.3, 1) })
				cleanup(p, (time or 0.2) + 0.05)
			end
			for _, t in b.twigs do
				tween(t.part, time or 0.2, { Transparency = 1 })
				cleanup(t.part, (time or 0.2) + 0.05)
			end
		end
		return b
	end

	-- a branch out of his arm toward `goal` (it grows there over reachTime)
	-- and holds on: to a spot, or to someone (arm.target) - until arm.life
	-- runs out or arm.retract is set (it shrinks back into his hand)
	function KW.reach(char, thick, segs, goal, bend, reachTime, right)
		local old = KW.arms[char]
		if old then
			old.done = true
		end
		local arm = { branch = KW.branch(thick, segs), goal = goal, bend = bend or 1, t0 = os.clock(), reachTime = reachTime or 0.14, life = 0.7, done = false }
		KW.arms[char] = arm
		local conn
		conn = RunService.RenderStepped:Connect(function()
			local t = os.clock() - arm.t0
			local troot = arm.target and arm.target:FindFirstChild("HumanoidRootPart")
			if arm.done or not char.Parent or t > arm.life or (arm.target and not (troot and troot.Parent)) then
				conn:Disconnect()
				arm.branch.fade(0.2)
				if KW.arms[char] == arm then
					KW.arms[char] = nil
				end
				return
			end
			local from = handPos(char, right ~= false)
			local goalPos = troot and troot.Position or arm.goal
			local k = math.clamp(t / arm.reachTime, 0, 1)
			if arm.retract then
				k = 1 - math.clamp((os.clock() - arm.retract) / 0.15, 0, 1)
				if k <= 0 then
					arm.done = true
				end
			end
			arm.branch.set(from, from:Lerp(goalPos, k), arm.bend * (1 - k * 0.6), 0.15)
		end)
		return arm
	end

	-- the Lacquered Chain Prison: a blocky cage round someone - four corner
	-- posts and three square hoops of bars - tightening as it closes. It
	-- follows them; c.crush() splinters it apart, c.fade() just lets go.
	function KW.cage(target, duration)
		local troot = target and target:FindFirstChild("HumanoidRootPart")
		if not troot then
			return nil
		end
		local old = KW.cages[target]
		if old then
			old.fade()
		end
		local c = { parts = {}, t0 = os.clock(), dead = false }
		KW.cages[target] = c
		local R, H = 2.1, 6.2
		local pieces = {}
		for i = 1, 4 do
			local a = (i - 0.5) / 4 * math.pi * 2
			table.insert(pieces, { kind = "post", a = a })
		end
		for h = 1, 3 do
			for i = 1, 4 do
				table.insert(pieces, { kind = "bar", h = h, a = i / 4 * math.pi * 2 })
			end
		end
		for i = 1, 4 do
			table.insert(pieces, { kind = "leaf", a = (i - 0.5) / 4 * math.pi * 2 })
		end
		for i, p in pieces do
			if p.kind == "leaf" then
				p.part = KW.leafPart(0.9, troot.CFrame, i)
			else
				p.part = newPart(Vector3.one * 0.4, troot.CFrame, i % 2 == 0 and KW.DARK or KW.WOOD, Enum.Material.Wood)
			end
			c.parts[i] = p.part
		end
		local function place()
			local k = math.clamp((os.clock() - c.t0) / 0.18, 0, 1)
			local r = R * (1.6 - 0.6 * k)
			local base = CFrame.new(troot.Position) * CFrame.Angles(0, (1 - k) * 0.8, 0)
			for _, p in pieces do
				if p.kind == "post" then
					local pos = Vector3.new(math.cos(p.a) * r * 1.1, 0, math.sin(p.a) * r * 1.1)
					p.part.Size = Vector3.new(0.5, H * k + 0.1, 0.5)
					p.part.CFrame = base * CFrame.new(pos + Vector3.new(0, -H / 2 + H * k / 2, 0)) * CFrame.Angles(0, -p.a, 0)
				elseif p.kind == "leaf" then
					-- (sprouting off the top of the post, tipped outward)
					local pos = Vector3.new(math.cos(p.a) * r * 1.25, -H / 2 + H * k + 0.1, math.sin(p.a) * r * 1.25)
					p.part.CFrame = base * CFrame.new(pos) * CFrame.Angles(0, -p.a, 0) * CFrame.Angles(0, 0, math.rad(-30)) * CFrame.Angles(0, math.rad(45), 0)
				else
					local y = -H / 2 + H * (p.h - 0.5) / 3
					local pos = Vector3.new(math.cos(p.a) * r, y, math.sin(p.a) * r)
					p.part.Size = Vector3.new(0.42, 0.42, r * 1.55)
					p.part.CFrame = base * CFrame.new(pos) * CFrame.Angles(0, -p.a, 0)
				end
			end
		end
		local conn
		conn = RunService.RenderStepped:Connect(function()
			if c.dead or not troot.Parent or os.clock() - c.t0 > (duration or 1.6) + 0.5 then
				conn:Disconnect()
				if not c.dead then
					c.fade()
				end
				return
			end
			place()
		end)
		place()
		function c.fade()
			if c.dead then
				return
			end
			c.dead = true
			if KW.cages[target] == c then
				KW.cages[target] = nil
			end
			for _, part in c.parts do
				tween(part, 0.25, { Transparency = 1 })
				cleanup(part, 0.3)
			end
		end
		function c.crush()
			if c.dead then
				return
			end
			c.dead = true
			if KW.cages[target] == c then
				KW.cages[target] = nil
			end
			local center = troot.Position
			for _, part in c.parts do
				local out = (part.Position - center)
				out = out.Magnitude > 0.1 and out.Unit or rng:NextUnitVector()
				tween(part, 0.4, { CFrame = part.CFrame * CFrame.Angles(rand(-2, 2), rand(-2, 2), rand(-2, 2)) + out * rand(5, 9) - UP * rand(0, 3), Size = part.Size * 0.4, Transparency = 1 })
				cleanup(part, 0.45)
			end
			KW.splinters(center, 1.2, 12)
			VFX.PlaySound("WoodCrush", center, 1)
		end
		return c
	end

	-- wood chips flying off a point
	function KW.splinters(pos, scale, count)
		for _ = 1, count or 6 do
			local chip = newPart(Vector3.new(rand(0.15, 0.35), rand(0.1, 0.2), rand(0.4, 0.8)) * scale, CFrame.new(pos) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)),
				rng:NextNumber() < 0.5 and KW.WOOD or KW.LIGHT, Enum.Material.Wood)
			local out = rng:NextUnitVector()
			tween(chip, 0.45, { CFrame = CFrame.new(pos + out * rand(3, 7) * scale + UP * rand(0, 3)) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)), Transparency = 1 }, Enum.EasingStyle.Quad)
			cleanup(chip, 0.5)
		end
	end

	-- a frame at `from` with its Y running towards `to` (straight up is fine:
	-- the look needs an up that isn't along it)
	function KW.upright(from, to)
		local d = to - from
		local up = (d.Magnitude < 1e-3 or math.abs(d.Unit.Y) > 0.98) and Vector3.new(0, 0, 1) or UP
		return CFrame.lookAt(from, d.Magnitude < 1e-3 and from + UP or to, up) * CFrame.Angles(math.rad(-90), 0, 0)
	end

	-- a stake bursting out of the street at `pos`: a square post with a
	-- wedge point, leaning along `lean`; sinks back after `life`
	function KW.stake(pos, height, width, lean, life)
		local g = groundPoint(pos + UP * 2)
		local dir = (UP + (lean or Vector3.zero)).Unit
		local topCF = KW.upright(g, g + dir) -- (Y along the stake)
		local post = newPart(Vector3.new(width, height, width), topCF * CFrame.new(0, -height / 2, 0), rng:NextNumber() < 0.5 and KW.WOOD or KW.DARK, Enum.Material.Wood)
		local tipH = width * 1.3
		local tips = {}
		for half = 0, 1 do
			local w = Instance.new("WedgePart")
			w.Anchored = true
			w.CanCollide = false
			w.CanQuery = false
			w.CanTouch = false
			w.CastShadow = false
			w.Size = Vector3.new(width, tipH, width / 2)
			w.Color = KW.LIGHT
			w.Material = Enum.Material.Wood
			w.CFrame = topCF * CFrame.new(0, -tipH / 2, 0)
			w.Parent = folder
			tips[half + 1] = { part = w, rel = CFrame.new(0, height + tipH / 2, (half == 0 and -1 or 1) * width / 4) * CFrame.Angles(0, half == 0 and 0 or math.pi, 0) }
		end
		-- (most sprout a sprig of leaves off one side, near the top)
		local sprig = {}
		if rng:NextNumber() < 0.7 then
			local side = rng:NextNumber() < 0.5 and 1 or -1
			local at = CFrame.new(side * width / 2, height * rand(0.55, 0.8), 0) * CFrame.Angles(0, rand(-0.6, 0.6), math.rad(-side * 55))
			for _, piece in KW.sprig(math.clamp(width * 0.8, 0.7, 1.3), rng:NextInteger(0, 2)) do
				piece.rel = at * piece.rel
				piece.part.CFrame = topCF * CFrame.new(0, -height, 0) * piece.rel
				table.insert(sprig, piece)
			end
		end
		-- (up out of the street)
		tween(post, 0.12, { CFrame = topCF * CFrame.new(0, height / 2, 0) }, Enum.EasingStyle.Back)
		for _, t in tips do
			tween(t.part, 0.12, { CFrame = topCF * t.rel }, Enum.EasingStyle.Back)
		end
		for _, piece in sprig do
			tween(piece.part, 0.12, { CFrame = topCF * piece.rel }, Enum.EasingStyle.Back)
		end
		dustPuffs(g, 0.4 + width * 0.12, 2, KW.DUST, 0.6, false)
		task.delay(life or 1.2, function()
			tween(post, 0.35, { CFrame = topCF * CFrame.new(0, -height / 2, 0), Transparency = 0.6 })
			cleanup(post, 0.4)
			for _, t in tips do
				tween(t.part, 0.35, { CFrame = topCF * CFrame.new(0, -tipH, 0), Transparency = 0.6 })
				cleanup(t.part, 0.4)
			end
			for _, piece in sprig do
				tween(piece.part, 0.35, { CFrame = topCF * CFrame.new(0, -height, 0) * piece.rel, Transparency = 1 })
				cleanup(piece.part, 0.4)
			end
		end)
		return post
	end

	-- a trunk growing out of the street from `base` up to `top`: square,
	-- bark stripes, a few stubby branches off it; gone after `life`
	function KW.trunk(base, top, thick, life, grow)
		local span = top - base
		local len = math.max(span.Magnitude, 1)
		local cf = KW.upright(base, top) -- (Y up the trunk)
		local parts = {}
		local main = newPart(Vector3.new(thick, 0.2, thick), cf, KW.WOOD, Enum.Material.Wood)
		table.insert(parts, { part = main, size = Vector3.new(thick, len, thick), rel = CFrame.new(0, len / 2, 0) })
		for i = -1, 1, 2 do
			local stripe = newPart(Vector3.new(thick * 0.18, 0.2, 0.1), cf, KW.DARK, Enum.Material.Wood)
			table.insert(parts, { part = stripe, size = Vector3.new(thick * 0.18, len * 0.9, 0.1), rel = CFrame.new(i * thick * 0.25, len / 2, -thick / 2 - 0.05) })
		end
		for i = 1, 3 do
			local y = len * (0.45 + i * 0.15)
			local a = i * 2.1
			local stub = newPart(Vector3.new(thick * 0.35, thick * 0.35, 0.2), cf, KW.DARK, Enum.Material.Wood)
			local stubLen = thick * 1.3
			local stubRel = CFrame.new(0, y, 0) * CFrame.Angles(0, a, 0) * CFrame.Angles(math.rad(35), 0, 0) * CFrame.new(0, 0, -thick / 2 - stubLen / 2)
			table.insert(parts, { part = stub, size = Vector3.new(thick * 0.35, thick * 0.35, stubLen), rel = stubRel })
			-- (a bunch of leaves on the end of each)
			for k = 1, 3 do
				local size = thick * rand(0.45, 0.6)
				local rel = stubRel * CFrame.new(0, 0, -stubLen / 2) * CFrame.Angles(0, 0, k * 2.1) * CFrame.new(0, thick * 0.2, 0) * CFrame.Angles(math.rad(20), math.rad(45), 0)
				table.insert(parts, { part = KW.leafPart(0.2, cf, i + k), size = Vector3.new(size, 0.1, size), rel = rel })
			end
		end
		-- (and a crown of them on top)
		for k = 1, 5 do
			local size = thick * rand(0.6, 0.85)
			local rel = CFrame.new(0, len, 0) * CFrame.Angles(0, k / 5 * math.pi * 2, 0) * CFrame.new(0, 0, -thick * 0.45) * CFrame.Angles(math.rad(-25), math.rad(45), 0)
			table.insert(parts, { part = KW.leafPart(0.2, cf, k), size = Vector3.new(size, 0.1, size), rel = rel })
		end
		local g = grow or 0.2
		for _, p in parts do
			p.part.CFrame = cf * CFrame.new(p.rel.Position.X, 0, p.rel.Position.Z)
			tween(p.part, g, { Size = p.size, CFrame = cf * p.rel }, Enum.EasingStyle.Back)
		end
		task.delay(life or 1.5, function()
			for _, p in parts do
				tween(p.part, 0.4, { Transparency = 1, Size = p.part.Size * Vector3.new(0.6, 1, 0.6) })
				cleanup(p.part, 0.45)
			end
		end)
		return main
	end

	-- a blocky canopy: a cluster of square leaf blocks round `pos`
	function KW.canopy(pos, size, life)
		for i = 1, 7 do
			local off = i == 1 and Vector3.zero or Vector3.new(rand(-1, 1), rand(-0.4, 0.6), rand(-1, 1)) * size * 0.5
			local s = size * rand(0.45, 0.7)
			local leaf = newPart(Vector3.new(s, s * 0.7, s), CFrame.new(pos + off) * CFrame.Angles(0, rand(0, 3), 0), KW.leafColor(i), Enum.Material.Grass)
			leaf.Size = Vector3.one * 0.2
			tween(leaf, 0.25, { Size = Vector3.new(s, s * 0.7, s) }, Enum.EasingStyle.Back)
			task.delay(life or 2, function()
				tween(leaf, 0.4, { Transparency = 1 })
				cleanup(leaf, 0.45)
			end)
		end
	end

	-- square leaves drifting down round a point, tumbling as they go
	function KW.leaves(pos, count, spread)
		for _ = 1, count or 4 do
			local from = pos + Vector3.new(rand(-1, 1), rand(0, 1), rand(-1, 1)) * (spread or 3)
			local leaf = KW.leafPart(rand(0.4, 0.6), CFrame.new(from) * CFrame.Angles(0, rand(0, 6), 0))
			local life = rand(1.1, 1.6)
			tween(leaf, life, { CFrame = CFrame.new(from - UP * rand(3, 7) + Vector3.new(rand(-2.5, 2.5), 0, rand(-2.5, 2.5))) * CFrame.Angles(rand(-1.2, 1.2), rand(0, 6), rand(-1.2, 1.2)), Transparency = 1 }, Enum.EasingStyle.Sine)
			cleanup(leaf, life + 0.05)
		end
	end

	-- a sprig: a stubby twig with a few leaves on it, in frame `cf` (the
	-- twig runs up its Y). Returns { part, rel } pieces for the caller to
	-- place (cf * rel) as whatever it's on moves.
	function KW.sprig(scale, seed)
		local pieces = {}
		local twigLen = 0.9 * scale
		table.insert(pieces, { part = newPart(Vector3.new(0.22, twigLen, 0.22) * Vector3.new(scale, 1, scale), CFrame.new(), KW.DARK, Enum.Material.Wood), rel = CFrame.new(0, twigLen / 2, 0) })
		for k = 1, 3 do
			local a = (k / 3) * math.pi * 2 + (seed or 0)
			local size = (0.55 + 0.1 * k) * scale
			local rel = CFrame.new(0, twigLen * (0.55 + 0.2 * k), 0) * CFrame.Angles(0, a, 0) * CFrame.new(0, 0, -size * 0.45) * CFrame.Angles(math.rad(-28), math.rad(45), 0)
			table.insert(pieces, { part = KW.leafPart(size, CFrame.new(), k + (seed or 0)), rel = rel })
		end
		return pieces
	end

	-- poses ---------------------------------------------------------------
	POSES.BranchCast = { RightArm = { 92, 0, -4 }, RightElbow = 0, RightWrist = { -10, 0, 0 }, LeftArm = { 30, 0, 20 }, LeftElbow = 50, Waist = { -8, 22, 0 }, Neck = { 0, -16, 0 }, RightLeg = -16, LeftLeg = 24, LeftKnee = 28 }
	POSES.BranchCastUp = { RightArm = { 145, 0, -4 }, RightElbow = 0, LeftArm = { 30, 0, 20 }, LeftElbow = 50, Waist = { 8, 18, 0 }, Neck = { -22, -12, 0 }, RightLeg = -16, LeftLeg = 24, LeftKnee = 28 }
	POSES.SwingHang = { RightArm = { 172, 0, 8 }, RightElbow = 8, LeftArm = { 60, 0, 40 }, LeftElbow = 70, Waist = { -6, 0, 0 }, Neck = { -10, 0, 0 }, RightLeg = 45, RightKnee = 80, LeftLeg = 15, LeftKnee = 50 }
	-- a real swing: the legs trail as he drops into it, tuck up through the
	-- bottom, then kick out forward as he's flung off the end
	MOTIONS.SwingArc = {
		{ pose = { RightArm = { 176, 0, 6 }, RightElbow = 4, LeftArm = { 40, 0, 50 }, LeftElbow = 40, Waist = { 8, 0, 0 }, Neck = { -18, 0, 0 },
			RightLeg = -20, LeftLeg = -30, RightKnee = 30, LeftKnee = 45 }, t = 0.12, hold = 0.18, style = Enum.EasingStyle.Sine },
		{ pose = "SwingHang", t = 0.22, hold = 0.12, style = Enum.EasingStyle.Sine },
		{ pose = { RightArm = { 165, 0, 10 }, RightElbow = 12, LeftArm = { 75, 0, 30 }, LeftElbow = 60, Waist = { -18, 0, 0 }, Neck = { -4, 0, 0 },
			RightLeg = 80, LeftLeg = 70, RightKnee = 110, LeftKnee = 100, Hips = { -10, 0, 0, 0, 0, 0 } }, t = 0.2, hold = 0.12, style = Enum.EasingStyle.Sine },
		{ pose = { RightArm = { 150, 0, 25 }, RightElbow = 20, LeftArm = { 100, 0, 45 }, LeftElbow = 30, Waist = { 14, 0, 0 }, Neck = { -20, 0, 0 },
			RightLeg = 70, LeftLeg = 50, RightKnee = 10, LeftKnee = 25 }, t = 0.16, hold = 0.25, style = SNAP },
		recover = 0.35,
	}
	POSES.SlingPull = { RightArm = { 165, 0, -10 }, LeftArm = { 150, 0, 10 }, RightElbow = 30, LeftElbow = 40, Waist = { 10, 0, 0 }, Neck = { -20, 0, 0 }, RightLeg = 30, LeftLeg = 10, RightKnee = 50, LeftKnee = 30 }
	POSES.SlingTuck = { RightArm = { 60, 0, 40 }, LeftArm = { 60, 0, 40 }, RightElbow = 90, LeftElbow = 90, Waist = { -30, 0, 0 }, Neck = { 20, 0, 0 }, RightLeg = 80, LeftLeg = 80, RightKnee = 110, LeftKnee = 110 }
	POSES.TreeSlam = { RightArm = { 175, 0, -14 }, LeftArm = { 175, 0, -14 }, RightElbow = 15, LeftElbow = 15, Waist = { 16, 0, 0 }, Neck = { -12, 0, 0 }, RightLeg = 35, LeftLeg = 15, RightKnee = 55, LeftKnee = 40 }
	POSES.TreeSlamDown = { RightArm = { 40, 0, 10 }, LeftArm = { 40, 0, 10 }, Waist = { -30, 0, 0 }, Neck = { 20, 0, 0 }, RightLeg = 50, LeftLeg = -10, RightKnee = 70, LeftKnee = 40, Hips = { 0, 0, 0, 0, -0.6, 0 } }
	POSES.PalmDown = { RightArm = { 40, 0, 10 }, RightElbow = 10, RightWrist = { -60, 0, 0 }, LeftArm = { 20, 0, 30 }, Waist = { -32, 10, 0 }, Neck = { 22, 0, 0 }, RightLeg = 50, RightKnee = 90, LeftLeg = -20, LeftKnee = 60, Hips = { 0, 0, 0, 0, -0.9, 0 } }
	POSES.TrunkRaise = { RightArm = { 170, 0, -6 }, RightElbow = 5, LeftArm = { 40, 0, 30 }, LeftElbow = 40, Waist = { 14, 18, 0 }, Neck = { -14, -10, 0 }, RightLeg = -18, LeftLeg = 26, LeftKnee = 30 }
	POSES.TrunkDown = { RightArm = { 70, 0, -4 }, RightElbow = 0, LeftArm = { -20, 0, 30 }, Waist = { -26, 20, 0 }, Neck = { 16, -12, 0 }, RightLeg = -28, LeftLeg = 40, LeftKnee = 45, Hips = { 0, 0, 0, 0, -0.4, 0 } }
	POSES.ForestRise = { RightArm = { 20, 0, 60 }, LeftArm = { 20, 0, 60 }, RightElbow = 20, LeftElbow = 20, Waist = { 10, 0, 0 }, Neck = { -18, 0, 0 } }
	POSES.LogsPush = { RightArm = { 95, 0, 10 }, LeftArm = { 95, 0, 10 }, RightElbow = 5, LeftElbow = 5, Waist = { -14, 0, 0 }, RightLeg = -25, LeftLeg = 35, LeftKnee = 40 }

	-- LACQUERED CHAIN PRISON ----------------------------------------------
	function Effects.ChainPrison(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		local aim = Config.AimedDirection(data.Dir, d, { Up = 60, Down = 30 })
		if isLocal then
			face(root, d)
		end
		VFX.Pose(char, aim.Y > 0.35 and "BranchCastUp" or "BranchCast", 0.5)
		VFX.PlaySound("BranchShoot", root.Position, 1)
		local range = (ability and ability.Range) or 50
		local goal = root.Position + UP * 1.5 + aim * range * 0.8
		KW.reach(char, 0.7, 12, goal, 1.4, math.min(range * 0.8 / 180, 0.25))
		-- (a spare branch from the other arm, for the look of it)
		task.delay(0.05, function()
			if char.Parent then
				local spare = KW.branch(0.45, 7)
				local t0 = os.clock()
				local conn
				conn = RunService.RenderStepped:Connect(function()
					local t = os.clock() - t0
					if t > 0.35 or not char.Parent then
						conn:Disconnect()
						spare.fade(0.15)
						return
					end
					local k = math.sin(math.clamp(t / 0.35, 0, 1) * math.pi)
					local from = handPos(char, false)
					spare.set(from, from + aim * 9 * k + UP * 2 * k, 1.5, 0.3)
				end)
			end
		end)
	end

	-- ...and what it caught: the cage closes round them (or the branch pulls back)
	function Effects.ChainPrisonCatch(char, data)
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		local arm = KW.arms[char]
		if not target then
			if arm then
				arm.retract = os.clock()
			end
			return
		end
		local troot = target:FindFirstChild("HumanoidRootPart")
		if not troot then
			return
		end
		local duration = tonumber(data.Duration) or 1.6
		if not arm then
			arm = KW.reach(char, 0.7, 12, troot.Position, 1.2, 0.05)
		end
		arm.target = target
		arm.life = math.min(duration, 0.6)
		local cage = KW.rootCage(target, duration) -- (the roots coiling up round them, as in the ult)
		KW.splinters(troot.Position, 0.8, 8)
		KW.leaves(troot.Position + UP * 2, 10, 2.5)
		VFX.PlaySound("WoodBind", troot.Position, 1)
		VFX.ShakeAt(troot.Position, 0.6, 40, 0.15)
		task.delay(duration, function()
			if cage and not cage.dead then
				cage.crush()
			end
		end)
	end

	-- TIMBER SLINGSHOT ----------------------------------------------------
	function Effects.TimberSlingshot(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		VFX.Pose(char, "BranchCast", 0.3)
		VFX.PlaySound("BranchShoot", root.Position, 0.9)
		KW.reach(char, 0.6, 8, root.Position + UP + d * 10, 0.6, 0.12)
	end
	-- (the ult's GREAT TIMBER SLINGSHOT is the same move, bigger: the server
	-- runs one handler for both, so it needs the same opening here)
	Effects.GreatSlingshot = Effects.TimberSlingshot

	function Effects.TimberWhiff(char)
		local arm = KW.arms[char]
		if arm then
			arm.retract = os.clock()
		end
	end

	-- the whole of it, from the server's timeline: up they go, the branch to
	-- the building (or the trunk out of the street), the pull, the fling
	function Effects.TimberToss(char, data)
		local root = charParts(char)
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		local troot = target and target:FindFirstChild("HumanoidRootPart")
		local anchor = typeof(data.Anchor) == "Vector3" and data.Anchor
		if not root or not troot or not anchor then
			return
		end
		local st = { dead = false }
		KW.states[char] = st
		local toss, shoot, pull, fling = tonumber(data.Toss) or 0.4, tonumber(data.Shoot) or 0.12, tonumber(data.Pull) or 0.26, tonumber(data.Fling) or 0.24
		local big = data.Big == true
		-- the throw: a branch under them heaves them skyward
		local arm = KW.arms[char] or KW.reach(char, 0.6, 8, troot.Position, 0.6, 0.05)
		arm.target = target
		arm.life = toss
		VFX.Pose(char, "BranchCastUp", toss)
		VFX.PlaySound("WoodCrack", troot.Position, 1)
		KW.splinters(troot.Position, 0.8, 6)
		dustPuffs(groundPoint(troot.Position), 0.8, 4, KW.DUST, 0.7, false)
		local stopTrail = addTrail(troot, KW.LIGHT, 0.25, 1.6)
		streaks(troot.Position, UP, 6, 0.3, 4, 12, Color3.new(1, 1, 1), 0.25)
		task.delay(toss, function()
			stopTrail(0.2)
			if KW.states[char] ~= st or st.dead or not char.Parent then
				return
			end
			-- the anchor: a trunk bursts out of the street if there's no building
			if data.Pillar then
				local base = groundPoint(anchor)
				KW.trunk(base, anchor + UP * 2, big and 4.5 or 3.4, shoot + pull + fling + 0.8, 0.12)
				VFX.PlaySound("TreeBurst", base, 0.8)
				dustPuffs(base, 1.2, 6, KW.DUST, 0.9, true)
				rocks(base, 0.8, 6)
			end
			-- a branch shoots out to it...
			local line = KW.reach(char, 0.55, 12, anchor, 0.8, shoot, true)
			line.life = shoot + pull + 0.05
			VFX.Pose(char, "BranchCastUp", shoot)
			VFX.PlaySound("BranchShoot", root.Position, 1)
			task.delay(shoot, function()
				if KW.states[char] ~= st or st.dead or not char.Parent then
					return
				end
				-- ...he's hauled up it...
				VFX.Pose(char, "SlingPull", pull)
				VFX.PlaySound("WoodCreak", anchor, 0.9)
				KW.splinters(anchor, 0.8, 6)
				KW.leaves(anchor, 7, 2)
				local trail = addTrail(root, KW.LIGHT, 0.2, 1.8)
				task.delay(pull, function()
					if not char.Parent then
						return
					end
					-- ...and flung off it, over them
					line.retract = os.clock()
					VFX.Pose(char, "SlingTuck", fling)
					VFX.PlaySound("BranchSwing", root.Position, 1)
					afterimage(char, KW.LIGHT, 0.2)
					task.delay(fling, function()
						trail(0.2)
					end)
				end)
			end)
		end)
	end

	-- the downslam: straight down onto them, both fists (and a wooden fist) first
	function Effects.TimberDive(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local time = tonumber(data.Time) or 0.18
		VFX.Pose(char, "TreeSlam", time * 0.4)
		task.delay(time * 0.4, function()
			if char.Parent then
				VFX.Pose(char, "TreeSlamDown", 0.4)
			end
		end)
		local from = typeof(data.From) == "Vector3" and data.From or root.Position
		local pos = typeof(data.Pos) == "Vector3" and data.Pos or from - UP * 20
		streaks(from, -UP, 8, 0.4, 6, math.max((from - pos).Magnitude, 4), Color3.new(1, 1, 1), 0.2)
		local trail = addTrail(root, KW.LIGHT, 0.2, 2)
		task.delay(time + 0.05, function()
			trail(0.1)
		end)
	end

	function Effects.TimberSlam(char, data)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos
		if not pos then
			return
		end
		local st = KW.states[char]
		if st then
			st.dead = true
			KW.states[char] = nil
		end
		local big = data.Big == true
		local s = big and 1.35 or 1
		shockDisc(pos + UP * 0.3, UP, 2, 30 * s, 0.4, Color3.new(1, 1, 1))
		shockDisc(pos + UP * 0.5, UP, 1, 20 * s, 0.32, KW.LIGHT)
		billboardRing(pos + UP * 2, 3, 26 * s, KW.WOOD, 8, 0.35)
		rocks(pos, 1.6 * s, 14)
		dustPuffs(pos, 1.8 * s, 9, KW.DUST, 1.2, true)
		groundMark(pos, 7 * s, Color3.fromRGB(56, 50, 46), 4)
		KW.splinters(pos + UP, 1.4, 14)
		KW.leaves(pos + UP * 4, big and 18 or 12, 6 * s)
		-- stakes burst out all round the crater
		for i = 1, big and 10 or 7 do
			local a = i / (big and 10 or 7) * math.pi * 2 + rand(-0.15, 0.15)
			local out = Vector3.new(math.cos(a), 0, math.sin(a))
			KW.stake(pos + out * rand(5, 8) * s, rand(4, 7) * s, rand(0.9, 1.4), out * 0.6, 1.4)
		end
		VFX.PlaySound("TrunkSlam", pos, 1.1)
		if nearCamera(pos, 90) then
			VFX.ImpactFrame(0.08)
		end
		VFX.ShakeAt(pos, 2.2 * s, 110, 0.35)
	end

	function Effects.TimberCancel(char)
		local st = KW.states[char]
		if st then
			st.dead = true
			KW.states[char] = nil
		end
		local arm = KW.arms[char]
		if arm then
			arm.retract = os.clock()
		end
	end

	-- ROOT BREAKER --------------------------------------------------------
	-- both forearms turn to timber and plunge into the street in front of
	-- him; two roots braid away down his aim, taking turns to weave up out of
	-- the street and back into it - chunks of road and splinters flying
	-- wherever one breaks the surface - and burst up in stakes at the end
	POSES.RootPull = { RightArm = { -34, 0, 10 }, LeftArm = { -34, 0, 10 }, RightElbow = 40, LeftElbow = 40, Waist = { 12, 0, 0 }, Neck = { -8, 0, 0 }, RightLeg = -10, LeftLeg = 22, LeftKnee = 26 }
	POSES.RootDrive = {
		RightArm = { 52, 0, 4 }, LeftArm = { 52, 0, 4 }, RightElbow = 6, LeftElbow = 6, RightWrist = { -46, 0, 0 }, LeftWrist = { -46, 0, 0 },
		Waist = { -26, 0, 0 }, Neck = { 16, 0, 0 }, RightLeg = 42, RightKnee = 72, LeftLeg = -18, LeftKnee = 40, Hips = { 0, 0, 0, 0, -0.6, 0 },
	}
	MOTIONS.RootBreaker = {
		{ pose = "RootPull", t = 0.07, hold = 0.05 },
		{ pose = "RootDrive", t = 0.06, hold = 0.55, style = SNAP },
		recover = 0.25,
	}

	-- a root's path: along the street from where it dives in, weaving up
	-- (above the street) and down (under it), crossing the other root
	function KW.rootPath(dive, d, right, side, range, width, groundY)
		local points = {}
		local n = math.max(math.floor(range / 1.1), 8)
		for i = 0, n do
			local s = i / n
			local weave = 3.1 * math.sin(math.pi * 2 * 3.5 * s - math.pi / 2 + (side > 0 and 0 or math.pi)) - 0.5
			local across = right * side * width * 0.3 * math.cos(math.pi * 2.5 * s)
			local flat = dive + d * range * s + across
			points[i + 1] = { pos = Vector3.new(flat.X, groundY(s) + weave * math.min(s * 6, 1), flat.Z), s = s, up = weave > 0 }
		end
		return points
	end

	function Effects.RootBreaker(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		VFX.Motion(char, "RootBreaker")
		local range, width = (ability and ability.Range) or 42, (ability and ability.Width) or 8
		local start = root.Position
		local right = d:Cross(UP)
		-- the street's height along the way (sampled, then interpolated)
		local heights = {}
		for i = 0, 6 do
			heights[i] = groundPoint(start + d * (2.5 + range * i / 6) + UP * 3).Y
		end
		local function groundY(s)
			local x = math.clamp(s, 0, 1) * 6
			local i = math.min(math.floor(x), 5)
			return heights[i] + (heights[i + 1] - heights[i]) * (x - i)
		end
		VFX.PlaySound("WoodCreak", start, 0.9)
		local strands = {}
		for _, side in { 1, -1 } do
			local dive = start + d * 2.5 + right * side * 0.7
			local path = KW.rootPath(Vector3.new(dive.X, 0, dive.Z), d, right, side, range, width, groundY)
			local segs = {}
			-- (one continuous root: where it dives under the street it's drawn
			-- running along it half sunk in the road, so the arches are joined up
			-- - from above too)
			local function drawn(pt)
				local thick = 1.15 - 0.5 * pt.s
				return Vector3.new(pt.pos.X, math.max(pt.pos.Y, groundY(pt.s) - thick * 0.25), pt.pos.Z)
			end
			for i = 1, #path - 1 do
				local a, b = path[i], path[i + 1]
				do
					local thick = 1.15 - 0.5 * a.s
					local pa, pb = drawn(a), drawn(b)
					local len = (pb - pa).Magnitude + 0.25
					local mid = (pa + pb) / 2
					local part = newPart(Vector3.new(thick, thick, len), CFrame.lookAt(mid, pb, right), i % 2 == 0 and KW.DARK or KW.WOOD, Enum.Material.Wood)
					part.Transparency = 1
					segs[#segs + 1] = { part = part, s = a.s, final = CFrame.lookAt(mid, pb, right), size = part.Size }
					-- (a leaf sprouting off every third stretch above the street)
					if i % 3 == 0 and mid.Y > groundY(a.s) + 0.3 then
						local size = thick * 1.2
						local leafCF = CFrame.lookAt(mid, pb, right) * CFrame.new((i % 2 == 0 and 1 or -1) * thick * 0.8, thick * 0.45, 0) * CFrame.Angles(0, math.rad(45), math.rad(20))
						local leaf = KW.leafPart(size, leafCF, i)
						leaf.Transparency = 1
						segs[#segs + 1] = { part = leaf, s = a.s, final = leafCF, size = leaf.Size }
					end
				end
			end
			-- where it breaks the surface, and where it dives back in
			local crossings = {}
			for i = 2, #path do
				if path[i].up ~= path[i - 1].up then
					crossings[#crossings + 1] = { pos = Vector3.new(path[i].pos.X, groundY(path[i].s), path[i].pos.Z), s = path[i].s, up = path[i].up }
				end
			end
			strands[side] = { side = side, dive = Vector3.new(dive.X, groundY(0), dive.Z), segs = segs, crossings = crossings, next = 1, arm = KW.branch(0.9, 6) }
		end
		-- the forearms reaching down into the street
		local RUN, DELAY = 0.36, 0.2
		local t0 = os.clock()
		local conn
		conn = RunService.RenderStepped:Connect(function()
			local t = os.clock() - t0
			if not char.Parent or t > DELAY + RUN + 0.75 then
				conn:Disconnect()
				for _, st in strands do
					st.arm.fade(0.2)
					for _, seg in st.segs do
						tween(seg.part, 0.35, { CFrame = seg.final - UP * 2.5, Transparency = 1 })
						cleanup(seg.part, 0.4)
					end
				end
				return
			end
			local head = math.clamp((t - DELAY) / RUN, 0, 1)
			for side, st in strands do
				local hand = handPos(char, side == 1)
				local reach = math.clamp(t / DELAY, 0, 1)
				st.arm.set(hand, hand:Lerp(st.dive - UP * 1.2, reach), 0.35, 0.1)
				if t >= DELAY then
					for _, seg in st.segs do
						if seg.part.Transparency > 0.5 and seg.s <= head then
							seg.part.Transparency = 0
							seg.part.Size = seg.size * Vector3.new(0.3, 0.3, 1)
							tween(seg.part, 0.12, { Size = seg.size }, Enum.EasingStyle.Back)
						end
					end
					while st.crossings[st.next] and st.crossings[st.next].s <= head do
						local c = st.crossings[st.next]
						st.next += 1
						-- the road cracks and chunks of it fly where the root bursts out
						KW.splinters(c.pos + UP * 0.6, c.up and 0.9 or 0.6, c.up and 7 or 4)
						groundMark(c.pos, c.up and 2.2 or 1.6, Color3.fromRGB(62, 54, 48), 2.5)
						if c.up then
							rocks(c.pos, 0.55, 3)
							dustPuffs(c.pos, 0.55, 2, KW.DUST, 0.7, false)
							KW.leaves(c.pos + UP * 1.5, 2, 1.2)
							if st.next % 2 == 0 then
								VFX.PlaySound("StakeBurst", c.pos, 0.7)
							end
						end
					end
				end
			end
		end)
		KW.splinters(groundPoint(start + d * 2.5), 0.8, 8)
		VFX.PlaySound("WoodCrack", start, 1)
		task.wait(DELAY + RUN)
		if not char.Parent then
			return
		end
		-- the end of the line: the two roots burst up together in stakes
		local finish = groundPoint(start + d * range + UP * 3)
		for k = 1, 5 do
			local a = k / 5 * math.pi * 2
			local off = right * math.cos(a) * 2.2 + d * math.sin(a) * 2.2
			KW.stake(finish + off, rand(5, 8), rand(1.1, 1.6), off.Unit * 0.5, 1)
		end
		shockDisc(finish + UP * 0.3, UP, 2, width * 2.4, 0.35, KW.LIGHT)
		dustPuffs(finish, 1, 5, KW.DUST, 1, true)
		rocks(finish, 0.9, 6)
		VFX.PlaySound("StakeBurst", finish, 1)
		VFX.ShakeAt(start + d * range / 2, 1.1, 70, 0.25)
	end

	-- GREAT TREE HAMMER ---------------------------------------------------
	-- a mallet grown out of both his arms: a long square handle and a head
	-- like a cut log - blocky, bark on its sides and the growth rings in
	-- squares on both ends. He raises it over his head and brings it down
	-- on the street in front of him with the side of the log.
	-- Built in the grip's frame: the handle runs up +Y, the head's rings
	-- face +X and -X (across his swing).
	function KW.mallet(handle, head)
		local LIGHT_END = Color3.fromRGB(222, 178, 118)
		local pieces = {}
		local function add(size, rel, color, material)
			local p = newPart(size, CFrame.new(), color, material or Enum.Material.Wood)
			table.insert(pieces, { part = p, rel = rel, size = size })
		end
		local hx, hy = head * 1.15, head
		local top = handle + hy / 2
		-- the handle, its grain and a collar where it meets the head
		add(Vector3.new(1.5, handle, 1.5), CFrame.new(0, handle / 2, 0), KW.WOOD)
		for _, z in { -1, 1 } do
			add(Vector3.new(0.3, handle * 0.9, 0.08), CFrame.new(0.3 * z, handle / 2, 0.78 * z), KW.DARK)
		end
		add(Vector3.new(2.3, 0.9, 2.3), CFrame.new(0, handle - 0.25, 0), KW.DARK)
		add(Vector3.new(1.9, 0.5, 1.9), CFrame.new(0, 0.2, 0), KW.DARK) -- (the grip)
		-- the head: a log, bark round its sides
		add(Vector3.new(hx, hy, hy), CFrame.new(0, top, 0), KW.WOOD)
		for _, side in { { 0, 1 }, { 0, -1 }, { 1, 0 }, { -1, 0 } } do
			for k = -1, 1, 2 do
				local y, z = side[1] * (hy / 2 + 0.04), side[2] * (hy / 2 + 0.04)
				local along = k * hy * 0.22
				local size = side[1] ~= 0 and Vector3.new(hx * 0.96, 0.08, 0.34) or Vector3.new(hx * 0.96, 0.34, 0.08)
				local rel = side[1] ~= 0 and CFrame.new(0, top + y, along) or CFrame.new(0, top + along, z)
				add(size, rel, KW.DARK)
			end
		end
		-- the rings on both ends: squares inside squares, light and dark
		for _, x in { -1, 1 } do
			local rings = { { 0.9, LIGHT_END }, { 0.74, KW.DARK }, { 0.62, LIGHT_END }, { 0.46, KW.DARK }, { 0.34, LIGHT_END }, { 0.18, KW.DARK }, { 0.07, LIGHT_END } }
			for i, ring in rings do
				local s = hy * ring[1]
				add(Vector3.new(0.06, s, s), CFrame.new(x * (hx / 2 + 0.02 + i * 0.025), top, 0), ring[2])
			end
		end
		-- living wood: sprigs of leaves sprouting off the log (on its back,
		-- and one off its far end)
		local spots = {
			CFrame.new(-hx * 0.28, top + hy * 0.12, hy / 2) * CFrame.Angles(math.rad(90), 0, math.rad(-18)),
			CFrame.new(hx * 0.3, top - hy * 0.2, hy / 2) * CFrame.Angles(math.rad(90), 0, math.rad(22)),
			CFrame.new(hx * 0.1, top + hy / 2, -hy * 0.2) * CFrame.Angles(math.rad(-15), 0, math.rad(12)),
		}
		for i, at in spots do
			for _, piece in KW.sprig(head * 0.3, i) do
				table.insert(pieces, { part = piece.part, rel = at * piece.rel, size = piece.part.Size })
			end
		end
		local m = { pieces = pieces, reach = top }
		-- place it: grip frame `cf`, grown by `k` (0 -> 1)
		function m.place(cf, k)
			local g = math.max(k, 0.05)
			for _, p in pieces do
				p.part.Size = p.size * (0.35 + 0.65 * g)
				p.part.CFrame = cf * CFrame.new(p.rel.Position * Vector3.new(1, g, 1)) * (p.rel - p.rel.Position)
			end
		end
		function m.fade(time)
			for _, p in pieces do
				tween(p.part, time, { Transparency = 1, Size = p.part.Size * 0.6 })
				cleanup(p.part, time + 0.05)
			end
		end
		return m
	end

	function Effects.TreeHammer(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		local range, width = (ability and ability.Range) or 20, (ability and ability.Width) or 10
		local handle, head = range * 0.68, width * 0.6
		VFX.Pose(char, "TreeSlam", 0.42)
		VFX.PlaySound("WoodCreak", root.Position, 1)
		local right = d:Cross(UP)
		local hammer = KW.mallet(handle, head)
		-- (the street where the head comes down: it lands on it, not in it)
		local floorY = groundPoint(root.Position + d * hammer.reach + UP * 3).Y
		local t0 = os.clock()
		local GROW, SWING = 0.28, 0.14
		local impact = false
		local conn
		conn = RunService.RenderStepped:Connect(function()
			local t = os.clock() - t0
			if not root.Parent or t > GROW + SWING + 0.6 then
				conn:Disconnect()
				hammer.fade(0.3)
				return
			end
			-- the grip: between his hands (both arms grew it)
			local grip = (handPos(char, true) + handPos(char, false)) / 2
			local grow = math.clamp(t / GROW, 0, 1)
			grow = 1 - (1 - grow) ^ 3
			local swing = math.clamp((t - GROW) / SWING, 0, 1)
			-- from leaning back over his head down to the head resting on the street
			local last = math.acos(math.clamp((floorY + head / 2 - grip.Y) / hammer.reach, -0.6, 0.95))
			local angle = math.rad(-28) + (last + math.rad(28)) * swing * swing
			local up = UP * math.cos(angle) + d * math.sin(angle)
			local cf = CFrame.fromMatrix(grip, right, up, right:Cross(up))
			hammer.place(cf, grow)
			if swing >= 1 and not impact then
				impact = true
				VFX.Pose(char, "TreeSlamDown", 0.6)
				local land = groundPoint(grip + up * hammer.reach + UP * 4)
				shockDisc(land + UP * 0.3, UP, 3, width * 3.2, 0.35, Color3.new(1, 1, 1))
				shockDisc(land + UP * 0.5, UP, 2, width * 2, 0.3, KW.LIGHT)
				billboardRing(land + UP * 2, 3, width * 3, KW.LIGHT, 6, 0.3)
				for k = 1, 4 do
					dustPuffs(groundPoint(root.Position + d * range * k / 4), 1.1, 3, KW.DUST, 1, k == 4)
				end
				rocks(land, 1.4, 12)
				groundMark(land, width * 0.7, Color3.fromRGB(58, 52, 48), 4)
				KW.splinters(land + UP, 1.4, 14)
				KW.leaves(land + UP * 3, 16, 6)
				VFX.PlaySound("TrunkSlam", land, 1.1)
				VFX.ShakeAt(land, 2, 95, 0.32)
				if isLocal then
					VFX.ImpactFrame(0.05)
				end
			end
		end)
	end

	-- BRANCH SWING (R) ----------------------------------------------------
	-- the branch from his hand to the anchor for the swing (everyone); his
	-- own screen swings him too
	function Effects.BranchSwing(char, data, isLocal, ability)
		local root = charParts(char)
		local anchor = typeof(data.Pos) == "Vector3" and data.Pos
		if not root or not anchor then
			return
		end
		local time = (ability and ability.SwingTime) or 1.3
		local arm = KW.reach(char, 0.5, 12, anchor, 0.4, 0.08)
		arm.life = time + 0.1
		VFX.MuteGait(char, time)
		VFX.Motion(char, "SwingArc")
		VFX.PlaySound("BranchSwing", root.Position, 1)
		task.delay(0.08, function()
			KW.splinters(anchor, 0.6, 4)
			KW.leaves(anchor, 7, 2)
		end)
		-- (leaves shaken off the branch all the way along the swing)
		task.spawn(function()
			local t0 = os.clock()
			while os.clock() - t0 < time and char.Parent and KW.arms[char] == arm and not arm.done do
				KW.leaves(handPos(char, true):Lerp(anchor, rand(0.1, 0.6)), 1, 0.8)
				task.wait(0.09)
			end
		end)
		if isLocal then
			VFX.Swing(char, anchor, {
				Time = time,
				Speed = ability and ability.SwingSpeed,
				Exit = ability and ability.ExitSpeed,
				Lift = ability and ability.ExitLift,
				Carry = ability and ability.Carry,
				Range = ((ability and ability.Range) or 80) + 10,
				OnEnd = function()
					if KW.arms[char] == arm then
						arm.retract = os.clock()
					end
				end,
			})
		end
	end

	-- (the server found nothing to swing from after all)
	function Effects.SwingDenied(char)
		VFX.SwingRelease(char)
		local arm = KW.arms[char]
		if arm then
			arm.retract = os.clock()
		end
		VFX.Hooks.Callout("NOTHING TO SWING FROM", Color3.fromRGB(255, 180, 120))
	end

	-- THOUSAND-BRANCH PRISON (ult) ----------------------------------------
	-- his forearms plunge into the street and roots race out through it all
	-- round him, weaving up out of the road and back into it; wherever they
	-- find someone they burst up round them and coil up them - a cage of
	-- roots, crossing over each other and meeting over their head.

	-- a cage of roots round someone (the same to the rest as KW.cage:
	-- c.crush(), c.fade(), and it's in KW.cages)
	function KW.rootCage(target, duration)
		local troot = target and target:FindFirstChild("HumanoidRootPart")
		if not troot then
			return nil
		end
		local old = KW.cages[target]
		if old then
			old.fade()
		end
		local c = { parts = {}, t0 = os.clock(), dead = false }
		KW.cages[target] = c
		local ROOTS, SEGS, H = 5, 8, 7.4
		local floorY = groundPoint(troot.Position).Y
		local strands = {}
		for r = 1, ROOTS do
			local st = { a0 = r / ROOTS * math.pi * 2 + rand(-0.2, 0.2), twist = (r % 2 == 0 and 1 or -1) * rand(1.2, 1.6), segs = {}, leaves = {} }
			for i = 1, SEGS do
				st.segs[i] = newPart(Vector3.one * 0.3, troot.CFrame, i % 2 == 0 and KW.DARK or KW.WOOD, Enum.Material.Wood)
				table.insert(c.parts, st.segs[i])
			end
			for k = 1, 2 do
				st.leaves[k] = { at = 0.3 + 0.35 * k + rand(-0.05, 0.05), side = k == 1 and 1 or -1, part = KW.leafPart(0.85, troot.CFrame, r + k) }
				table.insert(c.parts, st.leaves[k].part)
			end
			strands[r] = st
			-- (where it breaks the street)
			local a = st.a0
			local base = Vector3.new(troot.Position.X + math.cos(a) * 2.8, floorY, troot.Position.Z + math.sin(a) * 2.8)
			groundMark(base, 1.3, Color3.fromRGB(62, 54, 48), (duration or 1.8) + 0.4)
			rocks(base, 0.4, 2)
		end
		-- a root's path, s from 0 (in the street) to 1 (over their head): out
		-- round them, coiling up, then in over the top
		local function at(st, s, base, spread)
			local inward = math.cos(math.pi / 2 * math.max(0, (s - 0.55) / 0.45))
			local r = (0.45 + 2.3 * inward) * spread
			local a = st.a0 + st.twist * s
			return base + Vector3.new(math.cos(a) * r, -0.8 + H * s, math.sin(a) * r)
		end
		local function place()
			local t = os.clock() - c.t0
			local k = math.clamp(t / 0.28, 0, 1)
			k = 1 - (1 - k) ^ 2
			local spread = 1.35 - 0.35 * math.clamp(t / 0.4, 0, 1) -- (closing in)
			local base = Vector3.new(troot.Position.X, math.max(floorY, troot.Position.Y - 3.2), troot.Position.Z)
			for _, st in strands do
				local prev = at(st, 0, base, spread)
				local frames = {}
				for i, part in st.segs do
					local nextP = at(st, i / SEGS * math.max(k, 0.02), base, spread)
					local seg = nextP - prev
					local len = seg.Magnitude
					if len > 0.01 then
						local fwd = seg / len
						local w = 0.95 - 0.5 * (i - 1) / SEGS
						local cf = CFrame.lookAt((prev + nextP) / 2, nextP, math.abs(fwd.Y) > 0.97 and Vector3.new(1, 0, 0) or UP)
						part.Size = Vector3.new(w, w, len + w * 0.3)
						part.CFrame = cf
						frames[i] = { cf = cf, w = w }
					end
					prev = nextP
				end
				for _, leaf in st.leaves do
					local f = frames[math.clamp(math.floor(leaf.at * SEGS) + 1, 1, SEGS)]
					if f and k >= leaf.at then
						leaf.part.Transparency = 0
						leaf.part.CFrame = f.cf * CFrame.new(leaf.side * (f.w / 2 + 0.35), f.w * 0.3, 0) * CFrame.Angles(0, math.rad(45), math.rad(leaf.side * 24))
					else
						leaf.part.Transparency = 1
					end
				end
			end
		end
		local conn
		conn = RunService.RenderStepped:Connect(function()
			if c.dead or not troot.Parent or os.clock() - c.t0 > (duration or 1.8) + 0.5 then
				conn:Disconnect()
				if not c.dead then
					c.fade()
				end
				return
			end
			place()
		end)
		place()
		function c.fade()
			if c.dead then
				return
			end
			c.dead = true
			if KW.cages[target] == c then
				KW.cages[target] = nil
			end
			-- (the roots draw back down into the street)
			for _, part in c.parts do
				tween(part, 0.3, { CFrame = part.CFrame - UP * 3, Transparency = 1 })
				cleanup(part, 0.35)
			end
		end
		function c.crush()
			if c.dead then
				return
			end
			c.dead = true
			if KW.cages[target] == c then
				KW.cages[target] = nil
			end
			local center = troot.Position
			for _, part in c.parts do
				local out = (part.Position - center)
				out = out.Magnitude > 0.1 and out.Unit or rng:NextUnitVector()
				tween(part, 0.4, { CFrame = part.CFrame * CFrame.Angles(rand(-2, 2), rand(-2, 2), rand(-2, 2)) + out * rand(5, 9) - UP * rand(0, 3), Size = part.Size * 0.4, Transparency = 1 })
				cleanup(part, 0.45)
			end
			KW.splinters(center, 1.2, 12)
			KW.leaves(center + UP * 2, 8, 2.5)
			VFX.PlaySound("WoodCrush", center, 1)
		end
		return c
	end

	function Effects.ThousandBranch(char, _data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		local radius = (ability and ability.Radius) or 28
		VFX.Pose(char, "PalmDown", 0.6)
		VFX.PlaySound("TreeBurst", root.Position, 1)
		if isLocal then
			VFX.Hooks.Dim(0.25, 0.5)
		end
		local center = root.Position
		local g0 = groundPoint(center + UP * 2)
		local look = flatten(root.CFrame.LookVector, root)
		local RUN, N = 0.3, 10
		-- the roots: out through the street in every direction, weaving up
		-- out of it and back in (only what's above the road is drawn)
		local strands = {}
		for i = 1, N do
			local a = i / N * math.pi * 2 + rand(-0.12, 0.12)
			local d = Vector3.new(math.cos(a), 0, math.sin(a))
			local right = d:Cross(UP)
			local phase, phase2 = rand(0, 6), rand(0, 6)
			local heights = {}
			for h = 0, 4 do
				heights[h] = groundPoint(center + d * (1.5 + radius * h / 4) + UP * 3).Y
			end
			local function groundY(s)
				local x = math.clamp(s, 0, 1) * 4
				local j = math.min(math.floor(x), 3)
				return heights[j] + (heights[j + 1] - heights[j]) * (x - j)
			end
			local n = math.max(math.floor(radius / 1.2), 8)
			local points = {}
			for j = 0, n do
				local s = j / n
				local weave = (1.9 * math.sin(math.pi * 2 * 2.2 * s + phase) - 0.35) * math.min(s * 5, 1) - (1 - math.min(s * 5, 1)) * 0.8
				local flat = center + d * (1.5 + radius * s) + right * 1.6 * math.sin(math.pi * 2 * 1.3 * s + phase2)
				points[j + 1] = { pos = Vector3.new(flat.X, groundY(s) + weave, flat.Z), s = s, up = weave > 0 }
			end
			local segs, crossings = {}, {}
			-- (one continuous root: under the street it runs along it half sunk)
			local function drawn(pt)
				return Vector3.new(pt.pos.X, math.max(pt.pos.Y, groundY(pt.s) - (1.1 - 0.5 * pt.s) * 0.25), pt.pos.Z)
			end
			for j = 1, #points - 1 do
				local pa, pb = points[j], points[j + 1]
				do
					local thick = 1.1 - 0.5 * pa.s
					local da, db = drawn(pa), drawn(pb)
					local mid = (da + db) / 2
					local final = CFrame.lookAt(mid, db, UP)
					local part = newPart(Vector3.new(thick, thick, (db - da).Magnitude + 0.25), final, j % 2 == 0 and KW.DARK or KW.WOOD, Enum.Material.Wood)
					part.Transparency = 1
					segs[#segs + 1] = { part = part, s = pa.s, final = final, size = part.Size }
					if j % 3 == 0 and mid.Y > groundY(pa.s) + 0.3 then
						local leafCF = final * CFrame.new((j % 2 == 0 and 1 or -1) * thick * 0.8, thick * 0.45, 0) * CFrame.Angles(0, math.rad(45), math.rad(20))
						local leaf = KW.leafPart(thick * 1.2, leafCF, j + i)
						leaf.Transparency = 1
						segs[#segs + 1] = { part = leaf, s = pa.s, final = leafCF, size = leaf.Size }
					end
				end
				if pb.up ~= pa.up and pb.up then
					crossings[#crossings + 1] = { pos = Vector3.new(pb.pos.X, groundY(pb.s), pb.pos.Z), s = pb.s }
				end
			end
			strands[i] = { segs = segs, crossings = crossings, next = 1 }
		end
		-- both forearms turn to roots and plunge into the street
		local arms = { KW.branch(0.9, 6), KW.branch(0.9, 6) }
		local t0 = os.clock()
		local conn
		conn = RunService.RenderStepped:Connect(function()
			local t = os.clock() - t0
			if not char.Parent or t > RUN + 1.1 then
				conn:Disconnect()
				for _, arm in arms do
					arm.fade(0.2)
				end
				for _, st in strands do
					for _, seg in st.segs do
						tween(seg.part, 0.4, { CFrame = seg.final - UP * 2.5, Transparency = 1 })
						cleanup(seg.part, 0.45)
					end
				end
				return
			end
			for side, arm in arms do
				local hand = handPos(char, side == 1)
				local into = g0 + look * 1.2 + look:Cross(UP) * (side == 1 and 0.8 or -0.8) - UP * 1.2
				arm.set(hand, hand:Lerp(into, math.clamp(t / 0.1, 0, 1)), 0.3, 0.1)
			end
			local head = math.clamp(t / RUN, 0, 1)
			for _, st in strands do
				for _, seg in st.segs do
					if seg.part.Transparency > 0.5 and seg.s <= head and t < RUN + 1.05 then
						seg.part.Transparency = 0
						seg.part.Size = seg.size * Vector3.new(0.3, 0.3, 1)
						tween(seg.part, 0.1, { Size = seg.size }, Enum.EasingStyle.Back)
					end
				end
				while st.crossings[st.next] and st.crossings[st.next].s <= head do
					local cr = st.crossings[st.next]
					st.next += 1
					KW.splinters(cr.pos + UP * 0.6, 0.8, 4)
					groundMark(cr.pos, 1.8, Color3.fromRGB(62, 54, 48), 2.5)
					rocks(cr.pos, 0.5, 2)
					if st.next % 2 == 0 then
						KW.leaves(cr.pos + UP * 1.5, 2, 1.2)
					end
				end
			end
		end)
		KW.splinters(g0 + UP * 0.5, 1, 10)
		groundMark(g0, 4, Color3.fromRGB(58, 52, 48), 3)
		shockDisc(g0 + UP * 0.3, UP, 4, radius * 2, 0.45, KW.LIGHT)
		dustPuffs(g0, 1.6, 10, KW.DUST, 1.2, true)
		KW.leaves(center + UP * 5, 14, radius * 0.4)
		VFX.ShakeAt(center, 1.5, 90, 0.35)
	end

	function Effects.ThousandBranchCatch(_char, data)
		for _, target in typeof(data.Targets) == "table" and data.Targets or {} do
			if typeof(target) == "Instance" then
				KW.rootCage(target, (tonumber(data.Duration) or 1.8) + 0.4)
				local troot = target:FindFirstChild("HumanoidRootPart")
				if troot then
					KW.splinters(troot.Position, 0.8, 6)
					KW.leaves(troot.Position + UP * 3, 6, 2)
				end
			end
		end
		VFX.PlaySound("WoodBind", typeof(data.Center) == "Vector3" and data.Center or nil, 1)
	end

	function Effects.ThousandBranchCrush(_char, data)
		for _, target in typeof(data.Targets) == "table" and data.Targets or {} do
			local cage = typeof(target) == "Instance" and KW.cages[target]
			if cage then
				cage.crush()
			end
		end
		local center = typeof(data.Center) == "Vector3" and data.Center
		if center then
			VFX.ShakeAt(center, 1.4, 90, 0.25)
		end
	end

	-- TIMBER TORRENT (ult) ------------------------------------------------
	function Effects.TimberTorrent(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		local range, width = (ability and ability.Range) or 80, (ability and ability.Width) or 16
		VFX.Pose(char, "LogsPush", 1)
		VFX.PlaySound("LogRoll", root.Position, 1.1)
		local start = root.Position
		local right = d:Cross(UP)
		task.wait(0.25)
		-- three staggered rows of logs rolling down the lane
		local logs = {}
		for row = 1, 3 do
			for k = 1, 2 do
				local diameter = rand(3.2, 4.4)
				local len = width * 0.5
				local across = (k - 1.5) * width * 0.5
				local log = newPart(Vector3.new(len, diameter, diameter), CFrame.new(), row % 2 == 0 and KW.DARK or KW.WOOD, Enum.Material.Wood, Enum.PartType.Cylinder)
				local rings = newPart(Vector3.new(len + 0.1, diameter * 0.7, diameter * 0.7), CFrame.new(), KW.LIGHT, Enum.Material.Wood, Enum.PartType.Cylinder)
				table.insert(logs, { log = log, rings = rings, across = across, back = (row - 1) * 5, r = diameter / 2 })
			end
		end
		local t0 = os.clock()
		local travel = 0.56
		local conn
		conn = RunService.RenderStepped:Connect(function()
			local t = os.clock() - t0
			if t > travel + 0.3 or not char.Parent then
				conn:Disconnect()
				for _, l in logs do
					tween(l.log, 0.3, { Transparency = 1 })
					tween(l.rings, 0.3, { Transparency = 1 })
					cleanup(l.log, 0.35)
					cleanup(l.rings, 0.35)
				end
				return
			end
			local k = math.clamp(t / travel, 0, 1)
			for _, l in logs do
				local dist = math.max(k * range - l.back, 0)
				local ground = start + d * dist + right * l.across
				local pos = Vector3.new(ground.X, groundPoint(ground).Y + l.r, ground.Z)
				local cf = CFrame.fromMatrix(pos, right, UP) * CFrame.Angles(-dist / l.r, 0, 0)
				l.log.CFrame = cf
				l.rings.CFrame = cf
			end
		end)
		for i = 1, 6 do
			task.delay(i * travel / 6, function()
				local p = start + d * range * i / 6
				dustPuffs(groundPoint(p), 1, 3, KW.DUST, 0.8, false)
				KW.splinters(p, 0.8, 4)
				KW.leaves(p + UP * 3, 3, width * 0.3)
			end)
		end
		VFX.ShakeAt(start + d * range / 2, 1.3, 100, travel)
	end

	-- SEQUOIA SPEAR (ult 4) -----------------------------------------------
	function Effects.SequoiaSpear(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		local target = aimGround(root, data, (ability and ability.Range) or 70)
		if isLocal then
			face(root, target - root.Position)
		end
		VFX.Pose(char, "ForestRise", 0.8)
		-- the street bulges and cracks first
		groundMark(target, 5, Color3.fromRGB(62, 54, 48), 2.5)
		shockDisc(target + UP * 0.2, UP, 10, 3, 0.4, KW.WOOD)
		VFX.PlaySound("WoodCreak", target, 1)
		task.wait(0.45)
		local top = target + UP * 42
		KW.trunk(target - UP * 2, top, 7, 2.6, 0.14)
		KW.canopy(top + UP * 3, 14, 2.6)
		shockDisc(target + UP * 0.4, UP, 4, 34, 0.45, Color3.new(1, 1, 1))
		billboardRing(target + UP * 3, 4, 40, KW.LIGHT, 10, 0.4)
		dustPuffs(target, 2, 10, KW.DUST, 1.4, true)
		rocks(target, 2, 16)
		KW.splinters(target + UP * 2, 1.5, 14)
		streaks(target, UP, 12, 0.4, 10, 40, Color3.new(1, 1, 1), 0.3)
		VFX.PlaySound("TreeBurst", target, 1.2)
		if nearCamera(target, 120) then
			VFX.ImpactFrame(0.1)
		end
		VFX.ShakeAt(target, 2.4, 130, 0.4)
		task.delay(0.6, function()
			KW.leaves(top, 24, 10)
		end)
	end

	-- the M1s: wood chips off every hit, a wooden fist on the 4th
	function VFX.ArborPunch(_char, _count, finisher, fist, look)
		KW.splinters(fist, finisher and 1 or 0.6, finisher and 8 or 3)
		KW.leaves(fist + UP, finisher and 5 or 1, 1)
		if finisher then
			local block = newPart(Vector3.one * 1.6, CFrame.lookAt(fist, fist + look), KW.WOOD, Enum.Material.Wood)
			tween(block, 0.2, { Size = Vector3.one * 0.4, Transparency = 1 })
			cleanup(block, 0.25)
			VFX.PlaySound("Arbor", fist, 0.8)
		end
	end

	-- a dash: leaves and chips in his wake
	QUIRK_FX.Dash.Arbor = function(char, root, dir)
		KW.leaves(root.Position - dir * 2 + UP, 7, 1.8)
		KW.splinters(root.Position - dir * 1.5, 0.5, 3)
		legTrails(char, 0.25, KW.LIGHT)
	end

	-- the awakening: branches burst out of him all round, leaves come down
	QUIRK_FX.Ult.Arbor = function(_char, root, g)
		for i = 1, 8 do
			local a = i / 8 * math.pi * 2
			local b = KW.branch(1, 9)
			local out = Vector3.new(math.cos(a), 0, math.sin(a))
			local t0 = os.clock()
			local conn
			conn = RunService.RenderStepped:Connect(function()
				local t = os.clock() - t0
				if not root.Parent or t > 0.9 then
					conn:Disconnect()
					b.fade(0.3)
					return
				end
				local k = math.sin(math.clamp(t / 0.9, 0, 1) * math.pi)
				b.set(root.Position, root.Position + out * 13 * k + UP * 7 * k, 2.5, 0.4)
			end)
		end
		for i = 1, 8 do
			local a = i / 8 * math.pi * 2 + 0.4
			KW.stake(g + Vector3.new(math.cos(a), 0, math.sin(a)) * 7, rand(4, 6), 1.1, Vector3.new(math.cos(a), 0, math.sin(a)) * 0.4, 1.4)
		end
		KW.leaves(root.Position + UP * 6, 26, 8)
		billboardRing(root.Position, 3, 32, KW.LEAF, 6, 0.45)
		dustPuffs(g, 1.4, 8, KW.DUST, 1.2, false)
		VFX.PlaySound("Arbor", root.Position, 1.2)
	end
end

---------------------------------------------------------------------------
-- KO FINISHERS (Config.KOFinisher): a move's killing blow plays out - time
-- slows for everyone near, a "K.O.!" bursts off the body in the killer's
-- colours, their quirk goes off round it (a blast, a gale, lightning, ice
-- and fire, roots...), the killer strikes a pose, and their camera swings
-- round for a second to watch the body fly (the server launches it)
---------------------------------------------------------------------------
do
	local V3 = Vector3.new
	local WHITE = Color3.new(1, 1, 1)
	-- the killer's pose, by quirk
	POSES.KO_Explosion = { RightArm = { 88, 0, 8 }, RightElbow = 6, RightWrist = { -50, 0, 0 }, LeftArm = { 10, 0, 20 }, LeftElbow = 95, Waist = { -4, 25, 0 }, Neck = { 8, -22, 0 }, RightLeg = -14, LeftLeg = 20, LeftKnee = 22 }
	POSES.KO_OneForAll = { RightArm = { 176, 0, 10 }, RightElbow = 8, LeftArm = { 20, 0, 25 }, LeftElbow = 100, Waist = { 10, 0, 0 }, Neck = { -22, 0, 0 }, RightLeg = -10, LeftLeg = 14 }
	POSES.KO_FullCowl = { RightArm = { 96, 0, 0 }, RightElbow = 4, LeftArm = { -35, 0, 22 }, LeftElbow = 40, Waist = { -12, 30, 0 }, Neck = { 0, -18, 0 }, RightLeg = -30, LeftLeg = 42, LeftKnee = 45, RightKnee = 10 }
	POSES.KO_HalfCold = { RightArm = { 40, 0, 62 }, RightElbow = 10, LeftArm = { 40, 0, 62 }, LeftElbow = 10, Waist = { 0, 0, 0 }, Neck = { -6, 0, 0 } }
	POSES.KO_Engine = { RightLeg = 125, RightKnee = 6, LeftKnee = 12, Waist = { 18, 0, 0 }, RightArm = { -30, 0, 40 }, LeftArm = { 40, 0, 50 } }
	POSES.KO_Arbor = { RightArm = { 72, 0, -62 }, RightElbow = 105, LeftArm = { 72, 0, -62 }, LeftElbow = 105, Waist = { 4, 0, 0 }, Neck = { -8, 0, 0 } }
	POSES.KO_Decay = { RightArm = { 84, 0, 4 }, RightWrist = { -45, 0, 0 }, LeftArm = { 10, 0, 12 }, Waist = { -16, 6, 0 }, Neck = { 14, -8, 0 } }
	POSES.KO_Overhaul = { RightArm = { 70, 0, -30 }, RightElbow = 105, LeftArm = { 62, 0, -22 }, LeftElbow = 112, Neck = { 8, 0, 0 } }
	POSES.KO_Lemillion = { RightArm = { 70, 0, 22 }, RightElbow = 115, LeftArm = { 15, 0, 25 }, LeftElbow = 90, Waist = { 6, -10, 0 }, Neck = { -8, 10, 0 } }
	POSES.KO_Manifest = { Waist = { -22, 0, 0 }, Neck = { 22, 0, 0 }, RightArm = { 40, 0, -20 }, RightElbow = 110, LeftArm = { 40, 0, -20 }, LeftElbow = 110 }
	POSES.KO_Limitless = { RightArm = { 72, 0, -22 }, RightElbow = 92, LeftArm = { 8, 0, 12 }, Neck = { -10, 8, 0 }, Waist = { 0, 8, 0 } }
	POSES.KO_CrazyDiamond = {
		RightArm = { 150, 0, -40 }, RightElbow = 100, LeftArm = { 45, 0, 70 }, LeftElbow = 30, Waist = { 6, -30, 16 },
		Hips = { 0, 16, 0, 0, -0.2, 0 }, RightLeg = { 10, 0, -14 }, LeftLeg = 20, LeftKnee = 30,
	}
	POSES.KO_Default = { RightArm = { 170, 0, 12 }, RightElbow = 8, LeftArm = { 15, 0, 25 }, Neck = { -18, 0, 0 } }

	-- what their quirk does round the body
	local function colorOf(quirk)
		local q = Config.Quirks[quirk or ""]
		return q and q.Color or Color3.fromRGB(255, 220, 90), q and q.AccentColor or WHITE
	end
	local BURST = {
		Explosion = function(pos, dir)
			toonExplosion(pos, 3.6, { SmokeLife = 2.4 })
			shockDisc(pos, dir, 3, 34, 0.35, FIRE[2], 5)
			billboardRing(pos, 3, 30, FIRE[1], 8, 0.35)
		end,
		OneForAll = function(pos, dir)
			for k = 1, 3 do
				shockDisc(pos, dir, 2 + k, 22 + 14 * k, 0.3 + 0.06 * k, WHITE, 6 + 4 * k)
			end
			streaks(pos, dir, 14, 0.6, 8, 40, WHITE, 0.35)
			dustPuffs(groundPoint(pos), 1.6, 8, Color3.fromRGB(200, 190, 175), 1, true)
		end,
		FullCowl = function(pos, dir)
			local green = Color3.fromRGB(90, 255, 120)
			sparks(pos, 1.6, WHITE, green, 24)
			shockDisc(pos, dir, 2, 28, 0.3, green, 5)
			streaks(pos, dir, 10, 0.5, 8, 30, green, 0.3)
			billboardRing(pos, 2, 22, green, 6, 0.3)
		end,
		HalfCold = function(pos, dir)
			-- (round 81) ice and fire at once: a crown of crystals bursts up
			-- round the body on one side, flame on the other, and the
			-- superheated air between them goes off in white steam (not
			-- Bakugo's fireball)
			local g = groundPoint(pos)
			local flat = V3(dir.X, 0, dir.Z)
			flat = flat.Magnitude > 0.05 and flat.Unit or V3(0, 0, -1)
			local side = flat:Cross(UP)
			local model = outlineModel(ICE_OUTLINE)
			local list = {}
			for i = 1, 6 do
				local a = (i / 6 - 0.5) * math.pi * 0.9
				local out = (side * math.cos(a) + flat * math.sin(a)).Unit
				table.insert(list, {
					set = makeSpike(model, g + out * 2.4 - UP * 0.5, (UP * 1.1 + out * 0.8).Unit, rand(4, 6.5), 1.7, false, { quiet = true, shards = 0, face = pos - flat * 10 }),
					delay = i * 0.012,
				})
			end
			growSpikes(list, 0.08)
			for _ = 1, 3 do
				Flame.burst(g - side * rand(2.5, 4) + flat * rand(-2, 2) + UP * 2, rand(4, 5.5), 10)
			end
			IceKit.steamBlast(pos, dir, 0.45, { quiet = true })
			billboardRing(pos, 2, 24, Color3.fromRGB(205, 240, 255), 6, 0.3)
			task.delay(0.35, function()
				shatter(model, 14, { from = pos, instant = true, force = 1.6 })
			end)
		end,
		Engine = function(pos, dir)
			local blue = Color3.fromRGB(110, 170, 255)
			streaks(pos, dir, 16, 0.5, 10, 45, blue, 0.35)
			shockDisc(pos, dir, 2, 30, 0.3, blue, 8)
			billboardRing(pos, 2, 20, WHITE, 5, 0.25)
		end,
		Compress = function(pos, dir)
			VFX.MC.burst(pos, dir)
		end,
		Electrification = function(pos, dir)
			VFX.DK.burst(pos, dir)
		end,
		Hellflame = function(pos, dir)
			VFX.HF.burst(pos, dir)
		end,
		Blueflame = function(pos, dir)
			VFX.HF.dabiBurst(pos, dir)
		end,
		Arbor = function(pos)
			local KW = VFX.KW
			if KW then
				local g = groundPoint(pos)
				for i = 1, 6 do
					local a = i / 6 * math.pi * 2
					local out = V3(math.cos(a), 0, math.sin(a))
					KW.stake(g + out * 3, rand(4, 6), 1.1, out * 0.5, 1.2)
				end
				KW.leaves(pos + UP * 3, 18, 4)
			end
			shockDisc(pos, UP, 2, 24, 0.35, Color3.fromRGB(236, 128, 36))
		end,
		Decay = function(pos, dir, target, data)
			VFX.DecayKit.koBurst(pos, dir, target, data) -- (round 83: they're ash)
		end,
		Overhaul = function(pos, dir)
			rocks(groundPoint(pos), 1.2, 10)
			shockDisc(pos, dir, 2, 26, 0.3, Color3.fromRGB(200, 40, 50), 4)
			sparks(pos, 1.2, WHITE, Color3.fromRGB(220, 60, 60), 14)
		end,
		Lemillion = function(pos)
			for k = 1, 3 do
				task.delay(k * 0.08, function()
					billboardRing(pos, 2, 18 + k * 8, Color3.fromRGB(255, 226, 80), 6, 0.3)
				end)
			end
		end,
	}
	local function burst(quirk, pos, dir, target, data)
		local fn = BURST[quirk or ""]
		if fn then
			fn(pos, dir, target, data)
			return
		end
		local c, a = colorOf(quirk)
		shockDisc(pos, dir, 2, 28, 0.3, c, 5)
		billboardRing(pos, 2, 24, a, 6, 0.3)
		sparks(pos, 1.3, WHITE, c, 18)
	end

	-- "K.O.!" bursting off the body in comic letters
	local function koText(pos, color)
		local anchor = newPart(Vector3.one * 0.1, CFrame.new(pos + UP * 3), WHITE, nil)
		anchor.Transparency = 1
		local bb = Instance.new("BillboardGui")
		bb.Size = UDim2.fromOffset(60, 30)
		bb.AlwaysOnTop = true
		bb.MaxDistance = 160
		bb.LightInfluence = 0
		bb.Parent = anchor
		local label = Instance.new("TextLabel")
		label.Size = UDim2.fromScale(1, 1)
		label.BackgroundTransparency = 1
		label.Text = "K.O.!"
		label.TextScaled = true
		label.Font = Enum.Font.LuckiestGuy
		label.TextColor3 = color
		label.TextStrokeTransparency = 0
		label.TextStrokeColor3 = Color3.new(0, 0, 0)
		label.Rotation = rand(-10, 10)
		label.Parent = bb
		tween(bb, 0.18, { Size = UDim2.fromOffset(260, 130) }, Enum.EasingStyle.Back)
		tween(anchor, 1.3, { CFrame = anchor.CFrame + UP * 2 })
		task.delay(0.9, function()
			tween(label, 0.4, { TextTransparency = 1, TextStrokeTransparency = 1 })
		end)
		cleanup(anchor, 1.35)
	end

	function Effects.KOFinisher(char, data)
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		local root = charParts(char)
		local troot = target and target:FindFirstChild("HumanoidRootPart")
		local KF = Config.KOFinisher or {}
		if not root or not troot then
			return
		end
		local pos = typeof(data.Pos) == "Vector3" and data.Pos or troot.Position
		local dir = typeof(data.Dir) == "Vector3" and data.Dir or flatten(pos - root.Position, root)
		local quirk = char:GetAttribute("Quirk") or (Players:GetPlayerFromCharacter(char) and Players:GetPlayerFromCharacter(char):GetAttribute("Quirk"))
		local color = colorOf(quirk)
		-- time slows for everyone near it; the body flashes white
		local endSlow = VFX.SlowMoScreen and VFX.SlowMoScreen(pos, KF.SlowMo or 0.9)
		if endSlow then
			task.delay(KF.SlowMo or 0.9, endSlow)
		end
		if nearCamera(pos, 80) then
			VFX.ImpactFrame(0.09)
		end
		local flash = Instance.new("Highlight")
		flash.FillColor = WHITE
		flash.OutlineColor = color
		flash.FillTransparency = 0.1
		flash.Parent = target
		tween(flash, 0.5, { FillTransparency = 1, OutlineTransparency = 1 })
		cleanup(flash, 0.55)
		burst(quirk, pos, dir, target, data)
		koText(pos, color)
		armTrails(char, 0.45, color) -- (the swing that did it, streaking)
		VFX.PlaySound("KO", pos, 1)
		VFX.ShakeAt(pos, 3, 120, 0.4)
		-- the killer strikes a pose
		VFX.Pose(char, POSES["KO_" .. tostring(quirk)] and ("KO_" .. quirk) or "KO_Default", 1.1)
		-- and their camera swings round to watch the body fly
		local me = Players.LocalPlayer
		if KF.KillCam ~= false and me and me.Character == char then
			local dist = math.clamp((pos - root.Position).Magnitude, 3, 30)
			local camTime = KF.CamTime or 1
			VFX.Cinematic(char, {
				{ T = camTime * 0.55, From = { V3(6, 2.5, 2), V3(0, 1.5, -dist * 0.6) }, To = { V3(7, 3, -dist * 0.2), V3(0, 3, -dist * 0.9) }, Fov = { 55, 60 } },
				{ T = camTime * 0.45, Cut = true, From = { V3(-2, 3, 7), V3(0, 4, -dist - 6) }, To = { V3(-2.5, 3.5, 6), V3(0, 9, -dist - 16) }, Fov = { 60, 72 } },
			}, { Title = "K.O.", Subtitle = typeof(data.Name) == "string" and data.Name or nil, Color = color, Face = pos })
		end
	end
end

-- poses for moves that used to leave the body standing there
POSES.PhaseSink = { RightArm = { 170, 0, 12 }, LeftArm = { 170, 0, 12 }, Waist = { 6, 0, 0 }, Neck = { -10, 0, 0 }, RightKnee = 30, LeftKnee = 30 }
POSES.BlinkSign = { RightArm = { 95, 0, -35 }, RightElbow = 100, LeftArm = { 10, 0, 20 }, Waist = { 4, -18, 0 }, Neck = { -4, 14, 0 } }
POSES.CycleFist = { RightArm = { 70, 0, -20 }, RightElbow = 120, LeftArm = { 15, 0, 20 }, Waist = { 6, -14, 0 }, Neck = { 6, 0, 0 } }
POSES.StandUser = {
	RightArm = { 150, 0, -30 }, RightElbow = 80, LeftArm = { 60, 0, -40 }, LeftElbow = 100,
	Waist = { -10, 25, 8 }, Neck = { 10, -20, 0 }, RightLeg = -10, LeftLeg = 20, LeftKnee = 30,
}
-- (round 66) Josuke while Crazy Diamond throws his M1s: he stands his ground
