	function Effects.LightningRod(char, data, isLocal)
		local root = charParts(char)
		if root and isLocal and typeof(data.Dir) == "Vector3" then
			face(root, flatten(data.Dir, root))
		end
		VFX.Pose(char, "BlastUp", 0.6)
