	-- ...rockets straight up on a column of fire with them in his arms...
	function Effects.SkyProminenceRise(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local time = tonumber(data.Time) or 1.1
		VFX.Pose(char, "SkyHold", time + 0.4)
		VFX.PlaySound("SkyRise", root.Position, 1.2)
		local j = B.jet({ From = root.Position - UP * 2.5, Dir = -UP, Length = 26, Width = 8, Pal = "hell", Rolls = 3 })
		local t0 = os.clock()
		while os.clock() - t0 < time and root.Parent do
			j.aim(root.Position - UP * 2.5, -UP)
			task.wait()
		end
		j.stop(0.4)
		local from = typeof(data.From) == "Vector3" and data.From
		if from then
			B.burst(groundPoint(from) + UP, 5, { Pal = "hell", Tongues = 8 })
		end
	end
	-- ...and lets it all out, up there: a sun over the city
	function Effects.SkyProminenceBurst(char, data)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos
		if not pos then
			return
		end
		VFX.Pose(char, "NovaRelease", 1)
		local pal = HF.mono(pos, 1.3) and "mono" or "white"
		B.burst(pos, 16, { Pal = pal, Tongues = 20, NoScorch = true })
		-- (the pillar: up out of them into the clouds)
		local col = B.flame({ CF = CFrame.new(pos), Pal = pal, Height = 140, Width = 26, Tongues = 7, Volume = 3, Light = 60, Grow = 0.15, Spin = 1.2 })
		task.delay(2.2, function()
			col.kill(0.8)
		end)
		for k = 1, 3 do
			task.delay(k * 0.1, function()
				shockDisc(pos, UP, 6, 90 + k * 30, 0.6, k == 2 and B.PAL.hell.body or WHITE)
				billboardRing(pos, 6, 80 + k * 20, WHITE, 10, 0.5)
			end)
		end
		if nearCamera(pos, 500) then
			VFX.Hooks.Flash(Color3.fromRGB(255, 244, 214), 0.35)
			VFX.Hooks.Callout("PLUS ULTRA!!", B.PAL.hell.body)
		end
		VFX.PlaySound("SkyProminence", pos, 1.5)
		VFX.ShakeAt(pos, 4, 600, 0.8)
	end

	-- OVERHEATED: steam pouring off him, glowing red, hands on his knees
	function Effects.Overheat(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local time = tonumber(data.Time) or 2.5
		VFX.Motion(char, "Overheat")
		VFX.PlaySound("Overheat", root.Position, 1)
		local glow = Instance.new("Highlight")
		glow.FillColor = Color3.fromRGB(255, 60, 30)
		glow.FillTransparency = 0.55
		glow.OutlineTransparency = 1
		glow.DepthMode = Enum.HighlightDepthMode.Occluded
		glow.Parent = char
		local t0 = os.clock()
		while os.clock() - t0 < time and root.Parent do
			smokeBurst(root.Position + UP * rand(0, 2), Color3.fromRGB(236, 236, 240), 0.9, 1.5, 0.8, 3)
			glow.FillTransparency = 0.45 + 0.25 * math.sin((os.clock() - t0) * 10)
			task.wait(0.18)
		end
		tween(glow, 0.4, { FillTransparency = 1 })
		cleanup(glow, 0.45)
	end

	-- his awakening: the column, and the No. 1 pose
	QUIRK_FX.Ult.Hellflame = function(char, root, g)
		VFX.Motion(char, "EndeavorUlt")
		B.pillar(g, 46, 6, "hell", 1.3, { Ring = 8 })
		B.burst(root.Position + UP * 2, 5, { Pal = "white", Tongues = 10, NoScorch = true })
		billboardRing(root.Position + UP, 3, 34, B.PAL.hell.body, 8, 0.4)
		HF.aura(char, "hell")
	end
	-- a dash on the flames out of his feet
	QUIRK_FX.Dash.Hellflame = function(char, _root, dir)
		for _, names in { { "RightFoot", "Right Leg" }, { "LeftFoot", "Left Leg" } } do
			local leg = limb(char, names[1], names[2])
			if leg then
				local f = B.flame({ Part = leg, Offset = CFrame.new(0, -leg.Size.Y / 2, 0) * CFrame.Angles(math.pi, 0, 0), Pal = "hell", Height = 2.6, Width = 0.9, Tongues = 2, Volume = 0.5, Light = 0, Grow = 0.04, Wind = -dir * 40 })
				task.delay(0.3, function()
					f.kill(0.2)
				end)
			end
		end
		legTrails(char, 0.25, B.PAL.hell.body)
	end
	-- his M1s: every punch flares; the 4th throws fire
	function VFX.HellflamePunch(char, count, finisher, fist, look)
		B.burst(fist + look * 0.6, finisher and 2.4 or 1.1, { Pal = char:GetAttribute("UltActive") and "white" or "hell", Tongues = finisher and 6 or 3, NoScorch = true, Smoke = false })
		if finisher or count == 4 then
			B.jet({ From = fist, Dir = look, Length = 14, Width = 4, Pal = "hell", Life = 0.22, Fade = 0.15, Rolls = 2 })
		end
		VFX.PlaySound(finisher and "FireBlast" or "FirePunch", fist, finisher and 1 or 0.6)
	end
	-- the finisher: the fist in their gut, and Jet Burn through them
	function HF.finisher(char, _target, troot, d, time)
		VFX.Motion(char, "JetBurn")
		task.wait(time * 0.3)
		if not troot.Parent then
			return
		end
		local j = B.jet({ From = HF.handCF(char, true).Position, Dir = d, Length = 30, Width = 7, Pal = "hell", Rolls = 3 })
		task.wait(time * 0.45)
		j.stop(0.25)
		if troot.Parent then
			B.burst(troot.Position, 4, { Pal = "white", Tongues = 8 })
			VFX.PlaySound("FireBlast", troot.Position, 1)
		end
	end
	function HF.burst(pos, _dir)
		B.pillar(groundPoint(pos + UP * 2), 30, 5, "hell", 1.2)
		B.burst(pos, 5, { Pal = "white", Tongues = 10 })
	end

	-- an ult's fire all over him (Endeavor: flames off his arms and back;
	-- Dabi: burning everywhere) while it's up
	function HF.aura(char, pal)
		if HF.auras[char] then
			return
		end
		local flames = {}
		HF.auras[char] = flames
		for _, spec in {
			{ "UpperTorso", "Torso", CFrame.new(0, 0.2, 0.3), 3.2, 1.6 },
			{ "RightUpperArm", "Right Arm", CFrame.new(0, 0, 0), 2.2, 0.9 },
			{ "LeftUpperArm", "Left Arm", CFrame.new(0, 0, 0), 2.2, 0.9 },
			{ "RightUpperLeg", "Right Leg", CFrame.new(0, 0, 0), 1.8, 0.8 },
			{ "LeftUpperLeg", "Left Leg", CFrame.new(0, 0, 0), 1.8, 0.8 },
		} do
			local part = limb(char, spec[1], spec[2])
			if part then
				table.insert(flames, B.flame({ Part = part, Offset = spec[3], Pal = pal, Height = spec[4], Width = spec[5], Tongues = 3, Volume = 0.6, Heart = false, Light = spec[1] == "UpperTorso" and 14 or 0, Grow = 0.4, Soft = true }))
			end
		end
		task.spawn(function()
			while char.Parent and char:GetAttribute("UltActive") do
				task.wait(0.3)
			end
			for _, f in flames do
				f.kill(0.5)
			end
			HF.auras[char] = nil
		end)
	end

	-- THE COSTUME OF FIRE: every FireSpot on anyone's look (Endeavor's
	-- beard, brows, shoulders, boots) is lit while they're near enough to
	-- see - out while his flames are out (Vanishing Fist) or you've hidden
	-- cosmetics - and burns higher in his ult
	task.spawn(function()
		while true do
			task.wait(0.35)
			local cam = workspace.CurrentCamera
			local camPos = cam and cam.CFrame.Position
			local seen = {}
			for _, plr in Players:GetPlayers() do
				local ch = plr.Character
				local gear = ch and ch:FindFirstChild("QuirkGear")
				local cos = gear and gear:FindFirstChild("Cosmetics")
				local root = ch and ch:FindFirstChild("HumanoidRootPart")
				if cos and root then
					local near = camPos == nil or (root.Position - camPos).Magnitude < 200
					local out = (HF.out[ch] or 0) > os.clock()
					local lvl = ch:GetAttribute("UltActive") and 1.45 or 1
					for _, a in cos:GetDescendants() do
						if a:IsA("Attachment") and a.Name == "FireSpot" then
							seen[a] = true
							local holder = a.Parent
							local okL, ltm = pcall(function()
								return holder.LocalTransparencyModifier
							end)
							local hidden = okL and type(ltm) == "number" and ltm > 0.5
							local want = near and not out and not hidden
							local f = HF.spots[a]
							if want and not f and holder then
								f = B.flame({
									Part = holder, Offset = a.CFrame, Pal = a:GetAttribute("Pal") or "hell",
									Height = a:GetAttribute("Height") or 1, Width = a:GetAttribute("Width") or 0.5,
									Tongues = a:GetAttribute("Tongues") or 2, Volume = 0.3, Heart = false, Light = 0, Grow = 0.2, Soft = true,
								})
								HF.spots[a] = f
							elseif f and not want then
								f.kill(0.12)
								HF.spots[a] = nil
								f = nil
							end
							if f then
								f.level(lvl)
							end
						end
					end
				end
			end
			for a, f in HF.spots do
				if not seen[a] then
					f.kill(0.2)
					HF.spots[a] = nil
				end
			end
		end
	end)

	-------------------------------------------------------------------------
	-- DABI
	-------------------------------------------------------------------------

	-- 1: CREMATION - a wave of blue fire off his palm
	function Effects.Cremation(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local d = HF.aim(data, root)
		if isLocal then
			face(root, flatten(d, root))
		end
		VFX.Motion(char, "Cremation")
		local stop = HF.handFlame(char, false, 1.2, "blue")
		task.wait(0.16)
		stop(0.05)
		if not root.Parent then
			return
		end
		VFX.PlaySound("Cremation", root.Position, 1)
		local j = B.jet({ From = HF.handCF(char, false).Position, Dir = d, Length = ability.Range or 40, Width = ability.Width or 12, Pal = "blue", Rolls = 6 })
		local t0 = os.clock()
		while os.clock() - t0 < 0.6 and root.Parent do
			j.aim(HF.handCF(char, false).Position + d * 0.6, d)
			task.wait()
		end
		j.stop(0.3)
	end
	-- the street where it went stays alight (the server says where)
	function Effects.CremationPatches(_char, data)
		for _, p in typeof(data.Points) == "table" and data.Points or {} do
			if typeof(p) == "Vector3" then
				local f = B.flame({ CF = CFrame.new(p), Pal = "blue", Height = rand(3, 4.5), Width = (tonumber(data.Radius) or 4) * 0.9, Tongues = 4, Volume = 0.6, Light = 10, Grow = 0.3 })
				B.scorch(p, (tonumber(data.Radius) or 4) * 0.9, "blue")
				task.delay(tonumber(data.Life) or 5, function()
					f.kill(0.6)
				end)
			end
		end
	end

	-- 2: HELL MINEFIELD - a hand on the street; the fire runs under it
	function Effects.HellMinefield(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		VFX.Motion(char, "HellMinefield")
		VFX.PlaySound("Minefield", root.Position, 1)
		local P = B.PAL.blue
		-- where his palm is: a glow, and cracks running out ahead of him
		local g = groundPoint(root.Position + d * 2)
		local palm = newPart(Vector3.new(0.12, 4, 4), CFrame.new(g + UP * 0.06) * CFrame.Angles(0, 0, math.rad(90)), P.body, Enum.Material.Neon, Enum.PartType.Cylinder)
		palm.Transparency = 0.3
		tween(palm, 0.8, { Transparency = 1, Size = Vector3.new(0.12, 8, 8) })
		cleanup(palm, 0.85)
		local range = ability.Range or 46
		local target = typeof(data.Pos) == "Vector3" and data.Pos or root.Position + d * range
		local v = Vector3.new(target.X - g.X, 0, target.Z - g.Z)
		if v.Magnitude > range then
			v = v.Unit * range
		end
		for k = 1, 3 do
			local wob = d:Cross(UP) * (k - 2) * 1.2
			local prev = g
			for s = 1, 8 do
				local p = groundPoint(g + v * (s / 8) + wob * math.sin(s) + Vector3.new(rand(-0.6, 0.6), 2, rand(-0.6, 0.6)))
				task.delay(s * 0.04, function()
					HF.cut(prev, p, "blue")
					prev = p
				end)
			end
		end
	end
	-- each pillar, as it erupts
	function Effects.MinefieldErupt(_char, data)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos
		if not pos then
			return
		end
		local r = tonumber(data.Radius) or 6.5
		B.pillar(pos, r * 3.4, r * 0.7, "blue", 0.85, { Ring = 5, Grow = 0.06 })
		rocks(pos, 1, 6)
		shockDisc(pos + UP * 0.5, UP, 2, r * 3, 0.3, B.PAL.blue.hot)
		VFX.PlaySound("MinefieldErupt", pos, 1)
		VFX.ShakeAt(pos, 1.2, 60, 0.25)
	end

	-- 3: HELL SPIDER (Dabi's): roaring streams, not threads
	function Effects.BlueSpider(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local d = HF.aim(data, root)
		if isLocal then
			face(root, flatten(d, root))
		end
		VFX.Motion(char, "BlueSpider")
		task.wait(0.12)
		if not root.Parent then
			return
		end
		VFX.PlaySound("BlueSpider", root.Position, 1)
		local n = ability.Streams or 5
		local spread = math.rad(ability.Spread or 30)
		local jets = {}
		for i = 1, n do
			local a = (i - (n + 1) / 2) / math.max(n - 1, 1) * spread
			local dir = CFrame.fromAxisAngle(UP, a) * d
			jets[i] = { j = B.jet({ From = root.Position, Dir = dir, Length = ability.Range or 46, Width = 3, Pal = "blue", Rolls = 2 }), dir = dir }
		end
		local t0 = os.clock()
		while os.clock() - t0 < 0.55 and root.Parent do
			local tips = HF.tips(char, true, n)
			for i, s in jets do
				s.j.aim(tips[i] or root.Position, s.dir)
			end
			task.wait()
		end
		for _, s in jets do
			s.j.stop(0.25)
		end
	end

	-- R: BLUE WALL - a stamp, and a ring of blue fire bursts up round him
	function Effects.BlueWall(char, _data, _isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		VFX.Motion(char, "BlueWall")
		task.wait(0.17)
		if not root.Parent then
			return
		end
		local g = groundPoint(root.Position)
		local r = ability.Radius or 16
		VFX.PlaySound("BlueWall", g, 1)
		B.ring(g, r, 9, "blue", ability.Duration or 5, { Spacing = 3.4, Volume = 0.45, Grow = 0.1, Light = 0 })
		shockDisc(g + UP * 0.5, UP, 2, r * 2.4, 0.35, B.PAL.blue.hot)
		billboardRing(g + UP, 2, r * 2.2, B.PAL.blue.heart, 7, 0.3)
		VFX.ShakeAt(g, 1.3, 70, 0.3)
	end

	-- 4: JET BURN (Dabi's) - blue fire out behind him, rocketing him in
	function Effects.BlueJetBurn(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local d = flatten(data.Dir, root)
		local time = (ability.Range or 40) / (ability.Speed or 140)
		if isLocal then
			face(root, d)
			HF.dashes[char] = dash(root, d * (ability.Speed or 140), time)
		end
		VFX.Pose(char, "RushBack", time + 0.1)
		VFX.PlaySound("BlueJet", root.Position, 1)
		local j = B.jet({ From = root.Position - d * 1.5, Dir = -d, Length = 12, Width = 5, Pal = "blue", Rolls = 2 })
		local t0 = os.clock()
		while os.clock() - t0 < time and root.Parent and not j.dead do
			j.aim(root.Position - d * 1.5 + UP * 0.5, -d)
			task.wait()
		end
		j.stop(0.2)
	end
	function Effects.BlueJetBurnHit(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		if HF.dashes[char] then
			HF.dashes[char]()
			HF.dashes[char] = nil
		end
		local d = typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.1 and data.Dir.Unit or flatten(root.CFrame.LookVector, root)
		local at = typeof(data.At) == "Vector3" and data.At or root.Position + d * 4
		VFX.Pose(char, "CremationPalm", 0.45)
		B.burst(at, 5.5, { Pal = "blue", Tongues = 10 })
		B.jet({ From = at - d * 1.5, Dir = d, Length = 18, Width = 7, Pal = "blue", Life = 0.3, Fade = 0.2, Rolls = 3 })
		shockDisc(at, d, 2, 22, 0.3, B.PAL.blue.hot, 8)
		sparks(at, 1.4, WHITE, B.PAL.blue.body, 20)
		VFX.PlaySound("BlueBlast", at, 1)
		VFX.ShakeAt(at, 2, 90, 0.35)
	end

	-- ult 1: PROMINENCE BURN (his) - arms thrown wide, and a beam of blue
	-- fire out of his whole chest
	function Effects.BlueProminence(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local d = HF.aim(data, root)
		if isLocal then
			face(root, flatten(d, root))
		end
		cinematicFor(char, "BlueProminence", isLocal, ability.Name or "PROMINENCE BURN", B.PAL.blue.body)
		VFX.Motion(char, "BlueProminence")
		VFX.PlaySound("ProminenceCharge", root.Position, 1)
		local chest = B.flame({ Part = root, Offset = CFrame.new(0, 0.6, -0.8) * CFrame.Angles(-math.pi / 2, 0, 0), Pal = "blue", Height = 3, Width = 2.2, Volume = 1.2, Light = 16, Grow = 0.4 })
		task.wait(0.5)
		chest.kill(0.1)
		if not root.Parent then
			return
		end
		VFX.PlaySound("BlueProminence", root.Position, 1.3)
		local len, wid = ability.Range or 120, ability.Width or 14
		local from = root.Position + UP * 0.6 + d * 1.5
		local outer = B.jet({ From = from, Dir = d, Length = len, Width = wid * 1.3, Pal = HF.mono(from + d * 20, 1) and "mono" or "blue", Rolls = 7 })
		local inner = B.jet({ From = from, Dir = d, Length = len, Width = wid * 0.45, Pal = "white", Rolls = 0 })
		local t0 = os.clock()
		local nextMark = 0
		while os.clock() - t0 < 1 and root.Parent do
			from = root.Position + UP * 0.6 + d * 1.5
			outer.aim(from, d)
			inner.aim(from, d)
			if os.clock() > nextMark then
				nextMark = os.clock() + 0.08
				local at = groundPoint(from + d * rand(8, len))
				B.scorch(at, rand(3, 5), "blue")
			end
			task.wait()
		end
		outer.stop(0.4)
		inner.stop(0.3)
		if nearCamera(from, 100) then
			VFX.Hooks.Flash(B.PAL.blue.heart, 0.2)
		end
		VFX.ShakeAt(from + d * len * 0.4, 2.5, 200, 0.5)
	end

	-- ult 2: SEKOTO PEAK - the fire spreads out of him over the street
	function Effects.SekotoPeak(char, _data, _isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		VFX.Motion(char, "SekotoPeak")
		VFX.PlaySound("SekotoPeak", root.Position, 1.2)
		local g = groundPoint(root.Position)
		local R, dur = ability.Radius or 38, ability.Duration or 6
		for k = 1, 4 do
			task.delay(k * 0.14, function()
				local r = R * k / 4
				B.ring(g, r, 5 + k, "blue", dur - k * 0.14, { Spacing = 5 + k, Volume = 0.35, Grow = 0.2, Light = 0 })
				shockDisc(g + UP * 0.5, UP, r * 1.6, r * 2.2, 0.4, B.PAL.blue.hot)
			end)
		end
		VFX.ShakeAt(g, 1.6, 120, 0.5)
	end

	-- ult 3: VANISHING FIST (thrown): the fist flies on FlameFistFly
	function Effects.BlueVanishing(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		if isLocal then
			face(root, flatten(data.Dir, root))
		end
		VFX.Motion(char, "FistThrow")
		local stop = HF.handFlame(char, true, 2, "blue")
		task.delay(0.42, stop)
	end

	-- SEARED: his own fire burning him - smoke off his scars, a flicker of
	-- blue up his arms, and his staples bleed (if blood's on)
	function Effects.Seared(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		for _, names in { { "RightLowerArm", "Right Arm" }, { "LeftLowerArm", "Left Arm" } } do
			local arm = limb(char, names[1], names[2])
			if arm then
				smokeBurst(arm.Position, Color3.fromRGB(90, 86, 96), 0.6, 1, 0.7, 2)
				local f = B.flame({ Part = arm, Offset = CFrame.new(0, -0.3, 0), Pal = "blue", Height = 1.4, Width = 0.8, Tongues = 2, Volume = 0.3, Heart = false, Light = 0, Grow = 0.05, Soft = true })
				task.delay(0.35, function()
					f.kill(0.2)
				end)
			end
		end
		if VFX.BLOOD and (tonumber(data.Amount) or 0) >= 3 then
			local head = char:FindFirstChild("Head")
			if head then
				VFX.BLOOD.drip(head, (head.CFrame * CFrame.new(rand(-0.3, 0.3), -0.2, -0.5)).Position, 2)
			end
		end
	end

	-- his awakening: the dye washes out, and he's burning all over
	QUIRK_FX.Ult.Blueflame = function(char, root, g)
		VFX.Motion(char, "ToyaAwaken")
		B.pillar(g, 50, 7, "blue", 1.4, { Ring = 10 })
		B.ring(g, 12, 6, "blue", 1.6, { Spacing = 3.5 })
		billboardRing(root.Position + UP, 3, 36, B.PAL.blue.hot, 8, 0.4)
		HF.aura(char, "blue")
	end
	QUIRK_FX.Dash.Blueflame = function(char, root, dir)
		local f = B.flame({ Part = root, Offset = CFrame.new(0, -1.5, 0.8), Pal = "blue", Height = 2.5, Width = 1.6, Tongues = 3, Volume = 0.5, Light = 0, Grow = 0.04, Wind = -dir * 50 })
		task.delay(0.3, function()
			f.kill(0.2)
		end)
		legTrails(char, 0.25, B.PAL.blue.body)
	end
	function VFX.BlueflamePunch(char, count, finisher, fist, look)
		B.burst(fist + look * 0.6, finisher and 2.4 or 1.1, { Pal = char:GetAttribute("UltActive") and "white" or "blue", Tongues = finisher and 6 or 3, NoScorch = true, Smoke = false })
		if finisher or count == 4 then
			B.jet({ From = fist, Dir = look, Length = 16, Width = 5, Pal = "blue", Life = 0.25, Fade = 0.15, Rolls = 2 })
		end
		VFX.PlaySound(finisher and "BlueBlast" or "FirePunch", fist, finisher and 1 or 0.6)
	end
	function HF.dabiFinisher(char, _target, troot, d, time)
		VFX.Pose(char, "Grab", time * 0.5)
		task.wait(time * 0.35)
		if not troot.Parent then
			return
		end
		VFX.Pose(char, "CremationPalm", time * 0.6)
		local j = B.jet({ From = HF.handCF(char, false).Position, Dir = d, Length = 26, Width = 9, Pal = "blue", Rolls = 4 })
		task.wait(time * 0.45)
		j.stop(0.25)
	end
	function HF.dabiBurst(pos, _dir)
		B.pillar(groundPoint(pos + UP * 2), 34, 5, "blue", 1.3)
		B.ring(groundPoint(pos + UP * 2), 8, 5, "blue", 1.5)
	end
end

---------------------------------------------------------------------------
-- MANGA: the anime's screen language, for the big moments. The frame going
-- black and white on the hit (the IMPACT FRAME), focus lines rushing in from
-- the edges, colour bands streaming past on a blitz, a lens-flare star on a
-- flash, and the rainbow of shock rings a big punch throws out. Each only on
-- your screen, only when you're close enough to see it.
---------------------------------------------------------------------------
do
	local MG = { token = 0 }
	VFX.MANGA = MG
	MG.RAINBOW = {
		Color3.fromRGB(255, 70, 70), Color3.fromRGB(255, 160, 50), Color3.fromRGB(255, 110, 200),
		Color3.fromRGB(120, 255, 140), Color3.fromRGB(80, 220, 255), Color3.fromRGB(110, 120, 255),
	}

	-- (the layer the lines are drawn on, over everything)
	function MG.gui()
		local me = Players.LocalPlayer
		local pg = me and me:FindFirstChildOfClass("PlayerGui")
		if not pg then
			return nil
		end
		if not (MG.screen and MG.screen.Parent) then
			local g = Instance.new("ScreenGui")
			g.Name = "MangaFX"
			g.IgnoreGuiInset = true
			g.ResetOnSpawn = false
			g.DisplayOrder = 40
			g.Parent = pg
			MG.screen = g
		end
		return MG.screen
	end
	function MG.view()
		local cam = workspace.CurrentCamera
		local v = cam and cam.ViewportSize
		if not v or v.X < 10 then
			return Vector2.new(1280, 720)
		end
		return v
	end

	-- BLACK AND WHITE: the whole screen goes to hard greyscale for t seconds
	-- (Contrast, Brightness), then the colour floods back in (Fade)
	function MG.mono(t, opts)
		opts = opts or {}
		MG.token += 1
		local token = MG.token
		local lighting = game:GetService("Lighting")
		local cc = lighting:FindFirstChild("MangaMono")
		if not cc then
			cc = Instance.new("ColorCorrectionEffect")
			cc.Name = "MangaMono"
			cc.Parent = lighting
		end
		cc.Enabled = true
		cc.Saturation = -1
		cc.Contrast = opts.Contrast or 1.1
		cc.Brightness = opts.Brightness or 0.06
		cc.TintColor = opts.Tint or Color3.new(1, 1, 1)
		task.delay(t or 0.1, function()
			if MG.token ~= token then
				return
			end
			local fade = opts.Fade or 0.12
			tween(cc, fade, { Saturation = 0, Contrast = 0, Brightness = 0 })
			task.delay(fade + 0.02, function()
				if MG.token == token then
					cc.Enabled = false
				end
			end)
		end)
	end

	-- SPEED LINES for t seconds, redrawn twelve times a second (hand-drawn
	-- boil). Kind "focus": black lines rushing in from the edges at the middle
	-- (clear in the centre). Kind "stream": bands of Colors sliding past at
	-- Angle degrees. Count, Thick, Alpha tune them.
	function MG.lines(t, opts)
		opts = opts or {}
		local gui = MG.gui()
		if not gui then
			return
		end
		local box = Instance.new("Frame")
		box.Name = "SpeedLines"
		box.BackgroundTransparency = 1
		box.Size = UDim2.fromScale(1, 1)
		box.ZIndex = 5
		box.Parent = gui
		local v = MG.view()
		local diag = v.Magnitude
		local stream = opts.Kind == "stream"
		local colors = opts.Colors or { Color3.new(0, 0, 0) }
		local lines = {}
		for i = 1, opts.Count or (stream and 26 or 44) do
			local f = Instance.new("Frame")
			f.BorderSizePixel = 0
			f.AnchorPoint = Vector2.new(0.5, 0.5)
			f.BackgroundColor3 = colors[(i - 1) % #colors + 1]
			f.BackgroundTransparency = opts.Alpha or (stream and 0.25 or 0.05)
			f.ZIndex = 5
			f.Parent = box
			lines[i] = f
		end
		local function draw()
			for i, f in lines do
				if stream then
					local a = math.rad(opts.Angle or -20)
					local along = Vector2.new(math.cos(a), math.sin(a))
					local across = Vector2.new(-along.Y, along.X)
					local c = v / 2 + across * rand(-0.6, 0.6) * diag + along * rand(-0.3, 0.3) * diag
					f.Position = UDim2.fromOffset(c.X, c.Y)
					f.Size = UDim2.fromOffset(diag * rand(0.4, 1.1), (opts.Thick or 10) * rand(0.4, 2.2))
					f.Rotation = math.deg(a)
				else
					local a = (i / #lines) * math.pi * 2 + rand(-0.08, 0.08)
					local r = diag * rand(0.5, 0.6)
					local c = v / 2 + Vector2.new(math.cos(a), math.sin(a)) * r
					f.Position = UDim2.fromOffset(c.X, c.Y)
					f.Size = UDim2.fromOffset(diag * rand(0.22, 0.42), (opts.Thick or 7) * rand(0.35, 1.6))
					f.Rotation = math.deg(a)
				end
			end
		end
		task.spawn(function()
			local t0 = os.clock()
			while os.clock() - t0 < (t or 0.2) and box.Parent do
				draw()
				task.wait(1 / 12)
			end
			box:Destroy()
		end)
	end

	-- a LENS FLARE on a world point: a bright core, a cross, and the long
	-- horizontal streak of an anamorphic lens; it blooms and is gone in life
	function MG.flare(pos, color, size, life)
		if typeof(pos) ~= "Vector3" then
			return
		end
		color = color or Color3.new(1, 1, 1)
		size = size or 4
		life = life or 0.4
		local anchor = newPart(Vector3.one * 0.1, CFrame.new(pos), color)
		anchor.Transparency = 1
		local bb = Instance.new("BillboardGui")
		bb.Size = UDim2.fromScale(size * 8, size * 8)
		bb.LightInfluence = 0
		bb.AlwaysOnTop = true
		bb.Parent = anchor
		for _, spec in {
			{ 1, 0.018, color, 0.1 }, { 0.36, 0.05, Color3.new(1, 1, 1), 0 },
			{ 0.022, 0.5, color, 0.1 }, { 0.018, 0.22, Color3.new(1, 1, 1), 0 },
			{ 0.09, 0.09, Color3.new(1, 1, 1), 0 },
		} do
			local f = Instance.new("Frame")
			f.AnchorPoint = Vector2.new(0.5, 0.5)
			f.Position = UDim2.fromScale(0.5, 0.5)
			f.Size = UDim2.fromScale(spec[1], spec[2])
			f.BackgroundColor3 = spec[3]
			f.BackgroundTransparency = spec[4]
			f.BorderSizePixel = 0
			f.Parent = bb
			if spec[1] == spec[2] then
				local corner = Instance.new("UICorner")
				corner.CornerRadius = UDim.new(1, 0)
				corner.Parent = f
			end
			tween(f, life, { BackgroundTransparency = 1, Size = UDim2.fromScale(spec[1] * 1.3, spec[2] * 0.4) }, Enum.EasingStyle.Quad)
		end
		cleanup(anchor, life + 0.05)
	end

	-- the RAINBOW: shock rings one after another out along dir, each a colour
	function MG.rainbow(pos, dir, size, life)
		dir = (typeof(dir) == "Vector3" and dir.Magnitude > 0.1) and dir.Unit or UP
		for i, c in MG.RAINBOW do
			task.delay(i * 0.03, function()
				shockDisc(pos + dir * i * size * 0.12, dir, size * 0.25, size * (0.9 + i * 0.22), life or 0.4, c)
			end)
		end
		billboardRing(pos, size * 0.4, size * 3, Color3.new(1, 1, 1), 6, (life or 0.4) * 0.8)
	end

	-- the IMPACT FRAME on a hit you're close to: black and white, the focus
	-- lines, and a flash of white if it's huge (opts.Flash)
	function MG.impact(pos, t, opts)
		opts = opts or {}
		if typeof(pos) == "Vector3" and not nearCamera(pos, opts.Radius or 120) then
			return false
		end
		MG.mono(t or 0.1, opts)
		MG.lines((t or 0.1) + 0.1, { Kind = "focus" })
		if opts.Flash then
			VFX.Hooks.Flash(Color3.new(1, 1, 1), opts.Flash)
		end
		return true
	end
end

do
	-- PROMINENCE BURN is so hot the world goes black and white - for anyone
	-- close enough to see it (true if it did: the fire is drawn white, inked
	-- in black, to match)
	function VFX.HF.mono(pos, t)
		if typeof(pos) ~= "Vector3" or not nearCamera(pos, 260) then
			return false
		end
		VFX.MANGA.mono(t or 1, { Contrast = 1.35, Brightness = 0.1, Fade = 0.45 })
		VFX.MANGA.lines((t or 1) * 0.5, { Kind = "focus" })
		return true
	end
end

---------------------------------------------------------------------------
-- DEKU AT 100%, the way the movies animate him. At Full Cowl 100% his eyes
-- burn white (a streak off them when he moves) and the tattered yellow cape
-- streams off his shoulders; the awakening is a crouch in a storm of
-- lightning - a white-hot disc under him, orange rings whipping round him,
-- green lightning up his body, bolts tearing out across the street, the
-- frame going black and white. SHOOT STYLE RUSH is a blitz: a streak of
-- lightning zig-zagging round them, a kick every time he lands, afterimages
-- where he was, colour streaming past, then the big kick through them in a
-- rainbow of rings. INFINITE 100%'s fists multiply. And the 1,000,000%
-- DELAWARE DETROIT SMASH is "GO... BEYOND... PLUS ULTRA!!" - All Might is
-- there behind him, and they throw the punch together.
---------------------------------------------------------------------------
do
	local D9 = {
		capes = setmetatable({}, { __mode = "k" }),
		CYAN = Color3.fromRGB(96, 232, 255), ORANGE = Color3.fromRGB(255, 150, 44),
		GOLD = Color3.fromRGB(222, 176, 60), GOLD_DARK = Color3.fromRGB(176, 128, 40), SPIRIT = Color3.fromRGB(255, 214, 120),
	}
	VFX.D9 = D9
	local MG, DK = VFX.MANGA, VFX.DK

	-- the power crouch (knees deep, arms out and down, fists shut, chest out)
	-- and the blitz kicks, one off each leg
	POSES.CowlCrouch = { RightArm = { 18, 0, 40 }, LeftArm = { 18, 0, 40 }, RightElbow = 35, LeftElbow = 35, Waist = { -22, 0, 0 }, Neck = { 18, 0, 0 }, RightLeg = 36, RightKnee = 76, LeftLeg = -12, LeftKnee = 62, Crouch = 0.8 }
	POSES.BlitzKick = { RightLeg = { 100, 0, 10 }, RightKnee = 5, LeftLeg = -20, LeftKnee = 30, RightArm = { -40, 0, 40 }, LeftArm = { 40, 0, 30 }, Waist = { 18, 30, 0 }, Neck = { 6, -24, 0 } }
	POSES.BlitzKickL = { LeftLeg = { 100, 0, 10 }, LeftKnee = 5, RightLeg = -20, RightKnee = 30, LeftArm = { -40, 0, 40 }, RightArm = { 40, 0, 30 }, Waist = { 18, -30, 0 }, Neck = { 6, 24, 0 } }

	---------------------------------------------------------------------------
	-- THE CAPE AND THE EYES (every screen draws them for every Deku at 100%
	-- close enough to see). Five strips off the back of his collar, each a
	-- chain of cloth panels, the torn ones shorter; the faster he goes the
	-- further out behind him it streams (falling lifts it), and the ends
	-- flutter. His eyes: white-hot, with a streak left behind them.
	---------------------------------------------------------------------------
	function D9.cape(char)
		if D9.capes[char] then
			return
		end
		local torso = limb(char, "UpperTorso", "Torso")
		if not torso then
			return
		end
		local model = Instance.new("Model")
		model.Name = "DekuCape"
		model.Parent = folder
		local c = { char = char, torso = torso, head = char:FindFirstChild("Head"), model = model, strips = {}, eyes = {}, grow = 0, phase = rand(0, 10) }
		for s = 1, 5 do
			local segs = {}
			for k = 1, (s == 2 or s == 5) and 4 or 5 do
				local p = newPart(Vector3.new(0.58 * (1 - k * 0.06), 0.05, 0.56), CFrame.new(), (k + s) % 2 == 0 and D9.GOLD or D9.GOLD_DARK, Enum.Material.Fabric, nil, model)
				p.Name = "Cape"
				segs[k] = p
			end
			c.strips[s] = { x = (s - 3) / 4, segs = segs, lag = rand(0, 1) }
		end
		if c.head then
			for _, side in { -1, 1 } do
				local e = newPart(Vector3.new(0.17, 0.08, 0.05), CFrame.new(), Color3.new(1, 1, 1), Enum.Material.Neon, nil, model)
				e.Name = "Eye"
				local a0 = Instance.new("Attachment")
				a0.Position = Vector3.new(0, 0.035, 0)
				a0.Parent = e
				local a1 = Instance.new("Attachment")
				a1.Position = Vector3.new(0, -0.035, 0)
				a1.Parent = e
				local tr = Instance.new("Trail")
				tr.Attachment0, tr.Attachment1 = a0, a1
				tr.Lifetime = 0.22
				tr.Color = ColorSequence.new(Color3.new(1, 1, 1), D9.CYAN)
				tr.Transparency = NumberSequence.new(0.1, 1)
				tr.LightEmission = 1
				tr.FaceCamera = true
				tr.Parent = e
				table.insert(c.eyes, { part = e, side = side })
			end
		end
		D9.capes[char] = c
	end
	function D9.dropCape(char)
		local c = D9.capes[char]
		if c then
			D9.capes[char] = nil
			c.model:Destroy()
		end
	end
	function D9.stepCape(c, now, camPos)
		local torso = c.torso
		if not torso.Parent or not c.char.Parent then
			return false
		end
		local cf = torso.CFrame
		if camPos and (cf.Position - camPos).Magnitude > 220 then
			c.model.Parent = nil
			return true
		end
		c.model.Parent = folder
		local okV, vel = pcall(function()
			return torso.AssemblyLinearVelocity
		end)
		local lv = cf:VectorToObjectSpace(okV and typeof(vel) == "Vector3" and vel or Vector3.zero)
		local speed = Vector3.new(lv.X, 0, lv.Z).Magnitude
		local lift = math.clamp(-lv.Z / 45, 0, 1) + math.clamp(-lv.Y / 70, 0, 0.6)
		local base = math.rad(14) + math.min(lift, 1.25) * math.rad(60)
		c.grow = math.min(1, c.grow + 0.06)
		local ts = torso.Size
		for _, st in c.strips do
			local pos = (cf * CFrame.new(st.x * ts.X * 0.72, ts.Y / 2 - 0.08, ts.Z / 2 + 0.06 + math.abs(st.x) * 0.04)).Position
			local sway = math.sin(now * 3.1 + st.lag * 6) * 0.1 + lv.X / 90
			local n = #st.segs
			for k, p in st.segs do
				local flutter = math.sin(now * (7 + math.min(speed, 60) * 0.2) - k * 0.9 + st.lag * 5 + c.phase) * math.rad(6 + math.min(speed, 60) * 0.35) * (k / n + 0.3)
				local a = base + k * math.rad(6) * (1 - math.clamp(lift, 0, 1)) + flutter
				local dir = cf:VectorToWorldSpace(Vector3.new(sway * k * 0.3 + st.x * 0.14 * k, -math.cos(a), math.sin(a))).Unit
				local len = p.Size.Z * c.grow
				local mid = pos + dir * len / 2
				p.CFrame = CFrame.lookAt(mid, mid + dir, cf.LookVector)
				pos += dir * len
			end
		end
		local head = c.head
		if head and head.Parent then
			local s = head.Size.Y
			for _, e in c.eyes do
				e.part.CFrame = head.CFrame * CFrame.new(e.side * 0.19 * s, 0.1 * s, -0.6 * s)
			end
		end
		return true
	end
	RunService.RenderStepped:Connect(function()
		D9.tick = (D9.tick or 0) + 1
		-- (every so often: any Deku at 100% near you gets his, however you got here)
		if D9.tick % 30 == 0 then
			for _, plr in Players:GetPlayers() do
				local ch = plr.Character
				if ch and not D9.capes[ch] and ch:GetAttribute("UltActive") and ch:GetAttribute("Quirk") == "FullCowl" then
					D9.cape(ch)
				end
			end
		end
		if next(D9.capes) == nil then
			return
		end
		local now = os.clock()
		local cam = workspace.CurrentCamera
		local camPos = cam and cam.CFrame.Position
		for char, c in D9.capes do
			if not (char.Parent and char:GetAttribute("UltActive") and char:GetAttribute("Quirk") == "FullCowl") then
				D9.dropCape(char)
			else
				local ok, keep = pcall(D9.stepCape, c, now, camPos)
				if not ok or not keep then
					D9.dropCape(char)
				end
			end
		end
	end)

	---------------------------------------------------------------------------
	-- pieces of the storm
	---------------------------------------------------------------------------
	-- rings: thin neon loops round him, each on its own tilt, spinning
	function D9.rings(root, life, color, count)
		for i = 1, count or 3 do
			local segs = {}
			local r = 2.3 + i * 0.35
			for k = 1, 20 do
				segs[k] = newPart(Vector3.new(0.12, 0.12, r * 0.34), CFrame.new(root.Position), color or D9.ORANGE, Enum.Material.Neon)
			end
			local tilt = CFrame.Angles(rand(-1.1, 1.1), rand(0, 6.28), rand(-1.1, 1.1))
			local spin = rand(6, 10) * (i % 2 == 0 and -1 or 1)
			task.spawn(function()
				local t0 = os.clock()
				while os.clock() - t0 < life and root.Parent do
					local t = os.clock() - t0
					local ring = CFrame.new(root.Position) * tilt * CFrame.Angles(0, t * spin, 0)
					local fade = math.clamp((t - life * 0.6) / (life * 0.4), 0, 1)
					for k, p in segs do
						local a = k / 20 * math.pi * 2
						local at = ring * Vector3.new(math.cos(a) * r, 0, math.sin(a) * r)
						p.CFrame = CFrame.lookAt(at, at + ring:VectorToWorldSpace(Vector3.new(-math.sin(a), 0, math.cos(a))))
						p.Transparency = fade
					end
					task.wait()
				end
				for _, p in segs do
					p:Destroy()
				end
			end)
		end
	end
	-- a pillar of lightning up his body, bolt after bolt
	function D9.pillar(root, life, color)
		task.spawn(function()
			local t0 = os.clock()
			while os.clock() - t0 < life and root.Parent do
				local off = Vector3.new(rand(-1.2, 1.2), 0, rand(-1.2, 1.2))
				DK.zig(groundPoint(root.Position) + off, root.Position + UP * rand(4, 7) + off * 0.3, color or COWL_GREEN, 0.3, 0.14, 0.7)
				task.wait(0.07)
			end
		end)
	end
	-- the white-hot disc under him and the bolts tearing out over the street
	function D9.storm(root, life)
		local g = groundPoint(root.Position)
		local disc = newPart(Vector3.new(0.2, 1, 1), CFrame.new(g + UP * 0.07) * CFrame.Angles(0, 0, math.rad(90)), Color3.fromRGB(214, 246, 255), Enum.Material.Neon, Enum.PartType.Cylinder)
		disc.Name = "CowlDisc"
		disc.Transparency = 0.15
		tween(disc, 0.25, { Size = Vector3.new(0.2, 15, 15) }, Enum.EasingStyle.Quad)
		tween(disc, life, { Transparency = 1, Size = Vector3.new(0.2, 19, 19) }, Enum.EasingStyle.Linear, nil, 0.25)
		cleanup(disc, life + 0.3)
		task.spawn(function()
			local t0 = os.clock()
			while os.clock() - t0 < life and root.Parent do
				local a = rand(0, 6.28)
				local out = Vector3.new(math.cos(a), 0, math.sin(a))
				DK.zig(root.Position + UP * rand(-1, 1.5), groundPoint(root.Position + out * rand(8, 18)) + UP * 0.2, D9.CYAN, 0.28, 0.16, 1)
				task.wait(0.06)
			end
		end)
	end
	-- a ghost of him standing at `at` (a frame of the blitz, left behind)
	function D9.ghost(char, at, color, life, alpha)
		local root = char:FindFirstChild("HumanoidRootPart")
		if not root then
			return
		end
		local rel = root.CFrame:Inverse()
		for _, part in char:GetChildren() do
			if part:IsA("BasePart") and part ~= root and part.Transparency < 1 then
				local g = part:Clone()
				if g then
					g:ClearAllChildren()
					if g:IsA("MeshPart") then
						g.TextureID = ""
					end
					g.Anchored, g.CanCollide, g.CanQuery, g.CanTouch, g.CastShadow, g.Massless = true, false, false, false, false, true
					g.Material = Enum.Material.Neon
					g.Color = color
					g.Transparency = alpha or 0.35
					g.CFrame = at * (rel * part.CFrame)
					g.Name = "Afterimage"
					g.Parent = folder
					tween(g, life, { Transparency = 1 })
					cleanup(g, life + 0.05)
				end
			end
		end
	end
	-- a ghost fist, flung from `from` into `to` (the barrage multiplying)
	function D9.fist(from, to, color)
		local dir = to - from
		if dir.Magnitude < 0.2 then
			return
		end
		local p = newPart(Vector3.new(0.9, 0.9, 1.1), CFrame.lookAt(from, to), color, Enum.Material.Neon)
		p.Name = "GhostFist"
		p.Transparency = 0.3
		tween(p, 0.06, { CFrame = CFrame.lookAt(to, to + dir) }, Enum.EasingStyle.Quad)
		tween(p, 0.12, { Transparency = 1, Size = Vector3.new(1.3, 1.3, 0.6) }, nil, nil, 0.06)
		cleanup(p, 0.2)
		local streak = newPart(Vector3.new(0.14, 0.14, dir.Magnitude), CFrame.lookAt(from + dir / 2, to), color, Enum.Material.Neon)
		streak.Transparency = 0.4
		tween(streak, 0.1, { Transparency = 1 })
		cleanup(streak, 0.12)
	end

	---------------------------------------------------------------------------
	-- THE AWAKENING: FULL COWL 100%
	---------------------------------------------------------------------------
	function D9.awaken(char, root)
		VFX.Pose(char, "CowlCrouch", 0.9)
		D9.rings(root, 0.75, D9.ORANGE, 3)
		D9.pillar(root, 0.6, COWL_GREEN)
		D9.storm(root, 1.1)
		DK.crackleOn(char, 1.2, D9.CYAN)
		D9.cape(char)
		local head = char:FindFirstChild("Head")
		task.delay(0.35, function()
			if root.Parent then
				MG.flare((head or root).Position, D9.CYAN, 3, 0.5)
				MG.impact(root.Position, 0.09, { Radius = 90 })
				MG.rainbow(root.Position, UP, 10, 0.45)
			end
		end)
	end
	D9.oldUlt = QUIRK_FX.Ult.FullCowl
	QUIRK_FX.Ult.FullCowl = function(char, root, g)
		if D9.oldUlt then
			D9.oldUlt(char, root, g)
		end
		D9.awaken(char, root)
	end

	---------------------------------------------------------------------------
	-- 100%: SHOOT STYLE RUSH - the crouch, then the server's blitz (RushBlitz)
	---------------------------------------------------------------------------
	Effects.GearshiftRush = function(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		if isLocal then
			face(root, flatten(data.Dir, root))
		end
		VFX.Pose(char, "CowlCrouch", 0.14)
		DK.crackleOn(char, 0.8, D9.CYAN)
		for _ = 1, 3 do
			bolt(root.Position, 2.5, COWL_GREEN)
		end
		VFX.PlaySound("DekuLaunch", root.Position, 0.6)
	end
	function Effects.RushBlitz(char, data)
		local root = charParts(char)
		local pts = type(data.Points) == "table" and data.Points or {}
		local center = typeof(data.Center) == "Vector3" and data.Center
		if not root or not center or #pts == 0 then
			return
		end
		local gap = tonumber(data.Gap) or 0.07
		local d = typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.1 and data.Dir.Unit or root.CFrame.LookVector
		if nearCamera(center, 120) then
			MG.lines(#pts * gap + 0.25, { Kind = "stream", Colors = { D9.CYAN, Color3.fromRGB(255, 236, 90), COWL_GREEN, Color3.new(1, 1, 1) }, Angle = -18, Alpha = 0.35 })
		end
		local prev = typeof(data.From) == "Vector3" and data.From or root.Position
		for i, p in pts do
			if typeof(p) ~= "Vector3" then
				break
			end
			DK.zig(prev + UP * 0.5, p + UP * 0.5, D9.CYAN, 0.26, 0.2, 0.9)
			DK.zig(prev + UP * 1.2, p + UP * 1.2, COWL_GREEN, 0.14, 0.16, 1.2)
			D9.ghost(char, CFrame.lookAt(p, Vector3.new(center.X, p.Y, center.Z)), i % 2 == 0 and COWL_GREEN or D9.CYAN, 0.32, 0.3)
			VFX.Pose(char, i % 2 == 0 and "BlitzKickL" or "BlitzKick", gap + 0.02)
			local away = p - center
			local hit = center + UP * rand(0.8, 2) + (away.Magnitude > 0.1 and away.Unit or -d) * 1.2
			DK.zap(hit, 0.9, D9.CYAN)
			MG.flare(hit, D9.CYAN, 1.4, 0.18)
			VFX.PlaySound("Kick", hit, 0.55)
			prev = p
			task.wait(gap)
		end
		-- then back in front of them: the big one
		local fin = typeof(data.Finish) == "Vector3" and data.Finish or center - d * 3.6
		DK.zig(prev + UP * 0.5, fin + UP * 0.5, D9.CYAN, 0.3, 0.2, 0.9)
		D9.ghost(char, CFrame.lookAt(prev, Vector3.new(center.X, prev.Y, center.Z)), Color3.new(1, 1, 1), 0.25, 0.5)
		task.wait(0.08)
		VFX.Motion(char, "StLouis")
		local hit = center + UP * 1.6
		streaks(hit - d * 1.5, d, 26, 2.2, 7, 26, D9.CYAN, 0.35)
		MG.rainbow(hit, d, 8, 0.42)
		MG.flare(hit, Color3.new(1, 1, 1), 5, 0.45)
		billboardRing(hit, 1, 18, D9.CYAN, 6, 0.3)
		MG.impact(hit, 0.08, { Radius = 100 })
		VFX.PlaySound("DekuImpact", hit, 1)
		VFX.ShakeAt(hit, 2.2, 90, 0.35)
	end

	---------------------------------------------------------------------------
	-- BLACKWHIP: COLLAPSE - the slam cracks the street with lightning
	---------------------------------------------------------------------------
	D9.bind = Effects.BlackwhipBind
	Effects.BlackwhipBind = function(char, data, ...)
		task.spawn(D9.bind, char, data, ...)
		task.delay(tonumber(data.SlamDelay) or 0.6, function()
			for _, target in type(data.Targets) == "table" and data.Targets or {} do
				local tr = typeof(target) == "Instance" and target:FindFirstChild("HumanoidRootPart")
				if tr then
					local g = groundPoint(tr.Position)
					DK.zap(g + UP, 1.4, D9.CYAN)
					for _ = 1, 5 do
						local a = rand(0, 6.28)
						DK.zig(g + UP * 0.2, groundPoint(g + Vector3.new(math.cos(a), 0, math.sin(a)) * rand(6, 12)) + UP * 0.2, COWL_GREEN, 0.2, 0.25, 1)
					end
					MG.impact(g, 0.07, { Radius = 90 })
				end
			end
		end)
	end

	---------------------------------------------------------------------------
	-- INFINITE 100%: colour streams past while the fists multiply; the finish
	-- goes black and white in a rainbow of rings
	---------------------------------------------------------------------------
	D9.catch, D9.strike, D9.finish = Effects.FistRainCatch, Effects.FistRainStrike, Effects.FistRainFinish
	Effects.FistRainCatch = function(char, data, ...)
		local at = typeof(data.At) == "Vector3" and data.At
		if at and nearCamera(at, 110) then
			task.delay(tonumber(data.RiseTime) or 0.3, function()
				MG.lines(tonumber(data.Barrage) or 1.2, { Kind = "stream", Colors = { D9.ORANGE, COWL_GREEN, Color3.fromRGB(70, 120, 255) }, Angle = -35, Alpha = 0.3, Thick = 18 })
			end)
		end
		return D9.catch(char, data, ...)
	end
	Effects.FistRainStrike = function(char, data, ...)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos
		local root = char and char:FindFirstChild("HumanoidRootPart")
		if pos and root then
			local i = tonumber(data.Index) or 1
			for k = 1, 2 do
				local from = root.Position + (pos - root.Position) * 0.35 + rng:NextUnitVector() * 1.4
				D9.fist(from, pos + rng:NextUnitVector() * 1.1, ({ D9.ORANGE, COWL_GREEN, D9.CYAN })[(i + k) % 3 + 1])
			end
		end
		return D9.strike(char, data, ...)
	end
	Effects.FistRainFinish = function(char, data, ...)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos
		if pos then
			MG.impact(pos, 0.12, { Radius = 130, Flash = 0.12 })
			MG.rainbow(pos + UP * 2, UP, 14, 0.5)
			MG.flare(pos + UP * 3, D9.CYAN, 8, 0.6)
		end
		return D9.finish(char, data, ...)
	end

	---------------------------------------------------------------------------
	-- 1,000,000% DELAWARE DETROIT SMASH: "GO... BEYOND... PLUS ULTRA!!"
	-- All Might behind him - golden, bigger than life, grinning - winding up
	-- with him, and the two of them throw it together
	---------------------------------------------------------------------------
	SHOTS.MillionSmash = {
		-- his face in the storm, then up at the two of them, then over their
		-- shoulders as it goes, then wide down the street
		{ T = 0.5, From = { V(1.2, 1.6, -3.6), V(0, 1.5, 0) }, To = { V(0.9, 1.6, -2.8), V(0, 1.6, 0) }, Fov = { 45, 38 } },
		{ T = 0.5, Cut = true, From = { V(2.6, 0.2, -7.5), V(0, 3.6, 1) }, To = { V(2, 0.5, -6.5), V(0, 4.2, 1.5) }, Fov = { 62, 56 } },
		{ T = 0.45, Cut = true, From = { V(-3.2, 3.6, 7.5), V(0, 2, -20) }, To = { V(-2.4, 3.2, 6), V(0, 2, -30) }, Fov = { 60, 70 } },
		{ T = 1.3, Cut = true, From = { V(40, 25, -40), V(0, 5, -90) }, To = { V(60, 45, -60), V(0, 5, -140) }, Fov = { 75, 80 } },
	}
	function D9.spirit()
		local model = Instance.new("Model")
		model.Name = "AllMightSpirit"
		model.Parent = folder
		local sp = { model = model, list = {}, alpha = 1, wind = 0, punch = 0 }
		local function mk(key, size, color, shape)
			local p = newPart(size * 1.9, CFrame.new(), color, Enum.Material.Neon, shape, model)
			p.Transparency = 1
			p.Name = key
			sp[key] = p
			table.insert(sp.list, p)
		end
		mk("torso", Vector3.new(2.3, 2, 1.1), D9.SPIRIT)
		mk("chest", Vector3.new(2.8, 1.1, 1.2), D9.SPIRIT)
		mk("head", Vector3.new(1.2, 1.25, 1.2), D9.SPIRIT, Enum.PartType.Ball)
		mk("hairL", Vector3.new(0.34, 1.7, 0.3), Color3.fromRGB(255, 238, 110))
		mk("hairR", Vector3.new(0.34, 1.7, 0.3), Color3.fromRGB(255, 238, 110))
		mk("armR", Vector3.new(0.95, 2.3, 0.95), D9.SPIRIT)
		mk("armL", Vector3.new(0.95, 2.3, 0.95), D9.SPIRIT)
		mk("eyes", Vector3.new(0.85, 0.1, 0.08), Color3.new(1, 1, 1))
		mk("smile", Vector3.new(0.7, 0.14, 0.08), Color3.new(1, 1, 1))
		local hl = Instance.new("Highlight")
		hl.FillColor = D9.SPIRIT
		hl.OutlineColor = Color3.new(1, 1, 1)
		hl.FillTransparency = 1
		hl.OutlineTransparency = 1
		hl.Parent = model
		sp.hl = hl
		return sp
	end
	-- where the spirit stands (behind him, towering) and how it's moving
	function D9.poseSpirit(sp, root, d)
		local S = 1.9
		local at = root.Position - d * 2.6 + UP * 3.4
		local base = CFrame.lookAt(at, at + d)
		sp.torso.CFrame = base
		sp.chest.CFrame = base * CFrame.new(0, 0.55 * S, 0)
		sp.head.CFrame = base * CFrame.new(0, 1.75 * S, -0.05 * S)
		sp.hairL.CFrame = base * CFrame.new(-0.35 * S, 2.65 * S, -0.3 * S) * CFrame.Angles(0.35, 0, math.rad(28))
		sp.hairR.CFrame = base * CFrame.new(0.35 * S, 2.65 * S, -0.3 * S) * CFrame.Angles(0.35, 0, math.rad(-28))
		sp.eyes.CFrame = base * CFrame.new(0, 1.85 * S, -0.62 * S)
		sp.smile.CFrame = base * CFrame.new(0, 1.5 * S, -0.6 * S)
		-- the right arm: back for the wind-up, then straight out past him
		local len = 2.3 * S * (1 + sp.punch * 0.9)
		sp.armR.Size = Vector3.new(0.95 * S, len, 0.95 * S)
		sp.armR.CFrame = base * CFrame.new(1.5 * S, 0.9 * S, 0) * CFrame.Angles(math.rad(-65 * sp.wind + 155 * sp.punch), 0, 0) * CFrame.new(0, -len / 2, 0)
		sp.armL.CFrame = base * CFrame.new(-1.5 * S, 0.9 * S, 0) * CFrame.Angles(math.rad(35 + 20 * sp.wind - 40 * sp.punch), 0, math.rad(-12)) * CFrame.new(0, -1.15 * S, 0)
		for _, p in sp.list do
			p.Transparency = (p == sp.eyes or p == sp.smile) and sp.alpha * 0.7 or sp.alpha
		end
		sp.hl.FillTransparency = 0.6 + 0.4 * sp.alpha
		sp.hl.OutlineTransparency = sp.alpha
	end
	Effects.MillionSmash = function(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		local C = (ability and ability.Charge) or 1.45
		local range = char:GetAttribute("UltActive") == true and 300 or ((ability and ability.Range) or 230)
		cinematicFor(char, "MillionSmash", isLocal, (ability and ability.Name) or "1,000,000% SMASH", COWL_GREEN)
		VFX.Pose(char, "CowlCrouch", C * 0.45)
		VFX.PlaySound("MillionCharge", root.Position, 1)
		D9.rings(root, C * 0.5, D9.ORANGE, 3)
		D9.pillar(root, C * 0.45, COWL_GREEN)
		DK.crackleOn(char, C, D9.CYAN)
		if isLocal then
			VFX.Hooks.Callout("GO...", Color3.new(1, 1, 1))
		end
		task.spawn(chargeFist, char, root, math.max(C - 0.45, 0.3), 1.8)
		local sp = D9.spirit()
		local t0 = os.clock()
		local beyond = false
		while os.clock() - t0 < C and root.Parent do
			local t = os.clock() - t0
			sp.alpha = 1 - 0.55 * math.clamp((t - 0.15) / 0.3, 0, 1)
			sp.wind = math.clamp((t - C * 0.5) / (C * 0.4), 0, 1)
			D9.poseSpirit(sp, root, d)
			if not beyond and t > C * 0.38 then
				beyond = true
				VFX.Pose(char, "PunchCharge", C * 0.6)
				MG.flare(sp.head.Position, D9.SPIRIT, 3, 0.4)
				if isLocal then
					VFX.Hooks.Callout("...BEYOND!", Color3.fromRGB(255, 222, 110))
				end
			end
			if rng:NextNumber() < 0.4 then
				bolt(handPos(char, true), 2.2, COWL_GREEN)
			end
			task.wait()
		end
		if not root.Parent then
			sp.model:Destroy()
			return
		end
		if isLocal then
			VFX.Hooks.Callout("PLUS ULTRA!!", Color3.fromRGB(255, 240, 150))
		end
		VFX.Motion(char, "DetroitSmash")
		-- the two of them, together
		task.spawn(function()
			local p0 = os.clock()
			while os.clock() - p0 < 0.9 and sp.model.Parent and root.Parent do
				local t = os.clock() - p0
				sp.wind = math.max(0, 1 - t / 0.06)
				sp.punch = math.clamp(t / 0.1, 0, 1)
				sp.alpha = 0.45 + 0.55 * math.clamp((t - 0.45) / 0.45, 0, 1)
				D9.poseSpirit(sp, root, d)
				task.wait()
			end
			sp.model:Destroy()
		end)
		local origin = root.Position + d * 3 + UP * 1.5
		MG.impact(origin, 0.14, { Radius = 220, Flash = 0.25, Contrast = 1.4 })
		MG.rainbow(origin, d, 16, 0.55)
		MG.flare(origin + d * 4, D9.CYAN, 10, 0.7)
		task.delay(0.12, function()
			MG.flare(origin + d * 18 + UP * 2, Color3.fromRGB(120, 140, 255), 14, 0.8)
		end)
		-- the ring it leaves glowing in the street
		local g = groundPoint(origin)
		shockDisc(g + UP * 0.3, UP, 4, 70, 1.3, D9.CYAN)
		billboardRing(g + UP, 3, 60, Color3.fromRGB(180, 230, 255), 8, 0.9)
		windBlast(origin, d, 4)
		-- the wall of wind rolling down the street
		for i = 1, 14 do
			task.delay(i * 0.04, function()
				shockDisc(origin + d * i * 6, d, 20 + i * 2, 70 + i * 3, 0.9, WIND, range - i * 6)
			end)
		end
		streaks(origin, d, 60, 18, 26, range, WIND, 0.8)
		for s = 12, range, 18 do
			task.delay(s / 300, function()
				local right = d:Cross(UP)
				for _, off in { -1, 0, 1 } do
					dustPuffs(groundPoint(origin + d * s + right * off * (12 + s * 0.1)), 2.4 + s / 90, 4, Color3.fromRGB(206, 196, 186), 1.6, true)
				end
				if s % 36 == 12 then
					rocks(groundPoint(origin + d * s), 2, 6)
				end
			end)
		end
		VFX.PlaySound("MillionSmash", origin, 1.6)
		VFX.PlaySound("DetroitImpact", origin, 1.5)
		VFX.ShakeAt(origin, 6, 400, 1.2)
	end
end

---------------------------------------------------------------------------
-- MORE EMOTES: KAMEHAMEHA (Dragon Ball Z: cup it at the hip - KA... ME...
-- HA... ME... - and HA!!, a beam down the street), DUBIOUS FOOD (Breath of
-- the Wild: squat by the pot on the campfire, toss the ingredients in, they
-- hop about in it the way they do, poof - and hold up what came out, the
-- item jingle and all), HERO LANDING (up out of sight and back down in a
-- three-point landing that cracks the street), T-POSE (asserting dominance,
-- slowly revolving), THE GRIDDY, NAP (a snot bubble that grows till it pops
-- and wakes him) and FAKE DEATH (he dies; his soul floats up; it's sucked
-- back in; "JK!!"). The props are each client's own and go the moment the
-- emote is broken off.
---------------------------------------------------------------------------
do
	local EM = { props = {} }
	VFX.EMOTES = EM
	-- still going? (the same checks that break the emote off)
	function EM.alive(char, token, root)
		if poseTokens[char] ~= token or not root.Parent then
			return false
		end
		local v = root.AssemblyLinearVelocity
		return not (Vector3.new(v.X, 0, v.Z).Magnitude > 4 or math.abs(v.Y) > 12 or char:GetAttribute("Stunned") or char:GetAttribute("Ragdolled"))
	end
	-- a word over his head (a BillboardGui), rising and fading
	function EM.label(root, text, color, size, life, rise)
		local anchor = newPart(Vector3.one * 0.1, CFrame.new(root.Position + UP * 4), Color3.new(), nil, nil)
		anchor.Transparency = 1
		local bb = Instance.new("BillboardGui")
		bb.Size = UDim2.fromOffset(260, 60)
		bb.StudsOffsetWorldSpace = Vector3.zero
		bb.MaxDistance = 90
		bb.LightInfluence = 0
		bb.Parent = anchor
		local t = Instance.new("TextLabel")
		t.Size = UDim2.fromScale(1, 1)
		t.BackgroundTransparency = 1
		t.Font = Enum.Font.GothamBlack
		t.TextSize = size or 26
		t.TextColor3 = color or Color3.new(1, 1, 1)
		t.TextStrokeTransparency = 0
		t.Text = text
		t.Parent = bb
		tween(anchor, life or 1, { CFrame = CFrame.new(root.Position + UP * (4 + (rise or 1.5))) })
		tween(t, 0.3, { TextTransparency = 1, TextStrokeTransparency = 1 }, nil, nil, (life or 1) - 0.3)
		cleanup(anchor, (life or 1) + 0.05)
		return anchor
	end
	-- the props for one run of an emote: gone together
	function EM.bag()
		local model = Instance.new("Model")
		model.Name = "EmoteProps"
		model.Parent = folder
		return model
	end
	local function part(model, size, cf, color, material, shape)
		local p = newPart(size, cf, color, material or Enum.Material.SmoothPlastic, shape, model)
		p.Name = "EmoteProp"
		return p
	end
	EM.part = part

	---------------------------------------------------------------------------
	-- KAMEHAMEHA
	---------------------------------------------------------------------------
	POSES.KameCup = { RightArm = { -35, 0, 12 }, RightElbow = 95, LeftArm = { -5, 0, -38 }, LeftElbow = 105, Waist = { -4, -42, 0 }, Neck = { 0, 38, 0 }, RightLeg = -22, LeftLeg = 26, RightKnee = 30, LeftKnee = 38, Crouch = 0.55 }
	POSES.KameFire = { RightArm = { 90, 0, -8 }, LeftArm = { 90, 0, -8 }, RightElbow = 0, LeftElbow = 0, Waist = { -8, 0, 0 }, Neck = { -4, 0, 0 }, RightLeg = -24, LeftLeg = 30, RightKnee = 20, LeftKnee = 40, Crouch = 0.4 }
	MOTIONS.EmoteKamehameha = { { pose = "KameCup", t = 0.25, hold = 1.9 }, { pose = "KameFire", t = 0.07, hold = 1.35, style = SNAP }, recover = 0.35 }
	EM.props.Kamehameha = function(char, token, root)
		local bag = EM.bag()
		local ball = part(bag, Vector3.one * 0.2, root.CFrame, Color3.fromRGB(110, 200, 255), Enum.Material.Neon, Enum.PartType.Ball)
		ball.Transparency = 0.25
		local core = part(bag, Vector3.one * 0.1, root.CFrame, Color3.new(1, 1, 1), Enum.Material.Neon, Enum.PartType.Ball)
		local light = Instance.new("PointLight")
		light.Color = Color3.fromRGB(110, 200, 255)
		light.Range = 12
		light.Parent = ball
		local words = { { 0.1, "KA..." }, { 0.5, "ME..." }, { 0.9, "HA..." }, { 1.35, "ME..." }, { 2.15, "HA!!!" } }
		local w = 1
		VFX.PlaySound("BlastCharge", root.Position, 0.8)
		local t0 = os.clock()
		while os.clock() - t0 < 2.15 and EM.alive(char, token, root) do
			local t = os.clock() - t0
			if words[w] and t >= words[w][1] then
				VFX.SpeechBubble(char, words[w][2], 0.45)
				w += 1
			end
			local at = (handPos(char, true) + handPos(char, false)) / 2
			local s = 0.3 + 1.4 * math.clamp(t / 2, 0, 1) * (0.9 + 0.2 * math.sin(t * 40))
			ball.Size, core.Size = Vector3.one * s, Vector3.one * s * 0.55
			ball.CFrame, core.CFrame = CFrame.new(at), CFrame.new(at)
			light.Brightness = 1 + t * 2
			if rng:NextNumber() < 0.35 then
				VFX.DK.arc(at, at + rng:NextUnitVector() * s * 1.2, Color3.fromRGB(110, 200, 255), 0.05)
			end
			task.wait()
		end
		if not EM.alive(char, token, root) then
			bag:Destroy()
			return
		end
		VFX.SpeechBubble(char, "HA!!!", 0.9)
		-- HA!! : the beam, straight down the street
		local look = Vector3.new(root.CFrame.LookVector.X, 0, root.CFrame.LookVector.Z).Unit
		local from = (handPos(char, true) + handPos(char, false)) / 2 + look * 0.6
		ball:Destroy()
		core:Destroy()
		local outer = part(bag, Vector3.new(3.2, 3.2, 0.2), CFrame.lookAt(from, from + look), Color3.fromRGB(100, 190, 255), Enum.Material.Neon, Enum.PartType.Cylinder)
		outer.Transparency = 0.3
		local inner = part(bag, Vector3.new(1.6, 1.6, 0.2), CFrame.lookAt(from, from + look), Color3.new(1, 1, 1), Enum.Material.Neon, Enum.PartType.Cylinder)
		local cap = part(bag, Vector3.one * 3.6, CFrame.new(from), Color3.fromRGB(150, 220, 255), Enum.Material.Neon, Enum.PartType.Ball)
		cap.Transparency = 0.2
		shockDisc(from, look, 2, 12, 0.3, Color3.fromRGB(150, 220, 255))
		streaks(from, look, 24, 2, 8, 60, Color3.fromRGB(160, 225, 255), 0.6)
		VFX.PlaySound("Beam", from, 1)
		VFX.ShakeAt(from, 1.4, 60, 0.9)
		local b0 = os.clock()
		while os.clock() - b0 < 1.25 and EM.alive(char, token, root) do
			local t = os.clock() - b0
			local len = 70 * math.min(t / 0.15, 1)
			local thick = (t > 1 and (1.25 - t) / 0.25 or 1) * (0.9 + 0.12 * math.sin(t * 50))
			-- (a cylinder lies along its X: turned to run down the look)
			local mid = from + look * len / 2
			local cf = CFrame.lookAt(mid, mid + look) * CFrame.Angles(0, math.pi / 2, 0)
			outer.Size, outer.CFrame = Vector3.new(len, 3.2 * thick, 3.2 * thick), cf
			inner.Size, inner.CFrame = Vector3.new(len, 1.5 * thick, 1.5 * thick), cf
			cap.CFrame = CFrame.new(from + look * len)
			cap.Size = Vector3.one * 3.8 * thick
			task.wait()
		end
		bag:Destroy()
	end

	---------------------------------------------------------------------------
	-- DUBIOUS FOOD (the cooking pot)
	---------------------------------------------------------------------------
	POSES.CookSquat = { Hips = { 0, 0, 0, 0, -1.3, 0 }, RightLeg = 80, LeftLeg = 80, RightKnee = 120, LeftKnee = 120, RightArm = { 38, 0, 18 }, LeftArm = { 38, 0, 18 }, RightElbow = 60, LeftElbow = 60, Waist = { -16, 0, 0 }, Neck = { -24, 0, 0 } }
	POSES.CookToss = { Hips = { 0, 0, 0, 0, -1.3, 0 }, RightLeg = 80, LeftLeg = 80, RightKnee = 120, LeftKnee = 120, RightArm = { 70, 0, 8 }, LeftArm = { 30, 0, 18 }, RightElbow = 20, LeftElbow = 60, Waist = { -12, 10, 0 }, Neck = { -18, 0, 0 } }
	POSES.ItemGet = { RightArm = { 172, 0, 12 }, LeftArm = { 172, 0, 12 }, RightElbow = 12, LeftElbow = 12, Waist = { 6, 0, 0 }, Neck = { 30, 0, 0 } }
	MOTIONS.EmoteDubiousFood = {
		{ pose = "CookSquat", t = 0.3, hold = 0.2 },
		{ pose = "CookToss", t = 0.12, hold = 0.25 }, { pose = "CookSquat", t = 0.12, hold = 0.1 },
		{ pose = "CookToss", t = 0.12, hold = 0.25 }, { pose = "CookSquat", t = 0.12, hold = 0.1 },
		{ pose = "CookToss", t = 0.12, hold = 0.25 }, { pose = "CookSquat", t = 0.12, hold = 1.85 },
		{ pose = "ItemGet", t = 0.22, hold = 2.2, style = SNAP },
		recover = 0.35,
	}
	-- the three things he puts in: an apple, a mushroom, a hunk of meat
	function EM.ingredient(bag, kind, at)
		local m = Instance.new("Model")
		m.Parent = bag
		local pieces = {}
		if kind == 1 then
			table.insert(pieces, { part(m, Vector3.one * 0.62, CFrame.new(at), Color3.fromRGB(214, 36, 40), nil, Enum.PartType.Ball), CFrame.new() })
			table.insert(pieces, { part(m, Vector3.new(0.08, 0.26, 0.08), CFrame.new(at), Color3.fromRGB(90, 60, 30)), CFrame.new(0, 0.34, 0) })
			table.insert(pieces, { part(m, Vector3.new(0.24, 0.06, 0.14), CFrame.new(at), Color3.fromRGB(70, 170, 60)), CFrame.new(0.12, 0.38, 0) })
		elseif kind == 2 then
			table.insert(pieces, { part(m, Vector3.new(0.26, 0.42, 0.26), CFrame.new(at), Color3.fromRGB(240, 232, 214), nil, Enum.PartType.Cylinder), CFrame.Angles(0, 0, math.pi / 2) })
			table.insert(pieces, { part(m, Vector3.new(0.72, 0.32, 0.72), CFrame.new(at), Color3.fromRGB(206, 48, 44), nil, Enum.PartType.Ball), CFrame.new(0, 0.28, 0) })
			table.insert(pieces, { part(m, Vector3.one * 0.12, CFrame.new(at), Color3.new(1, 1, 1), nil, Enum.PartType.Ball), CFrame.new(0.16, 0.42, 0.1) })
		else
			table.insert(pieces, { part(m, Vector3.new(0.7, 0.44, 0.5), CFrame.new(at), Color3.fromRGB(150, 60, 50)), CFrame.new() })
			table.insert(pieces, { part(m, Vector3.new(0.5, 0.12, 0.12), CFrame.new(at), Color3.fromRGB(244, 238, 226), nil, Enum.PartType.Cylinder), CFrame.new(0.5, 0, 0) })
		end
		return function(cf)
			for _, pc in pieces do
				pc[1].CFrame = cf * pc[2]
			end
		end
	end
	EM.props.DubiousFood = function(char, token, root)
		local bag = EM.bag()
		local look = Vector3.new(root.CFrame.LookVector.X, 0, root.CFrame.LookVector.Z).Unit
		local g = groundPoint(root.Position + look * 2.6)
		-- the pot on its fire
		local pot = part(bag, Vector3.new(1.1, 1.5, 1.5), CFrame.new(g + UP * 1.05) * CFrame.Angles(0, 0, math.pi / 2), Color3.fromRGB(40, 40, 44), Enum.Material.Metal, Enum.PartType.Cylinder)
		part(bag, Vector3.new(0.14, 1.7, 1.7), CFrame.new(g + UP * 1.62) * CFrame.Angles(0, 0, math.pi / 2), Color3.fromRGB(60, 60, 66), Enum.Material.Metal, Enum.PartType.Cylinder)
		local stew = part(bag, Vector3.new(0.05, 1.35, 1.35), CFrame.new(g + UP * 1.56) * CFrame.Angles(0, 0, math.pi / 2), Color3.fromRGB(150, 110, 60), nil, Enum.PartType.Cylinder)
		for _, side in { -1, 1 } do
			part(bag, Vector3.new(0.12, 0.3, 0.3), CFrame.new(g + UP * 1.4 + look:Cross(UP) * side * 0.85), Color3.fromRGB(60, 60, 66), Enum.Material.Metal)
		end
		for i = 1, 3 do
			local a = i / 3 * math.pi * 2
			part(bag, Vector3.new(1.2, 0.2, 0.2), CFrame.new(g + UP * 0.12) * CFrame.Angles(0, a, 0.15), Color3.fromRGB(110, 70, 40), Enum.Material.Wood, Enum.PartType.Cylinder)
		end
		local fire = VFX.BLAZE and VFX.BLAZE.flame({ CF = CFrame.new(g + UP * 0.15), Pal = "hell", Height = 1.1, Width = 1, Tongues = 4, Volume = 0.3, Light = 8, Grow = 0.2 })
		local potBase = pot.CFrame
		local items = {}
		local function done()
			if fire then
				fire.kill(0.3)
			end
			bag:Destroy()
		end
		-- the tosses (on the motion's beats) into the pot
		for i = 1, 3 do
			local toss = 0.5 + (i - 1) * 0.47
			task.delay(toss, function()
				if not EM.alive(char, token, root) then
					return
				end
				local from = handPos(char, true)
				local place = EM.ingredient(bag, i, from)
				local into = g + UP * 1.7 + Vector3.new(rand(-0.3, 0.3), 0, rand(-0.3, 0.3))
				local t0 = os.clock()
				while os.clock() - t0 < 0.35 and bag.Parent do
					local a = (os.clock() - t0) / 0.35
					place(CFrame.new(from:Lerp(into, a) + UP * math.sin(a * math.pi) * 1.6) * CFrame.Angles(a * 6, a * 4, 0))
					task.wait()
				end
				items[i] = { place = place, at = into }
				VFX.PlaySound("Boing", into, 0.35)
			end)
		end
		-- then they hop about in it (that bounce), the pot jiggling, steam
		local t0 = os.clock()
		while os.clock() - t0 < 3.7 do
			if not EM.alive(char, token, root) then
				done()
				return
			end
			local t = os.clock() - t0
			if t > 1.9 then
				local beat = (t - 1.9) * 4
				for i, it in items do
					local ph = (beat + i / 3) % 1
					it.place(CFrame.new(it.at + UP * (math.sin(ph * math.pi) * 1.4)) * CFrame.Angles(beat * 2 + i, beat * 3, 0))
				end
				local j = 1 + 0.06 * math.abs(math.sin(beat * math.pi))
				pot.Size = Vector3.new(1.1 * j, 1.5 / j, 1.5 / j)
				pot.CFrame = potBase
				if math.floor(beat) ~= math.floor(beat - 0.05) then
					VFX.PlaySound("Boing", g, 0.25)
					smokeBurst(g + UP * 2, Color3.fromRGB(240, 240, 240), 0.5, 0.6, 0.6, 2)
				end
			end
			task.wait()
		end
		-- poof: what came out of it
		smokeBurst(g + UP * 1.8, Color3.fromRGB(140, 110, 160), 1.3, 1.5, 0.8, 8)
		VFX.PlaySound("HairPoof", g, 0.8)
		for _, it in items do
			it.place(CFrame.new(0, -500, 0))
		end
		stew.Color = Color3.fromRGB(110, 90, 120)
		local dish = Instance.new("Model")
		dish.Parent = bag
		local plate = part(dish, Vector3.new(0.08, 1.4, 1.4), CFrame.new(), Color3.fromRGB(236, 232, 222), nil, Enum.PartType.Cylinder)
		local lumps = {}
		for i = 1, 4 do
			table.insert(lumps, { part(dish, Vector3.one * rand(0.4, 0.62), CFrame.new(), Color3.fromRGB(120, 100, 128), Enum.Material.Slate, Enum.PartType.Ball), Vector3.new(rand(-0.3, 0.3), 0.18 + i * 0.05, rand(-0.3, 0.3)) })
		end
		local stink = {}
		for i = 1, 3 do
			stink[i] = part(dish, Vector3.new(0.06, 0.7, 0.06), CFrame.new(), Color3.fromRGB(120, 200, 90), Enum.Material.Neon)
		end
		VFX.PlaySound("RankUp", root.Position, 0.9)
		sparks(root.Position + UP * 4, 1.2, Color3.new(1, 1, 1), Color3.fromRGB(255, 230, 120), 20)
		-- the item box
		EM.label(root, "Dubious Food", Color3.new(1, 1, 1), 26, 2.4, 0.2)
		EM.label(root, "Hard to say what this is. Technically edible.", Color3.fromRGB(210, 210, 210), 13, 2.4, -0.35)
		local d0 = os.clock()
		while os.clock() - d0 < 2.3 and EM.alive(char, token, root) do
			local t = os.clock() - d0
			local at = (handPos(char, true) + handPos(char, false)) / 2 + UP * 0.2
			plate.CFrame = CFrame.new(at) * CFrame.Angles(0, 0, math.pi / 2)
			for _, l in lumps do
				l[1].CFrame = CFrame.new(at + l[2])
			end
			for i, s in stink do
				s.CFrame = CFrame.new(at + Vector3.new((i - 2) * 0.3 + math.sin(t * 6 + i) * 0.1, 0.9 + (t * 0.8 + i * 0.3) % 1, 0)) * CFrame.Angles(0, 0, math.sin(t * 8 + i) * 0.4)
			end
			task.wait()
		end
		done()
	end

