	POSES.LandFly = { Hips = { 0, 0, 0, 0, 42, 0 }, RightArm = { 170, 0, 10 }, LeftArm = { 20, 0, 30 }, RightLeg = 20, LeftLeg = -10, RightKnee = 40, LeftKnee = 20 }
	POSES.LandThreePoint = { Hips = { -20, 0, 0, 0, -1.2, -0.3 }, RightLeg = 85, RightKnee = 110, LeftLeg = -25, LeftKnee = 110, RightArm = { -30, 0, 60 }, LeftArm = { 75, 0, 0 }, Waist = { -32, 0, 0 }, Neck = { -12, 0, 0 } }
	POSES.LandRise = { Hips = { -6, 0, 0, 0, -0.4, 0 }, RightLeg = 30, RightKnee = 40, LeftLeg = -10, LeftKnee = 30, RightArm = { 10, 0, 25 }, LeftArm = { 10, 0, 25 }, Waist = { -6, 0, 0 }, Neck = { 12, 0, 0 } }
	MOTIONS.EmoteHeroLanding = {
		{ pose = "LandSquat", t = 0.12, hold = 0.12 },
		{ pose = "LandFly", t = 0.28, hold = 0.35, style = Enum.EasingStyle.Quad },
		{ pose = "LandThreePoint", t = 0.1, hold = 1.3, style = SNAP },
		{ pose = "LandRise", t = 0.6, hold = 0.45 },
		recover = 0.4,
	}
	EM.props.HeroLanding = function(char, token, root)
		task.wait(0.24)
		if not EM.alive(char, token, root) then
			return
		end
		local g = groundPoint(root.Position)
		dustPuffs(g, 1, 6, Color3.fromRGB(200, 192, 180), 0.8, true)
		streaks(g, UP, 12, 1.2, 6, 30, Color3.new(1, 1, 1), 0.4)
		VFX.PlaySound("Leap", g, 1)
		task.wait(0.73)
		if not EM.alive(char, token, root) then
			return
		end
		-- the landing
		g = groundPoint(root.Position)
		rocks(g, 1.6, 10)
		shockDisc(g + UP * 0.4, UP, 3, 34, 0.5, Color3.fromRGB(230, 226, 214))
		billboardRing(g + UP, 2, 26, Color3.new(1, 1, 1), 6, 0.35)
		for i = 1, 6 do
			local a = i / 6 * math.pi * 2 + rand(-0.3, 0.3)
			local out = Vector3.new(math.cos(a), 0, math.sin(a))
			local len = rand(4, 7)
			local crack = newPart(Vector3.new(0.22, 0.06, len), CFrame.lookAt(g + out * len / 2 + UP * 0.04, g + out * len + UP * 0.04), Color3.fromRGB(34, 30, 28))
			crack.Name = "EmoteProp"
			tween(crack, 0.6, { Transparency = 1 }, nil, nil, 2.2)
			cleanup(crack, 2.9)
		end
		for _, off in { -1, 0, 1 } do
			dustPuffs(g + Vector3.new(off * 2.5, 0, 0), 1.2, 3, Color3.fromRGB(206, 196, 186), 1.4, true)
		end
		VFX.MANGA.impact(g, 0.07, { Radius = 60 })
		VFX.PlaySound("ColoradoImpact", g, 0.9)
		VFX.ShakeAt(g, 3, 70, 0.45)
	end

