	-- every M1 leaves the weapon's mark (Config.M1.Styles: "Weapon"): the
	-- blade's thin arc, the staff's wide sweep, the spear's straight line (a
	-- crescent for its low sweep). The swing's sound came with the swing
	-- (VFX.WeaponKit); the 4th hit gets its own finish.
	-- [weapon][hit] = { roll of the arc (degrees), its radius, height }
	YM.ARCS = {
		Sword = { { 125, 4.2, 0.7 }, { -55, 4.2, 0.7 }, { 95, 4.6, 0.5 }, { 0, 5, 0.6 } },
		Staff = { { 100, 5.4, 0.6 }, { -80, 5.4, 0.6 }, { 180, 5, 0.4 }, { 0, 5.6, 0.6 } },
		Spear = { [3] = { 95, 6.2, -0.9 } },
	}
	function VFX.CreationPunch(char, count, finisher, fist, look)
		local root = charParts(char)
		if not root then
			return
		end
		local weapon = VFX.WeaponOf(char)
		local d = Vector3.new(look.X, 0, look.Z)
		d = d.Magnitude > 0.1 and d.Unit or UP
		local arc = YM.ARCS[weapon or "Staff"][count]
		if arc then
			local color = weapon == "Staff" and YM.GOLD or YM.STEEL
			crescent(root.Position + d * 1.5 + UP * arc[3], d, math.rad(arc[1]), arc[2] * (finisher and 1.15 or 1), finisher and 0.9 or (weapon == "Staff" and 0.75 or 0.5), finisher and 7 or 3, finisher and 0.3 or 0.2, color)
		else
			-- a thrust: the point's line, straight out
			local from = root.Position + UP * 0.5 + d * 2
			streaks(from, d, finisher and 8 or 5, 0.35, finisher and 5 or 3.5, finisher and 13 or 8, YM.STEEL, 0.14)
			shockDisc(from + d * (finisher and 6 or 4.5), d, 0.5, finisher and 5 or 3, 0.15, YM.GLOW_HOT, 2)
		end
		sparks(fist, finisher and 0.7 or 0.35, Color3.new(1, 1, 1), YM.GLOW, finisher and 8 or 3)
		if not weapon then
			VFX.PlaySound(finisher and "WeaponHit" or "WeaponSwing", fist, finisher and 1 or 0.7)
		end
		if not finisher then
			return
		end
		if weapon == "Staff" then
			-- the slam into the street
			local g = groundPoint(root.Position + d * 4)
			if (g - (root.Position + d * 4)).Magnitude < 7 then
				dustPuffs(g, 1, 6, Color3.fromRGB(205, 196, 190), 0.7, false)
				shockDisc(g + UP * 0.3, UP, 2, 14, 0.3, YM.GLOW_HOT, 0)
				VFX.ShakeAt(g, 1, 35, 0.18)
			end
			VFX.PlaySound("StaffSlam", g, 1)
		elseif weapon == "Spear" then
			-- the point punches a line through the air
			local from = root.Position + UP * 0.5 + d * 3
			local line = newPart(Vector3.new(0.1, 0.1, 10), CFrame.lookAt(from + d * 5, from + d * 10), Color3.new(1, 1, 1), Enum.Material.Neon)
			tween(line, 0.06, { Size = Vector3.new(0.4, 0.4, 14) })
			tween(line, 0.25, { Size = Vector3.new(0.05, 0.05, 16), Transparency = 1 }, nil, nil, 0.06)
			cleanup(line, 0.35)
			shockDisc(from + d * 8, d, 1, 8, 0.2, YM.GLOW_HOT, 4)
		else
			shockDisc(fist + d, d, 1.5, 12, 0.25, YM.GLOW_HOT, 4)
			VFX.PlaySound("SwordRing", fist, 0.7)
		end
	end

	---------------------------------------------------------------------------
	-- R: CREATE - the next weapon grows out of her hand
	function Effects.CreateWeapon(char)
		local root = charParts(char)
		if not root then
			return
		end
		VFX.Pose(char, "CreateDraw", 0.35)
		YM.glow(handPos(char, true), 1)
		VFX.PlaySound("Create", root.Position, 1)
		local gear = char:FindFirstChild("QuirkGear")
		local before = gear and gear:FindFirstChild("CreatedWeapon")
		task.spawn(function()
			local t0 = os.clock()
			while os.clock() - t0 < 1.5 and char.Parent do
				local g = char:FindFirstChild("QuirkGear")
				local now = g and g:FindFirstChild("CreatedWeapon")
				if now and now ~= before then
					YM.emerge(now:GetChildren(), 0.3, now)
					-- (round 62) and it sounds like what it is
					local w = now:GetAttribute("Weapon")
					VFX.PlaySound((w == "Sword" and "SwordDraw") or (w == "Spear" and "SpearHeavy") or "StaffHeavy", root.Position, 0.8)
					return
				end
				task.wait(0.05)
			end
		end)
	end

	-- 1: MATRYOSHKA FLASH - the dolls out of her palm and thrown in a fan; each
	-- goes off where the server says it stopped (MatryoshkaPop)
	function Effects.MatryoshkaFlash(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or (Config.FindAbilityById and Config.FindAbilityById("MatryoshkaFlash")) or {}
		local flat = flatten(data.Dir, root).Unit
		if isLocal then
			face(root, flat)
		end
		VFX.Motion(char, "MatryoshkaThrow")
		YM.glow(handPos(char, true), 0.8)
		VFX.PlaySound("Create", root.Position, 0.8)
		task.wait(0.18)
		if not root.Parent then
			return
		end
		local d = Config.AimedDirection(typeof(data.Dir) == "Vector3" and data.Dir or flat, flat, { Up = 30, Down = 30 })
		local origin = root.Position + UP * 1.2
		local n, range, speed = ability.Dolls or 3, ability.Range or 46, ability.Speed or 95
		local list = {}
		YM.dolls[char] = list
		VFX.PlaySound("WeaponSwing", origin, 0.6)
		for i = 1, n do
			local di = CFrame.fromAxisAngle(UP, math.rad(((i - 1) - (n - 1) / 2) * (ability.Spread or 13))):VectorToWorldSpace(d)
			local hit = workspace:Raycast(origin, di * range, YM.mapParams())
			local reach = hit and hit.Distance or range
			local doll = YM.doll(CFrame.new(origin), 0.55)
			list[i] = doll
			task.spawn(function()
				local t0 = os.clock()
				local spin = 0
				while doll.model.Parent and not doll.popped do
					local t = os.clock() - t0
					local s = math.min(t * speed, reach)
					spin += 0.4
					doll.set(CFrame.new(origin + di * s + UP * math.sin(math.clamp(s / math.max(reach, 1), 0, 1) * math.pi) * 1.2) * CFrame.Angles(spin, 0, spin * 0.5))
					if s >= reach then
						break
					end
					RunService.Heartbeat:Wait()
				end
				-- (never told where it went off: it goes off where it stopped)
				task.wait(0.35)
				if doll.model.Parent and not doll.popped then
					doll.popped = true
					local at = doll.base.Position
					doll.model:Destroy()
					YM.flashbang(at, di)
				end
			end)
		end
	end
	function Effects.MatryoshkaPop(char, data)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos
		if not pos then
			return
		end
		local list = char and YM.dolls[char]
		local doll = list and list[tonumber(data.Index) or 0]
		if doll then
			if doll.popped then
				return
			end
			doll.popped = true
			doll.model:Destroy()
		end
		YM.flashbang(pos)
	end

	-- 2: UNFALLING CASTLE WALL - the tower shield out of her forearm, held up
	-- in front of her for as long as she holds it ("Shielding")
	function YM.armShield(char)
		local arm = limb(char, "LeftHand", "Left Arm")
		if not arm or YM.shields[char] then
			return YM.shields[char]
		end
		local m = Instance.new("Model")
		m.Name = "CreatiShield"
		m.Parent = folder
		local parts = {}
		local function piece(size, offset, color, material)
			local p = newPart(size, arm.CFrame * offset, color, material or Enum.Material.Metal, nil, m)
			YM.attach(arm, p, offset)
			table.insert(parts, p)
			return p
		end
		local y = arm.Name == "Left Arm" and -arm.Size.Y / 2 - 0.2 or -0.3
		piece(Vector3.new(3.2, 0.25, 4.2), CFrame.new(0, y, 0), YM.STEEL)
		piece(Vector3.new(3.4, 0.3, 0.3), CFrame.new(0, y, 2.1), YM.GOLD)
		piece(Vector3.new(3.4, 0.3, 0.3), CFrame.new(0, y, -2.1), YM.GOLD)
		piece(Vector3.new(0.3, 0.3, 4.4), CFrame.new(1.6, y, 0), YM.GOLD)
		piece(Vector3.new(0.3, 0.3, 4.4), CFrame.new(-1.6, y, 0), YM.GOLD)
		piece(Vector3.new(0.35, 0.34, 2.6), CFrame.new(0, y - 0.06, 0), YM.RED, Enum.Material.SmoothPlastic)
		piece(Vector3.new(2, 0.34, 0.35), CFrame.new(0, y - 0.06, -0.4), YM.RED, Enum.Material.SmoothPlastic)
		YM.emerge(parts, 0.22, m)
		YM.shields[char] = m
		return m
	end
	function YM.dropShield(char, fade)
		local m = YM.shields[char]
		YM.shields[char] = nil
		if not m then
			return
		end
		for _, p in m:GetChildren() do
			if p:IsA("BasePart") then
				tween(p, fade or 0.25, { Transparency = 1, Size = p.Size * 0.7 })
			end
		end
		cleanup(m, (fade or 0.25) + 0.05)
	end
	function Effects.CastleWall(char, _data, _isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or (Config.FindAbilityById and Config.FindAbilityById("CastleWall")) or {}
		local max = (ability.Hold and ability.Hold.Max) or 3
		YM.armShield(char)
		YM.glow(handPos(char, false), 1)
		VFX.PlaySound("Create", root.Position, 1)
		VFX.Pose(char, "ShieldUp", max + 0.5)
		task.spawn(function()
			local t0 = os.clock()
			-- (the server's "Shielding" gets here a moment later; then held for as
			-- long as it's there)
			while char.Parent and os.clock() - t0 < 0.6 and not char:GetAttribute("Shielding") do
				task.wait(0.03)
			end
			while char.Parent and char:GetAttribute("Shielding") and os.clock() - t0 < max + 1 do
				task.wait(0.03)
			end
			task.wait(0.05)
			if YM.shields[char] and not YM.bashing[char] then
				YM.dropShield(char)
				VFX.ReleasePose(char, 0.2)
			end
		end)
	end
	-- a tap: the shield planted - the real wall is the server's; this is it
	-- coming into being
	function Effects.CastleWallPlant(char, data)
		local cf, size = typeof(data.CF) == "CFrame" and data.CF, typeof(data.Size) == "Vector3" and data.Size
		if not cf or not size then
			return
		end
		if char then
			YM.dropShield(char, 0.15)
			VFX.Pose(char, "ShieldPlant", 0.4)
		end
		local plate = newPart(size + Vector3.new(0.4, 0.4, 0.4), cf, YM.GLOW, Enum.Material.Neon)
		plate.Transparency = 0.2
		tween(plate, 0.45, { Transparency = 1, Size = size + Vector3.new(1.5, 1.5, 0.6) })
		cleanup(plate, 0.5)
		local w, h = size.X / 2, size.Y / 2
		for _, e in { { Vector3.new(size.X, 0.2, 0.2), CFrame.new(0, h, -0.7) }, { Vector3.new(size.X, 0.2, 0.2), CFrame.new(0, -h, -0.7) },
			{ Vector3.new(0.2, size.Y, 0.2), CFrame.new(w, 0, -0.7) }, { Vector3.new(0.2, size.Y, 0.2), CFrame.new(-w, 0, -0.7) } } do
			local edge = newPart(e[1], cf * e[2], YM.GLOW_HOT, Enum.Material.Neon)
			tween(edge, 0.5, { Transparency = 1 })
			cleanup(edge, 0.55)
		end
		for _ = 1, 8 do
			sparks((cf * CFrame.new(rand(-w, w), rand(-h, h), -0.7)).Position, 0.4, YM.GLOW_HOT, YM.GOLD, 3)
		end
		dustPuffs(cf.Position - UP * h, 0.9, 6, Color3.fromRGB(205, 196, 190), 0.8, false)
		VFX.PlaySound("CreateBig", cf.Position, 1)
		VFX.ShakeAt(cf.Position, 0.8, 40, 0.2)
	end
	-- something hit the wall (and not whoever was behind it)
	function Effects.CastleWallHit(_, data)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos
		if not pos then
			return
		end
		local cf = typeof(data.CF) == "CFrame" and data.CF or CFrame.new(pos)
		sparks(pos, 0.7, Color3.new(1, 1, 1), YM.GOLD, 8)
		shockDisc(pos, -cf.LookVector, 1, 6, 0.18, YM.STEEL, 1)
		VFX.PlaySound("ShieldBlock", pos, 1)
	end
	-- broken (or its time's up and it melts back to nothing)
	function Effects.CastleWallBreak(_, data)
		local cf, size = typeof(data.CF) == "CFrame" and data.CF, typeof(data.Size) == "Vector3" and data.Size
		if not cf or not size then
			return
		end
		if data.Broken then
			for _ = 1, 14 do
				local at = cf * CFrame.new(rand(-size.X / 2, size.X / 2), rand(-size.Y / 2, size.Y / 2), 0)
				local shard = newPart(Vector3.new(rand(0.8, 2), rand(0.8, 2), 0.3), at, YM.STEEL, Enum.Material.Metal)
				local fly = at.Position + (cf.LookVector * rand(-1, 1) + rng:NextUnitVector() * 0.6) * rand(3, 8) - UP * rand(2, size.Y / 2 + 2)
				tween(shard, 0.6, { CFrame = CFrame.new(fly) * CFrame.Angles(rand(-3, 3), rand(-3, 3), rand(-3, 3)), Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
				cleanup(shard, 0.65)
			end
			VFX.PlaySound("WallBreak", cf.Position, 1)
			VFX.ShakeAt(cf.Position, 1, 40, 0.2)
		else
			for _ = 1, 10 do
				sparks((cf * CFrame.new(rand(-size.X / 2, size.X / 2), rand(-size.Y / 2, size.Y / 2), 0)).Position, 0.4, YM.GLOW_HOT, YM.GLOW, 3)
			end
		end
	end
	-- let go after holding it: she drives the shield forward
	function Effects.ShieldBash(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root).Unit
		local time = tonumber(data.Time) or 0.22
		local dist = tonumber(data.Dist) or 14
		YM.bashing[char] = true
		YM.armShield(char)
		VFX.Pose(char, "ShieldBash", time + 0.25)
		VFX.PlaySound("HeavySwing", root.Position, 1)
		if Players.LocalPlayer and char == Players.LocalPlayer.Character then
			face(root, d)
			dash(root, d * (dist / time), time)
		end
		streaks(root.Position, d, 8, 2, 4, 10, YM.STEEL, 0.25)
		task.delay(time, function()
			YM.bashing[char] = nil
			local r = charParts(char)
			if r then
				shockDisc(r.Position + d * 3, d, 2, 12, 0.25, YM.GOLD, 3)
				dustPuffs(r.Position - UP * 2.5 + d * 2, 0.8, 5, Color3.fromRGB(205, 196, 190), 0.7, false)
			end
			task.wait(0.2)
			YM.dropShield(char)
			VFX.ReleasePose(char, 0.2)
		end)
	end
	-- a hit from in front, on the shield she's holding up
	function Effects.ShieldBlock(char, data)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos
		if not pos then
			return
		end
		sparks(pos, 0.8, Color3.new(1, 1, 1), YM.GOLD, 9)
		billboardRing(pos, 1, 7, YM.GOLD, 4, 0.2)
		VFX.PlaySound("ShieldBlock", pos, 1)
		local root = char and charParts(char)
		if root then
			shockDisc(pos, root.CFrame.LookVector, 1, 6, 0.18, YM.STEEL, 1)
		end
	end

	-- 3: BULLET RAIN - she calls it out of her side; the cannon and its
	-- shells come with the server's word (BulletRainShells)
	function Effects.BulletRain(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root).Unit
		if isLocal then
			face(root, d)
		end
		VFX.Pose(char, "CannonCall", 1.2)
		YM.glow(root.Position + d:Cross(UP) * 1.6, 1.2)
		VFX.PlaySound("CreateBig", root.Position, 1)
	end
	function Effects.BulletRainShells(char, data)
		local base = typeof(data.Cannon) == "Vector3" and data.Cannon
		local d = typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.1 and data.Dir.Unit
		if not base or not d or type(data.Shells) ~= "table" then
			return
		end
		local cannon = YM.cannon(CFrame.lookAt(base, base + d), 1)
		YM.emerge(cannon.parts, 0.3, cannon.model)
		local t0 = os.clock()
		local last = 0
		for _, sh in data.Shells do
			local land = typeof(sh.Land) == "Vector3" and sh.Land
			local at, flight = tonumber(sh.At) or 0.5, tonumber(sh.Flight) or 0.8
			if land then
				last = math.max(last, at + flight + 0.5)
				task.delay(math.max(at - (os.clock() - t0), 0), function()
					if not cannon.model.Parent then
						return
					end
					local muzzle = cannon.muzzle()
					-- the shot: recoil, a flash, smoke
					local back = cannon.base
					cannon.set(back * CFrame.new(0, 0, 0.6))
					task.delay(0.12, function()
						if cannon.model.Parent then
							cannon.set(back)
						end
					end)
					toonExplosion(muzzle, 0.3)
					smokeBurst(muzzle, Color3.fromRGB(210, 204, 196), 1.5, 2.5, 0.8, 5)
					VFX.PlaySound("CannonFire", muzzle, 1)
					-- the shell's arc
					local ball = newPart(Vector3.one * 0.9, CFrame.new(muzzle), Color3.fromRGB(30, 30, 34), Enum.Material.Metal, Enum.PartType.Ball)
					local height = math.max((land - muzzle).Magnitude * 0.3, 6)
					local s0 = os.clock()
					while ball.Parent and os.clock() - s0 < flight do
						local k = (os.clock() - s0) / flight
						ball.CFrame = CFrame.new(muzzle:Lerp(land, k) + UP * (height * 4 * k * (1 - k)))
						RunService.Heartbeat:Wait()
					end
					ball:Destroy()
					-- it lands: a blast, then the little dolls hop out and go off
					toonExplosion(land + UP, 1.1)
					dustPuffs(land, 1, 6, Color3.fromRGB(205, 196, 190), 0.9, false)
					groundMark(land, 3, Color3.fromRGB(58, 52, 50), 3)
					VFX.PlaySound("ShellBoom", land, 1)
					VFX.ShakeAt(land, 1, 50, 0.2)
					for _, b in (type(sh.Bombs) == "table" and sh.Bombs) or {} do
						if typeof(b) == "Vector3" then
							local doll = YM.doll(CFrame.new(land + UP), 0.4)
							task.spawn(function()
								local h0 = os.clock()
								while doll.model.Parent and os.clock() - h0 < 0.3 do
									local k = (os.clock() - h0) / 0.3
									doll.set(CFrame.new((land + UP):Lerp(b + UP * 0.6, k) + UP * (3 * 4 * k * (1 - k))) * CFrame.Angles(k * 6, 0, 0))
									RunService.Heartbeat:Wait()
								end
								task.wait(0.05)
								doll.model:Destroy()
								local core = newPart(Vector3.one * 0.6, CFrame.new(b + UP * 0.6), YM.FLASH, Enum.Material.Neon, Enum.PartType.Ball)
								tween(core, 0.16, { Size = Vector3.one * 6, Transparency = 1 })
								cleanup(core, 0.2)
								sparks(b + UP * 0.6, 0.5, Color3.new(1, 1, 1), YM.GOLD, 5)
								VFX.PlaySound("DollPop", b, 0.7)
							end)
						end
					end
				end)
			end
		end
		task.delay(math.max(last, 1.5), function()
			if cannon.model.Parent then
				cannon.fade(0.45, 0.8)
			end
			if char then
				VFX.ReleasePose(char, 0.2)
			end
		end)
	end

	-- 4 (staff): STRIKE AND STOP - the staff whirled round her
	function Effects.StrikeAndStop(char, _data, _isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		local radius = (ability and ability.Radius) or 9
		local clip = VFX.Clip(char, "StrikeAndStop")
		if not clip then
			VFX.Motion(char, "StrikeAndStop")
		end
		VFX.WeaponSwings[char] = os.clock()
		VFX.PlaySound("StaffHeavy", root.Position, 1)
		task.wait(clip and clip.hit or 0.12)
		if not root.Parent then
			return
		end
		for i = 0, 7 do
			local a = i / 8 * math.pi * 2
			local out = Vector3.new(math.cos(a), 0, math.sin(a))
			task.delay(i * 0.018, function()
				crescent(root.Position + out * 2.5, out, math.rad(90), radius * 0.45, 0.6, 3, 0.2, YM.STEEL)
			end)
		end
		shockDisc(root.Position - UP * 1.5, UP, 2, radius * 2.2, 0.28, YM.GLOW_HOT, 0)
		billboardRing(root.Position, 2, radius * 2, YM.GOLD, 4, 0.25)
		VFX.PlaySound("StaffSwing", root.Position, 1)
	end
	-- ...and whoever it caught is STOPPED
	function Effects.StrikeStop(target)
		local head = target and target:FindFirstChild("Head")
		if not head then
			return
		end
		local bb = Instance.new("BillboardGui")
		bb.Name = "StopMark"
		bb.Adornee = head
		bb.AlwaysOnTop = true
		bb.Size = UDim2.fromOffset(110, 44)
		bb.StudsOffset = Vector3.new(0, 2.6, 0)
		bb.Parent = folder
		local t = Instance.new("TextLabel")
		t.BackgroundTransparency = 1
		t.Size = UDim2.fromScale(1, 1)
		t.Font = Enum.Font.GothamBlack
		t.TextScaled = true
		t.Text = "STOP!"
		t.TextColor3 = YM.RED
		t.TextStrokeColor3 = YM.GOLD
		t.TextStrokeTransparency = 0
		t.Parent = bb
		tween(t, 0.7, { TextTransparency = 1, TextStrokeTransparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0.35)
		cleanup(bb, 1.1)
		billboardRing(head.Position, 1, 6, Color3.new(1, 1, 1), 3, 0.2)
	end

	-- 4 (sword): IAI RUSH - low, the blade back, and she's through them
	function Effects.IaiRush(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local d = flatten(data.Dir, root).Unit
		local time, dist = ability.DashTime or 0.24, ability.Dash or 24
		local from = root.Position
		local clip = VFX.Clip(char, "IaiRush")
		if not clip then
			VFX.Pose(char, "IaiLow", 0.1)
		end
		VFX.WeaponSwings[char] = os.clock()
		VFX.PlaySound("SwordDraw", root.Position, 1)
		task.wait(0.05)
		if not root.Parent then
			return
		end
		if isLocal then
			face(root, d)
			dash(root, d * (dist / time), time)
		end
		afterimage(char, YM.GLOW, 0.3)
		task.wait(time)
		if not root.Parent then
			return
		end
		if not clip then
			VFX.Pose(char, "IaiDone", 0.45)
		end
		VFX.PlaySound("SwordHeavy", root.Position, 1)
		-- the cut she left behind, a beat late
		local to = root.Position
		local mid = (from + to) / 2
		local len = math.max((to - from).Magnitude, 4)
		local slash = newPart(Vector3.new(0.12, 0.12, len), CFrame.lookAt(mid, to) * CFrame.Angles(0, 0, math.rad(20)), Color3.new(1, 1, 1), Enum.Material.Neon)
		tween(slash, 0.08, { Size = Vector3.new(0.35, 1.6, len + 2) })
		tween(slash, 0.35, { Size = Vector3.new(0.05, 0.05, len + 3), Transparency = 1 }, nil, nil, 0.1)
		cleanup(slash, 0.5)
		sparks(mid, 0.8, Color3.new(1, 1, 1), YM.GLOW, 10)
		VFX.PlaySound("SwordRing", mid, 0.8)
	end

	-- 4 (spear): PIERCING THRUST - a step and the spear straight out
	function Effects.PiercingThrust(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root).Unit
		if isLocal then
			face(root, d)
		end
		local clip = VFX.Clip(char, "PiercingThrust")
		if not clip then
			VFX.Motion(char, "PiercingThrust")
		end
		VFX.WeaponSwings[char] = os.clock()
		task.wait(clip and math.max(clip.hit - 0.03, 0.05) or 0.14)
		if not root.Parent then
			return
		end
		if isLocal then
			dash(root, d * 22, 0.1)
		end
		local reach = (ability and ability.Range) or 15
		streaks(root.Position + UP * 0.5, d, 8, 0.4, reach * 0.5, reach, YM.STEEL, 0.18)
		shockDisc(root.Position + UP * 0.5 + d * reach * 0.8, d, 0.6, 5, 0.18, YM.GLOW_HOT, 2)
		VFX.PlaySound("SpearHeavy", root.Position, 1)
	end
	function Effects.SpearRun(_, data)
		local target = typeof(data.Target) == "Instance" and data.Target
		local troot = target and target:FindFirstChild("HumanoidRootPart")
		if not troot then
			return
		end
		local d = typeof(data.Dir) == "Vector3" and data.Dir or UP
		sparks(troot.Position, 0.8, Color3.new(1, 1, 1), YM.GLOW, 8)
		streaks(troot.Position, d, 6, 1, 4, 10, YM.STEEL, 0.25)
		VFX.PlaySound("SpearHit", troot.Position, 1)
	end

	-- ULT 1: GRAND CANNON - it rises out of the street beside her...
	function Effects.GrandCannon(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root).Unit
		if isLocal then
			face(root, d)
		end
		local base = groundPoint(root.Position + d:Cross(UP) * 4.5)
		local old = YM.grand[char]
		if old and old.model.Parent then
			old.fade(0.2)
		end
		local cannon = YM.cannon(CFrame.lookAt(base - UP * 6, base - UP * 6 + d), 2.2)
		YM.grand[char] = cannon
		YM.emerge(cannon.parts, 0.35, cannon.model)
		VFX.Pose(char, "CannonCommand", 1.4)
		YM.glow(base + UP * 2, 2)
		rocks(base, 1, 8)
		dustPuffs(base, 1.4, 8, Color3.fromRGB(205, 196, 190), 1, false)
		VFX.PlaySound("CreateBig", base, 1.2)
		VFX.ShakeAt(base, 1.2, 60, 0.3)
		local t0 = os.clock()
		while cannon.model.Parent and os.clock() - t0 < 0.5 do
			local k = math.clamp((os.clock() - t0) / 0.5, 0, 1)
			cannon.set(CFrame.lookAt(base - UP * 6 * (1 - k) ^ 2, base - UP * 6 * (1 - k) ^ 2 + d))
			RunService.Heartbeat:Wait()
		end
		-- (never fired - she was stopped: it sinks away)
		task.delay(3, function()
			if YM.grand[char] == cannon and cannon.model.Parent then
				cannon.fade(0.4, 1)
			end
		end)
	end
	-- ...and fires
	function Effects.GrandCannonFire(char, data)
		local muzzle, target = typeof(data.Muzzle) == "Vector3" and data.Muzzle, typeof(data.Target) == "Vector3" and data.Target
		if not muzzle or not target then
			return
		end
		local flight = tonumber(data.Flight) or 0.7
		local cannon = char and YM.grand[char]
		if cannon and cannon.model.Parent then
			local back = cannon.base
			cannon.set(back * CFrame.new(0, 0, 1.4))
			task.delay(0.2, function()
				if cannon.model.Parent then
					cannon.set(back)
				end
			end)
			task.delay(1.1, function()
				if cannon.model.Parent then
					cannon.fade(0.45, 1.2)
				end
			end)
		end
		toonExplosion(muzzle, 1.6)
		smokeBurst(muzzle, Color3.fromRGB(210, 204, 196), 5, 6, 1.2, 10)
		VFX.PlaySound("GrandCannonFire", muzzle, 1)
		VFX.ShakeAt(muzzle, 2, 80, 0.3)
		local shell = newPart(Vector3.one * 2.2, CFrame.new(muzzle), Color3.fromRGB(30, 30, 34), Enum.Material.Metal, Enum.PartType.Ball)
		local height = math.max((target - muzzle).Magnitude * 0.18, 5)
		local t0 = os.clock()
		while shell.Parent and os.clock() - t0 < flight do
			local k = (os.clock() - t0) / flight
			shell.CFrame = CFrame.new(muzzle:Lerp(target, k) + UP * (height * 4 * k * (1 - k)))
			RunService.Heartbeat:Wait()
		end
		shell:Destroy()
		toonExplosion(target + UP * 2, 3)
		rocks(target, 1.4, 12)
		groundMark(target, 8, Color3.fromRGB(58, 52, 50), 5)
		VFX.PlaySound("ShellBoom", target, 1.4)
		VFX.PlaySound("Explosion", target, 1)
		VFX.ShakeAt(target, 3, 120, 0.4)
		if char then
			VFX.ReleasePose(char, 0.25)
		end
	end

	-- ULT 2: CAPTURE NET - a catapult behind her...
	function Effects.CaptureNet(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root).Unit
		if isLocal then
			face(root, d)
		end
		local base = groundPoint(root.Position - d * 3)
		local cat = YM.rig("CreatiCatapult", CFrame.lookAt(base, base + d))
		cat.add(Vector3.new(3, 0.6, 3.6), CFrame.new(0, 0.3, 0), Color3.fromRGB(110, 72, 44), Enum.Material.Wood)
		for _, x in { -1.2, 1.2 } do
			cat.add(Vector3.new(0.4, 2.6, 0.4), CFrame.new(x, 1.6, 0), Color3.fromRGB(110, 72, 44), Enum.Material.Wood)
		end
		cat.add(Vector3.new(2.8, 0.3, 0.3), CFrame.new(0, 2.8, 0), YM.IRON)
		cat.arm = cat.add(Vector3.new(0.35, 0.35, 4.5), CFrame.new(0, 2.8, 1.6) * CFrame.Angles(math.rad(-40), 0, 0), Color3.fromRGB(110, 72, 44), Enum.Material.Wood)
		YM.catapults[char] = cat
		YM.emerge(cat.parts, 0.3, cat.model)
		YM.glow(base + UP * 2, 1.5)
		VFX.Pose(char, "NetThrow", 0.9)
		VFX.PlaySound("CreateBig", base, 1)
		task.delay(2, function()
			if cat.model.Parent then
				cat.fade(0.4, 0.8)
			end
		end)
	end
	-- ...flings the net, and it comes down over them
	function Effects.CaptureNetFly(char, data)
		local from, pos = typeof(data.From) == "Vector3" and data.From, typeof(data.Pos) == "Vector3" and data.Pos
		if not from or not pos then
			return
		end
		local flight = tonumber(data.Flight) or 0.7
		local radius = tonumber(data.Radius) or 12
		local pin = tonumber(data.Pin) or 2.8
		local cat = char and YM.catapults[char]
		if cat and cat.arm and cat.arm.Parent then
			cat.offsets[cat.arm] = CFrame.new(0, 3.4, -0.6) * CFrame.Angles(math.rad(50), 0, 0)
			cat.set(cat.base)
		end
		VFX.PlaySound("NetLaunch", from, 1)
		-- (the bundle in the air, opening as it goes)
		local bundle = newPart(Vector3.new(2, 1.2, 2), CFrame.new(from), YM.ROPE, Enum.Material.Fabric, Enum.PartType.Ball)
		local height = math.max((pos - from).Magnitude * 0.3, 8)
		local t0 = os.clock()
		while bundle.Parent and os.clock() - t0 < flight do
			local k = (os.clock() - t0) / flight
			bundle.CFrame = CFrame.new(from:Lerp(pos + UP * 3, k) + UP * (height * 4 * k * (1 - k)))
			bundle.Size = Vector3.new(2 + k * radius * 1.4, 1.2, 2 + k * radius * 1.4)
			RunService.Heartbeat:Wait()
		end
		bundle:Destroy()
		-- the net over the spot: ropes both ways, a dome over whoever's under it
		local m = Instance.new("Model")
		m.Name = "CreatiNet"
		m.Parent = folder
		local lines = 9
		local function domeY(x, z)
			local r = math.sqrt(x * x + z * z) / radius
			return math.max(0, 1 - r * r) * 5 + 0.3
		end
		for i = 0, lines - 1 do
			local o = -radius + i * (2 * radius / (lines - 1))
			for axis = 1, 2 do
				local segs = 8
				for s = 0, segs - 1 do
					local a0 = -radius + s * (2 * radius / segs)
					local a1 = a0 + 2 * radius / segs
					local p0 = axis == 1 and Vector3.new(o, 0, a0) or Vector3.new(a0, 0, o)
					local p1 = axis == 1 and Vector3.new(o, 0, a1) or Vector3.new(a1, 0, o)
					if p0.Magnitude <= radius * 1.05 or p1.Magnitude <= radius * 1.05 then
						local w0 = pos + p0 + UP * domeY(p0.X, p0.Z)
						local w1 = pos + p1 + UP * domeY(p1.X, p1.Z)
						local rope = newPart(Vector3.new(0.18, 0.18, (w1 - w0).Magnitude + 0.1), CFrame.lookAt((w0 + w1) / 2, w1), YM.ROPE, Enum.Material.Fabric, nil, m)
						rope.Transparency = 0
					end
				end
			end
		end
		for i = 1, 10 do
			local a = i / 10 * math.pi * 2
			newPart(Vector3.new(0.7, 0.7, 0.7), CFrame.new(pos + Vector3.new(math.cos(a), 0, math.sin(a)) * radius * 0.95 + UP * 0.35), YM.IRON, Enum.Material.Metal, Enum.PartType.Ball, m)
		end
		dustPuffs(pos, 1.2, 8, Color3.fromRGB(205, 196, 190), 0.9, false)
		VFX.PlaySound("Skid", pos, 1)
		VFX.ShakeAt(pos, 1, 50, 0.2)
		task.delay(pin, function()
			for _, p in m:GetChildren() do
				if p:IsA("BasePart") then
					tween(p, 0.4, { Transparency = 1 })
				end
			end
			cleanup(m, 0.45)
		end)
		if char then
			VFX.ReleasePose(char, 0.25)
		end
	end

	-- ULT 3: DISCHARGE CANNON - the railgun on her shoulder, charging...
	function Effects.DischargeCannon(char, data, isLocal, ability)
		local root = charParts(char)
		local torso = char and (char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso"))
		if not root or not torso then
			return
		end
		local d = flatten(data.Dir, root).Unit
		if isLocal then
			face(root, d)
		end
		local charge = (ability and ability.Charge) or 0.9
		local m = Instance.new("Model")
		m.Name = "CreatiRailgun"
		m.Parent = folder
		local parts = {}
		local function piece(size, offset, color, material, shape)
			local p = newPart(size, torso.CFrame * offset, color, material or Enum.Material.Metal, shape, m)
			YM.attach(torso, p, offset)
			table.insert(parts, p)
			return p
		end
		local ALONG = CFrame.Angles(0, math.rad(90), 0)
		piece(Vector3.new(6, 0.8, 0.8), CFrame.new(1.1, 1.4, -1.4) * ALONG, Color3.fromRGB(236, 238, 244), Enum.Material.Metal, Enum.PartType.Cylinder)
		for _, z in { 0.4, -0.6, -1.6, -2.6 } do
			piece(Vector3.new(0.3, 1.1, 1.1), CFrame.new(1.1, 1.4, -1.4 + z) * ALONG, YM.RAIL, Enum.Material.Neon, Enum.PartType.Cylinder)
		end
		piece(Vector3.new(1.2, 1, 1.4), CFrame.new(1.1, 1.3, 0.6), YM.IRON)
		YM.emerge(parts, 0.3, m)
		YM.rails[char] = m
		VFX.Pose(char, "RailgunAim", charge + 0.6)
		VFX.PlaySound("CreateBig", root.Position, 1)
		VFX.PlaySound("RailCharge", root.Position, 1)
		local t0 = os.clock()
		while m.Parent and os.clock() - t0 < charge do
			local tip = (torso.CFrame * CFrame.new(1.1, 1.4, -4.4)).Position
			bolt(tip, 1.4 + (os.clock() - t0) * 1.5, YM.RAIL)
			task.wait(0.07)
		end
		task.delay(0.9, function()
			if YM.rails[char] == m then
				YM.rails[char] = nil
			end
			for _, p in parts do
				if p.Parent then
					tween(p, 0.35, { Transparency = 1 })
				end
			end
			cleanup(m, 0.4)
		end)
	end
	-- ...and the slug, down the aim and through everything
	function Effects.DischargeCannonFire(char, data)
		local origin, d = typeof(data.Origin) == "Vector3" and data.Origin, typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.1 and data.Dir.Unit
		if not origin or not d then
			return
		end
		local length = tonumber(data.Length) or 220
		local width = tonumber(data.Width) or 7
		local b = origin + d * length
		beam(origin + d * 3, b, width * 0.45, Color3.new(1, 1, 1), YM.RAIL, 0.45)
		for i = 1, 10 do
			local p = origin + d * (length * i / 11)
			bolt(p, width * 0.7, YM.RAIL)
			if i % 3 == 0 then
				billboardRing(p, 2, width * 2.4, YM.RAIL, 4, 0.3)
			end
		end
		shockDisc(origin + d * 3, d, 2, 16, 0.3, YM.RAIL, 6)
		streaks(origin + d * 3, d, 14, 2, 14, 60, Color3.new(1, 1, 1), 0.35)
		VFX.PlaySound("Railgun", origin, 1)
		VFX.ShakeAt(origin, 2.4, 100, 0.35)
		if char then
			task.delay(0.3, function()
				VFX.ReleasePose(char, 0.25)
			end)
		end
	end

	-- ULT 4: LUCKY BAG - a bag drops out of her hands and spills what's in it
	function Effects.LuckyBag(char)
		local root = charParts(char)
		if not root then
			return
		end
		VFX.Pose(char, "BagOffer", 0.7)
		YM.glow(root.Position + root.CFrame.LookVector * 1.5, 1.2)
		VFX.PlaySound("Create", root.Position, 1)
	end
	function Effects.LuckyBagDrop(char, data)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos
		if not pos then
			return
		end
		local bag = YM.rig("LuckyBag", CFrame.new(pos + UP * 1.4))
		bag.add(Vector3.new(2.6, 2.4, 2.6), CFrame.identity, Color3.fromRGB(168, 112, 62), Enum.Material.Fabric, Enum.PartType.Ball)
		bag.add(Vector3.new(0.9, 0.7, 0.9), CFrame.new(0, 1.3, 0), Color3.fromRGB(150, 98, 54), Enum.Material.Fabric, Enum.PartType.Ball)
		bag.add(Vector3.new(1.2, 0.25, 1.2), CFrame.new(0, 1, 0), YM.RED, Enum.Material.SmoothPlastic, Enum.PartType.Cylinder)
		bag.add(Vector3.new(0.8, 0.8, 0.12), CFrame.new(0, 0, -1.25), YM.GOLD, Enum.Material.SmoothPlastic, Enum.PartType.Ball)
		YM.emerge(bag.parts, 0.3, bag.model)
		VFX.PlaySound("LuckyBag", pos, 1)
		task.delay(0.45, function()
			sparks(pos + UP * 1.5, 1, Color3.new(1, 1, 1), YM.GOLD, 12)
			billboardRing(pos + UP * 1.5, 1, 9, YM.GOLD, 4, 0.3)
			local root = char and charParts(char)
			for i, id in (type(data.Items) == "table" and data.Items) or {} do
				local item = Config.Items and Config.Items[id]
				local icon = item and item.Icon or "💗"
				local p = newPart(Vector3.one * 0.2, CFrame.new(pos + UP * 2), Color3.new(1, 1, 1), Enum.Material.SmoothPlastic)
				p.Transparency = 1
				local bb = Instance.new("BillboardGui")
				bb.Size = UDim2.fromOffset(46, 46)
				bb.AlwaysOnTop = true
				bb.Parent = p
				local t = Instance.new("TextLabel")
				t.BackgroundTransparency = 1
				t.Size = UDim2.fromScale(1, 1)
				t.TextScaled = true
				t.Text = icon
				t.Parent = bb
				local up = pos + UP * (4 + i) + rng:NextUnitVector() * 1.5
				tween(p, 0.35, { CFrame = CFrame.new(up) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out, (i - 1) * 0.12)
				task.delay(0.5 + (i - 1) * 0.12, function()
					local to = root and root.Parent and root.Position or pos
					tween(p, 0.3, { CFrame = CFrame.new(to) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
					tween(t, 0.3, { TextTransparency = 1 }, nil, nil, 0.15)
				end)
				cleanup(p, 1.3)
			end
			bag.fade(0.4, 0.8)
		end)
		if char then
			VFX.ReleasePose(char, 0.3)
		end
	end

	-- a dash: a glimmer off her skin
	QUIRK_FX.Dash.Creation = function(_char, root, dir)
		sparks(root.Position - dir * 1.2 + UP * 0.5, 0.45, YM.GLOW_HOT, YM.GLOW, 5)
	end
	-- FULL ARSENAL: arms out, everything she can make at once - a burst of
	-- dolls, steel and gold out of her, a ring of light
	QUIRK_FX.Ult.Creation = function(char, root, g)
		VFX.Pose(char, "CreationAwaken", 1.1)
		YM.glow(root.Position + UP, 3)
		shockDisc(g + UP * 0.3, UP, 2, 34, 0.4, YM.GLOW, 5)
		billboardRing(root.Position + UP, 2, 30, YM.GOLD, 6, 0.4)
		for i = 1, 14 do
			local a = i / 14 * math.pi * 2
			local out = Vector3.new(math.cos(a), 0.5, math.sin(a))
			local from = root.Position + UP
			local to = from + out * rand(6, 11)
			if i % 3 == 0 then
				local doll = YM.doll(CFrame.new(from), 0.5)
				task.spawn(function()
					local t0 = os.clock()
					while doll.model.Parent and os.clock() - t0 < 0.5 do
						local k = (os.clock() - t0) / 0.5
						doll.set(CFrame.new(from:Lerp(to, 1 - (1 - k) ^ 2)) * CFrame.Angles(k * 4, 0, 0))
						RunService.Heartbeat:Wait()
					end
					doll.fade(0.3)
				end)
			else
				local bar = newPart(Vector3.new(0.3, 0.3, rand(1.5, 3)), CFrame.lookAt(from, to), i % 2 == 0 and YM.STEEL or YM.GOLD, Enum.Material.Metal)
				tween(bar, 0.5, { CFrame = CFrame.lookAt(to, to + out) * CFrame.Angles(rand(-2, 2), rand(-2, 2), 0), Transparency = 1 })
				cleanup(bar, 0.55)
			end
		end
		sparks(root.Position + UP * 2, 1.4, YM.GLOW_HOT, YM.GOLD, 20)
	end

	-- the finisher: a cannon out of her forearm, point blank
	function YM.finisher(char, _target, troot, d, time)
		VFX.Pose(char, "CannonCall", time)
		local root = charParts(char)
		if not root then
			return
		end
		local base = groundPoint(root.Position + d * 2.2)
		local cannon = YM.cannon(CFrame.lookAt(base, base + d), 0.8)
		YM.emerge(cannon.parts, 0.3, cannon.model)
		YM.glow(handPos(char, false), 1.4)
		VFX.PlaySound("CreateBig", root.Position, 1)
		task.wait(math.max(time - 0.1, 0.1))
		if not troot.Parent then
			cannon.fade(0.3)
			return
		end
		toonExplosion(cannon.muzzle(), 1.4)
		toonExplosion(troot.Position, 2)
		VFX.PlaySound("GrandCannonFire", troot.Position, 1)
		VFX.ShakeAt(troot.Position, 2, 70, 0.3)
		task.delay(0.6, function()
			cannon.fade(0.4, 0.8)
		end)
	end
end

-- (round 63) THE HIT STAR: a sharp star of light facing the camera, spikes
-- of two lengths, snapping open and gone in a blink (the JJS contact flash)
function VFX.HitStar(pos, size, tint)
	local anchor = newPart(Vector3.one * 0.1, CFrame.new(pos), Color3.new(1, 1, 1))
	anchor.Transparency = 1
	local bb = Instance.new("BillboardGui")
	bb.Size = UDim2.fromScale(size * 0.3, size * 0.3)
	bb.LightInfluence = 0
	bb.Adornee = anchor
	bb.Parent = anchor
	local spin = rand(0, 45)
	for k = 1, 8 do
		local long = k % 2 == 1
		local spike = Instance.new("Frame")
		spike.AnchorPoint = Vector2.new(0.5, 1)
		spike.Position = UDim2.fromScale(0.5, 0.5)
		spike.Size = UDim2.fromScale(long and 0.07 or 0.05, long and 0.5 or 0.3)
		spike.Rotation = spin + k * 45
		spike.BackgroundColor3 = long and Color3.new(1, 1, 1) or tint
		spike.BorderSizePixel = 0
		spike.Parent = bb
		local g = Instance.new("UIGradient")
		g.Rotation = 90
		g.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.35, 0), NumberSequenceKeypoint.new(1, 0) })
		g.Parent = spike
		tween(spike, 0.12, { BackgroundTransparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0.04)
	end
	tween(bb, 0.06, { Size = UDim2.fromScale(size, size) }, Enum.EasingStyle.Quad)
	cleanup(anchor, 0.2)
end

-- (round 63) RAGDOLLS LAND: a body thrown into the street kicks up dust
-- (and chips of it, landing hard) - a hit on screen for every fall
do
	local lastVy = setmetatable({}, { __mode = "k" })
	local lastPuff = setmetatable({}, { __mode = "k" })
	local acc = 0
	local function check(model)
		if not model:GetAttribute("Ragdolled") then
			lastVy[model] = nil
			return
		end
		local torso = model:FindFirstChild("Torso") or model:FindFirstChild("UpperTorso")
		if not torso or not nearCamera(torso.Position, 140) then
			return
		end
		local vy = torso.AssemblyLinearVelocity.Y
		local before = lastVy[model]
		lastVy[model] = vy
		if before and before < -26 and vy > before * 0.35 and os.clock() - (lastPuff[model] or 0) > 0.3 then
			local g = groundPoint(torso.Position)
			if (torso.Position - g).Magnitude < 3.5 then
				lastPuff[model] = os.clock()
				local hard = math.clamp(-before / 70, 0.4, 1.4)
				dustPuffs(g, 0.6 + 0.5 * hard, 3 + math.floor(3 * hard), Color3.fromRGB(205, 196, 188), 0.7, false)
				if hard > 0.9 then
					rocks(g, 0.7, 4)
				end
				VFX.PlaySound("Knocked", g, 0.35 + 0.35 * hard)
			end
		end
	end
	RunService.Heartbeat:Connect(function(dt)
		acc += dt
		if acc < 1 / 30 then
			return
		end
		acc = 0
		for _, p in Players:GetPlayers() do
			if p.Character then
				check(p.Character)
			end
		end
		local dummies = workspace:FindFirstChild("Dummies")
		if dummies then
			for _, m in dummies:GetChildren() do
				if m:IsA("Model") then
					check(m)
				end
			end
		end
	end)
end

---------------------------------------------------------------------------
-- (round 66) THE SUPPORT DROP: a U.A. Support Course drop pod - Mei
-- Hatsume's work, so it's loud about it. A ring and a beam of light mark
-- where it'll land (everyone's warned), it comes down nose first out of the
-- sky on a burning tail and a smoke trail, slams in (a shockwave, dust, the
-- street shakes), vents steam, and the lid pops off - the buyer's delivery
-- sits on top. When it's taken (or left too long) the pod sinks back into
-- the street. The server says where and when; the pod is drawn here.
---------------------------------------------------------------------------
do
	local POD = { drops = {} } -- [id] = { model, parts, lid, ring, ... }
	VFX.POD = POD
	local WHITE, INK = Color3.fromRGB(236, 236, 240), Color3.fromRGB(28, 28, 34)
	local PINK, GOLD2 = Color3.fromRGB(255, 92, 170), Color3.fromRGB(255, 200, 40)
	local DUST = Color3.fromRGB(205, 196, 190)

	-- a frame at pos whose up is `up` (the pod's tail end)
	function POD.frame(pos, up)
		up = up.Unit
		local right = up:Cross(Vector3.zAxis)
		if right.Magnitude < 0.1 then
			right = up:Cross(Vector3.xAxis)
		end
		right = right.Unit
		return CFrame.fromMatrix(pos, right, up, right:Cross(up))
	end

	-- the pod, built upright in its own space: y = 0 is the tip of its nose
	function POD.build()
		local model = Instance.new("Model")
		model.Name = "SupportPod"
		local parts = {}
		local function add(size, offset, color, material, shape)
			local p = newPart(size, offset, color, material or Enum.Material.SmoothPlastic, shape, model)
			table.insert(parts, { part = p, offset = offset })
			return p
		end
		local UPRIGHT = CFrame.Angles(0, 0, math.pi / 2) -- (a cylinder runs along its X)
		add(Vector3.new(3.2, 3.2, 3.2), CFrame.new(0, 1.6, 0), INK, Enum.Material.Metal, Enum.PartType.Ball) -- nose
		add(Vector3.new(4.4, 3.2, 3.2), CFrame.new(0, 3.3, 0) * UPRIGHT, WHITE, Enum.Material.SmoothPlastic, Enum.PartType.Cylinder) -- body
		for _, y in { 2.1, 4.6 } do
			add(Vector3.new(0.3, 3.34, 3.34), CFrame.new(0, y, 0) * UPRIGHT, INK, Enum.Material.Metal, Enum.PartType.Cylinder) -- bands
		end
		add(Vector3.new(0.18, 3.36, 3.36), CFrame.new(0, 3.35, 0) * UPRIGHT, PINK, Enum.Material.Neon, Enum.PartType.Cylinder) -- the glowing stripe
		-- the fins, round the tail
		for k = 0, 3 do
			local a = k * math.pi / 2 + math.pi / 4
			add(Vector3.new(0.22, 1.9, 1.3), CFrame.Angles(0, a, 0) * CFrame.new(0, 5.0, 1.9) * CFrame.Angles(math.rad(-14), 0, 0), GOLD2, Enum.Material.Metal)
		end
		-- the Support Course's mark: a pink panel with a big gear
		add(Vector3.new(1.3, 1.1, 0.12), CFrame.new(0, 3.3, -1.62), PINK, Enum.Material.SmoothPlastic)
		add(Vector3.new(0.7, 0.7, 0.14), CFrame.new(0, 3.3, -1.66) * CFrame.Angles(0, 0, math.rad(45)), WHITE, Enum.Material.Neon)
		-- the lid (it pops) and its handle
		local lid = add(Vector3.new(0.5, 3.4, 3.4), CFrame.new(0, 5.8, 0) * UPRIGHT, PINK, Enum.Material.SmoothPlastic, Enum.PartType.Cylinder)
		local knob = add(Vector3.new(0.7, 0.7, 0.7), CFrame.new(0, 6.2, 0), GOLD2, Enum.Material.Metal, Enum.PartType.Ball)
		-- the burning tail (while it falls)
		local flame = add(Vector3.new(2.2, 1.6, 1.6), CFrame.new(0, 7.1, 0) * UPRIGHT, Color3.fromRGB(255, 160, 60), Enum.Material.Neon, Enum.PartType.Cylinder)
		flame.Transparency = 0.25
		local hl = Instance.new("Highlight")
		hl.FillTransparency = 1
		hl.OutlineColor = INK
		hl.OutlineTransparency = 0.2
		hl.DepthMode = Enum.HighlightDepthMode.Occluded
		hl.Parent = model
		model.Parent = folder
		return model, parts, lid, knob, flame
	end

	function POD.place(drop, cf)
		local list, cfs = {}, {}
		for _, e in drop.parts do
			if e.part.Parent == drop.model then
				list[#list + 1] = e.part
				cfs[#cfs + 1] = cf * e.offset
			end
		end
		if not pcall(function()
			workspace:BulkMoveTo(list, cfs, Enum.BulkMoveMode.FireCFrameChanged)
		end) then
			for i, p in list do
				p.CFrame = cfs[i]
			end
		end
	end

	-- the mark on the street: a ring, a disc closing in on the spot as it
	-- comes, and a beam up into the sky - with who it's for
	function POD.mark(drop, data)
		local pos = data.Pos
		local flat = CFrame.new(pos + UP * 0.06) * CFrame.Angles(0, 0, math.pi / 2)
		local ring = newPart(Vector3.new(0.08, 13, 13), flat, PINK, Enum.Material.Neon, Enum.PartType.Cylinder)
		ring.Transparency = 0.72
		local inner = newPart(Vector3.new(0.1, 12, 12), flat + UP * 0.02, GOLD2, Enum.Material.Neon, Enum.PartType.Cylinder)
		inner.Transparency = 0.45
		tween(inner, data.Time, { Size = Vector3.new(0.1, 2.2, 2.2), Transparency = 0.2 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
		local beam = newPart(Vector3.new(120, 0.5, 0.5), CFrame.new(pos + UP * 60) * CFrame.Angles(0, 0, math.pi / 2), PINK, Enum.Material.Neon, Enum.PartType.Cylinder)
		beam.Transparency = 0.6
		local tag = Instance.new("BillboardGui")
		tag.Size = UDim2.fromOffset(220, 50)
		tag.StudsOffsetWorldSpace = Vector3.new(0, 5, 0)
		tag.AlwaysOnTop = true
		tag.MaxDistance = 220
		tag.LightInfluence = 0
		tag.Adornee = ring
		tag.Parent = ring
		local label = Instance.new("TextLabel")
		label.Size = UDim2.fromScale(1, 1)
		label.BackgroundTransparency = 1
		label.Font = Enum.Font.GothamBlack
		label.TextScaled = true
		label.TextColor3 = Color3.new(1, 1, 1)
		label.TextStrokeColor3 = Color3.fromRGB(120, 20, 70)
		label.TextStrokeTransparency = 0
		label.Text = "▼ SUPPORT DROP ▼\n" .. tostring(data.Icon or "📦") .. " " .. tostring(data.Name or "")
		label.Parent = tag
		drop.marks = { ring, inner, beam }
		-- (it pulses while it waits)
		task.spawn(function()
			local t0 = os.clock()
			while ring.Parent and os.clock() - t0 < data.Time do
				ring.Transparency = 0.6 + 0.2 * math.sin((os.clock() - t0) * 18)
				task.wait()
			end
		end)
	end

	function Effects.SupportDrop(_, data)
		if typeof(data.Pos) ~= "Vector3" or typeof(data.From) ~= "Vector3" then
			return
		end
		local fall = math.clamp(tonumber(data.Time) or 1.6, 0.3, 5)
		data.Time = fall
		local model, parts, lid, knob, flame = POD.build()
		local drop = { model = model, parts = parts, lid = lid, knob = knob, flame = flame }
		POD.drops[data.Id or 0] = drop
		POD.mark(drop, data)
		VFX.PlaySound("PodIncoming", data.Pos, 1)
		local path = data.Pos - data.From
		local up = -path.Unit
		local t0 = os.clock()
		local lastPuff = 0
		local stopTrail = addTrail(flame, Color3.fromRGB(255, 190, 90), 0.35, 1.4)
		-- down it comes, nose first, faster and faster
		while os.clock() - t0 < fall and model.Parent do
			local k = (os.clock() - t0) / fall
			local at = data.From + path * (k * k)
			POD.place(drop, POD.frame(at, up) * CFrame.Angles(0, k * 9, 0))
			if os.clock() - lastPuff > 0.045 then
				lastPuff = os.clock()
				local puff = newPart(Vector3.one * rand(2.2, 3.4), CFrame.new(at + up * 7.5), Color3.fromRGB(235, 232, 228), Enum.Material.SmoothPlastic, Enum.PartType.Ball)
				puff.Transparency = 0.25
				tween(puff, 0.9, { Size = puff.Size * 2.4, Transparency = 1 })
				cleanup(puff, 0.95)
			end
			task.wait()
		end
		stopTrail()
		for _, m in drop.marks or {} do
			m:Destroy()
		end
		if not model.Parent then
			return
		end
		-- the slam: in up to its bands, leaning a touch
		local rest = POD.frame(data.Pos - UP * 0.9, UP) * CFrame.Angles(math.rad(rand(-6, 6)), rand(0, 6.28), math.rad(rand(-6, 6)))
		POD.place(drop, rest)
		drop.rest = rest
		flame:Destroy()
		shockDisc(data.Pos + UP * 0.3, UP, 3, 28, 0.35, WIND)
		dustPuffs(data.Pos, 1.8, 10, DUST, 1.1, false)
		sparks(data.Pos + UP, 1.3, Color3.fromRGB(255, 232, 120), PINK, 22)
		VFX.PlaySound("PodLand", data.Pos, 1)
		VFX.ShakeAt(data.Pos, 1.2, 70, 0.3)
		for k = 1, 6 do
			-- chunks of street thrown up round it
			local a = k / 6 * math.pi * 2 + rand(-0.3, 0.3)
			local chunk = newPart(Vector3.new(rand(0.6, 1.2), rand(0.4, 0.8), rand(0.6, 1.2)), CFrame.new(data.Pos + Vector3.new(math.cos(a) * 2.5, 0.4, math.sin(a) * 2.5)), Color3.fromRGB(110, 108, 104), Enum.Material.Slate)
			local out = Vector3.new(math.cos(a), 0, math.sin(a))
			tween(chunk, 0.5, { CFrame = chunk.CFrame + out * rand(4, 7) + UP * rand(1.5, 3) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			tween(chunk, 0.35, { CFrame = chunk.CFrame + out * rand(7, 9) - UP * 0.6, Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0.5)
			cleanup(chunk, 0.9)
		end
		-- steam, then the lid pops off
		smokeBurst(data.Pos + UP * 2, WHITE, 3, 3, 0.4, 14)
		task.wait(math.clamp(tonumber(data.Open) or 0.5, 0, 2))
		if not model.Parent then
			return
		end
		local top = rest * CFrame.new(0, 6, 0)
		smokeBurst(top.Position, WHITE, 2.5, 2, 0.35, 18)
		VFX.PlaySound("PodOpen", top.Position, 1)
		for _, p in { lid, knob } do
			if p.Parent then
				local flip = p.CFrame + (rest.UpVector * 7 + rest.RightVector * 3)
				tween(p, 0.7, { CFrame = flip * CFrame.Angles(math.rad(140), 0, math.rad(60)), Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
				cleanup(p, 0.75)
			end
		end
		billboardRing(top.Position, 1, 9, PINK, 5, 0.3)
		local light = Instance.new("PointLight")
		light.Color = PINK
		light.Range = 14
		light.Brightness = 2
		light.Parent = parts[2].part
		-- (it goes when the server says so, or on its own a little after)
		task.delay((tonumber(data.Despawn) or 10) + 3, function()
			POD.remove(data.Id or 0)
		end)
	end

	function POD.remove(id)
		local drop = POD.drops[id]
		if not drop then
			return
		end
		POD.drops[id] = nil
		local rest = drop.rest
		for _, e in drop.parts do
			local p = e.part
			if p.Parent then
				tween(p, 0.7, { Transparency = 1, CFrame = p.CFrame - UP * 3.5 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
			end
		end
		if rest then
			dustPuffs(rest.Position, 0.8, 4, DUST, 0.6, false)
		end
		cleanup(drop.model, 0.8)
	end

	function Effects.SupportDropDone(_, data)
		local drop = POD.drops[data.Id or 0]
		if drop and drop.rest and data.Taken then
			billboardRing((drop.rest * CFrame.new(0, 6, 0)).Position, 1, 7, GOLD2, 4, 0.25)
		end
		task.wait(0.3)
		POD.remove(data.Id or 0)
	end
end

